		local function genCode(obj)
			local path = clth(Explorer.GetInstancePath(obj))
			local cn = obj.ClassName
			local L = {"local obj = " .. path}
			local function add(t) L[#L + 1] = t end
			if cn == "Animation" then
				add('local plr = game:GetService("Players").LocalPlayer')
				add('local hum = (plr.Character or plr.CharacterAdded:Wait()):FindFirstChildOfClass("Humanoid")')
				add('local track = (hum:FindFirstChildOfClass("Animator") or hum):LoadAnimation(obj)')
				add("track:Play()")
			elseif cn == "Sound" then
				add("local snd = obj:Clone()")
				add("snd.Parent = workspace")
				add("snd:Play()")
				add('game:GetService("Debris"):AddItem(snd, math.max(snd.TimeLength, 1) + 1)')
			elseif cn == "ParticleEmitter" or cn == "Fire" or cn == "Smoke" or cn == "Sparkles" or cn:find("Light") then
				add('local root = game:GetService("Players").LocalPlayer.Character:WaitForChild("HumanoidRootPart")')
				add("local fx = obj:Clone()")
				add("fx.Parent = root")
				if cn == "ParticleEmitter" then add("fx:Emit(20)") end
			else
				add("print(obj)")
			end
			return table.concat(L, "\n")
		end
		local function exactCode(obj, cb)
			local C = (getgenv or function() return _G end)().__RPP_Copy
			if C and C.targetCode and C.classify then
				local kind = C.classify(obj) or "structure"
				local done = false
				local ok = pcall(C.targetCode, {kind = kind, inst = obj}, function(code)
					if done then return end
					done = true
					if code then cb(code) else cb((select(2, pcall(genCode, obj)))) end
				end)
				if not ok and not done then done = true cb((select(2, pcall(genCode, obj)))) end
			else
				cb((select(2, pcall(genCode, obj))))
			end
		end
		local function exactAll(cb)
			local sList = selection.List
			local objs = {}
			for i = 1,#sList do objs[#objs + 1] = sList[i].Obj end
			if #objs == 0 then return end
			local results, pending = {}, #objs
			for i, obj in ipairs(objs) do
				exactCode(obj, function(code)
					results[i] = {obj, code}
					pending -= 1
					if pending == 0 then cb(results) end
				end)
			end
		end
		local function dexNotify(msg)
			pcall(function() game:GetService("StarterGui"):SetCore("SendNotification", {Title = "Dex Copy", Text = tostring(msg), Duration = 4}) end)
		end
		local function joinCodes(results)
			local parts = {}
			for i = 1,#results do
				if type(results[i][2]) == "string" then parts[#parts + 1] = results[i][2] end
			end
			if #parts == 0 then return nil, 0 end
			if #parts == 1 then return parts[1], 1 end
			for i = 1,#parts do parts[i] = "task.spawn(function()\n" .. parts[i] .. "\nend)" end
			return table.concat(parts, "\n\n"), #parts
		end
		context:Register("COPY_CODE",{Name = "Copy Code", IconMap = Explorer.MiscIcons, Icon = "Copy", OnClick = function()
			exactAll(function(results)
				local code, n = joinCodes(results)
				local clip = env.setclipboard or setclipboard or toclipboard
				if code and clip then
					pcall(clip, code)
					dexNotify("Copied the code of " .. n .. (n == 1 and " object" or " objects"))
				else
					dexNotify("Could not copy: " .. (code and "this executor has no clipboard" or "nothing to copy for that selection"))
				end
			end)
		end})
		context:Register("SAVE_CODE",{Name = "Download Code to File", IconMap = Explorer.MiscIcons, Icon = "Save", OnClick = function()
			exactAll(function(results)
				local code, n = joinCodes(results)
				if not code then return dexNotify("Nothing to save for that selection") end
				local first = results[1][1]
				local default = (first.ClassName .. "_" .. first.Name):gsub("[^%w_%-]", "_")
				if n > 1 then default = "Selection_" .. n .. "_objects" end
				Lib.SaveAsPrompt(default, function(filename)
					pcall(function() if env.makefolder then env.makefolder("dex") env.makefolder("dex/saved") end end)
					local ok, err = pcall(env.writefile, "dex/saved/" .. filename, code)
					dexNotify(ok and ("Saved to workspace/dex/saved/" .. filename) or ("Could not save: " .. tostring(err)))
				end, "lua")
			end)
		end})
