	}

	Main.Plugins = {}

	Main.GetRandomString = function()
		local output = ""
		for i = 2, 25 do
			output = output .. string.char(math.random(1,250))
		end

		return output
	end

	Main.GetSecureContainer = function()
		return
			syn and syn.protect_gui or
			gethui and gethui() or
			service.CoreGui or
			service.Players.LocalPlayer:WaitForChild("PlayerGui")
	end

	Main.SecureGui = function(gui)
		gui.Name = "_DPP_".. Main.GetRandomString()
		if gethui then
			gui.Parent = gethui()
		elseif syn and syn.protect_gui then
			syn.protect_gui(gui)
			gui.Parent = service.CoreGui
		elseif protect_gui then
			protect_gui(gui)
			gui.Parent = service.CoreGui
		elseif protectgui then
			protectgui(gui)
			gui.Parent = service.CoreGui
		else
			if Main.Elevated then
				gui.Parent = service.CoreGui
			else
				gui.Parent = service.Players.LocalPlayer:WaitForChild("PlayerGui")
			end
		end
	end

	Main.GetInitDeps = function()
		return {
			Main = Main,
			Lib = Lib,
			Apps = Apps,
			Settings = Settings,

			API = API,
			RMD = RMD,
			env = env,
			service = service,
			plr = plr,
			create = create,
			createSimple = createSimple
		}
	end

	Main.Error = function(str)
		if rconsoleprint then
			rconsoleprint("DEX ERROR: "..tostring(str).."\n")
			wait(9e9)
		else
			error(str)
		end
	end

	Main.LoadModule = function(name)
		if Main.Elevated then
			local control

			if EmbeddedModules then
				control = EmbeddedModules[name]()

				if gethsfuncs then
					control = _G.moduleData
				end

				if not control then Main.Error("Missing Embedded Module: "..name) end
			else
				local hashs = Main.ModuleHashData
				if not hashs then
					local s,hashDataStr = pcall(oldgame.HttpGet, game, "https://api.github.com/repos/"..Main.GitRepoName.."/ModuleHashs.dat")
					if not s then Main.Error("Failed to get module hashs") end

					local s,hashData = pcall(service.HttpService.JSONDecode,service.HttpService,hashDataStr)
					if not s then Main.Error("Failed to decode module hash JSON") end

					hashs = hashData
					Main.ModuleHashData = hashs
				end

				local hashfunc = (syn and syn.crypt.hash) or function() return "" end
				local filePath = "dex/ModuleCache/"..name..".lua"
				local s,moduleStr = pcall(env.readfile,filePath)

				if s and hashfunc(moduleStr) == hashs[name] then
					control = loadstring(moduleStr)()
				else
					local s,moduleStr = pcall(oldgame.HttpGet, game, "https://api.github.com/repos/"..Main.GitRepoName.."/Modules/"..name..".lua")
					if not s then Main.Error("Failed to get external module data of "..name) end

					env.writefile(filePath,moduleStr)
					control = loadstring(moduleStr)()
				end
			end

			Main.AppControls[name] = control
			control.InitDeps(Main.GetInitDeps())

			local moduleData = control.Main()
			Apps[name] = moduleData
			return moduleData
		else
			local module = script:WaitForChild("Modules"):WaitForChild(name,2)
			if not module then Main.Error("CANNOT FIND MODULE "..name) end

			local control = require(module)
			Main.AppControls[name] = control
			control.InitDeps(Main.GetInitDeps())

			local moduleData = control.Main()
			Apps[name] = moduleData
			return moduleData
		end
	end

	Main.LoadPluginFile = function(pluginDir)
		if env.readfile then
			if isfile(pluginDir) then
				local preloadedPlugin = loadfile and loadfile(pluginDir) or loadstring(env.readfile(pluginDir))
				local loadedPlugin = preloadedPlugin()

				local control = loadedPlugin
				control.InitDeps(Main.GetInitDeps())

				local moduleData = control.Main()
				Apps[pluginDir] = moduleData
				Main.AppControls[pluginDir] = control

				moduleData.PluginData = control.PluginData

				return moduleData
			else
				Main.Error("CANNOT FIND FILE MODULE "..pluginDir)
			end
		end
	end

	Main.LoadModules = function()
		for i,v in pairs(Main.ModuleList) do
			local s,e = pcall(Main.LoadModule,v)
			if not s then
				Main.Error("FAILED LOADING " .. v .. " CAUSE " .. e)
			end
		end

		Explorer = Apps.Explorer
		Properties = Apps.Properties
		ScriptViewer = Apps.ScriptViewer
		Console = Apps.Console
		SaveInstance = Apps.SaveInstance
		ModelViewer = Apps.ModelViewer
		Notebook = Apps.Notebook
		SettingsWindow = Apps.SettingsWindow

		local appTable = {
			Explorer = Explorer,
			Properties = Properties,
			ScriptViewer = ScriptViewer,
			Console = Console,
			SaveInstance = SaveInstance,
			ModelViewer = ModelViewer,
			Notebook = Notebook,
			SettingsWindow = SettingsWindow
		}

		Main.AppControls.Lib.InitAfterMain(appTable)
		for i,v in pairs(Main.ModuleList) do
			local control = Main.AppControls[v]
			if control then
				control.InitAfterMain(appTable)
			end
		end
	end

	Main.InitEnv = function()
		setmetatable(env,{__newindex = function(self,name,func)
			if not func then Main.MissingEnv[#Main.MissingEnv+1] = name return end
			rawset(self,name,func)
		end})

		env.isonmobile = game:GetService("UserInputService").TouchEnabled

		env.loadstring = (pcall(loadstring,"local a = 1") and loadstring) or (game:GetService("RunService"):IsStudio() and script.Modules:FindFirstChild("Loadstring") and require(script.Modules:FindFirstChild("Loadstring")))

		env.isfile = isfile
		env.isfolder = isfolder
		env.readfile = readfile
		env.writefile = writefile
		env.appendfile = appendfile
		env.makefolder = makefolder
		env.listfiles = listfiles
		env.loadfile = loadfile
		-- Built-in saver. Used when the executor has no saveinstance and the online library can't be downloaded.
		-- Writes a normal .rbxlx (place) or .rbxmx (single object) file that Roblox Studio opens.
		env.builtinsave = function(obj, filepath, options)
			options = options or {}
			local writefile_, appendfile_ = env.writefile, env.appendfile
			if not writefile_ then error("this executor has no writefile") end
			if not API or not API.Classes then error("the Roblox API dump is not loaded yet, wait a few seconds and try again") end

			local Players = game:GetService("Players")
			local CollectionService = game:GetService("CollectionService")
			local isPlace = obj == game
			local ext = isPlace and ".rbxlx" or ".rbxmx"

			local path = tostring(filepath or "saved")
			for _, e in ipairs({".txt", ".rbxlx", ".rbxmx", ".rbxl", ".rbxm"}) do
				if path:lower():sub(-#e) == e then path = path:sub(1, #path - #e) end
			end
			path = path:gsub("[*?:<>|\"]+", ""):sub(1, 150)
			if path == "" then path = "saved" end
			local fullPath = path .. ext

			-- text helpers
			local XML = { ["&"] = "&amp;", ["<"] = "&lt;", [">"] = "&gt;", ['"'] = "&quot;", ["'"] = "&apos;" }
			local function esc(s)
				s = tostring(s):gsub("[\0-\8\11\12\14-\31]", "")
				return (s:gsub("[&<>\"']", XML))
			end
			local function cdata(s)
				s = tostring(s):gsub("[\0-\8\11\12\14-\31]", "")
				s = s:gsub("]]>", "]]]]><![CDATA[>")
				return "<![CDATA[" .. s .. "]]>"
			end
			local function fnum(n)
				if n ~= n then return "NAN" end
				if n == math.huge then return "INF" end
				if n == -math.huge then return "-INF" end
				if n == math.floor(n) and math.abs(n) < 1e15 then return string.format("%d", n) end
				return string.format("%.9g", n)
			end
			local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
			local function b64(s)
				local out = {}
				for i = 1, #s, 3 do
					local a, b, c = s:byte(i, i + 2)
					local n = a * 65536 + (b or 0) * 256 + (c or 0)
					local c1, c2, c3, c4 = math.floor(n / 262144) % 64, math.floor(n / 4096) % 64, math.floor(n / 64) % 64, n % 64
					out[#out + 1] = B64:sub(c1 + 1, c1 + 1) .. B64:sub(c2 + 1, c2 + 1)
						.. (b and B64:sub(c3 + 1, c3 + 1) or "=") .. (c and B64:sub(c4 + 1, c4 + 1) or "=")
				end
				return table.concat(out)
			end

			local ids, kids, order = {}, {}, 0
			local lastYield = os.clock()
			local function slice()
				if os.clock() - lastYield > 0.03 then
					task.wait()
					lastYield = os.clock()
				end
			end

			-- what to keep
			local camera = workspace.CurrentCamera
			local playerChars = {}
			if options.RemovePlayerCharacters ~= false then
				for _, p in ipairs(Players:GetPlayers()) do
					if p.Character then playerChars[p.Character] = true end
				end
			end
			local function keep(o)
				local cn = o.ClassName
				if not API.Classes[cn] then return false end
				if cn == "Player" and not options.SavePlayers then return false end
				if o == camera then return false end
				if playerChars[o] then return false end
				return true
			end

			local function build(o)
				order += 1
				ids[o] = "RBX" .. order
				local list = {}
				local okC, ch = pcall(o.GetChildren, o)
				if okC then
					for _, c in ipairs(ch) do
						if keep(c) then list[#list + 1] = c end
					end
				end
				kids[o] = list
				for _, c in ipairs(list) do build(c) end
				slice()
			end

			local roots = {}
			if isPlace then
				local names = {
					"Workspace", "Lighting", "ReplicatedFirst", "ReplicatedStorage", "StarterGui", "StarterPack", "StarterPlayer",
					"SoundService", "Teams", "Chat", "TextChatService", "MaterialService", "LocalizationService", "TestService",
					"VoiceChatService", "ServerScriptService", "ServerStorage",
				}
				if options.SavePlayers then table.insert(names, 1, "Players") end
				for _, n in ipairs(names) do
					local okS, svc = pcall(function() return game:FindService(n) end)
					if okS and svc then roots[#roots + 1] = svc end
				end
				if options.NilInstances and env.getnilinstances then
					local okN, nils = pcall(env.getnilinstances)
					if okN and type(nils) == "table" and #nils > 0 then
						local holder = Instance.new("Folder")
						holder.Name = "NilInstances"
						ids[holder] = "RBXNIL"
						local list = {}
						for _, n in ipairs(nils) do
							if typeof(n) == "Instance" and keep(n) then list[#list + 1] = n end
						end
						for _, n in ipairs(list) do build(n) end
						kids[holder] = list
						roots[#roots + 1] = holder
					end
				end
			else
				roots[1] = obj
			end
			for _, r in ipairs(roots) do
				if not ids[r] then build(r) end
			end
			local total = order

			-- properties
			local propCache = {}
			local function propsFor(cn)
				local c = propCache[cn]
				if c then return c end
				c = {}
				local seen = {}
				local cls = API.Classes[cn]
				while cls do
					for _, p in ipairs(cls.Properties) do
						if not seen[p.Name] then
							seen[p.Name] = true
							local s, vt = p.Serialization, p.ValueType
							if s and s.CanSave and vt and not (p.Tags and p.Tags.Deprecated) then
								c[#c + 1] = p
							end
						end
					end
					cls = cls.Superclass
				end
				propCache[cn] = c
				return c
			end

			local function contentUrl(x)
				if typeof(x) == "Content" then
					local okU, u = pcall(function() return x.Uri end)
					return okU and type(u) == "string" and u or ""
				end
				return tostring(x or "")
			end

			local function ser(name, v, vt)
				local t = typeof(v)
				local head = ' name="' .. esc(name) .. '"'
				if t == "string" then
					if vt == "Content" or vt == "ContentId" then
						if v == "" then return "<Content" .. head .. "><null></null></Content>" end
						return "<Content" .. head .. "><url>" .. esc(v) .. "</url></Content>"
					end
					return "<string" .. head .. ">" .. esc(v) .. "</string>"
				elseif t == "Content" then
					local u = contentUrl(v)
					if u == "" then return "<Content" .. head .. "><null></null></Content>" end
					return "<Content" .. head .. "><url>" .. esc(u) .. "</url></Content>"
				elseif t == "boolean" then
					return "<bool" .. head .. ">" .. (v and "true" or "false") .. "</bool>"
				elseif t == "number" then
					local tag = (vt == "int" and "int") or (vt == "int64" and "int64") or (vt == "double" and "double") or "float"
					return "<" .. tag .. head .. ">" .. fnum(v) .. "</" .. tag .. ">"
				elseif t == "EnumItem" then
					return "<token" .. head .. ">" .. v.Value .. "</token>"
				elseif t == "BrickColor" then
					return "<int" .. head .. ">" .. v.Number .. "</int>"
				elseif t == "Vector3" then
					return "<Vector3" .. head .. "><X>" .. fnum(v.X) .. "</X><Y>" .. fnum(v.Y) .. "</Y><Z>" .. fnum(v.Z) .. "</Z></Vector3>"
				elseif t == "Vector2" then
					return "<Vector2" .. head .. "><X>" .. fnum(v.X) .. "</X><Y>" .. fnum(v.Y) .. "</Y></Vector2>"
				elseif t == "Color3" then
					return "<Color3" .. head .. "><R>" .. fnum(v.R) .. "</R><G>" .. fnum(v.G) .. "</G><B>" .. fnum(v.B) .. "</B></Color3>"
				elseif t == "CFrame" then
					local c = { v:GetComponents() }
					local tags = { "X", "Y", "Z", "R00", "R01", "R02", "R10", "R11", "R12", "R20", "R21", "R22" }
					local out = { "<CoordinateFrame" .. head .. ">" }
					for i, tg in ipairs(tags) do out[#out + 1] = "<" .. tg .. ">" .. fnum(c[i]) .. "</" .. tg .. ">" end
					out[#out + 1] = "</CoordinateFrame>"
					return table.concat(out)
				elseif t == "UDim2" then
					return "<UDim2" .. head .. "><XS>" .. fnum(v.X.Scale) .. "</XS><XO>" .. fnum(v.X.Offset) .. "</XO><YS>" .. fnum(v.Y.Scale) .. "</YS><YO>" .. fnum(v.Y.Offset) .. "</YO></UDim2>"
				elseif t == "UDim" then
					return "<UDim" .. head .. "><S>" .. fnum(v.Scale) .. "</S><O>" .. fnum(v.Offset) .. "</O></UDim>"
				elseif t == "Rect" then
					return "<Rect2D" .. head .. "><min><X>" .. fnum(v.Min.X) .. "</X><Y>" .. fnum(v.Min.Y) .. "</Y></min><max><X>" .. fnum(v.Max.X) .. "</X><Y>" .. fnum(v.Max.Y) .. "</Y></max></Rect2D>"
				elseif t == "NumberRange" then
					return "<NumberRange" .. head .. ">" .. fnum(v.Min) .. " " .. fnum(v.Max) .. " </NumberRange>"
				elseif t == "NumberSequence" then
					local out = {}
					for _, k in ipairs(v.Keypoints) do out[#out + 1] = fnum(k.Time) .. " " .. fnum(k.Value) .. " " .. fnum(k.Envelope) .. " " end
					return "<NumberSequence" .. head .. ">" .. table.concat(out) .. "</NumberSequence>"
				elseif t == "ColorSequence" then
					local out = {}
					for _, k in ipairs(v.Keypoints) do
						out[#out + 1] = fnum(k.Time) .. " " .. fnum(k.Value.R) .. " " .. fnum(k.Value.G) .. " " .. fnum(k.Value.B) .. " 0 "
					end
					return "<ColorSequence" .. head .. ">" .. table.concat(out) .. "</ColorSequence>"
				elseif t == "Font" then
					return "<Font" .. head .. "><Family><url>" .. esc(contentUrl(v.Family)) .. "</url></Family><Weight>" .. v.Weight.Value .. "</Weight><Style>" .. v.Style.Name .. "</Style></Font>"
				elseif t == "PhysicalProperties" then
					return "<PhysicalProperties" .. head .. "><CustomPhysics>true</CustomPhysics><Density>" .. fnum(v.Density) .. "</Density><Friction>" .. fnum(v.Friction)
						.. "</Friction><Elasticity>" .. fnum(v.Elasticity) .. "</Elasticity><FrictionWeight>" .. fnum(v.FrictionWeight) .. "</FrictionWeight><ElasticityWeight>"
						.. fnum(v.ElasticityWeight) .. "</ElasticityWeight></PhysicalProperties>"
				elseif t == "Instance" then
					return "<Ref" .. head .. ">" .. (ids[v] or "null") .. "</Ref>"
				end
				return nil
			end

			local skipTypes = {
				ProtectedString = true, BinaryString = true, SharedString = true, Color3uint8 = true, Tags = true, Attributes = true,
				UniqueId = true, SecurityCapabilities = true, QDir = true, QFont = true,
			}
			local ghp = env.gethiddenproperty or gethiddenproperty
			local function read(o, name)
				local ok, v = pcall(function() return o[name] end)
				if ok then return true, v end
				if ghp then
					local ok2, v2 = pcall(ghp, o, name)
					if ok2 then return true, v2 end
				end
				return false
			end
			local function propFrag(o, p)
				local vt = p.ValueType
				if skipTypes[vt.Name] or p.Name == "Source" then return nil end
				local ok, v = read(o, p.Name)
				if not ok then return nil end
				if v == nil then
					if vt.Category == "Class" then return '<Ref name="' .. esc(p.Name) .. '">null</Ref>' end
					return nil
				end
				local okS, s = pcall(ser, p.Name, v, vt.Name)
				if okS then return s end
				return nil
			end

			local ignoreDefaults = options.IgnoreDefaultProps ~= false
			local alwaysKeep = { Name = true, Size = true, CFrame = true, MeshId = true, TextureID = true, TextureId = true }
			local defCache = {}
			local function defaultsFor(cn)
				local d = defCache[cn]
				if d ~= nil then return d or nil end
				local okI, inst = pcall(Instance.new, cn)
				if not okI or typeof(inst) ~= "Instance" then
					defCache[cn] = false
					return nil
				end
				d = {}
				for _, p in ipairs(propsFor(cn)) do
					local s = propFrag(inst, p)
					if s then d[p.Name] = s end
				end
				pcall(inst.Destroy, inst)
				defCache[cn] = d
				return d
			end

			-- scripts
			local canDecompile = env.isdecompile and env.isdecompile()
			local timeout = tonumber(options.DecompileTimeout) or 10
			local function ignored(o)
				local list = options.DecompileIgnore
				if type(list) ~= "table" or #list == 0 then return false end
				local a = o
				while a and a ~= game do
					for _, nm in ipairs(list) do
						if nm ~= "" and (a.Name == nm or a.ClassName == nm) then return true end
					end
					a = a.Parent
				end
				return false
			end
			local function getSource(o)
				if options.Decompile ~= false and canDecompile and not ignored(o) and (not env.isViableDecompileScript or env.isViableDecompileScript(o)) then
					local result, done
					task.spawn(function()
						local ok, r = pcall(env.decompile, o)
						if ok and type(r) == "string" then result = r end
						done = true
					end)
					local t0 = os.clock()
					while not done and os.clock() - t0 < timeout do task.wait() end
					if result and result ~= "" then return result end
					return "-- could not decompile " .. o.Name .. (done and " (empty result)" or " (timed out)")
				end
				local ok, s = pcall(function() return o.Source end)
				if ok and type(s) == "string" and s ~= "" then return s end
				return "-- source not available for " .. o.Name
			end

			local function pivotFrag(cf)
				local c = { cf:GetComponents() }
				local tags = { "X", "Y", "Z", "R00", "R01", "R02", "R10", "R11", "R12", "R20", "R21", "R22" }
				local out = { '<OptionalCoordinateFrame name="WorldPivotData"><CFrame>' }
				for i, tg in ipairs(tags) do out[#out + 1] = "<" .. tg .. ">" .. fnum(c[i]) .. "</" .. tg .. ">" end
				out[#out + 1] = "</CFrame></OptionalCoordinateFrame>"
				return table.concat(out)
			end

			local function itemProps(o)
				local cn = o.ClassName
				local out = {}
				local defs = ignoreDefaults and defaultsFor(cn) or nil
				for _, p in ipairs(propsFor(cn)) do
					local s = propFrag(o, p)
					if s and not (defs and defs[p.Name] == s and not alwaysKeep[p.Name]) then
						out[#out + 1] = s
					end
				end
				pcall(function()
					if o:IsA("BasePart") and cn ~= "Terrain" then
						local c = o.Color
						local r, g, b = math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)
						out[#out + 1] = '<Color3uint8 name="Color3uint8">' .. string.format("%d", 4278190080 + r * 65536 + g * 256 + b) .. "</Color3uint8>"
					end
				end)
				pcall(function()
					if cn == "MeshPart" and ghp then
						local v = ghp(o, "InitialSize")
						if typeof(v) == "Vector3" then out[#out + 1] = ser("InitialSize", v, "Vector3") end
					end
				end)
				pcall(function()
					if o:IsA("Model") and not o.PrimaryPart then out[#out + 1] = pivotFrag(o.WorldPivot) end
				end)
				pcall(function()
					local tags = CollectionService:GetTags(o)
					if #tags > 0 then out[#out + 1] = '<BinaryString name="Tags">' .. b64(table.concat(tags, "\0")) .. "</BinaryString>" end
				end)
				if o:IsA("LuaSourceContainer") then
					out[#out + 1] = '<ProtectedString name="Source">' .. cdata(getSource(o)) .. "</ProtectedString>"
				end
				return out
			end

			-- output
			local useAppend = appendfile_ ~= nil
			local buf, bufLen, started, all = {}, 0, false, {}
			local function flush()
				if #buf == 0 then return end
				local chunk = table.concat(buf)
				buf, bufLen = {}, 0
				if not started then
					writefile_(fullPath, chunk)
					started = true
				else
					appendfile_(fullPath, chunk)
				end
			end
			local function emit(s)
				buf[#buf + 1] = s
				bufLen += #s
				if useAppend and bufLen > 750000 then flush() end
			end

			local done = 0
			local function writeItem(o)
				emit('<Item class="' .. esc(o.ClassName) .. '" referent="' .. ids[o] .. '"><Properties>')
				local okP, props = pcall(itemProps, o)
				if okP then
					for _, f in ipairs(props) do emit(f) end
				end
				emit("</Properties>")
				for _, c in ipairs(kids[o]) do writeItem(c) end
				emit("</Item>")
				done += 1
				if done % 150 == 0 then
					slice()
					if options.ProgressCallback then pcall(options.ProgressCallback, done, total) end
				end
			end

			emit('<roblox xmlns:xmime="http://www.w3.org/2005/05/xmlmime" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://www.roblox.com/roblox.xsd" version="4">')
			emit('<Meta name="ExplicitAutoJoints">true</Meta><External>null</External><External>nil</External>')
			for _, r in ipairs(roots) do writeItem(r) end
			emit("</roblox>")

			if useAppend then
				flush()
			else
				writefile_(fullPath, table.concat(buf))
			end
			if options.ProgressCallback then pcall(options.ProgressCallback, total, total) end
			return fullPath
		end

		env.saveinstance = (function()
			local native = saveinstance or (syn and syn.saveinstance) or (getgenv and getgenv().saveinstance)
			local libFn, libTried

			local function notify(text)
				pcall(function()
					game:GetService("StarterGui"):SetCore("SendNotification", { Title = "Save Instance", Text = text, Duration = 6 })
				end)
			end

			local function loadLib()
				if libFn then return libFn end
				if libTried then return nil end
				libTried = true
				local urls = {}
				local repoBase = getgenv and getgenv().InstanceX_Base
				if type(repoBase) == "string" then urls[1] = repoBase .. "modules/SaveInstance.lua" end
				for _, u in ipairs({
					"https://raw.githubusercontent.com/luau/SynSaveInstance/main/saveinstance.luau",
					"https://raw.githubusercontent.com/luau/UniversalSynSaveInstance/main/saveinstance.luau",
				}) do urls[#urls + 1] = u end
				for _, url in ipairs(urls) do
					local ok, res = pcall(function()
						local src
						local okG, body = pcall(function() return oldgame:HttpGet(url, true) end)
						if okG and type(body) == "string" and #body > 200 then
							src = body
						elseif env.request then
							local r = env.request({ Url = url, Method = "GET" })
							if r and type(r.Body) == "string" and #r.Body > 200 then src = r.Body end
						end
						if not src then error("no response") end
						local fn = loadstring(src, "saveinstance")
						return fn()
					end)
					if ok and type(res) == "function" then libFn = res break end
					if ok and type(res) == "table" and type(res.saveinstance) == "function" then libFn = res.saveinstance break end
				end
				return libFn
			end

			return function(obj, filepath, options)
				if game:GetService("RunService"):IsStudio() then error("Cannot run in Roblox Studio!") end
				options = options or {}
				local function withTarget()
					local o2 = {}
					for k, v in pairs(options) do
						if k ~= "ProgressCallback" then o2[k] = v end
					end
					o2.Object = obj
					o2.FilePath = filepath
					o2.FileName = filepath
					return o2
				end

				-- 1. the executor's own saveinstance (whole place only)
				if type(native) == "function" and obj == game then
					if pcall(native, withTarget()) or pcall(native, obj, filepath, options) then
						notify("Saved: " .. tostring(filepath))
						return filepath
					end
				end

				-- 2. the online library
				local lib = loadLib()
				if lib then
					local ok, err = pcall(lib, withTarget())
					if ok then
						notify("Saved: " .. tostring(filepath))
						return filepath
					end
					warn("[Instance X] online saveinstance failed (" .. tostring(err) .. "), using the built-in saver")
				end

				-- 3. built-in saver, no download needed
				local saved = env.builtinsave(obj, filepath, options)
				notify("Saved: " .. tostring(saved))
				return saved
			end
		end)()

		env.parsefile = function(name)
			return tostring(name):gsub("[*\\?:<>|]+", ""):sub(1, 175)
		end

		env.getupvalues = debug.getupvalues or getupvalues or getupvals
		env.getconstants = debug.getconstants or getconstants or getconsts
		env.islclosure = islclosure or is_l_closure
		env.checkcaller = checkcaller
		env.getreg = getreg
		env.getgc = getgc

		env.hookfunction = hookfunction
		env.hookmetamethod = hookmetamethod

		env.getscriptbytecode = getscriptbytecode
		env.setfflag = setfflag
		env.protectgui = protect_gui or (syn and syn.protect_gui)
		env.gethui = gethui
		env.setclipboard = setclipboard
		env.getnilinstances = getnilinstances or get_nil_instances
		env.getloadedmodules = getloadedmodules

		env.isViableDecompileScript = function(obj)
			if obj:IsA("ModuleScript") then
				return true
			elseif obj:IsA("LocalScript") and (obj.RunContext == Enum.RunContext.Client or obj.RunContext == Enum.RunContext.Legacy) then
				return true
			elseif obj:IsA("Script") and obj.RunContext == Enum.RunContext.Client then
				return true
			end
			return false
		end
		env.request = (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request

		env.isdecompile = function()
			return typeof(decompile) == "function" or typeof(getscriptbytecode) == "function" or false
		end

		env.isdecompilefallback = function()
			return typeof(decompile) ~= "function" or typeof(getscriptbytecode) == "function" or false
		end

		local AdvancedDecompilerCache
		pcall(function()
			AdvancedDecompilerCache = loadstring(game:HttpGet("https://raw.githubusercontent.com/"..Main.GitName.."/Advanced-Decompiler-V3/refs/heads/main/init.lua"))()
		end)

		local konstant_last_call = 0

		local function KonstantDec(...)
			local API = "http://api.plusgiant5.com"

			local request = env.request

			local function call(konstantType, scriptPath)
				local success, bytecode = pcall(env.getscriptbytecode, scriptPath)

				if (not success) then
					return `-- Failed to get script bytecode, error:\n\n--[[\n{bytecode}\n--]]`
				end

				local time_elapsed = os.clock() - konstant_last_call
				if time_elapsed <= .5 then
					task.wait(.5 - time_elapsed)
				end

				local httpResult = env.request({
					Url = API .. konstantType,
					Body = bytecode,
					Method = "POST",
					Headers = {
						["Content-Type"] = "text/plain"
					}
				})

				konstant_last_call = os.clock()

				if (httpResult.StatusCode ~= 200) then
					return `-- Error occurred while requesting Konstant API, error:\n\n--[[\n{httpResult.Body}\n--]]`
				else
					return httpResult.Body
				end
			end

			local function konstantDecompile(scriptPath)
				return call("/konstant/decompile", scriptPath)
			end

			return konstantDecompile(...)
		end
		local ADDec = AdvancedDecompilerCache or function() return "Failed to load Advanced Decompiler" end

		local function ShinyDec(script_instance)
			if typeof(crypt) ~= "table" then return "-- 'crypt' library is missing!" end
			local success, result = pcall(function()
				return game:HttpGet("http://127.0.0.1:"..tostring(Settings.Decompiler.ShinyDecompilerPort))
			end)
			if not success then return "-- Shiny decompiler is not active or port is wrong!" end

			local bytecode = getscriptbytecode(script_instance)
			local encoded = crypt.base64encode(bytecode)
			return env.request(
				{
					Url = "http://127.0.0.1:"..tostring(Settings.Decompiler.ShinyDecompilerPort).."/luau/decompile",
					Method = "POST",
					Body = encoded
				}
			).Body
		end
		env.decompile = function(...)
			if typeof(decompile) == "function" and Settings.Decompiler.PreferDecompilerFallback == false then
				return decompile(...)
			elseif typeof(getscriptbytecode) == "function" then
				local fallbackMode = Settings.Decompiler.DecompilerFallback

				if fallbackMode == "Konstant" then
					return KonstantDec(...)
				elseif fallbackMode == "AdvancedDecompiler" then
					return ADDec(...)
				elseif  fallbackMode == "Shiny" then
					return ShinyDec(...)
				end
			end
		end

		if identifyexecutor then
			Main.Executor = identifyexecutor()
		end

		Main.GuiHolder = Main.Elevated and service.CoreGui or plr:FindFirstChildOfClass("PlayerGui")

		setmetatable(env,nil)
	end

	Main.IncompatibleTest = function()
	end

	local function serialize(val)
		if typeof(val) == "Color3" then
			local serializedColor = {}
			serializedColor.R = val.R
			serializedColor.G = val.G
			serializedColor.B = val.B
			return serializedColor
		else
			return val
		end
	end

	local function deserialize(val)
		if typeof(val) == "table" then
			if val.R and val.G and val.B then
				return Color3.new(val.R, val.G, val.B)
			else
				return val
			end
		else
			return val
		end
	end

	Main.ExportSettings = function()
		local rawData = Settings or DefaultSettings

		local function recur(tbl)
			local newTbl = {}
			for i, v in pairs(tbl) do
				if typeof(v) == "table" then
					newTbl[i] = recur(v)
				else
					newTbl[i] = serialize(v)
				end
			end
			return newTbl
		end

		local serializedData = recur(rawData)

		local s, json = pcall(service.HttpService.JSONEncode, service.HttpService, serializedData)
		if s and json then
			return json
		end
	end

	Main.LoadSettings = function()
		local s, data = pcall(env.readfile or error, "DexPlusPlusSettings.json")
		if s and data and data ~= "" then

			local s, decoded = pcall(service.HttpService.JSONDecode, service.HttpService, data)
			if s and decoded then

				local function recur(tbl)
					local newTbl = {}
					for i, v in pairs(tbl) do
						if typeof(v) == "table" then
							newTbl[i] = deserialize(recur(v))
						else
							newTbl[i] = deserialize(v)
						end
					end
					return newTbl
				end

				local deserializedData = recur(decoded)
				for k, v in pairs(deserializedData) do
					Settings[k] = v
				end
			else
				warn("failed to decode settings json")
			end
		else
			Main.ResetSettings()
		end
	end

	Main.ResetSettings = function()
		local function recur(t,res)
			for set,val in pairs(t) do
				if type(val) == "table" and val._Recurse then
					if type(res[set]) ~= "table" then
						res[set] = {}
					end
					recur(val,res[set])
				else
					res[set] = val
				end
			end
			return res
		end
		recur(DefaultSettings,Settings)
	end

	Main.FetchAPI = function(callbackiflong, callbackiftoolong, XD)
		local downloaded = false
		local api,rawAPI
		if Main.Elevated then
			if Main.LocalDepsUpToDate() then
				local localAPI = Lib.ReadFile("dex/rbx_api.dat")
				if localAPI then
					rawAPI = localAPI
				else
					Main.DepsVersionData[1] = ""
				end
			end
			task.spawn(function()
				task.wait(10)
				if not downloaded and callbackiflong then callbackiflong() end

				task.wait(20)
				if not downloaded and callbackiftoolong then callbackiftoolong() end

				task.wait(30)
				if not downloaded and XD then XD() end
			end)
			if not rawAPI then
				local srcs = {}
				if Main.RobloxVersion then srcs[#srcs+1] = "http://setup.roblox.com/"..Main.RobloxVersion.."-API-Dump.json" end
				srcs[#srcs+1] = "https://raw.githubusercontent.com/MaximumADHD/Roblox-Client-Tracker/roblox/API-Dump.json"
				for _, u in ipairs(srcs) do
					local okA, r = pcall(function() return game:HttpGet(u) end)
					if okA and type(r) == "string" and #r > 1000 then rawAPI = r break end
				end
				if not rawAPI then error("Failed to download the Roblox API dump") end
			end
		else
			if script:FindFirstChild("API") then
				rawAPI = require(script.API)
			else
				error("NO API EXISTS")
			end
		end
		downloaded = true

		Main.RawAPI = rawAPI
		api = service.HttpService:JSONDecode(rawAPI)

		local classes,enums = {},{}
		local categoryOrder,seenCategories = {},{}

		local function insertAbove(t,item,aboveItem)
			local findPos = table.find(t,item)
			if not findPos then return end
			table.remove(t,findPos)

			local pos = table.find(t,aboveItem)
			if not pos then return end
			table.insert(t,pos,item)
		end

		for _,class in pairs(api.Classes) do
			local newClass = {}
			newClass.Name = class.Name
			newClass.Superclass = class.Superclass
			newClass.Properties = {}
			newClass.Functions = {}
			newClass.Events = {}
			newClass.Callbacks = {}
			newClass.Tags = {}

			if class.Tags then for c,tag in pairs(class.Tags) do newClass.Tags[tag] = true end end
			for __,member in pairs(class.Members) do
				local newMember = {}
				newMember.Name = member.Name
				newMember.Class = class.Name
				newMember.Security = member.Security
				newMember.Tags ={}
				if member.Tags then for c,tag in pairs(member.Tags) do newMember.Tags[tag] = true end end

				local mType = member.MemberType
				if mType == "Property" then
					local propCategory = member.Category or "Other"
					propCategory = propCategory:match("^%s*(.-)%s*$")
					if not seenCategories[propCategory] then
						categoryOrder[#categoryOrder+1] = propCategory
						seenCategories[propCategory] = true
					end
					newMember.ValueType = member.ValueType
					newMember.Category = propCategory
					newMember.Serialization = member.Serialization
					table.insert(newClass.Properties,newMember)
				elseif mType == "Function" then
					newMember.Parameters = {}
					newMember.ReturnType = member.ReturnType.Name
					for c,param in pairs(member.Parameters) do
						table.insert(newMember.Parameters,{Name = param.Name, Type = param.Type.Name})
					end
					table.insert(newClass.Functions,newMember)
				elseif mType == "Event" then
					newMember.Parameters = {}
					for c,param in pairs(member.Parameters) do
						table.insert(newMember.Parameters,{Name = param.Name, Type = param.Type.Name})
					end
					table.insert(newClass.Events,newMember)
				end
			end

			classes[class.Name] = newClass
		end

		for _,class in pairs(classes) do
			class.Superclass = classes[class.Superclass]
		end

		for _,enum in pairs(api.Enums) do
			local newEnum = {}
			newEnum.Name = enum.Name
			newEnum.Items = {}
			newEnum.Tags = {}

			if enum.Tags then for c,tag in pairs(enum.Tags) do newEnum.Tags[tag] = true end end
			for __,item in pairs(enum.Items) do
				local newItem = {}
				newItem.Name = item.Name
				newItem.Value = item.Value
				table.insert(newEnum.Items,newItem)
			end

			enums[enum.Name] = newEnum
		end

		local function getMember(class,member)
			if not classes[class] or not classes[class][member] then return end
			local result = {}

			local currentClass = classes[class]
			while currentClass do
				for _,entry in pairs(currentClass[member]) do
					result[#result+1] = entry
				end
				currentClass = currentClass.Superclass
			end

			table.sort(result,function(a,b) return a.Name < b.Name end)
			return result
		end

		insertAbove(categoryOrder,"Behavior","Tuning")
		insertAbove(categoryOrder,"Appearance","Data")
		insertAbove(categoryOrder,"Attachments","Axes")
		insertAbove(categoryOrder,"Cylinder","Slider")
		insertAbove(categoryOrder,"Localization","Jump Settings")
		insertAbove(categoryOrder,"Surface","Motion")
		insertAbove(categoryOrder,"Surface Inputs","Surface")
		insertAbove(categoryOrder,"Part","Surface Inputs")
		insertAbove(categoryOrder,"Assembly","Surface Inputs")
		insertAbove(categoryOrder,"Character","Controls")
		categoryOrder[#categoryOrder+1] = "Unscriptable"
		categoryOrder[#categoryOrder+1] = "Attributes"

		local categoryOrderMap = {}
		for i = 1,#categoryOrder do
			categoryOrderMap[categoryOrder[i]] = i
		end

		return {
			Classes = classes,
			Enums = enums,
			CategoryOrder = categoryOrderMap,
			GetMember = getMember
		}
	end

	Main.FetchRMD = function()
		local rawXML
		if Main.Elevated then
			if Main.LocalDepsUpToDate() then
				local localRMD = Lib.ReadFile("dex/rbx_rmd.dat")
				if localRMD then
					rawXML = localRMD
				else
					Main.DepsVersionData[1] = ""
				end
			end
			if not rawXML then
				for _, u in ipairs({
					"https://raw.githubusercontent.com/MaximumADHD/Roblox-Client-Tracker/roblox/ReflectionMetadata.xml",
					"https://raw.githubusercontent.com/CloneTrooper1019/Roblox-Client-Tracker/roblox/ReflectionMetadata.xml",
				}) do
					local okR, r = pcall(function() return game:HttpGet(u) end)
					if okR and type(r) == "string" and #r > 1000 then rawXML = r break end
				end
				if not rawXML then error("Failed to download Roblox reflection metadata") end
			end
		else
			if script:FindFirstChild("RMD") then
				rawXML = require(script.RMD)
			else
				error("NO RMD EXISTS")
			end
		end
		Main.RawRMD = rawXML
		local parsed = Lib.ParseXML(rawXML)
		local classList = parsed.children[1].children[1].children
		local enumList = parsed.children[1].children[2].children
		local propertyOrders = {}

		local classes,enums = {},{}
		for _,class in pairs(classList) do
			local className = ""
			for _,child in pairs(class.children) do
				if child.tag == "Properties" then
					local data = {Properties = {}, Functions = {}}
					local props = child.children
					for _,prop in pairs(props) do
						local name = prop.attrs.name
						name = name:sub(1,1):upper()..name:sub(2)
						data[name] = prop.children[1].text
					end
					className = data.Name
					classes[className] = data
				elseif child.attrs.class == "ReflectionMetadataProperties" then
					local members = child.children
					for _,member in pairs(members) do
						if member.attrs.class == "ReflectionMetadataMember" then
							local data = {}
							if member.children[1].tag == "Properties" then
								local props = member.children[1].children
								for _,prop in pairs(props) do
									if prop.attrs then
										local name = prop.attrs.name
										name = name:sub(1,1):upper()..name:sub(2)
										data[name] = prop.children[1].text
									end
								end
								if data.PropertyOrder then
									local orders = propertyOrders[className]
									if not orders then orders = {} propertyOrders[className] = orders end
									orders[data.Name] = tonumber(data.PropertyOrder)
								end
								classes[className].Properties[data.Name] = data
							end
						end
					end
				elseif child.attrs.class == "ReflectionMetadataFunctions" then
					local members = child.children
					for _,member in pairs(members) do
						if member.attrs.class == "ReflectionMetadataMember" then
							local data = {}
							if member.children[1].tag == "Properties" then
								local props = member.children[1].children
								for _,prop in pairs(props) do
									if prop.attrs then
										local name = prop.attrs.name
										name = name:sub(1,1):upper()..name:sub(2)
										data[name] = prop.children[1].text
									end
								end
								classes[className].Functions[data.Name] = data
							end
						end
					end
				end
			end
		end

		for _,enum in pairs(enumList) do
			local enumName = ""
			for _,child in pairs(enum.children) do
				if child.tag == "Properties" then
					local data = {Items = {}}
					local props = child.children
					for _,prop in pairs(props) do
						local name = prop.attrs.name
						name = name:sub(1,1):upper()..name:sub(2)
						data[name] = prop.children[1].text
					end
					enumName = data.Name
					enums[enumName] = data
				elseif child.attrs.class == "ReflectionMetadataEnumItem" then
					local data = {}
					if child.children[1].tag == "Properties" then
						local props = child.children[1].children
						for _,prop in pairs(props) do
							local name = prop.attrs.name
							name = name:sub(1,1):upper()..name:sub(2)
							data[name] = prop.children[1].text
						end
						enums[enumName].Items[data.Name] = data
					end
				end
			end
		end

		return {Classes = classes, Enums = enums, PropertyOrders = propertyOrders}
	end

