		openButton.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
				service.TweenService:Create(Main.MainGui.OpenButton,TweenInfo.new(0,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{BackgroundTransparency = Main.MainGuiOpen and 0 or 0.2}):Play()
			end
		end)

		local infoDexIntro, isInfoCD

		openButton.MainFrame.BottomFrame.Settings.MouseButton1Click:Connect(function()
			if not SettingsWindow.Window.Closed then
				SettingsWindow.Window:Hide()
			else
				SettingsWindow.Window:Show()
			end
		end)

		openButton.MainFrame.BottomFrame.Information.MouseButton1Click:Connect(function()
			local duration = 1
			local Infos = {
				"Revived/Upgraded by DuaKNo",
				"Dex ++ by Chillz",
				"Dex by Moons",
				"Toon (IY Dex and PRs)",
				"Cazan (3D Preview)",
			}

			if isInfoCD then return end
			isInfoCD = true
			if not infoDexIntro then
				infoDexIntro = Main.CreateIntro("Running")
				coroutine.wrap(function()
					while infoDexIntro and openButton.Parent ~= nil do
						for i,text in Infos do
							if not infoDexIntro or openButton.Parent == nil then break end
							infoDexIntro.SetProgress(text,(1 / #Infos) * i)
							task.wait(duration)
						end
					end
				end)()

				Lib.FastWait(1.5)
				isInfoCD = false
			else
				coroutine.wrap(function()
					infoDexIntro.Close()
					infoDexIntro = nil

					Lib.FastWait(1.5)
					isInfoCD = false
				end)()
			end
		end)

				Main.CreateApp({Name = "Explorer", IconMap = Main.LargeIcons, Icon = "Explorer", Open = true, Window = Explorer.Window})
		Main.CreateApp({Name = "Recorder", IconMap = Main.LargeIcons, Icon = "Watcher", Window = Main.RecorderWin})
		Main.CreateApp({Name = "Properties", IconMap = Main.LargeIcons, Icon = "Properties", Open = true, Window = Properties.Window})
		Main.CreateApp({Name = "Copy", IconMap = Main.LargeIcons, Icon = "ScriptEdit", Window = Main.CopyWin})
		Main.CreateApp({Name = "Tool Copy", IconMap = Main.LargeIcons, Icon = "Honey", Window = Main.ToolWin})
		Main.CreateApp({Name = "3D Viewer", IconMap = Main.LargeIcons, Icon = "Object", Window = ModelViewer.Window})
		local function actionApp(name, icon, fnName)
			local ctl
			ctl = Main.CreateApp({Name = name, IconMap = Main.LargeIcons, Icon = icon, OnClick = function(open)
				if open then
					local L = (getgenv or function() return _G end)().__RPP_Logger
					if L and L[fnName] then
						local ok, e = pcall(L[fnName])
						if not ok then warn("[Recorder ++] " .. name .. ": " .. tostring(e)) end
					else
						warn("[Recorder ++] the recorder is still loading")
					end
					task.defer(function() if ctl then ctl.Disable(true) end end)
				end
			end})
		end
		actionApp("VFX Editor", "Honey", "openVfx")
		actionApp("Anim Editor", "ScriptEdit", "openAnim")
		actionApp("Create Anim", "Watcher", "createAnim")
		actionApp("SFX Editor", "Executor", "openSfx")
		actionApp("FX Editor", "Object", "openFx")
		actionApp("FX Library", "Output", "openLib")
		actionApp("Saved", "Book", "openSaved")
		actionApp("NPC Hit", "Watcher", "openNpc")
		actionApp("Design Script", "Script_Viewer", "openDesign")

		local cptsOnMouseClick = nil
		local cptsCtl
		local AT = { mode = "single", pts = {}, up = 40, touch = false, token = 0, conns = {} }
		do
			local UIS = game:GetService("UserInputService")
			local Players = game:GetService("Players")
			local StarterGui = game:GetService("StarterGui")
			local GREEN, ORANGE = Color3.fromRGB(80, 220, 120), Color3.fromRGB(255, 170, 60)
			local viz, bar, info, ref
			local down

			local function notify(msg)
				pcall(function() StarterGui:SetCore("SendNotification", {Title = "Area select", Text = tostring(msg), Duration = 4}) end)
			end
			local function setInfo(t) if info then info.Text = t end end

			local function polygon()
				local p = AT.pts
				if #p < 2 then return nil end
				if #p == 2 then
					local x0, x1 = math.min(p[1].X, p[2].X), math.max(p[1].X, p[2].X)
					local z0, z1 = math.min(p[1].Z, p[2].Z), math.max(p[1].Z, p[2].Z)
					return { Vector2.new(x0, z0), Vector2.new(x1, z0), Vector2.new(x1, z1), Vector2.new(x0, z1) }
				end
				local poly = {}
				for i, v in ipairs(p) do poly[i] = Vector2.new(v.X, v.Z) end
				return poly
			end
			local function yRange()
				local lo, hi = math.huge, -math.huge
				for _, v in ipairs(AT.pts) do
					lo = math.min(lo, v.Y)
					hi = math.max(hi, v.Y)
				end
				return lo - 3, hi + AT.up
			end
			local function inPoly(x, z, poly)
				local inside = false
				local j = #poly
				for i = 1, #poly do
					local a, b = poly[i], poly[j]
					if (a.Y > z) ~= (b.Y > z) and x < (b.X - a.X) * (z - a.Y) / (b.Y - a.Y) + a.X then inside = not inside end
					j = i
				end
				return inside
			end
			local function cross(o, p, q) return (p.X - o.X) * (q.Y - o.Y) - (p.Y - o.Y) * (q.X - o.X) end
			local function segHit(a, b, c, d)
				local d1, d2 = cross(a, b, c), cross(a, b, d)
				local d3, d4 = cross(c, d, a), cross(c, d, b)
				return ((d1 > 0) ~= (d2 > 0)) and ((d3 > 0) ~= (d4 > 0))
			end
			local function rectHitsPoly(x0, z0, x1, z1, poly)
				for _, v in ipairs(poly) do
					if v.X >= x0 and v.X <= x1 and v.Y >= z0 and v.Y <= z1 then return true end
				end
				local c = { Vector2.new(x0, z0), Vector2.new(x1, z0), Vector2.new(x1, z1), Vector2.new(x0, z1) }
				for _, q in ipairs(c) do
					if inPoly(q.X, q.Y, poly) then return true end
				end
				for i = 1, #poly do
					local a, b = poly[i], poly[i % #poly + 1]
					for k = 1, 4 do
						if segHit(a, b, c[k], c[k % 4 + 1]) then return true end
					end
				end
				return false
			end
			local function isCharacterPart(p)
				local m = p:FindFirstAncestorOfClass("Model")
				while m do
					if Players:GetPlayerFromCharacter(m) then return true end
					m = m.Parent and m.Parent:FindFirstAncestorOfClass("Model")
				end
				return false
			end

			local function collect(done, uncancelable)
				AT.token += 1
				local my = AT.token
				local poly = polygon()
				if not poly then return done(nil) end
				local lo, hi = yRange()
				local minx, maxx, minz, maxz = math.huge, -math.huge, math.huge, -math.huge
				for _, v in ipairs(poly) do
					minx, maxx = math.min(minx, v.X), math.max(maxx, v.X)
					minz, maxz = math.min(minz, v.Y), math.max(maxz, v.Y)
				end
				local touch = AT.touch
				task.spawn(function()
					local set, list, n = {}, {}, 0
					for _, d in ipairs(workspace:GetDescendants()) do
						n += 1
						if n % 3000 == 0 then
							task.wait()
							if not uncancelable and AT.token ~= my then return end
						end
						if d:IsA("BasePart") and not d:IsA("Terrain") and not (viz and d:IsDescendantOf(viz)) then
							local pos = d.Position
							local ok = false
							if touch then
								local cf, s = d.CFrame, d.Size
								local r, u, l = cf.RightVector, cf.UpVector, cf.LookVector
								local hx = (math.abs(r.X) * s.X + math.abs(u.X) * s.Y + math.abs(l.X) * s.Z) / 2
								local hy = (math.abs(r.Y) * s.X + math.abs(u.Y) * s.Y + math.abs(l.Y) * s.Z) / 2
								local hz = (math.abs(r.Z) * s.X + math.abs(u.Z) * s.Y + math.abs(l.Z) * s.Z) / 2
								if pos.Y + hy >= lo and pos.Y - hy <= hi and pos.X + hx >= minx and pos.X - hx <= maxx and pos.Z + hz >= minz and pos.Z - hz <= maxz then
									ok = rectHitsPoly(pos.X - hx, pos.Z - hz, pos.X + hx, pos.Z + hz, poly)
								end
							else
								ok = pos.Y >= lo and pos.Y <= hi and inPoly(pos.X, pos.Z, poly)
							end
							if ok and not isCharacterPart(d) then
								set[d] = true
								list[#list + 1] = d
							end
						end
					end
					if not uncancelable and AT.token ~= my then return end
					done(list, set)
				end)
			end

			local function mkPart(size, cf, color, shape)
				local p = Instance.new("Part")
				p.Anchored = true
				p.CanCollide = false
				p.CanQuery = false
				p.CanTouch = false
				p.CastShadow = false
				p.Material = Enum.Material.Neon
				p.Color = color
				if shape then p.Shape = shape end
				p.Size = size
				p.CFrame = cf
				p.Parent = viz
			end
			local function seg(a, b)
				local len = (b - a).Magnitude
				if len < 0.05 then return end
				mkPart(Vector3.new(0.4, 0.4, len), CFrame.lookAt((a + b) / 2, b), GREEN)
			end
			local function draw()
				if not viz or not viz.Parent then
					viz = Instance.new("Folder")
					viz.Name = "RPP_AreaViz"
					viz.Parent = workspace
				end
				viz:ClearAllChildren()
				for _, v in ipairs(AT.pts) do
					mkPart(Vector3.new(1.6, 1.6, 1.6), CFrame.new(v), ORANGE, Enum.PartType.Ball)
				end
				local poly = polygon()
				if poly then
					local lo, hi = yRange()
					for i = 1, #poly do
						local a, b = poly[i], poly[i % #poly + 1]
						local a0, b0 = Vector3.new(a.X, lo, a.Y), Vector3.new(b.X, lo, b.Y)
						local a1, b1 = Vector3.new(a.X, hi, a.Y), Vector3.new(b.X, hi, b.Y)
						seg(a0, b0)
						seg(a1, b1)
						seg(a0, a1)
					end
				end
				pcall(function() Main.Mouse.TargetFilter = viz end)
			end
			local function updateButtons()
				if not ref then return end
				ref.mode.Text = AT.mode == "area" and "Mode: Area" or "Mode: Single"
				ref.mode.BackgroundColor3 = AT.mode == "area" and Color3.fromRGB(40, 120, 70) or Color3.fromRGB(11, 90, 175)
				ref.match.Text = AT.touch and "In: Touch" or "In: Center"
				ref.up.Text = "Up " .. AT.up
			end
			local function refresh()
				updateButtons()
				if AT.mode ~= "area" then
					if viz then viz:ClearAllChildren() end
					return setInfo("Single: tap a part to select it in the Explorer")
				end
				draw()
				if #AT.pts == 0 then
					setInfo("Area: tap spots in the world to mark the area")
				elseif #AT.pts == 1 then
					setInfo("1 point. Tap a second spot (3+ spots make a shape)")
				else
					setInfo("Counting parts...")
					collect(function(list)
						if list then setInfo(#list .. " parts inside, " .. #AT.pts .. " points. Copy or Save") end
					end)
				end
			end

			local function generate(cb)
				local C = (getgenv or function() return _G end)().__RPP_Copy
				if not (C and C.structCodeMulti) then return notify("The Copy module is not loaded yet") end
				if #AT.pts < 2 then return notify("Tap at least 2 spots first") end
				setInfo("Building code...")
				collect(function(list, set)
					if not list or #list == 0 then
						setInfo("Nothing inside that area")
						return notify("Nothing inside that area")
					end
					local roots = {}
					for _, p in ipairs(list) do
						local top, a = true, p.Parent
						while a and a ~= workspace do
							if set[a] then top = false break end
							a = a.Parent
						end
						if top then roots[#roots + 1] = p end
					end
					local ok, code, count, skipped = pcall(C.structCodeMulti, roots, "Area", {
						container = true, maxNodes = 4000, keep = function(o) return set[o] == true end,
					})
					if not ok or not code then
						setInfo("Could not build the code")
						return notify("Could not build the code: " .. tostring(code))
					end
					setInfo(count .. " instances ready" .. ((skipped or 0) > 0 and (", " .. skipped .. " left out (too many)") or ""))
					cb(code, count, skipped or 0)
				end, true)
			end

			local function addPoint()
				local mouse = Main.Mouse
				local t, hit = mouse.Target, mouse.Hit
				if not t or not hit then return notify("Tap on a part or the ground") end
				AT.pts[#AT.pts + 1] = hit.Position
				refresh()
			end

			local function hook()
				AT.conns[#AT.conns + 1] = UIS.InputBegan:Connect(function(input, gp)
					if gp or AT.mode ~= "area" then return end
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						down = { pos = Vector2.new(input.Position.X, input.Position.Y), t = os.clock() }
					end
				end)
				AT.conns[#AT.conns + 1] = UIS.InputEnded:Connect(function(input)
					if not down then return end
					if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
					local s = down
					down = nil
					if AT.mode ~= "area" then return end
					if (Vector2.new(input.Position.X, input.Position.Y) - s.pos).Magnitude > 14 or os.clock() - s.t > 0.7 then return end
					task.defer(addPoint)
				end)
			end

			local function buildBar()
				local gui = Instance.new("ScreenGui")
				gui.ResetOnSpawn = false
				gui.IgnoreGuiInset = true
				gui.DisplayOrder = Main.DisplayOrders.Menu
				Main.SecureGui(gui)
				AT.gui = gui
				local cam = workspace.CurrentCamera
				local W = math.min(380, (cam and cam.ViewportSize.X or 600) - 16)
				bar = Instance.new("Frame")
				bar.Name = "AreaBar"
				bar.AnchorPoint = Vector2.new(0.5, 0)
				bar.Position = UDim2.new(0.5, 0, 0, 78)
				bar.Size = UDim2.fromOffset(W, 94)
				bar.BackgroundColor3 = Color3.fromRGB(38, 38, 38)
				bar.BorderSizePixel = 0
				bar.Active = true
				bar.Parent = gui
				Instance.new("UICorner", bar).CornerRadius = UDim.new(0, 6)
				local st = Instance.new("UIStroke", bar)
				st.Color = Color3.fromRGB(70, 70, 70)
				info = Instance.new("TextLabel")
				info.BackgroundTransparency = 1
				info.Position = UDim2.new(0, 8, 0, 3)
				info.Size = UDim2.new(1, -16, 0, 20)
				info.Font = Enum.Font.SourceSansBold
				info.TextSize = 14
				info.TextColor3 = Color3.new(1, 1, 1)
				info.TextXAlignment = Enum.TextXAlignment.Left
				info.TextTruncate = Enum.TextTruncate.AtEnd
				info.Text = ""
				info.Parent = bar
				local function row(y, defs)
					local f = Instance.new("Frame")
					f.BackgroundTransparency = 1
					f.Position = UDim2.new(0, 4, 0, y)
					f.Size = UDim2.new(1, -8, 0, 30)
					f.Parent = bar
					local lay = Instance.new("UIListLayout")
					lay.FillDirection = Enum.FillDirection.Horizontal
					lay.Padding = UDim.new(0, 3)
					lay.SortOrder = Enum.SortOrder.LayoutOrder
					lay.Parent = f
					local total = 0
					for _, d in ipairs(defs) do total += (d.w or 1) end
					local made = {}
					for i, d in ipairs(defs) do
						local b = Instance.new("TextButton")
						b.LayoutOrder = i
						b.Size = UDim2.new((d.w or 1) / total, -3, 1, 0)
						b.BackgroundColor3 = d.color or Color3.fromRGB(62, 62, 62)
						b.BorderSizePixel = 0
						b.TextColor3 = Color3.new(1, 1, 1)
						b.Font = Enum.Font.SourceSans
						b.TextSize = 14
						b.Text = d.text
						b.Parent = f
						if d.fn then
							b.MouseButton1Click:Connect(function()
								local ok, err = pcall(d.fn, b)
								if not ok then notify("Error: " .. tostring(err)) end
							end)
						end
						made[d.key or i] = b
					end
					return made
				end
				local r1 = row(26, {
					{ key = "mode", text = "Mode: Single", w = 1.6, fn = function()
						AT.mode = AT.mode == "single" and "area" or "single"
						refresh()
					end },
					{ text = "Undo", w = 1, fn = function()
						table.remove(AT.pts)
						refresh()
					end },
					{ text = "Clear", w = 1, color = Color3.fromRGB(135, 50, 50), fn = function()
						AT.pts = {}
						refresh()
					end },
					{ key = "match", text = "In: Center", w = 1.4, fn = function()
						AT.touch = not AT.touch
						refresh()
					end },
					{ text = "X", w = 0.7, color = Color3.fromRGB(135, 50, 50), fn = function()
						if cptsCtl and cptsCtl.Disable then cptsCtl.Disable() else AT.stop() end
					end },
				})
				local function stepUp(d)
					AT.up = math.clamp(AT.up + d, 0, 1000)
					refresh()
				end
				local r2 = row(60, {
					{ text = "Up -", w = 0.9, fn = function() stepUp(AT.up > 100 and -50 or -10) end },
					{ key = "up", text = "Up 40", w = 1 },
					{ text = "Up +", w = 0.9, fn = function() stepUp(AT.up >= 100 and 50 or 10) end },
					{ text = "Copy", w = 1.2, color = Color3.fromRGB(40, 120, 70), fn = function()
						generate(function(code, count)
							local clip = (env and env.setclipboard) or setclipboard or toclipboard
							if clip then
								pcall(clip, code)
								notify("Copied " .. count .. " instances")
							else
								notify("This executor has no clipboard, use Save")
							end
						end)
					end },
					{ text = "Save", w = 1.2, color = Color3.fromRGB(11, 90, 175), fn = function()
						generate(function(code, count)
							Lib.SaveAsPrompt("Area_" .. count .. "_instances", function(filename)
								pcall(function() if env.makefolder then env.makefolder("dex") env.makefolder("dex/saved") end end)
								local ok, err = pcall(env.writefile, "dex/saved/" .. filename, code)
								notify(ok and ("Saved to workspace/dex/saved/" .. filename) or ("Could not save: " .. tostring(err)))
							end, "lua")
						end)
					end },
				})
				ref = { mode = r1.mode, match = r1.match, up = r2.up }
			end

			function AT.stop()
				for _, c in ipairs(AT.conns) do pcall(function() c:Disconnect() end) end
				AT.conns = {}
				if cptsOnMouseClick then
					cptsOnMouseClick:Disconnect()
					cptsOnMouseClick = nil
				end
				AT.token += 1
				if AT.gui then pcall(function() AT.gui:Destroy() end) AT.gui = nil end
				if viz then pcall(function() viz:Destroy() end) viz = nil end
				bar, info, ref, down = nil, nil, nil, nil
				pcall(function() Main.Mouse.TargetFilter = nil end)
				AT.pts = {}
			end

			function AT.start()
				AT.stop()
				buildBar()
				hook()
				local mouse = Main.Mouse
				cptsOnMouseClick = mouse.Button1Down:Connect(function()
					if AT.mode ~= "single" then return end
					pcall(function()
						local object = mouse.Target
						if nodes[object] then
							selection:Set(nodes[object])
							Explorer.ViewNode(nodes[object])
						end
					end)
				end)
				refresh()
			end
		end
		cptsCtl = Main.CreateApp({Name = "Click part to select", IconMap = Explorer.ClassIcons, Icon = "SelectionBox", OnClick = function(callback)
			if callback then AT.start() else AT.stop() end
		end})

		do
			local UIS = game:GetService("UserInputService")
			local StarterGui = game:GetService("StarterGui")
			local OE = { undo = {}, conns = {} }
			Main.ObjEdit = OE
			local gui, frame, status, boxes, togs, target
			local armed = false

			local function notify(msg)
				pcall(function() StarterGui:SetCore("SendNotification", {Title = "Obj Editor", Text = tostring(msg), Duration = 3}) end)
			end
			local function say(t) if status then status.Text = tostring(t) end end
			local function isObj(o)
				return typeof(o) == "Instance" and o.Parent ~= nil and (o:IsA("BasePart") or o:IsA("Model") or o:IsA("Tool") or o:IsA("Folder") or o:IsA("Accoutrement"))
			end
			local function partsOf(o)
				local l = {}
				if o:IsA("BasePart") then l[1] = o end
				for _, d in ipairs(o:GetDescendants()) do
					if d:IsA("BasePart") then l[#l + 1] = d end
				end
				return l
			end
			local function pivotOf(o)
				if o:IsA("BasePart") then return o.CFrame end
				if o:IsA("Model") then return o:GetPivot() end
				local l = partsOf(o)
				if #l == 0 then return nil end
				local sum = Vector3.new(0, 0, 0)
				for _, p in ipairs(l) do sum = sum + p.Position end
				return CFrame.new(sum / #l)
			end
			local function setPivot(o, cf)
				if o:IsA("BasePart") then o.CFrame = cf return end
				if o:IsA("Model") then o:PivotTo(cf) return end
				local cur = pivotOf(o)
				if not cur then return end
				local d = cf * cur:Inverse()
				for _, p in ipairs(partsOf(o)) do p.CFrame = d * p.CFrame end
			end
			local function snapshot(o)
				local snap = {}
				for _, p in ipairs(partsOf(o)) do
					snap[#snap + 1] = { p, p.CFrame, p.Size, p.Color, p.Material, p.Transparency, p.Anchored, p.CanCollide, p.CanTouch, p.CanQuery, p.Massless, p.CastShadow }
				end
				return { o, o.Name, snap }
			end
			local function restore(s)
				pcall(function() s[1].Name = s[2] end)
				for _, e in ipairs(s[3]) do
					local p = e[1]
					pcall(function()
						p.Size = e[3]
						p.CFrame = e[2]
						p.Color = e[4]
						p.Material = e[5]
						p.Transparency = e[6]
						p.Anchored = e[7]
						p.CanCollide = e[8]
						p.CanTouch = e[9]
						p.CanQuery = e[10]
						p.Massless = e[11]
						p.CastShadow = e[12]
					end)
				end
			end
			local function nums(text)
				local out = {}
				for n in tostring(text):gmatch("[%-%d%.eE]+") do
					local v = tonumber(n)
					if v then out[#out + 1] = v end
				end
				return out
			end
			local function fmt(n) return (string.format("%.3f", n):gsub("%.?0+$", "")) end
			local function v3(v) return fmt(v.X) .. ", " .. fmt(v.Y) .. ", " .. fmt(v.Z) end

			function OE.refresh()
				if not boxes then return end
				if not isObj(target) then
					for _, b in pairs(boxes) do b.Text = "" end
					return say("Nothing picked. Select a part or model in the Explorer, then Use selection")
				end
				local o = target
				boxes.name.Text = o.Name
				local first = partsOf(o)[1]
				if first then
					boxes.color.Text = string.format("%d, %d, %d", math.floor(first.Color.R * 255 + 0.5), math.floor(first.Color.G * 255 + 0.5), math.floor(first.Color.B * 255 + 0.5))
					boxes.transp.Text = fmt(first.Transparency)
					boxes.mat.Text = first.Material.Name
					boxes.size.Text = o:IsA("BasePart") and v3(first.Size) or "(use Scale)"
					for k, b in pairs(togs) do
						local on = first[k]
						b.Text = k .. ": " .. (on and "on" or "off")
						b.BackgroundColor3 = on and Color3.fromRGB(40, 120, 70) or Color3.fromRGB(62, 62, 62)
					end
				end
				local cf = pivotOf(o)
				if cf then
					boxes.pos.Text = v3(cf.Position)
					local rx, ry, rz = cf:ToEulerAnglesXYZ()
					boxes.rot.Text = fmt(math.deg(rx)) .. ", " .. fmt(math.deg(ry)) .. ", " .. fmt(math.deg(rz))
				end
				boxes.scale.Text = "1"
				say(o.ClassName .. ": " .. #partsOf(o) .. " parts")
			end

			local function change(fn)
				if not isObj(target) then return say("Nothing picked") end
				local s = snapshot(target)
				local ok, err = pcall(fn, target)
				if ok then
					OE.undo[#OE.undo + 1] = s
					if #OE.undo > 40 then table.remove(OE.undo, 1) end
				else
					say("Could not apply: " .. tostring(err))
				end
				OE.refresh()
			end
			local function eachPart(o, fn)
				for _, p in ipairs(partsOf(o)) do pcall(fn, p) end
			end

			local function pick()
				local sel = selection.List
				for i = 1, #sel do
					local o = sel[i].Obj
					if isObj(o) then
						target = o
						OE.refresh()
						return true
					end
				end
				say("Select a part or model in the Explorer first")
				return false
			end

			local function build()
				if gui then return end
				gui = Instance.new("ScreenGui")
				gui.ResetOnSpawn = false
				gui.IgnoreGuiInset = true
				gui.DisplayOrder = Main.DisplayOrders.Menu
				Main.SecureGui(gui)
				local cam = workspace.CurrentCamera
				local vp = cam and cam.ViewportSize or Vector2.new(800, 600)
				local W, H = math.min(310, vp.X - 16), math.min(400, vp.Y - 60)
				frame = Instance.new("Frame")
				frame.Position = UDim2.fromOffset(8, 60)
				frame.Size = UDim2.fromOffset(W, H)
				frame.BackgroundColor3 = Color3.fromRGB(38, 38, 38)
				frame.BorderSizePixel = 0
				frame.Active = true
				frame.Parent = gui
				Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 6)
				local st = Instance.new("UIStroke", frame)
				st.Color = Color3.fromRGB(70, 70, 70)

				local title = Instance.new("TextLabel")
				title.Size = UDim2.new(1, -34, 0, 26)
				title.BackgroundColor3 = Color3.fromRGB(52, 52, 52)
				title.BorderSizePixel = 0
				title.Font = Enum.Font.SourceSansBold
				title.TextSize = 15
				title.TextColor3 = Color3.new(1, 1, 1)
				title.Text = "  Obj Editor (drag here)"
				title.TextXAlignment = Enum.TextXAlignment.Left
				title.Active = true
				title.Parent = frame
				local close = Instance.new("TextButton")
				close.Position = UDim2.new(1, -32, 0, 0)
				close.Size = UDim2.fromOffset(32, 26)
				close.BackgroundColor3 = Color3.fromRGB(135, 50, 50)
				close.BorderSizePixel = 0
				close.Font = Enum.Font.SourceSansBold
				close.TextSize = 15
				close.TextColor3 = Color3.new(1, 1, 1)
				close.Text = "X"
				close.Parent = frame
				close.MouseButton1Click:Connect(function() OE.close() end)

				local dragging, startIn, startPos = false, nil, nil
				title.InputBegan:Connect(function(i)
					if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
						dragging, startIn, startPos = true, i.Position, frame.Position
					end
				end)
				OE.conns[#OE.conns + 1] = UIS.InputChanged:Connect(function(i)
					if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
						local d = i.Position - startIn
						frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
					end
				end)
				OE.conns[#OE.conns + 1] = UIS.InputEnded:Connect(function(i)
					if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = false end
				end)

				status = Instance.new("TextLabel")
				status.Position = UDim2.new(0, 6, 1, -20)
				status.Size = UDim2.new(1, -12, 0, 18)
				status.BackgroundTransparency = 1
				status.Font = Enum.Font.SourceSans
				status.TextSize = 13
				status.TextColor3 = Color3.fromRGB(185, 185, 185)
				status.TextXAlignment = Enum.TextXAlignment.Left
				status.TextTruncate = Enum.TextTruncate.AtEnd
				status.Text = ""
				status.Parent = frame

				local scroll = Instance.new("ScrollingFrame")
				scroll.Position = UDim2.new(0, 4, 0, 30)
				scroll.Size = UDim2.new(1, -8, 1, -52)
				scroll.BackgroundTransparency = 1
				scroll.BorderSizePixel = 0
				scroll.ScrollBarThickness = 5
				scroll.CanvasSize = UDim2.new()
				scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
				scroll.Parent = frame
				local lay = Instance.new("UIListLayout")
				lay.Padding = UDim.new(0, 3)
				lay.SortOrder = Enum.SortOrder.LayoutOrder
				lay.Parent = scroll
				local order = 0

				boxes, togs = {}, {}
				local function field(key, text, onApply)
					order += 1
					local row = Instance.new("Frame")
					row.Size = UDim2.new(1, -6, 0, 28)
					row.BackgroundTransparency = 1
					row.LayoutOrder = order
					row.Parent = scroll
					local l = Instance.new("TextLabel")
					l.Size = UDim2.new(0.28, 0, 1, 0)
					l.BackgroundTransparency = 1
					l.Font = Enum.Font.SourceSans
					l.TextSize = 14
					l.TextColor3 = Color3.new(1, 1, 1)
					l.TextXAlignment = Enum.TextXAlignment.Left
					l.Text = text
					l.Parent = row
					local b = Instance.new("TextBox")
					b.Position = UDim2.new(0.28, 0, 0, 0)
					b.Size = UDim2.new(0.72, 0, 1, 0)
					b.BackgroundColor3 = Color3.fromRGB(28, 28, 28)
					b.BorderSizePixel = 0
					b.Font = Enum.Font.SourceSans
					b.TextSize = 14
					b.TextColor3 = Color3.new(1, 1, 1)
					b.ClearTextOnFocus = false
					b.Text = ""
					b.Parent = row
					b.FocusLost:Connect(function()
						local ok, err = pcall(onApply, b.Text)
						if not ok then say("Error: " .. tostring(err)) OE.refresh() end
					end)
					boxes[key] = b
				end
				local function buttons(defs)
					order += 1
					local row = Instance.new("Frame")
					row.Size = UDim2.new(1, -6, 0, 28)
					row.BackgroundTransparency = 1
					row.LayoutOrder = order
					row.Parent = scroll
					local rl = Instance.new("UIListLayout")
					rl.FillDirection = Enum.FillDirection.Horizontal
					rl.Padding = UDim.new(0, 3)
					rl.Parent = row
					local made = {}
					for i, d in ipairs(defs) do
						local b = Instance.new("TextButton")
						b.LayoutOrder = i
						b.Size = UDim2.new(1 / #defs, -3, 1, 0)
						b.BackgroundColor3 = d.color or Color3.fromRGB(62, 62, 62)
						b.BorderSizePixel = 0
						b.Font = Enum.Font.SourceSans
						b.TextSize = 13
						b.TextColor3 = Color3.new(1, 1, 1)
						b.Text = d.text
						b.Parent = row
						b.MouseButton1Click:Connect(function()
							local ok, err = pcall(d.fn, b)
							if not ok then say("Error: " .. tostring(err)) end
						end)
						made[i] = b
					end
					return made
				end

				field("name", "Name", function(t) change(function(o) o.Name = t end) end)
				field("color", "Color r,g,b", function(t)
					local n = nums(t)
					if #n < 3 then return say("Use three numbers 0-255") end
					local c = Color3.fromRGB(math.clamp(n[1], 0, 255), math.clamp(n[2], 0, 255), math.clamp(n[3], 0, 255))
					change(function(o) eachPart(o, function(p) p.Color = c end) end)
				end)
				field("transp", "Transparency", function(t)
					local n = tonumber(t)
					if not n then return say("Use a number 0 to 1") end
					change(function(o) eachPart(o, function(p) p.Transparency = math.clamp(n, 0, 1) end) end)
				end)
				field("mat", "Material", function(t)
					local m = Enum.Material[(t:gsub("%s", ""))]
					if not m then return say("Unknown material, e.g. Neon, Wood, Metal, Glass") end
					change(function(o) eachPart(o, function(p) p.Material = m end) end)
				end)
				field("size", "Size x,y,z", function(t)
					if not (target and target:IsA("BasePart")) then return say("Size works on one part. Use Scale for models") end
					local n = nums(t)
					if #n < 3 then return say("Use three numbers") end
					change(function(o) o.Size = Vector3.new(n[1], n[2], n[3]) end)
				end)
				field("pos", "Position", function(t)
					local n = nums(t)
					if #n < 3 then return say("Use three numbers") end
					change(function(o)
						local cur = pivotOf(o)
						setPivot(o, CFrame.new(n[1], n[2], n[3]) * (cur - cur.Position))
					end)
				end)
				field("rot", "Rotation deg", function(t)
					local n = nums(t)
					if #n < 3 then return say("Use three numbers (degrees)") end
					change(function(o)
						local cur = pivotOf(o)
						setPivot(o, CFrame.new(cur.Position) * CFrame.Angles(math.rad(n[1]), math.rad(n[2]), math.rad(n[3])))
					end)
				end)
				field("scale", "Scale x", function(t)
					local n = tonumber(t)
					if not n or n <= 0 then return say("Use a number above 0, like 1.5") end
					change(function(o)
						if o:IsA("Model") then
							o:ScaleTo(o:GetScale() * n)
						elseif o:IsA("BasePart") then
							o.Size = o.Size * n
						else
							local c = pivotOf(o).Position
							for _, p in ipairs(partsOf(o)) do
								p.Size = p.Size * n
								p.CFrame = CFrame.new(c + (p.Position - c) * n) * (p.CFrame - p.Position)
							end
						end
					end)
				end)
				for _, key in ipairs({ "Anchored", "CanCollide", "CanTouch", "CanQuery", "Massless", "CastShadow" }) do
					togs[key] = nil
				end
				local tdefs = {}
				local function tog(key)
					return { text = key, fn = function(b)
						if not isObj(target) then return say("Nothing picked") end
						local first = partsOf(target)[1]
						if not first then return end
						local nv = not first[key]
						change(function(o) eachPart(o, function(p) p[key] = nv end) end)
					end }
				end
				local r1 = buttons({ tog("Anchored"), tog("CanCollide"), tog("CanTouch") })
				togs.Anchored, togs.CanCollide, togs.CanTouch = r1[1], r1[2], r1[3]
				local r2 = buttons({ tog("CanQuery"), tog("Massless"), tog("CastShadow") })
				togs.CanQuery, togs.Massless, togs.CastShadow = r2[1], r2[2], r2[3]
				buttons({
					{ text = "Use selection", color = Color3.fromRGB(11, 90, 175), fn = function() pick() end },
					{ text = "Undo", fn = function()
						local s = table.remove(OE.undo)
						if not s then return say("Nothing to undo") end
						restore(s)
						OE.refresh()
					end },
					{ text = "Clone", fn = function()
						if not isObj(target) then return say("Nothing picked") end
						local was = target.Archivable
						target.Archivable = true
						local c = target:Clone()
						target.Archivable = was
						if not c then return say("Could not clone that") end
						c.Parent = target.Parent
						setPivot(c, pivotOf(target) + Vector3.new(5, 0, 0))
						target = c
						OE.undo = {}
						OE.refresh()
					end },
				})
				buttons({
					{ text = "Copy code", color = Color3.fromRGB(40, 120, 70), fn = function()
						if not isObj(target) then return say("Nothing picked") end
						local C = (getgenv or function() return _G end)().__RPP_Copy
						if not (C and C.structCodeMulti) then return say("The Copy module is not loaded") end
						local code = C.structCodeMulti({ target }, target.Name)
						local clip = (env and env.setclipboard) or setclipboard or toclipboard
						if code and clip then
							pcall(clip, code)
							notify("Copied the code of " .. target.Name)
						else
							say(code and "No clipboard in this executor, use Save code" or "Could not build the code")
						end
					end },
					{ text = "Save code", color = Color3.fromRGB(11, 90, 175), fn = function()
						if not isObj(target) then return say("Nothing picked") end
						local C = (getgenv or function() return _G end)().__RPP_Copy
						if not (C and C.structCodeMulti) then return say("The Copy module is not loaded") end
						local code = C.structCodeMulti({ target }, target.Name)
						if not code then return say("Could not build the code") end
						local default = (target.ClassName .. "_" .. target.Name):gsub("[^%w_%-]", "_")
						Lib.SaveAsPrompt(default, function(filename)
							pcall(function() if env.makefolder then env.makefolder("dex") env.makefolder("dex/saved") end end)
							local ok, err = pcall(env.writefile, "dex/saved/" .. filename, code)
							notify(ok and ("Saved to workspace/dex/saved/" .. filename) or ("Could not save: " .. tostring(err)))
						end, "lua")
					end },
					{ text = "Delete", color = Color3.fromRGB(135, 50, 50), fn = function(b)
						if not isObj(target) then return say("Nothing picked") end
						if not armed then
							armed = true
							b.Text = "Sure?"
							task.delay(2.5, function()
								armed = false
								if b.Parent then b.Text = "Delete" end
							end)
							return
						end
						armed = false
						b.Text = "Delete"
						local o = target
						target = nil
						pcall(function() o:Destroy() end)
						OE.undo = {}
						OE.refresh()
						say("Deleted")
					end },
				})
			end

			function OE.close()
				for _, c in ipairs(OE.conns) do pcall(function() c:Disconnect() end) end
				OE.conns = {}
				if gui then pcall(function() gui:Destroy() end) end
				gui, frame, status, boxes, togs = nil, nil, nil, nil, nil
			end
			function OE.open()
				OE.close()
				build()
				if not pick() then target = nil end
			end
		end
		local oeCtl
		oeCtl = Main.CreateApp({Name = "Obj Editor", IconMap = Main.LargeIcons, Icon = "Object", OnClick = function(open)
			if open then
				local ok, e = pcall(Main.ObjEdit.open)
				if not ok then warn("[Recorder ++] Obj Editor: " .. tostring(e)) end
				task.defer(function() if oeCtl then oeCtl.Disable(true) end end)
			end
		end})

		Main.CreateApp({Name = "Notepad", IconMap = Main.LargeIcons, Icon = "Script_Viewer", Window = ScriptViewer.Window})

		Main.CreateApp({Name = "Console", IconMap = Main.LargeIcons, Icon = "Executor", Window = Console.Window})

		Main.CreateApp({Name = "Save Instance", IconMap = Main.LargeIcons, Icon = "Book", Window = SaveInstance.Window})

		for _, loadedplugin in pairs(Main.Plugins) do
			Main.CreateApp({Name = loadedplugin.PluginData.FriendlyName, IconMap = Explorer.ClassIcons, Icon = "Attachment", Window = loadedplugin.Window})
		end

		Lib.ShowGui(gui)
	end

	Main.Credit = function()
		local StarterGui = game:GetService("StarterGui")
		local icon
		pcall(function()
			local id = game:GetService("Players"):GetUserIdFromNameAsync("DuaKNo")
			icon = "rbxthumb://type=AvatarHeadShot&id=" .. id .. "&w=150&h=150"
		end)
		local list = {
			{ Title = "Instance X: Dex + copy suite", Text = "By DuaKNo", Icon = icon },
			{ Title = "Follow on Instagram", Text = "me_duakno" },
			{ Title = "Join Discord server for more", Text = "discord.gg/empgqd5qpq" },
		}
		for _, n in ipairs(list) do
			n.Duration = 6
			for _ = 1, 10 do
				local ok = pcall(function() StarterGui:SetCore("SendNotification", n) end)
				if ok then break end
				task.wait(0.3)
			end
			task.wait(0.4)
		end
	end

	Main.SetupFilesystem = function()
		if not env.writefile or not env.makefolder then return end

		local writefile,makefolder = env.writefile,env.makefolder

		makefolder("dex")
		makefolder("dex/assets")
		makefolder("dex/saved")
		makefolder("dex/plugins")
		makefolder("dex/ModuleCache")
	end

	Main.SaveCurrentSettings = function()
		if writefile then
			writefile("DexPlusPlusSettings.json", Main.ExportSettings())
		end
	end

	Main.LocalDepsUpToDate = function()
		return Main.DepsVersionData and Main.ClientVersion == Main.DepsVersionData[1]
	end

	Main.Init = function()
		Main.Elevated = pcall(function() local a = game:GetService("CoreGui"):GetFullName() end)

		if isfile and not isfile("DexPlusPlusSettings.json") then
			Main.SaveCurrentSettings()
		end

		Main.InitEnv()
		Main.LoadSettings()
		pcall(function()
			if isfile and readfile and isfile("RecorderPP_DexTheme.json") then
				local d = game:GetService("HttpService"):JSONDecode(readfile("RecorderPP_DexTheme.json"))
				for k, v in pairs(d) do
					if typeof(Settings.Theme[k]) == "Color3" and type(v) == "table" then Settings.Theme[k] = Color3.new(v[1], v[2], v[3]) end
				end
			end
		end)

		Main.SetupFilesystem()

		local intro = Main.CreateIntro("Initializing Library")
		Lib = Main.LoadModule("Lib")
		Lib.FastWait()

		Main.IncompatibleTest()

		Main.MiscIcons = Lib.IconMap.new("rbxassetid://6511490623",256,256,16,16)
		Main.MiscIcons:SetDict({
			Reference = 0,             Cut = 1,                         Cut_Disabled = 2,      Copy = 3,               Copy_Disabled = 4,    Paste = 5,                Paste_Disabled = 6,
			Delete = 7,                Delete_Disabled = 8,             Group = 9,             Group_Disabled = 10,    Ungroup = 11,         Ungroup_Disabled = 12,    TeleportTo = 13,
			Rename = 14,               JumpToParent = 15,               ExploreData = 16,      Save = 17,              CallFunction = 18,    CallRemote = 19,          Undo = 20,
			Undo_Disabled = 21,        Redo = 22,                       Redo_Disabled = 23,    Expand_Over = 24,       Expand = 25,          Collapse_Over = 26,       Collapse = 27,
			SelectChildren = 28,       SelectChildren_Disabled = 29,    InsertObject = 30,     ViewScript = 31,        AddStar = 32,         RemoveStar = 33,          Script_Disabled = 34,
			LocalScript_Disabled = 35, Play = 36,                       Pause = 37,            Rename_Disabled = 38,   Empty = 1000
		})
		Main.LargeIcons = Lib.IconMap.new("rbxassetid://129589545519436",256,256,32,32)
		Main.LargeIcons:SetDict({
			Explorer = 0, Properties = 1, Script_Viewer = 2, Watcher = 3, Output = 4, ScriptEdit = 5, Book = 6, Executor = 7, Object = 8, Honey = 9
		})

		intro.SetProgress("Fetching Roblox Version",0.3)
		if Main.Elevated then
			local fileVer = Lib.ReadFile("dex/deps_version.dat")
			Main.ClientVersion = Version()
			if fileVer then
				Main.DepsVersionData = string.split(fileVer,"\n")
				if Main.LocalDepsUpToDate() then
					Main.RobloxVersion = Main.DepsVersionData[2]
				end
			end

			if not Main.RobloxVersion then
				local okV, verStr = pcall(function() return oldgame:HttpGet("https://clientsettings.roblox.com/v2/client-version/WindowsStudio64/channel/LIVE") end)
				if okV and type(verStr) == "string" then Main.RobloxVersion = verStr:match("(version%-[%w]+)") end
			end
		end

		intro.SetProgress("Fetching API",0.35)
		API = Main.FetchAPI(
			function()
				intro.SetProgress("Fetching API, Please Wait.",0.4)
			end,
			function()
				intro.SetProgress("Fetching API, Please Wait Due To Huge API File To Download.",0.45)
			end,
			function()
				intro.SetProgress("Fetching API, LOL STILL DOWNlOADING? bad wifi xD",0.475)
			end
		)
		Lib.FastWait()
		intro.SetProgress("Fetching RMD",0.5)
		RMD = Main.FetchRMD()
		Lib.FastWait()

		if Main.Elevated and env.writefile and not Main.LocalDepsUpToDate() then
			env.writefile("dex/deps_version.dat",Main.ClientVersion.."\n"..Main.RobloxVersion)
			env.writefile("dex/rbx_api.dat",Main.RawAPI)
			env.writefile("dex/rbx_rmd.dat",Main.RawRMD)
		end

		intro.SetProgress("Loading Modules",0.75)
		Main.AppControls.Lib.InitDeps(Main.GetInitDeps())
		Main.LoadModules()
		Lib.FastWait()

		intro.SetProgress("Initializing Modules",0.8)
		Explorer.Init()
		Properties.Init()
		ScriptViewer.Init()
		Console.Init()
		SaveInstance.Init()
		ModelViewer.Init()
		SettingsWindow.Init()
		do
			local function makeWin(title, w, h)
				local win = Lib.Window.new()
				win:SetTitle(title)
				win:Resize(w, h)
				return win
			end
			Main.RecorderWin = makeWin("Recorder ++", 300, 360)
			Main.CopyWin = makeWin("Copy", 300, 320)
			Main.ToolWin = makeWin("Tool Copy", 420, 340)
		end

		if env.readfile and listfiles then
			if #listfiles("dex/plugins") > 0 then
				intro.SetProgress("Loading Plugin Files",0.8)
				for _, pluginDir in pairs(listfiles("dex/plugins")) do
					local moduleData = Main.LoadPluginFile(pluginDir)
					moduleData.PluginData = moduleData.PluginData or {}

					moduleData.Init()

					local pluginFriendlyName = moduleData.PluginData.FriendlyName or moduleData.Window.GuiElems.Title.Text or "Unnamed Plugin"
					local pluginName = moduleData.PluginData.Name or moduleData.Window.GuiElems.Title.Text:gsub(" ", "") or "unnamedPlugin"

					intro.SetProgress("Initializing Plugin: ".. pluginFriendlyName,0.9)

					moduleData.PluginData.Name = pluginName
					moduleData.PluginData.FriendlyName = pluginFriendlyName

					table.insert(Main.Plugins, moduleData)
				end
			end
		end

		Lib.FastWait()

		intro.SetProgress("Loading Recorder",0.95)

		Lib.Window.Init()
		Main.CreateMainGui()
		Explorer.Window:Show({Align = "right", Pos = 1, Size = 200, Silent = true})
		Properties.Window:Show({Align = "right", Pos = 2, Size = 150, Silent = true})
		pcall(function() Main.CopyWin.GuiElems.Main.Position = UDim2.new(0, 10, 0, 90) end)
		task.spawn(function() pcall(Main.Credit) end)
		Lib.DeferFunc(function() Lib.Window.ToggleSide("right") end)

		local genv = (getgenv or function() return _G end)()
		genv.__RPP = {
			Main = Main, Lib = Lib, Explorer = Explorer, Properties = Properties, ModelViewer = ModelViewer, ScriptViewer = ScriptViewer, Console = Console,
			RecorderWin = Main.RecorderWin, CopyWin = Main.CopyWin, ToolWin = Main.ToolWin,
			GetSelection = function()
				local r = {}
				for _, n in ipairs(selection.List) do if n.Obj then r[#r + 1] = n.Obj end end
				return r
			end,
		}
		genv.__RPP_CopyHost = Main.CopyWin.GuiElems.Content
		genv.__RPP.ApplyTheme = function(t)
			local c = t.c
			local function shade(col, a) return Color3.new(math.clamp(col.R + a, 0, 1), math.clamp(col.G + a, 0, 1), math.clamp(col.B + a, 0, 1)) end
			local T = Settings.Theme
			local new = {
				Main1 = c.title, Main2 = c.win, Outline1 = c.outline, Outline2 = c.outline, Outline3 = c.outline,
				TextBox = c.code, Menu = c.code, ListSelection = c.sel, Button = c.btn, ButtonHover = shade(c.btn, 0.03),
				ButtonPress = shade(c.btn, -0.06), Highlight = shade(c.title, 0.06), Text = c.text, PlaceholderText = c.sub,
			}
			local function key(col) return string.format("%.3f,%.3f,%.3f", col.R, col.G, col.B) end
			local map = {}
			for k, nc in pairs(new) do
				local oc = T[k]
				if typeof(oc) == "Color3" and not map[key(oc)] then map[key(oc)] = nc end
			end
			local roots = {}
			pcall(function()
				for _, g in ipairs(Main.GetSecureContainer():GetChildren()) do
					if string.sub(g.Name, 1, 5) == "_DPP_" then roots[#roots + 1] = g end
				end
			end)
			for _, g in ipairs(roots) do
				for _, o in ipairs(g:GetDescendants()) do
					pcall(function()
						if o:IsA("GuiObject") then
							local n = map[key(o.BackgroundColor3)]
							if n then o.BackgroundColor3 = n end
							n = map[key(o.BorderColor3)]
							if n then o.BorderColor3 = n end
							if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
								n = map[key(o.TextColor3)]
								if n then o.TextColor3 = n end
								if o:IsA("TextBox") then
									n = map[key(o.PlaceholderColor3)]
									if n then o.PlaceholderColor3 = n end
								end
							end
						elseif o:IsA("UIStroke") then
							local n = map[key(o.Color)]
							if n then o.Color = n end
						end
					end)
				end
			end
			for k, nc in pairs(new) do T[k] = nc end
			pcall(function() Explorer.Refresh() end)
			pcall(function()
				if writefile then
					local o = {}
					for k, v in pairs(new) do o[k] = { v.R, v.G, v.B } end
					writefile("RecorderPP_DexTheme.json", game:GetService("HttpService"):JSONEncode(o))
				end
			end)
		end
		task.spawn(function()
			local closed = false
			local function finish()
				if closed then return end
				closed = true
				pcall(function() intro.SetProgress("Complete",1) end)
				pcall(function() Lib.FastWait(0.8) end)
				pcall(function() intro.Close() end)
			end
			task.delay(25, finish)
			local function run(src, name)
				local fn, err = loadstring(src, "=" .. name)
				if not fn then
					warn("[Recorder ++] " .. name .. " did not load: " .. tostring(err))
					return
				end
				local ok, e2 = pcall(fn)
				if not ok then warn("[Recorder ++] " .. name .. " error: " .. tostring(e2)) end
			end
			run(Main.CopySrc, "Copy")
			run(Main.RecorderSrc, "Recorder")
			run(Main.ToolSrc, "ToolCopy")
			finish()
		end)
	end

	Main.Uninit = function()
		Main.MenuApps = {}
		Main.AppControls = {}
		Main.Plugins = {}
		for _, gui in pairs(Main.GetSecureContainer():GetChildren()) do
			if string.sub(gui.Name,1,5) == "_DPP_" then
				gui:Destroy()
			end
		end
	end

	Main.Reinit = function()
		Main.Uninit()
		task.wait()
		Main.Init()
	end

	return Main
end)()

Main.RecorderSrc = [=====[


local K = {}
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local SoundService = game:GetService("SoundService")
local TweenService = game:GetService("TweenService")
local TextService = game:GetService("TextService")
local HttpService = game:GetService("HttpService")
local Debris = game:GetService("Debris")
local lp = Players.LocalPlayer

local Run = { alive = true, conns = {} }
local X = {
	filter = "", compact = false, deep = true, thorough = true, guess = false, pre = 2,
	camSegs = {}, winLog = {}, sv = { list = {}, map = {} }, ds = { buttons = {} }, off = {}, offWhy = {}, cost = {},
	GUARD = { anim = "Animation logging", vfx = "VFX logging", sfx = "SFX logging", obj = "Spawned-object logging", cam = "Cutscene camera logging" },
	GUARD_ORDER = { "anim", "vfx", "sfx", "obj", "cam" },
	g = { frames = 0, time = 0, worst = 0 }, guardOn = true, t0 = os.clock(), svFilter = "all", svQuery = "",
	ACCESS_URL = "https://avl-design-server.mohammedsaifullahsaifmohammed.workers.dev",
	objOn = true, objSeen = setmetatable({}, { __mode = "k" }),
	markers = {}, fxEdit = {}, lens = {}, fastAnim = setmetatable({}, { __mode = "k" }), lastRow = setmetatable({}, { __mode = "k" }), compactButtons = {}, sizeIdx = 2,
}
do
	local env = (getgenv and getgenv()) or _G
	local prev = env.__AnimVFXLogger
	if type(prev) == "table" and type(prev.cleanup) == "function" then pcall(prev.cleanup) end
	local pg = lp:FindFirstChildOfClass("PlayerGui")
	if pg then
		for _, old in ipairs(pg:GetChildren()) do
			if old.Name == "AnimVFXLogger" or old.Name == "AnimVFXLoggerLoading" then pcall(function() old:Destroy() end) end
		end
	end
	env.__AnimVFXLogger = Run
end

X.loadStart = os.clock()
function X.finishLoading() X.loadDone = true end

local SETTINGS_FILE = "AnimVFXLogger_Settings.json"
local MAX_ENTRIES = 150
local POLL_RATE = 0.1
local CAPTURE_STEP = 1 / 30

local QUALITIES = { "Full", "High", "Medium", "Low" }
local QUALITY_TOL = { Full = 0, High = 0.01, Medium = 0.03, Low = 0.08 }
local QUALITY_INFO = {
	Full = "every sampled frame (largest script)",
	High = "drops frames that are almost exactly in between",
	Medium = "good balance of size and accuracy",
	Low = "smallest script, slightly less smooth",
}

local paused = false
local ownOnly = true
local uniqueOnly = true
local detailedMode = false
local QUALITY = "Medium"
local currentTab = "Anim"
local seenKeys = { Anim = {}, VFX = {}, SFX = {}, OBJ = {}, Search = {} }
local queues = { Anim = {}, VFX = {}, SFX = {}, OBJ = {}, Search = {} }
local counter = 0
local exportLog = { Anim = {}, VFX = {}, SFX = {}, OBJ = {}, Search = {} }
local ownTracks = setmetatable({}, { __mode = "k" })
local MAX_EXPORT = 2000

local excluded = {}
local excludedVFX = {}
local excludedSFX = {}
local blocked = {}
local blockedLogged = {}
X.blockV, X.blockS = {}, {}
X.fxAll = true
X.variants, X.strict = false, true
X.lead = setmetatable({}, { __mode = "k" })
X.vfxOff = setmetatable({}, { __mode = "k" })
local animInfo = {}
local animLabel = {}
local vfxLabel = {}
local sfxLabel = {}
local vfxSpec = {}
local sfxSpec = {}
local details = {}
local detailErr = {}
local rbxmxCache = {}
local detailJobs = {}
local detailQueue, detailWorking = {}, false
local progressListeners = {}
local entriesById = {}
local updaters = {}
local animFX = {}
local fxWindows = {}
local syncFns = {}
function K.syncUI()
	for _, f in ipairs(syncFns) do pcall(f) end
end

local VFX_CLASSES = {
	ParticleEmitter = true, Beam = true, Trail = true, Fire = true,
	Smoke = true, Sparkles = true, Explosion = true, Highlight = true,
	PointLight = true, SpotLight = true, SurfaceLight = true,
	ForceField = true, Atmosphere = true, BloomEffect = true, BlurEffect = true,
	ColorCorrectionEffect = true, DepthOfFieldEffect = true, SunRaysEffect = true,
}

local setclip = setclipboard or toclipboard

X.gui2d = true
X.animInstOf = setmetatable({}, { __mode = "v" })
X.rigKeep, X.rigKeepOrder = {}, {}
function X.keepRig(id, owner)
	if X.rigKeep[id] or not owner then return end
	pcall(function()
		local has = false
		for _, d in ipairs(owner:GetDescendants()) do
			if d:IsA("Motor6D") then
				has = true
				break
			end
		end
		if not has then return end
		local oa = owner.Archivable
		owner.Archivable = true
		local c = owner:Clone()
		owner.Archivable = oa
		if not c then return end
		c.Parent = nil
		X.rigKeep[id] = c
		table.insert(X.rigKeepOrder, id)
		while #X.rigKeepOrder > 12 do
			local oldId = table.remove(X.rigKeepOrder, 1)
			local oc = X.rigKeep[oldId]
			X.rigKeep[oldId] = nil
			if oc then pcall(function() oc:Destroy() end) end
		end
	end)
end

function K.loadSettings()
	if not (isfile and readfile) then return nil end
	local ok, data = pcall(function()
		if not isfile(SETTINGS_FILE) then return nil end
		return HttpService:JSONDecode(readfile(SETTINGS_FILE))
	end)
	if ok and type(data) == "table" then return data end
	return nil
end

X.guiSize = "big"
X.cutscenes = true
X.logMove = true
X.kept = {}
X.GUI_FACTOR = { big = 1, small = 0.75, tiny = 0.55 }
function X.viewSize()
	local g = X.rootGui
	local sz = g and g.Parent and g.AbsoluteSize
	if sz and sz.X > 50 and sz.Y > 50 then return sz end
	local cam = workspace.CurrentCamera
	return cam and cam.ViewportSize or Vector2.new(1280, 720)
end
function X.guiScale()
	local vp = X.viewSize()
	return math.clamp(math.min(vp.X / 1100, vp.Y / 540), 1, 3) * (X.GUI_FACTOR[X.guiSize] or 1)
end

local loaded = K.loadSettings()
if loaded then
	local function applyMap(target, src, labels)
		if type(src) ~= "table" then return end
		for id, label in pairs(src) do
			target[id] = true
			if labels and type(label) == "string" and label ~= "" then labels[id] = label end
		end
	end
	applyMap(excluded, loaded.excluded, animLabel)
	applyMap(excludedVFX, loaded.excludedVFX, vfxLabel)
	applyMap(excludedSFX, loaded.excludedSFX, sfxLabel)
	applyMap(blocked, loaded.blocked, animLabel)
	if type(loaded.logVariants) == "boolean" then X.variants = loaded.logVariants end
	if type(loaded.strictFX) == "boolean" then X.strict = loaded.strictFX end
	if type(loaded.fxAll) == "boolean" then X.fxAll = loaded.fxAll end
	if X.GUI_FACTOR[loaded.guiSize] then X.guiSize = loaded.guiSize end
	if type(loaded.logCutscenes) == "boolean" then X.cutscenes = loaded.logCutscenes end
	if type(loaded.logMovement) == "boolean" then X.logMove = loaded.logMovement end
	X.comboLoad = { on = loaded.autoCombine, gap = loaded.comboGap }
	applyMap(X.blockV, loaded.blockedVFX, vfxLabel)
	applyMap(X.blockS, loaded.blockedSFX, sfxLabel)
	if (tonumber(loaded.version) or 1) >= 2 then
		if type(loaded.ownOnly) == "boolean" then ownOnly = loaded.ownOnly end
		if type(loaded.uniqueOnly) == "boolean" then uniqueOnly = loaded.uniqueOnly end
	end
	if type(loaded.detailedMode) == "boolean" then detailedMode = loaded.detailedMode end
	if QUALITY_TOL[loaded.quality] then QUALITY = loaded.quality end
	if type(loaded.tab) == "string" then currentTab = loaded.tab end
	if type(loaded.filter) == "string" then X.filter = loaded.filter end
	if type(loaded.compact) == "boolean" then X.compact = loaded.compact end
	if type(loaded.deepHook) == "boolean" then X.deep = loaded.deepHook end
	if type(loaded.thorough) == "boolean" and (tonumber(loaded.version) or 1) >= 3 then X.thorough = loaded.thorough end
	if type(loaded.guessFX) == "boolean" then X.guess = loaded.guessFX end
	if type(loaded.objOn) == "boolean" then X.objOn = loaded.objOn end
	if type(loaded.gui2d) == "boolean" then X.gui2d = loaded.gui2d end
	if type(loaded.guardOn) == "boolean" then X.guardOn = loaded.guardOn end
	if tonumber(loaded.fxPre) then X.pre = math.clamp(tonumber(loaded.fxPre), 1, 10) end
end

function K.esc(s)
	return (tostring(s):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

function K.shortPath(inst)
	local parts, cur = {}, inst
	while cur and cur ~= workspace and cur ~= game do
		table.insert(parts, 1, cur.Name)
		cur = cur.Parent
	end
	if #parts > 3 then parts = { "..", parts[#parts - 2], parts[#parts - 1], parts[#parts] } end
	return table.concat(parts, ".")
end

function K.isOwn(inst)
	local char = lp.Character
	return char ~= nil and inst:IsDescendantOf(char)
end

function X.player()
	local t = X.filter:lower()
	if t == "" then return nil end
	local best
	for _, p in ipairs(Players:GetPlayers()) do
		local n, d = p.Name:lower(), p.DisplayName:lower()
		if n == t or d == t then return p end
		if not best and (n:find(t, 1, true) or d:find(t, 1, true)) then best = p end
	end
	return best
end
function X.passes(inst)
	if X.forceLog then return true end
	if X.filter ~= "" then
		local p = X.player()
		local ch = p and p.Character
		return ch ~= nil and inst:IsDescendantOf(ch)
	end
	return (not ownOnly) or K.isOwn(inst)
end

function K.countKeys(t)
	local n = 0
	for _ in pairs(t) do n += 1 end
	return n
end

function K.getRoot()
	local char = lp.Character
	return char and char:FindFirstChild("HumanoidRootPart")
end

local Clip = {}
Clip.HEADER = "-- This was generated by Dua's VFX/SFX/ANIMATION LOGGER"
function Clip.stamp(text)
	text = tostring(text)
	if text:sub(1, #Clip.HEADER) == Clip.HEADER or text:match("^%s*<") then return text end
	return Clip.HEADER .. "\n" .. text
end
function K.animName(id)
	local l = animLabel[id] or ""
	l = l:match("^(.-) / ") or l
	l = l:gsub("[\r\n]", " ")
	if l == "" then l = "(unnamed)" end
	return l
end
function Clip.set(text)
	if not setclip then return false end
	return (pcall(setclip, Clip.stamp(text)))
end

function K.g(n)
	if n == math.huge then return "math.huge" end
	if n == -math.huge then return "-math.huge" end
	if n ~= n then return "0" end
	return string.format("%.6g", n)
end

function K.num(n)
	local s = string.format("%.4f", n):gsub("0+$", ""):gsub("%.$", "")
	if s == "-0" or s == "" then s = "0" end
	return s
end

function K.cfStr(cf)
	local c = { cf:GetComponents() }
	for i, v in ipairs(c) do c[i] = K.num(v) end
	return "CFrame.new(" .. table.concat(c, ",") .. ")"
end

function K.cfDiffers(a, b)
	return (a.Position - b.Position).Magnitude > 0.002
		or (a.XVector - b.XVector).Magnitude > 0.002
		or (a.YVector - b.YVector).Magnitude > 0.002
end

function K.withTimeout(seconds, fn)
	local done, result = false, nil
	task.spawn(function()
		local ok, r = pcall(fn)
		if ok then result = r end
		done = true
	end)
	local t0 = os.clock()
	while not done and os.clock() - t0 < seconds do task.wait(0.05) end
	return result
end

function K.lit(v)
	local t = typeof(v)
	if t == "number" then
		return K.g(v)
	elseif t == "boolean" then
		return tostring(v)
	elseif t == "string" then
		return string.format("%q", v)
	elseif t == "Vector3" then
		return string.format("Vector3.new(%s,%s,%s)", K.g(v.X), K.g(v.Y), K.g(v.Z))
	elseif t == "Vector2" then
		return string.format("Vector2.new(%s,%s)", K.g(v.X), K.g(v.Y))
	elseif t == "Color3" then
		return string.format("Color3.new(%s,%s,%s)", K.g(v.R), K.g(v.G), K.g(v.B))
	elseif t == "NumberRange" then
		return string.format("NumberRange.new(%s,%s)", K.g(v.Min), K.g(v.Max))
	elseif t == "NumberSequence" then
		local kps = {}
		for _, k in ipairs(v.Keypoints) do
			kps[#kps + 1] = string.format("NumberSequenceKeypoint.new(%s,%s,%s)", K.g(k.Time), K.g(k.Value), K.g(k.Envelope))
		end
		return "NumberSequence.new({" .. table.concat(kps, ",") .. "})"
	elseif t == "ColorSequence" then
		local kps = {}
		for _, k in ipairs(v.Keypoints) do
			kps[#kps + 1] = string.format(
				"ColorSequenceKeypoint.new(%s,Color3.new(%s,%s,%s))",
				K.g(k.Time), K.g(k.Value.R), K.g(k.Value.G), K.g(k.Value.B)
			)
		end
		return "ColorSequence.new({" .. table.concat(kps, ",") .. "})"
	elseif t == "EnumItem" then
		return tostring(v)
	elseif t == "UDim2" then
		return string.format("UDim2.new(%s,%s,%s,%s)", K.g(v.X.Scale), K.g(v.X.Offset), K.g(v.Y.Scale), K.g(v.Y.Offset))
	elseif t == "UDim" then
		return string.format("UDim.new(%s,%s)", K.g(v.Scale), K.g(v.Offset))
	elseif t == "Rect" then
		return string.format("Rect.new(%s,%s,%s,%s)", K.g(v.Min.X), K.g(v.Min.Y), K.g(v.Max.X), K.g(v.Max.Y))
	elseif t == "CFrame" then
		return K.cfStr(v)
	end
	return nil
end

function K.playAnim(id)
	local char = lp.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not hum then error("no humanoid") end
	local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
	local a = Instance.new("Animation")
	a.AnimationId = id
	local track = animator:LoadAnimation(a)
	ownTracks[track] = true
	track:Play()
end

function K.frameError(a, b)
	return (a.Position - b.Position).Magnitude
		+ (a.XVector - b.XVector).Magnitude
		+ (a.YVector - b.YVector).Magnitude
end

function K.simplifyJoints(joints, tol)
	local n = #joints[1].frames
	if tol <= 0 or n <= 2 then return joints, n, n end

	local keep = { [1] = true, [n] = true }
	local stack = { { 1, n } }
	local ops = 0
	local times = joints[1].frames
	while #stack > 0 do
		local seg = table.remove(stack)
		local i, j = seg[1], seg[2]
		if j - i > 1 then
			local ti, tj = times[i][1], times[j][1]
			local span = math.max(tj - ti, 1e-6)
			local worst, worstK = 0, nil
			for k = i + 1, j - 1 do
				local alpha = (times[k][1] - ti) / span
				local e = 0
				for _, jt in ipairs(joints) do
					local f = jt.frames
					local err = K.frameError(f[k][2], f[i][2]:Lerp(f[j][2], alpha))
					if err > e then e = err end
				end
				if e > worst then worst, worstK = e, k end
				ops += #joints
			end
			if worst > tol and worstK then
				keep[worstK] = true
				stack[#stack + 1] = { i, worstK }
				stack[#stack + 1] = { worstK, j }
			end
			if ops > 40000 then
				ops = 0
				if coroutine.isyieldable() then task.wait() end
			end
		end
	end

	local out, kept = {}, 0
	for _, jt in ipairs(joints) do
		local list = {}
		for idx, f in ipairs(jt.frames) do
			if keep[idx] then list[#list + 1] = f end
		end
		kept = #list
		out[#out + 1] = { name = jt.name, part0 = jt.part0, part1 = jt.part1, frames = list }
	end
	return out, kept, n
end

