	return "-- Animation: " .. K.animName(id) .. " | Type: SIMPLE\n" .. string.format([==[-- Play animation %s on your character
-- (the animation must be usable by that game/account - otherwise use the frame-by-frame script)
local Players = game:GetService("Players")
