function K.paint(b, color)
	baseColor[b] = color
	b.BackgroundColor3 = color
end

function K.newButton(parent, text, color)
	local b = Instance.new("TextButton")
	b.AutoButtonColor = false
	b.BorderSizePixel = 1
	b.BorderColor3 = Color3.fromRGB(55, 55, 55)
	b.Text = text
	b.TextColor3 = C.text
	b.TextTransparency = 0.1
	b.Font = Th.font
	b.TextSize = 14
	K.paint(b, color or C.btn)
	b.MouseEnter:Connect(function()
		b.BackgroundColor3 = baseColor[b]:Lerp(Color3.new(1, 1, 1), 0.06)
	end)
	b.MouseLeave:Connect(function()
		b.BackgroundColor3 = baseColor[b]
	end)
	b.MouseButton1Down:Connect(function()
		b.BackgroundColor3 = baseColor[b]:Lerp(Color3.new(0, 0, 0), 0.3)
	end)
	b.MouseButton1Up:Connect(function()
		b.BackgroundColor3 = baseColor[b]:Lerp(Color3.new(1, 1, 1), 0.06)
	end)
	b.Parent = parent
	return b
end

function K.flash(btn, text)
	local old = btn.Text
	btn.Text = text
	task.delay(1, function()
		if btn.Parent then btn.Text = old end
	end)
end

function K.isPress(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function isMove(input)
	return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
end

local function makeDraggable(target, handle, onClick, conns)
	local dragging, startMouse, startPos, moved = false, nil, nil, false
	handle.InputBegan:Connect(function(input)
		if K.isPress(input) then
			dragging, moved = true, false
			startMouse, startPos = input.Position, target.Position
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
					if not moved and onClick then onClick() end
				end
			end)
		end
	end)
	table.insert(conns, UserInputService.InputChanged:Connect(function(input)
		if dragging and isMove(input) then
			local d = input.Position - startMouse
			if math.abs(d.X) + math.abs(d.Y) > 5 then moved = true end
			target.Position = UDim2.new(
				startPos.X.Scale, startPos.X.Offset + d.X,
				startPos.Y.Scale, startPos.Y.Offset + d.Y
			)
		end
	end))
end

function X.dexSideWindow(opts)
	local R = getgenv().__RPP
	local w = R.RecorderWin
	local win = { content = w.GuiElems.Content, frame = w.GuiElems.Main, hosted = true, window = w }
	function win.setMinimized(v)
		if v then
			pcall(function() w:Close() end)
		else
			pcall(function() w:Show({ Align = "right", Pos = 3, Size = 330 }) end)
		end
	end
	function win.destroy() pcall(function() w:Close() end) end
	function win.getState() return {} end
	return win
end

local function createWindow(opts)
	if opts.dexSide and getgenv and getgenv().__RPP and getgenv().__RPP.RecorderWin then return X.dexSideWindow(opts) end
	local win, conns = {}, {}

	do
		local vp = X.viewSize()
		local sc = X.guiScale()
		local maxW, maxH = math.max((vp.X - 16) / sc, 200), math.max(vp.Y * 0.8 / sc, 180)
		local ow, oh = opts.size.X, opts.size.Y
		local nw, nh = math.min(ow, maxW), math.min(oh, maxH)
		if nw ~= ow or nh ~= oh then
			local p = opts.pos
			local px, py = p.X, p.Y
			if px.Scale == 0.5 then px = UDim.new(0.5, px.Offset + ow / 2 - nw / 2) end
			if py.Scale == 0.5 then py = UDim.new(0.5, py.Offset + oh / 2 - nh / 2) end
			opts.pos = UDim2.new(px.Scale, px.Offset, py.Scale, py.Offset)
			opts.size = Vector2.new(nw, nh)
		end
		if sc ~= 1 then
			local p = opts.pos
			local px, py = p.X, p.Y
			if px.Scale == 0.5 then px = UDim.new(0.5, px.Offset + opts.size.X * (1 - sc) / 2) end
			if py.Scale == 0.5 then py = UDim.new(0.5, py.Offset + opts.size.Y * (1 - sc) / 2) end
			opts.pos = UDim2.new(px.Scale, px.Offset, py.Scale, py.Offset)
		end
		if opts.minSize then
			opts.minSize = Vector2.new(math.min(opts.minSize.X, nw), math.min(opts.minSize.Y, nh))
		end
	end

	local frame = Instance.new("Frame")
	frame.Name = opts.title
	frame:SetAttribute("WinCorner", true)
	frame.Size = UDim2.fromOffset(opts.size.X, opts.size.Y)
	frame.Position = opts.pos
	frame.BackgroundColor3 = C.win
	frame.BorderSizePixel = 0
	frame.ClipsDescendants = true
	frame.Active = true
	frame.Parent = gui
	local fscale = Instance.new("UIScale")
	fscale.Name = "AVLScale"
	fscale.Scale = X.guiScale()
	fscale.Parent = frame
	local stroke = Instance.new("UIStroke")
	stroke.Color = C.outline
	stroke.Thickness = 1
	stroke.Parent = frame

	local titleBar = Instance.new("Frame")
	titleBar.Size = UDim2.new(1, 0, 0, 20)
	titleBar:SetAttribute("NoCorner", true)
	titleBar.BackgroundColor3 = C.title
	titleBar.BorderSizePixel = 0
	titleBar.Parent = frame

	local titleLbl = Instance.new("TextLabel")
	titleLbl.Position = UDim2.new(0, 5, 0, 0)
	titleLbl.Size = UDim2.new(1, -44, 1, 0)
	titleLbl.BackgroundTransparency = 1
	titleLbl.Text = opts.title
	titleLbl.TextColor3 = C.text
	titleLbl.Font = Enum.Font.SourceSans
	titleLbl.TextSize = 14
	titleLbl.TextXAlignment = Enum.TextXAlignment.Left
	titleLbl.TextTruncate = Enum.TextTruncate.AtEnd
	titleLbl.Parent = titleBar

	local function barButton(x, image)
		local b = Instance.new("TextButton")
		b.AutoButtonColor = false
		b.Text = ""
		b.BackgroundColor3 = Color3.fromRGB(32, 32, 32)
		b.BackgroundTransparency = 1
		b.BorderSizePixel = 0
		b.Size = UDim2.fromOffset(16, 16)
		b.Position = UDim2.new(1, x, 0, 2)
		b:SetAttribute("NoCorner", true)
		local uc = Instance.new("UICorner")
		uc.CornerRadius = UDim.new(0, 4)
		uc.Parent = b
		local img = Instance.new("ImageLabel")
		img.BackgroundTransparency = 1
		img.Image = image
		img.Position = UDim2.fromOffset(3, 3)
		img.Size = UDim2.fromOffset(10, 10)
		img.Parent = b
		b.MouseEnter:Connect(function() b.BackgroundTransparency = 0 end)
		b.MouseLeave:Connect(function() b.BackgroundTransparency = 1 end)
		b.Parent = titleBar
		return b
	end
	local minBtn = barButton(-36, "rbxassetid://5034768003")
	local closeBtn = barButton(-18, "rbxassetid://5054663650")

	local content = Instance.new("Frame")
	content.Position = UDim2.new(0, 0, 0, 20)
	content.Size = UDim2.new(1, 0, 1, -20)
	content.BackgroundTransparency = 1
	content.Parent = frame
	local topLine = Instance.new("Frame")
	topLine.Size = UDim2.new(1, 0, 0, 1)
	topLine.BackgroundColor3 = Color3.fromRGB(33, 33, 33)
	topLine.BorderSizePixel = 0
	topLine.ZIndex = 5
	topLine:SetAttribute("NoCorner", true)
	topLine.Parent = content

	local grip = Instance.new("Frame")
	grip.Size = UDim2.fromOffset(16, 16)
	grip.Position = UDim2.new(1, -16, 1, -16)
	grip.BackgroundTransparency = 1
	grip.Active = true
	grip.ZIndex = 20
	grip.Parent = frame
	for _, p in ipairs({ { 12, 12 }, { 8, 12 }, { 12, 8 }, { 4, 12 }, { 8, 8 }, { 12, 4 } }) do
		local dot = Instance.new("Frame")
		dot.Size = UDim2.fromOffset(2, 2)
		dot.Position = UDim2.fromOffset(p[1], p[2])
		dot.BackgroundColor3 = C.sub
		dot.BorderSizePixel = 0
		dot:SetAttribute("NoCorner", true)
		dot.ZIndex = 21
		dot.Parent = grip
	end

	local resizing, rStart, rSize = false, nil, nil
	grip.InputBegan:Connect(function(input)
		if K.isPress(input) then
			resizing, rStart, rSize = true, input.Position, frame.AbsoluteSize / X.guiScale()
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then resizing = false end
			end)
		end
	end)
	table.insert(conns, UserInputService.InputChanged:Connect(function(input)
		if resizing and isMove(input) then
			local d = (input.Position - rStart) / X.guiScale()
			frame.Size = UDim2.fromOffset(
				math.max(opts.minSize.X, rSize.X + d.X),
				math.max(opts.minSize.Y, rSize.Y + d.Y)
			)
		end
	end))

	local mini = K.newButton(gui, opts.miniText or "+", C.title)
	mini.Size = UDim2.fromOffset(40, 40)
	mini.Font = Th.bold
	mini.TextSize = 17
	mini.Visible = false
	local mscale = Instance.new("UIScale")
	mscale.Name = "AVLScale"
	mscale.Scale = X.guiScale()
	mscale.Parent = mini
	local topMini = opts.topMini
	if topMini then mini.AnchorPoint = Vector2.new(0.5, 0) end
	local miniStroke = Instance.new("UIStroke")
	miniStroke.Color = C.outline
	miniStroke.Parent = mini

	local hostedTop = topMini and getgenv and getgenv().__RPP ~= nil
	function win.setMinimized(v)
		if hostedTop then
			frame.Visible = not v
			mini.Visible = false
			pcall(function()
				local app = getgenv().__RPP.Main.MenuApps.Recorder
				if app then (v and app.Disable or app.Enable)(true) end
			end)
			return
		end
		if v then
			mini.Position = topMini and UDim2.new(0.5, 0, 0, (getgenv and getgenv().__RPP) and 40 or 2) or frame.Position
			frame.Visible = false
			mini.Visible = true
		else
			if topMini then
				local sc = X.guiScale()
				frame.Position = UDim2.new(0.5, -frame.Size.X.Offset * sc / 2, 0.5, -frame.Size.Y.Offset * sc / 2)
			else
				frame.Position = mini.Position
			end
			mini.Visible = false
			frame.Visible = true
		end
	end

	function win.getState()
		local pos = (frame.Visible or topMini) and frame.AbsolutePosition or mini.AbsolutePosition
		return {
			x = pos.X, y = pos.Y,
			w = frame.Size.X.Offset, h = frame.Size.Y.Offset,
			minimized = not frame.Visible,
		}
	end

	function win.destroy()
		for _, c in ipairs(conns) do c:Disconnect() end
		frame:Destroy()
		mini:Destroy()
	end

	minBtn.MouseButton1Click:Connect(function() win.setMinimized(true) end)
	closeBtn.MouseButton1Click:Connect(function()
		if hostedTop then return win.setMinimized(true) end
		local function doClose()
			if opts.onClose then opts.onClose() end
			win.destroy()
		end
		if opts.confirmClose then
			X.confirm("Close the logger?", "Are you sure you want to close it? Your settings are saved. Run the script again to reopen it.", doClose)
		else
			doClose()
		end
	end)

	makeDraggable(frame, titleBar, nil, conns)
	if topMini then
		mini.MouseButton1Click:Connect(function() win.setMinimized(false) end)
	else
		makeDraggable(mini, mini, function() win.setMinimized(false) end, conns)
	end

	win.frame, win.content, win.mini = frame, content, mini
	if opts.startMinimized then win.setMinimized(true) end
	return win
end

function X.setGuiSize(name)
	if not X.GUI_FACTOR[name] then return end
	X.guiSize = name
	local sc = X.guiScale()
	local vp = X.viewSize()
	for _, o in ipairs(gui:GetChildren()) do
		local us = o:FindFirstChild("AVLScale")
		if us then
			us.Scale = sc
			if o:GetAttribute("WinCorner") then
				local w, h = o.Size.X.Offset, o.Size.Y.Offset
				local nw = math.min(w, math.max((vp.X - 16) / sc, 200))
				local nh = math.min(h, math.max(vp.Y * 0.8 / sc, 180))
				if nw ~= w or nh ~= h then o.Size = UDim2.fromOffset(nw, nh) end
			end
		end
	end
end

local KW, BI = {}, {}
for w in ("and break do else elseif end false for function if in local nil not or repeat return then true until while continue"):gmatch("%S+") do
	KW[w] = true
end
for w in (
	"game workspace script task math string table os print warn pairs ipairs pcall error type typeof tostring "
	.. "tonumber select next require loadstring getgenv setmetatable getmetatable rawget rawset unpack Instance "
	.. "CFrame Vector3 Vector2 Color3 Enum NumberRange NumberSequence NumberSequenceKeypoint ColorSequence "
	.. "ColorSequenceKeypoint UDim UDim2 TweenInfo RaycastParams Random BrickColor Ray Rect _G"
):gmatch("%S+") do
	BI[w] = true
end

local HL = { kw = "#f86d7c", str = "#adf195", num = "#ffc600", com = "#666666", bi = "#84d6f7", fn = "#fdfbac" }

local function highlightLine(line)
	local out, plain, i, n = {}, {}, 1, #line
	local function flushPlain()
		if #plain > 0 then
			out[#out + 1] = K.esc(table.concat(plain))
			plain = {}
		end
	end
	local function tok(color, text)
		flushPlain()
		out[#out + 1] = '<font color="' .. color .. '">' .. K.esc(text) .. "</font>"
	end

	while i <= n do
		local c = line:sub(i, i)
		if c == "-" and line:sub(i + 1, i + 1) == "-" then
			tok(HL.com, line:sub(i))
			break
		elseif c == '"' or c == "'" then
			local j = i + 1
			while j <= n do
				local d = line:sub(j, j)
				if d == "\\" then
					j += 2
				elseif d == c then
					break
				else
					j += 1
				end
			end
			tok(HL.str, line:sub(i, math.min(j, n)))
			i = j + 1
		elseif c:match("%d") or (c == "-" and line:sub(i + 1, i + 1):match("%d")
			and not (i > 1 and line:sub(i - 1, i - 1):match("[%w_%)%]]"))) then
			local s = line:match("^%-?%d[%d%.]*[eE][%-+]?%d+", i) or line:match("^%-?%d[%d%.]*", i)
			tok(HL.num, s)
			i += #s
		elseif c:match("[%a_]") then
			local w = line:match("^[%a_][%w_]*", i)
			if KW[w] then
				tok(HL.kw, w)
			elseif BI[w] then
				tok(HL.bi, w)
			elseif line:match("^%s*%(", i + #w) then
				tok(HL.fn, w)
			else
				plain[#plain + 1] = w
			end
			i += #w
		else
			plain[#plain + 1] = c
			i += 1
		end
	end
	flushPlain()
	return table.concat(out)
end

local CODE_TEXT_SIZE, LINE_H = 15, 18
local CHAR_W = 8
pcall(function()
	CHAR_W = TextService:GetTextSize("0000000000", CODE_TEXT_SIZE, Enum.Font.Code, Vector2.new(10000, 100)).X / 10
end)

local function splitLines(code)
	local out = {}
	for line in (code .. "\n"):gmatch("(.-)\r?\n") do out[#out + 1] = (line:gsub("\t", "    ")) end
	return out
end

local function createCodeView(parent, position, size)
	local view = {}
	local sf = Instance.new("ScrollingFrame")
	sf.Position, sf.Size = position, size
	sf.BackgroundColor3 = C.code
	sf.BorderSizePixel = 0
	sf.ScrollBarThickness = 16
	sf.ElasticBehavior = Enum.ElasticBehavior.Never
	sf.ScrollingEnabled = true
	sf.Active = true
	sf.CanvasSize = UDim2.new()
	sf.ScrollingDirection = Enum.ScrollingDirection.XY
	sf.Parent = parent
	view.frame = sf

	local lines, cache, pool = {}, {}, {}

	local function lineText(i)
		local c = cache[i]
		if not c then
			local ok, hl = pcall(highlightLine, lines[i])
			if not ok or type(hl) ~= "string" then
				hl = tostring(lines[i]):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
			end
			c = string.format('<font color="#6b6b6b">%5d</font>  %s', i, hl)
			cache[i] = c
		end
		return c
	end

	local function refresh()
		local total = #lines
		local first = math.max(math.floor(sf.CanvasPosition.Y / LINE_H), 0) + 1
		local visible = math.min(math.max(math.ceil(sf.AbsoluteSize.Y / LINE_H) + 2, 45), 120)
		while #pool < visible do
			local lbl = Instance.new("TextLabel")
			lbl.BackgroundTransparency = 1
			lbl.RichText = true
			lbl.TextWrapped = false
			lbl.Font = Enum.Font.Code
			lbl.TextSize = CODE_TEXT_SIZE
			lbl.TextColor3 = Color3.fromRGB(204, 204, 204)
			lbl.TextXAlignment = Enum.TextXAlignment.Left
			lbl.TextYAlignment = Enum.TextYAlignment.Top
			lbl.Active = false
			lbl.Size = UDim2.fromOffset(sf.CanvasSize.X.Offset, LINE_H)
			lbl.Visible = false
			lbl.Parent = sf
			pool[#pool + 1] = lbl
		end
		for k, lbl in ipairs(pool) do
			local idx = first + k - 1
			if k <= visible and idx <= total then
				if lbl:GetAttribute("L") ~= idx then
					lbl:SetAttribute("L", idx)
					lbl.Text = lineText(idx)
					lbl.Position = UDim2.fromOffset(4, (idx - 1) * LINE_H + 4)
				end
				lbl.Visible = true
			else
				lbl.Visible = false
			end
		end
	end

	sf:GetPropertyChangedSignal("CanvasPosition"):Connect(refresh)
	sf:GetPropertyChangedSignal("AbsoluteSize"):Connect(refresh)

	function view.setCode(code)
		view.code = code
		lines = splitLines(code)
		table.clear(cache)
		local maxLen = 0
		for _, l in ipairs(lines) do
			if #l > maxLen then maxLen = #l end
		end
		local w = (maxLen + 8) * CHAR_W + 40
		sf.CanvasSize = UDim2.fromOffset(w, #lines * LINE_H + 12)
		for _, lbl in ipairs(pool) do
			lbl:SetAttribute("L", nil)
			lbl.Size = UDim2.fromOffset(w, LINE_H)
		end
		sf.CanvasPosition = Vector2.zero
		refresh()
		task.defer(refresh)
		return #lines
	end

	function view.showRaw(code)
		for _, lbl in ipairs(pool) do lbl.Visible = false end
		if not view.rawBox then
			local tb = Instance.new("TextBox")
			tb.Size = UDim2.new(1, 0, 1, 0)
			tb.BackgroundColor3 = C.code
			tb.BorderSizePixel = 0
			tb.ClearTextOnFocus = false
			tb.MultiLine = true
			tb.TextEditable = false
			tb.TextWrapped = false
			tb.Font = Enum.Font.Code
			tb.TextSize = CODE_TEXT_SIZE
			tb.TextColor3 = Color3.fromRGB(204, 204, 204)
			tb.TextXAlignment = Enum.TextXAlignment.Left
			tb.TextYAlignment = Enum.TextYAlignment.Top
			tb.ZIndex = 5
			tb.Parent = parent
			view.rawBox = tb
		end
		view.rawBox.Position, view.rawBox.Size = sf.Position, sf.Size
		view.rawBox.Text = #code > 190000 and code:sub(1, 190000) or code
		view.rawBox.Visible = true
	end
	function view.hideRaw()
		if view.rawBox then view.rawBox.Visible = false end
	end

	return view
end

local function cycleQuality()
	local idx = table.find(QUALITIES, QUALITY) or 1
	QUALITY = QUALITIES[idx % #QUALITIES + 1]
	K.syncUI()
end

local viewerCount = 0
local function openViewer(titleText, variants, startIndex, toolId)
	viewerCount += 1
	local off = (viewerCount % 6) * 22
	local win = createWindow({
		title = titleText,
		size = Vector2.new(600, 440),
		pos = UDim2.new(0.5, -300 + off, 0.5, -220 + off),
		minSize = Vector2.new(340, 220),
		miniText = "{ }",
	})
	local content = win.content

	local bar = Instance.new("Frame")
	bar.Size = UDim2.new(1, -8, 0, 30)
	bar.Position = UDim2.new(0, 4, 0, 4)
	bar.BackgroundTransparency = 1
	bar.Parent = content

	local dropState = { open = false }
	local selBtn = K.newButton(bar, "v  Options", C.sel)
	selBtn.Size = UDim2.new(1, toolId and -350 or -264, 1, 0)
	selBtn.TextXAlignment = Enum.TextXAlignment.Left
	selBtn.TextTruncate = Enum.TextTruncate.AtEnd
	selBtn.TextSize = 15
	local selPad = Instance.new("UIPadding")
	selPad.PaddingLeft = UDim.new(0, 10)
	selPad.PaddingRight = UDim.new(0, 6)
	selPad.Parent = selBtn

	local qualityBtn = K.newButton(bar, "Quality: " .. QUALITY, C.btn)
	qualityBtn.Size = UDim2.new(0, 120, 1, 0)
	qualityBtn.Position = UDim2.new(1, -258, 0, 0)

	local runBtn = K.newButton(bar, "Run", C.green)
	runBtn.Size = UDim2.new(0, 64, 1, 0)
	runBtn.Position = UDim2.new(1, -134, 0, 0)

	local copyBtn = K.newButton(bar, "Copy", C.sel)
	copyBtn.Size = UDim2.new(0, 64, 1, 0)
	copyBtn.Position = UDim2.new(1, -64, 0, 0)

	local view = createCodeView(content, UDim2.new(0, 4, 0, 38), UDim2.new(1, -8, 1, -68))

	local status = Instance.new("TextLabel")
	status.Position = UDim2.new(0, 6, 1, -26)
	status.Size = UDim2.new(1, -250, 0, 22)
	status.BackgroundTransparency = 1
	status.TextColor3 = C.sub
	status.Font = Th.font
	status.TextSize = 15
	status.TextXAlignment = Enum.TextXAlignment.Left
	status.Text = ""
	status.Parent = content

	local function nav(label, xOff, fn)
		local b = K.newButton(content, label, C.btn)
		b.Size = UDim2.new(0, 46, 0, 24)
		b.Position = UDim2.new(1, xOff, 1, -27)
		b.TextSize = 14
		b.MouseButton1Click:Connect(function()
			local sf = view.frame
			local maxY = math.max(sf.CanvasSize.Y.Offset - sf.AbsoluteSize.Y, 0)
			local page = math.max(sf.AbsoluteSize.Y - 40, 40)
			sf.CanvasPosition = Vector2.new(sf.CanvasPosition.X, math.clamp(fn(sf.CanvasPosition.Y, page, maxY), 0, maxY))
		end)
	end
	nav("Top", -218, function() return 0 end)
	nav("PgUp", -168, function(y, page) return y - page end)
	nav("PgDn", -118, function(y, page) return y + page end)
	nav("End", -68, function(_, _, maxY) return maxY end)
	local current, token, currentIndex = nil, 0, startIndex or 1
	local tabButtonsV = {}

	local function show(i)
		currentIndex = i
		selBtn.Text = (dropState.open and "^  " or "v  ") .. variants[i].name
		token += 1
		local my = token
		current = nil
		for j, b in ipairs(tabButtonsV) do K.paint(b, j == i and C.sel or C.btn) end
		view.hideRaw()
		pcall(view.setCode, "")
		status.Text = "Generating..."
		local t0 = os.clock()
		task.spawn(function()
			local okGen, errGen = pcall(variants[i].get, function(code, err)
				if my ~= token or not view.frame.Parent then return end
				if not code then
					warn("[Logger] code generation failed: " .. tostring(err))
					status.Text = "Failed: " .. tostring(err)
					view.showRaw("-- Could not generate the code:\n-- " .. tostring(err) .. "\n-- Click the tab again or lower Quality to retry.")
					return
				end
				code = Clip.stamp(code)
				current = code
				view.hideRaw()
				local ok, n = pcall(view.setCode, code)
				if ok then
					status.Text = string.format("%d lines, %d characters (%.1fs)", n, #code, os.clock() - t0)
				else
					warn("[Logger] code view failed: " .. tostring(n))
					view.showRaw(code)
					status.Text = "Colored view failed (" .. tostring(n) .. ") - showing plain text. Copy still works."
				end
			end, function(text)
				if my == token and status.Parent then status.Text = text end
			end)
			if not okGen and my == token and status.Parent then
				warn("[Logger] generator error: " .. tostring(errGen))
				status.Text = "Failed: " .. tostring(errGen)
				view.showRaw("-- Generator error:\n-- " .. tostring(errGen))
			end
		end)
	end

	if toolId then
		local getBtn = K.newButton(bar, "GET tool", C.green)
		getBtn.Size = UDim2.new(0, 80, 1, 0)
		getBtn.Position = UDim2.new(1, -342, 0, 0)
		getBtn.MouseButton1Click:Connect(function()
			if not current then return K.flash(getBtn, "Wait...") end
			local base = current
			status.Text = "Looking for this animation's modules and models..."
			task.spawn(function()
				local okC, ctx = pcall(K.findAnimContext, toolId)
				if not okC then ctx = { modules = {}, models = {}, scripts = {} } end
				local okT, toolCode = pcall(K.buildToolCode, toolId, base, ctx, animLabel[toolId])
				if not status.Parent then return end
				if not okT then
					status.Text = "GET tool failed: " .. tostring(toolCode)
					return K.flash(getBtn, "Error")
				end
				token += 1
				current = toolCode
				view.hideRaw()
				if not pcall(view.setCode, toolCode) then view.showRaw(toolCode) end
				for _, tb in ipairs(tabButtonsV) do K.paint(tb, C.btn) end
				local loader = loadstring or load
				local fnT, errT = loader and loader(toolCode)
				local given = false
				if fnT then given = pcall(fnT) end
				if given then
					status.Text = string.format("Tool added to your backpack (%d module(s), %d model(s) found). The script is shown here if you want to Copy it.", #ctx.modules, #ctx.models)
					K.flash(getBtn, "Given!")
				else
					status.Text = "Could not give the tool: " .. tostring(errT or "your executor has no loadstring") .. " (the script is shown here - Copy it)"
					K.flash(getBtn, "Error")
				end
			end)
		end)
	end
	-- options bar: a button that slides a list open downward
	local TweenService = game:GetService("TweenService")
	local ROW_H, DROP_W = 28, 230

	local catcher = Instance.new("TextButton")
	catcher.Size = UDim2.new(1, 0, 1, 0)
	catcher.BackgroundTransparency = 1
	catcher.Text = ""
	catcher.AutoButtonColor = false
	catcher.ZIndex = 55
	catcher.Visible = false
	catcher.Parent = content

	local drop = Instance.new("Frame")
	drop.Name = "OptionsDrop"
	drop.Position = UDim2.new(0, 4, 0, 34)
	drop.Size = UDim2.new(0, DROP_W, 0, 0)
	drop.BackgroundColor3 = C.row2
	drop.BorderSizePixel = 1
	drop.BorderColor3 = C.outline
	drop.ClipsDescendants = true
	drop.Visible = false
	drop.ZIndex = 60
	drop.Parent = content

	local dropList = Instance.new("ScrollingFrame")
	dropList.Size = UDim2.new(1, 0, 1, 0)
	dropList.BackgroundTransparency = 1
	dropList.BorderSizePixel = 0
	dropList.ScrollBarThickness = 4
	dropList.ScrollBarImageColor3 = C.sub
	dropList.CanvasSize = UDim2.new()
	dropList.AutomaticCanvasSize = Enum.AutomaticSize.Y
	dropList.ScrollingDirection = Enum.ScrollingDirection.Y
	dropList.ZIndex = 61
	dropList.Parent = drop
	local dropLayout = Instance.new("UIListLayout")
	dropLayout.SortOrder = Enum.SortOrder.LayoutOrder
	dropLayout.Padding = UDim.new(0, 1)
	dropLayout.Parent = dropList

	local function styleRow(b)
		b.Size = UDim2.new(1, -6, 0, ROW_H)
		b.TextXAlignment = Enum.TextXAlignment.Left
		b.ZIndex = 62
		local pad = Instance.new("UIPadding")
		pad.PaddingLeft = UDim.new(0, 10)
		pad.Parent = b
	end

	local dropRows = #variants + (toolId and 1 or 0)
	local function setDrop(open)
		if open == dropState.open then return end
		dropState.open = open
		selBtn.Text = (open and "^  " or "v  ") .. variants[currentIndex].name
		catcher.Visible = open
		local want = dropRows * (ROW_H + 1) + 4
		local room = math.max(content.AbsoluteSize.Y - 44, ROW_H + 4)
		local goal = UDim2.new(0, DROP_W, 0, open and math.min(want, room) or 0)
		if open then drop.Visible = true end
		local tw = TweenService:Create(drop, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Size = goal })
		tw:Play()
		if not open then
			tw.Completed:Connect(function()
				if not dropState.open then drop.Visible = false end
			end)
		end
	end

	for i, v in ipairs(variants) do
		local b = K.newButton(dropList, v.name, C.btn)
		styleRow(b)
		b.LayoutOrder = i
		b.MouseButton1Click:Connect(function()
			setDrop(false)
			show(i)
		end)
		tabButtonsV[i] = b
	end

	local refreshMove = function() end
	if toolId then
		local moveBtn = K.newButton(dropList, "", C.btn)
		styleRow(moveBtn)
		moveBtn.LayoutOrder = 1000
		refreshMove = function()
			local rr = X.rootFor(toolId)
			if not rr then
				moveBtn.Text = "Move: none logged"
				K.paint(moveBtn, C.btn)
			elseif X.rootOn then
				moveBtn.Text = "Move: ON  (" .. X.rootShort(rr) .. ")"
				K.paint(moveBtn, C.green)
			else
				moveBtn.Text = "Move: OFF  (" .. X.rootShort(rr) .. ")"
				K.paint(moveBtn, C.btn)
			end
		end
		moveBtn.MouseButton1Click:Connect(function()
			if not X.rootFor(toolId) then
				status.Text = "No movement logged yet. Play the move while you dash or rise, then reopen this."
				return
			end
			X.rootOn = not X.rootOn
			refreshMove()
			setDrop(false)
			show(currentIndex)
		end)
		refreshMove()
	end

	selBtn.MouseButton1Click:Connect(function()
		refreshMove()
		setDrop(not dropState.open)
	end)
	catcher.MouseButton1Click:Connect(function() setDrop(false) end)

	qualityBtn.MouseButton1Click:Connect(function()
		cycleQuality()
		qualityBtn.Text = "Quality: " .. QUALITY
		show(currentIndex)
	end)

	runBtn.MouseButton1Click:Connect(function()
		if not current then return K.flash(runBtn, "Wait...") end
		local loader = loadstring or load
		local fn, cerr = loader(current)
		if not fn then
			status.Text = "Run failed to compile: " .. tostring(cerr)
			return K.flash(runBtn, "Error")
		end
		task.spawn(function()
			local ok, rerr = pcall(fn)
			if not ok then
				warn("[Logger] run error: " .. tostring(rerr))
				if status.Parent then status.Text = "Run error: " .. tostring(rerr) end
			end
		end)
		K.flash(runBtn, "Ran!")
	end)

	copyBtn.MouseButton1Click:Connect(function()
		if not current then return K.flash(copyBtn, "Wait...") end
		if Clip.set(current) then
			K.flash(copyBtn, "Copied!")
		else
			status.Text = "No clipboard in this executor - select the text and copy it manually."
		end
	end)

	show(currentIndex)
	return win
end

