	if tabNames[kind] and (kind == "Anim" or kind == "VFX" or kind == "SFX" or kind == "OBJ") then
		local n = #queues[kind]
		tabButtons[kind].Text = n > 0 and string.format("%s (%d)", tabNames[kind], n) or tabNames[kind]
	end
