local refreshAll
local searchBoxes, searchOf = {}, setmetatable({}, { __mode = "k" })

local function applyFilter(kind)
	local box = searchBoxes[kind]
	if not box then return end
	local f = box.Text:lower()
	for _, row in ipairs(queues[kind]) do
		row.Visible = f == "" or (searchOf[row] or ""):find(f, 1, true) ~= nil
	end
end

local pauseButtons = {}
local function clearKind(kind)
	for _, b in ipairs(queues[kind]) do b:Destroy() end
	table.clear(queues[kind])
	table.clear(seenKeys[kind])
	table.clear(exportLog[kind])
	if kind == "Anim" then table.clear(entriesById) end
	updateTabText(kind)
end

local stopMineFn
local function makeLogPage(kind)
	local page = newPage(kind)

	local btns = {}
	if kind == "Anim" then
		btns[#btns + 1] = { "Stop Mine", 90, function(b) K.flash(b, stopMineFn() > 0 and "Stopped" or "None") end }
		btns[#btns + 1] = { "Combine", 76, function() X.cmbOpen() end }
	end
	btns[#btns + 1] = { "Pause", 68, "pause" }
	btns[#btns + 1] = { "Compact", 82, "compact" }
	btns[#btns + 1] = { "Clear", 58, function() clearKind(kind) end }
	btns[#btns + 1] = { "Copy All", 84, function(b)
		local lines = {}
		for _, e in ipairs(exportLog[kind]) do table.insert(lines, e.copy) end
		toClip(table.concat(lines, "\n"), "all " .. kind .. " entries")
		K.flash(b, "Done!")
	end }

	local search = Instance.new("TextBox")
	search.Size = UDim2.new(1, 0, 0, 28)
	search.BackgroundColor3 = C.code
	search.BorderSizePixel = 0
	search.PlaceholderText = "Search..."
	search.PlaceholderColor3 = C.sub
	search.Text = ""
	search.TextColor3 = C.text
	search.Font = Th.font
	search.TextSize = 16
	search.TextXAlignment = Enum.TextXAlignment.Left
	search.ClearTextOnFocus = false
	search.Parent = page
	local sp = Instance.new("UIPadding")
	sp.PaddingLeft = UDim.new(0, 6)
	sp.Parent = search
	searchBoxes[kind] = search
	search:GetPropertyChangedSignal("Text"):Connect(function() applyFilter(kind) end)

	local n = #btns
	for i, def in ipairs(btns) do
		local b = K.newButton(page, def[1], C.btn)
		b.Size = UDim2.new(1 / n, -4, 0, 26)
		b.Position = UDim2.new((i - 1) / n, (i == 1) and 0 or 2, 0, 32)
		b.TextScaled = true
		local lim = Instance.new("UITextSizeConstraint")
		lim.MaxTextSize = 15
		lim.MinTextSize = 9
		lim.Parent = b
		if def[3] == "pause" then
			pauseButtons[#pauseButtons + 1] = b
			b.MouseButton1Click:Connect(function()
				paused = not paused
				K.syncUI()
			end)
		elseif def[3] == "compact" then
			X.compactButtons[#X.compactButtons + 1] = b
			b.MouseButton1Click:Connect(function() X.setCompact(not X.compact) end)
		else
			b.MouseButton1Click:Connect(function() def[3](b) end)
		end
	end

	lists[kind] = newList(page, UDim2.new(0, 0, 0, 62), UDim2.new(1, 0, 1, -62))
end
