local lastLogTab = "Anim"
local function setTab(name)
	if not pages[name] then name = "Anim" end
	currentTab = name
	if name == "Anim" or name == "VFX" or name == "SFX" or name == "OBJ" then lastLogTab = name end
	for n, p in pairs(pages) do p.Visible = (n == name) end
	for n, b in pairs(tabButtons) do
		K.paint(b, n == name and C.btn or C.title)
		local hl = b:FindFirstChild("Hl")
		if hl then hl.Visible = n == name end
	end
	if name == "Saved" and X.svReady and X.svRender then pcall(X.svRender) end
	if name == "NPC" and X.npc and X.npc.render then pcall(X.npc.render) end
end
for name, b in pairs(tabButtons) do
	b.MouseButton1Click:Connect(function()
		setTab(name)
		if name == "Search" and not X.db and not X.scanning and X.scan then task.spawn(X.scan) end
	end)
end

function X.sfxOpen(snd)
	X.sfx = X.sfx or {}
	local S = X.sfx
	if S.win and S.win.frame and S.win.frame.Parent then
		if not S.win.frame.Visible then S.win.setMinimized(false) end
		if snd then S.load(snd) end
		return
	end
	S.looped = false
	local win = createWindow({
		title = "SFX Editor", size = Vector2.new(440, 215), pos = UDim2.new(0.5, -220, 0.5, -108),
		minSize = Vector2.new(320, 190), miniText = "SFX",
		onClose = function()
			if S.prev then pcall(function() S.prev:Destroy() end) S.prev = nil end
			S.win = nil
		end,
	})
	S.win = win
	local c = win.content
	local bar1 = X.mkBar(c, 6, 34)
	X.mkLabel(bar1, "Sound id", 60)
	S.id = X.mkBox(bar1, 250, "", "rbxassetid://...")
	local bar2 = X.mkBar(c, 44, 34)
	X.mkLabel(bar2, "Volume", 50)
	S.vol = X.mkBox(bar2, 50, "1", "")
	X.mkLabel(bar2, "Speed", 42)
	S.spd = X.mkBox(bar2, 50, "1", "")
	X.mkLabel(bar2, "Start", 36)
	S.start = X.mkBox(bar2, 50, "0", "")
	local bar3 = X.mkBar(c, 82, 34)
	S.loopBtn = X.mkTool(bar3, "Loop: off", 82, C.btn, function(b)
		S.looped = not S.looped
		b.Text = "Loop: " .. (S.looped and "on" or "off")
	end)
	X.mkTool(bar3, "Play", 56, C.green, function() S.play() end)
	X.mkTool(bar3, "Stop", 52, C.btn, function() S.stop() end)
	X.mkTool(bar3, "Apply", 60, C.sel, function(b) K.flash(b, S.apply() and "Applied" or "No sound") end)
	local bar4 = X.mkBar(c, 120, 34)
	X.mkTool(bar4, "Copy code", 90, C.sel, function(b) toClip(S.code(), "the SFX code"); K.flash(b, "Copied!") end)
	X.mkTool(bar4, "Playing now", 100, C.btn, function(b)
		for _, d in ipairs(game:GetDescendants()) do
			if d:IsA("Sound") and d.IsPlaying and d ~= S.prev then S.load(d) return end
		end
		K.flash(b, "None playing")
	end)
	X.mkTool(bar4, "New", 50, C.btn, function()
		S.src = nil
		S.id.Text, S.vol.Text, S.spd.Text, S.start.Text = "", "1", "1", "0"
		S.looped = false
		S.loopBtn.Text = "Loop: off"
		S.status.Text = "New sound (not linked to a game sound: use Play and Copy code)"
	end)
	S.status = Instance.new("TextLabel")
	S.status.Position = UDim2.new(0, 8, 0, 158)
	S.status.Size = UDim2.new(1, -16, 0, 34)
	S.status.BackgroundTransparency = 1
	S.status.Font = Th.font
	S.status.TextSize = 13
	S.status.TextColor3 = C.sub
	S.status.TextWrapped = true
	S.status.TextXAlignment = Enum.TextXAlignment.Left
	S.status.TextYAlignment = Enum.TextYAlignment.Top
	S.status.Text = "Empty. Hold a sound in the Explorer > Edit SFX, or press Playing now."
	S.status.Parent = c

	function S.load(snd)
		S.src = snd
		S.id.Text = snd.SoundId
		S.vol.Text = tostring(snd.Volume)
		S.spd.Text = tostring(snd.PlaybackSpeed)
		S.start.Text = tostring(snd.TimePosition)
		S.looped = snd.Looped
		S.loopBtn.Text = "Loop: " .. (S.looped and "on" or "off")
		S.status.Text = "Editing: " .. snd:GetFullName()
	end
	function S.read()
		return { id = S.id.Text, vol = tonumber(S.vol.Text) or 1, spd = tonumber(S.spd.Text) or 1, start = tonumber(S.start.Text) or 0, looped = S.looped }
	end
	function S.stop()
		if S.prev then pcall(function() S.prev:Destroy() end) S.prev = nil end
	end
	function S.play()
		S.stop()
		local d = S.read()
		local snd = Instance.new("Sound")
		snd.SoundId, snd.Volume, snd.PlaybackSpeed, snd.TimePosition, snd.Looped = d.id, d.vol, d.spd, d.start, d.looped
		snd.Parent = SoundService
		S.prev = snd
		snd:Play()
	end
	function S.apply()
		if not (S.src and S.src.Parent) then return false end
		local d = S.read()
		pcall(function()
			S.src.SoundId, S.src.Volume, S.src.PlaybackSpeed, S.src.TimePosition, S.src.Looped = d.id, d.vol, d.spd, d.start, d.looped
		end)
		return true
	end
	function S.code()
		local d = S.read()
		return string.format('local snd = Instance.new("Sound")\nsnd.SoundId = %q\nsnd.Volume = %s\nsnd.PlaybackSpeed = %s\nsnd.TimePosition = %s\nsnd.Looped = %s\nsnd.Parent = workspace\nsnd:Play()',
			d.id, tostring(d.vol), tostring(d.spd), tostring(d.start), tostring(d.looped))
	end
	if snd then S.load(snd) end
end

function X.newAnim(name)
	local char = lp.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not hum then return out("Spawn your character first, then create the animation.") end
	local len = 1
	local joints, motors = {}, {}
	for _, m in ipairs(char:GetDescendants()) do
		if m:IsA("Motor6D") and m.Part0 and m.Part1 then
			local fr = { { 0, CFrame.new() }, { len / 2, CFrame.new() }, { len, CFrame.new() } }
			joints[#joints + 1] = { name = m.Name, part0 = m.Part0.Name, part1 = m.Part1.Name, frames = fr }
			motors[#motors + 1] = { name = m.Part1.Name, parent = m.Part0.Name, samples = fr }
		end
	end
	if #joints == 0 then return out("No joints found on your character.") end
	X.newAnimCount = (X.newAnimCount or 0) + 1
	local id = "custom_" .. os.time() .. "_" .. X.newAnimCount
	details[id] = {
		rig = hum.RigType.Name, length = len, looped = false, joints = joints, allMotors = motors,
		priorityValue = Enum.AnimationPriority.Action.Value, cache = {}, rawFrames = 3, source = "custom",
	}
	animInfo[id] = { priority = "Action", looped = false, speed = 1 }
	animLabel[id] = (name and name ~= "") and name or ("My animation " .. X.newAnimCount)
	X.lens[id] = len
	pcall(function() mainWin.setMinimized(false) end)
	X.aeOpen(id)
end

function X.animCreator(name)
	if X.ac and X.ac.win and X.ac.win.frame and X.ac.win.frame.Parent then
		if not X.ac.win.frame.Visible then X.ac.win.setMinimized(false) end
		return
	end
	local char = lp.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not hum then return out("Spawn your character first, then create the animation.") end
	local rigName = hum.RigType.Name
	local S = { name = (name and name ~= "") and name or "My animation", conns = {}, ci = 1, mode = "rot", sel = nil, looped = false, defDt = 0.3 }
	local was = char.Archivable
	char.Archivable = true
	local okC, model = pcall(function() return char:Clone() end)
	char.Archivable = was
	if not okC or not model then return out("Could not copy your character.") end
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("BaseScript") or d:IsA("Humanoid") or d:IsA("ForceField") or d:IsA("Sound") then pcall(function() d:Destroy() end) end
	end
	local joints, all = {}, {}
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("JointInstance") and d.Part0 and d.Part1 then
			all[#all + 1] = d
			if d:IsA("Motor6D") then joints[#joints + 1] = d end
		end
	end
	local children, isChild, queue, order = {}, {}, {}, {}
	for _, j in ipairs(all) do
		children[j.Part0] = children[j.Part0] or {}
		table.insert(children[j.Part0], j)
		isChild[j.Part1] = true
	end
	for part in pairs(children) do if not isChild[part] then queue[#queue + 1] = part end end
	if #joints == 0 or #queue == 0 then model:Destroy() return out("This rig has no joints I can pose.") end
	local qi = 1
	while qi <= #queue and qi < 2000 do
		local part = queue[qi]
		qi += 1
		for _, j in ipairs(children[part] or {}) do
			order[#order + 1] = j
			queue[#queue + 1] = j.Part1
		end
	end
	local motorIdx, partJoint = {}, {}
	for k, m in ipairs(joints) do motorIdx[m] = k partJoint[m.Part1] = k end
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("BasePart") then d.Anchored = true d.CanCollide = false end
	end
	model:PivotTo(CFrame.new(0, 0, 0))

	local function tfOf(p) return CFrame.new(p[4], p[5], p[6]) * CFrame.Angles(math.rad(p[1]), math.rad(p[2]), math.rad(p[3])) end
	local function fk(tfs)
		for _, j in ipairs(order) do
			local k = motorIdx[j]
			j.Part1.CFrame = j.Part0.CFrame * j.C0 * ((k and tfs[k]) or CFrame.new()) * j.C1:Inverse()
		end
	end
	local function newPose()
		local po = {}
		for k = 1, #joints do po[k] = { 0, 0, 0, 0, 0, 0 } end
		return po
	end
	local F = { { dt = 0, smooth = true, pose = newPose() } }
	local function poseTfs(po)
		local t = {}
		for k = 1, #joints do t[k] = tfOf(po[k]) end
		return t
	end
	local SMOOTH_STEPS = 8
	local function build()
		local t = 0
		for i, f in ipairs(F) do
			if i > 1 then t += math.max(f.dt, 0.02) end
			f.t = t
		end
		local length = math.max(F[#F].t, 0.5)
		local tracks = {}
		for k = 1, #joints do
			local list = {}
			for i, f in ipairs(F) do
				local cur = tfOf(f.pose[k])
				if i == 1 then
					list[1] = { 0, cur }
				else
					local prev, t0 = tfOf(F[i - 1].pose[k]), F[i - 1].t
					if f.smooth then
						for st = 1, SMOOTH_STEPS do
							local a = st / SMOOTH_STEPS
							list[#list + 1] = { t0 + (f.t - t0) * a, prev:Lerp(cur, a * a * (3 - 2 * a)) }
						end
					else
						list[#list + 1] = { f.t - 0.002, prev }
						list[#list + 1] = { f.t, cur }
					end
				end
			end
			if #F == 1 or list[#list][1] < length then list[#list + 1] = { length, list[#list][2] } end
			tracks[k] = list
		end
		return tracks, length
	end

	local win = createWindow({
		title = "Anim Creator - " .. S.name, size = Vector2.new(460, 590), pos = UDim2.new(0.5, -230, 0.5, -295),
		minSize = Vector2.new(340, 460), miniText = "ANIM",
		onClose = function()
			for _, cn in ipairs(S.conns) do pcall(function() cn:Disconnect() end) end
			if S.playConn then pcall(function() S.playConn:Disconnect() end) end
			pcall(function() model:Destroy() end)
			X.ac = nil
		end,
	})
	S.win = win
	X.ac = S
	local c = win.content
	local ctlH = 258
	local vp = Instance.new("ViewportFrame")
	vp.Position = UDim2.new(0, 6, 0, 6)
	vp.Size = UDim2.new(1, -12, 1, -(ctlH + 12))
	vp.BackgroundColor3 = C.code
	vp.BorderSizePixel = 0
	vp.Ambient = Color3.fromRGB(180, 180, 180)
	vp.Parent = c
	model.Parent = vp
	local cam = Instance.new("Camera")
	cam.FieldOfView = 50
	cam.Parent = vp
	vp.CurrentCamera = cam
	local bbCF, bbSize = model:GetBoundingBox()
	local focus, dist = bbCF.Position, math.max(bbSize.Magnitude * 1.05, 6)
	local yaw, pitch = math.pi, -0.15
	local function updCam() cam.CFrame = CFrame.new(focus) * CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0) * CFrame.new(0, 0, dist) end
	updCam()

	local ctl = Instance.new("Frame")
	ctl.Position = UDim2.new(0, 0, 1, -ctlH)
	ctl.Size = UDim2.new(1, 0, 0, ctlH)
	ctl.BackgroundTransparency = 1
	ctl.Parent = c

	local sliders = {}
	local chipBtns = {}
	local tinted
	local frameLbl, timeBox, smoothBtn, modeRot, modeMove, selLbl
	local function curPose() return F[S.ci].pose end
	local function syncSliders()
		local p = S.sel and curPose()[S.sel]
		for i = 1, 3 do
			local sl = sliders[i]
			if S.mode == "rot" then sl.min, sl.max = -180, 180 else sl.min, sl.max = -3, 3 end
			sl.lbl.Text = (S.mode == "rot" and "Rot " or "Move ") .. ({ "X", "Y", "Z" })[i]
			sl.set(p and (S.mode == "rot" and p[i] or p[3 + i]) or 0, true)
		end
	end
	local function refreshPose() fk(poseTfs(curPose())) end
	local function showFrame()
		frameLbl.Text = string.format("Frame %d/%d", S.ci, #F)
		timeBox.Text = S.ci == 1 and "0" or tostring(F[S.ci].dt)
		smoothBtn.Text = "Smooth: " .. (F[S.ci].smooth and "ON" or "OFF")
		refreshPose()
		syncSliders()
	end
	local function select(k)
		if tinted then pcall(function() tinted.part.Color = tinted.color end) tinted = nil end
		S.sel = k
		if k then
			local part = joints[k].Part1
			tinted = { part = part, color = part.Color }
			part.Color = Color3.fromRGB(70, 150, 255)
			selLbl.Text = "Selected: " .. part.Name
		else
			selLbl.Text = "Tap a body part (or pick it below)"
		end
		for kk, b in pairs(chipBtns) do K.paint(b, kk == k and C.sel or C.btn) end
		syncSliders()
	end

	local drag
	local function pick(pt)
		local ray = cam:ViewportPointToRay(pt.X - vp.AbsolutePosition.X, pt.Y - vp.AbsolutePosition.Y)
		local best, bestT
		for part, k in pairs(partJoint) do
			if part.Parent then
				local cf = part.CFrame
				local o, d, h = cf:PointToObjectSpace(ray.Origin), cf:VectorToObjectSpace(ray.Direction), part.Size / 2
				local tmin, tmax, ok = -math.huge, math.huge, true
				for _, ax in ipairs({ "X", "Y", "Z" }) do
					local oo, dd, hh = o[ax], d[ax], h[ax]
					if math.abs(dd) < 1e-6 then
						if math.abs(oo) > hh then ok = false break end
					else
						local t1, t2 = (-hh - oo) / dd, (hh - oo) / dd
						if t1 > t2 then t1, t2 = t2, t1 end
						tmin, tmax = math.max(tmin, t1), math.min(tmax, t2)
						if tmin > tmax then ok = false break end
					end
				end
				if ok and tmax > 0 and (not bestT or tmin < bestT) then best, bestT = k, tmin end
			end
		end
		if best then select(best) end
	end
	vp.InputBegan:Connect(function(input)
		if K.isPress(input) then
			local p = Vector2.new(input.Position.X, input.Position.Y)
			drag = { last = p, moved = 0 }
		end
	end)
	table.insert(S.conns, UserInputService.InputChanged:Connect(function(input)
		if drag and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local p = Vector2.new(input.Position.X, input.Position.Y)
			local d = p - drag.last
			drag.last = p
			drag.moved += d.Magnitude
			if drag.moved > 8 then
				yaw -= d.X * 0.01
				pitch = math.clamp(pitch - d.Y * 0.01, -1.3, 1.3)
				updCam()
			end
		end
	end))
	table.insert(S.conns, UserInputService.InputEnded:Connect(function(input)
		if drag and K.isPress(input) then
			if drag.moved <= 8 then pick(drag.last) end
			drag = nil
		end
	end))
	local zin = K.newButton(c, "+", C.btn)
	zin.Position, zin.Size, zin.ZIndex = UDim2.new(1, -64, 0, 12), UDim2.new(0, 24, 0, 24), 5
	zin.MouseButton1Click:Connect(function() dist = math.max(dist * 0.85, 2) updCam() end)
	local zout = K.newButton(c, "-", C.btn)
	zout.Position, zout.Size, zout.ZIndex = UDim2.new(1, -36, 0, 12), UDim2.new(0, 24, 0, 24), 5
	zout.MouseButton1Click:Connect(function() dist = math.min(dist * 1.15, 60) updCam() end)

	local bar1 = X.mkBar(ctl, 0, 30)
	X.mkTool(bar1, "< Prev", 56, C.btn, function() S.ci = math.max(S.ci - 1, 1) showFrame() end)
	frameLbl = X.mkLabel(bar1, "Frame 1/1", 72)
	X.mkTool(bar1, "Next >", 56, C.btn, function() S.ci = math.min(S.ci + 1, #F) showFrame() end)
	X.mkTool(bar1, "+ Frame", 66, C.green, function()
		local po = {}
		for k, v in ipairs(curPose()) do po[k] = { v[1], v[2], v[3], v[4], v[5], v[6] } end
		table.insert(F, S.ci + 1, { dt = S.defDt, smooth = F[S.ci].smooth, pose = po })
		S.ci += 1
		showFrame()
	end)
	X.mkTool(bar1, "Delete", 56, C.danger, function()
		if #F <= 1 then return end
		table.remove(F, S.ci)
		S.ci = math.min(S.ci, #F)
		showFrame()
	end)
	local bar2 = X.mkBar(ctl, 32, 30)
	X.mkLabel(bar2, "Time s", 44)
	timeBox = X.mkBox(bar2, 46, "0", "")
	timeBox.FocusLost:Connect(function()
		local n = tonumber(timeBox.Text)
		if S.ci > 1 and n then
			F[S.ci].dt = math.max(n, 0.02)
			S.defDt = F[S.ci].dt
		end
		timeBox.Text = S.ci == 1 and "0" or tostring(F[S.ci].dt)
	end)
	smoothBtn = X.mkTool(bar2, "Smooth: ON", 92, C.btn, function()
		F[S.ci].smooth = not F[S.ci].smooth
		showFrame()
	end)
	X.mkTool(bar2, "Smooth all", 80, C.btn, function(b)
		for _, f in ipairs(F) do f.smooth = true end
		showFrame()
		K.flash(b, "Done")
	end)
	X.mkTool(bar2, "Loop: off", 70, C.btn, function(b)
		S.looped = not S.looped
		b.Text = "Loop: " .. (S.looped and "on" or "off")
	end)
	local playBtn
	local function stopPlay()
		if S.playConn then S.playConn:Disconnect() S.playConn = nil end
		if playBtn then playBtn.Text = "Play" end
		showFrame()
	end
	playBtn = X.mkTool(bar2, "Play", 50, C.green, function()
		if S.playConn then return stopPlay() end
		local tracks, length = build()
		local t0 = os.clock()
		playBtn.Text = "Stop"
		S.playConn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if t > length then
				if S.looped then t = t % length else return stopPlay() end
			end
			local tfs = {}
			for k = 1, #joints do tfs[k] = K.aeEval(tracks[k], t) end
			fk(tfs)
		end)
	end)

	local bar3 = X.mkBar(ctl, 64, 30)
	for k, m in ipairs(joints) do
		chipBtns[k] = X.mkTool(bar3, m.Part1.Name, math.max(56, #m.Part1.Name * 8 + 14), C.btn, function() select(k) end)
	end
	local bar4 = X.mkBar(ctl, 96, 30)
	modeRot = X.mkTool(bar4, "Rotate", 62, C.sel, function()
		S.mode = "rot"
		K.paint(modeRot, C.sel) K.paint(modeMove, C.btn)
		syncSliders()
	end)
	modeMove = X.mkTool(bar4, "Move", 56, C.btn, function()
		S.mode = "move"
		K.paint(modeRot, C.btn) K.paint(modeMove, C.sel)
		syncSliders()
	end)
	X.mkTool(bar4, "Reset part", 78, C.btn, function()
		if S.sel then curPose()[S.sel] = { 0, 0, 0, 0, 0, 0 } showFrame() end
	end)
	X.mkTool(bar4, "Reset frame", 84, C.btn, function()
		F[S.ci].pose = newPose()
		showFrame()
	end)
	selLbl = Instance.new("TextLabel")
	selLbl.Position, selLbl.Size = UDim2.new(0, 10, 0, 128), UDim2.new(1, -20, 0, 16)
	selLbl.BackgroundTransparency = 1
	selLbl.Font, selLbl.TextSize, selLbl.TextColor3 = Th.font, 13, C.sub
	selLbl.TextXAlignment = Enum.TextXAlignment.Left
	selLbl.Text = "Tap a body part (or pick it below)"
	selLbl.Parent = ctl

	local function mkSlider(i, y)
		local sl = { min = -180, max = 180, value = 0 }
		local row = Instance.new("Frame")
		row.Position, row.Size, row.BackgroundTransparency = UDim2.new(0, 6, 0, y), UDim2.new(1, -12, 0, 22), 1
		row.Parent = ctl
		sl.lbl = Instance.new("TextLabel")
		sl.lbl.Size, sl.lbl.BackgroundTransparency = UDim2.new(0, 52, 1, 0), 1
		sl.lbl.Font, sl.lbl.TextSize, sl.lbl.TextColor3 = Th.font, 14, C.text
		sl.lbl.TextXAlignment = Enum.TextXAlignment.Left
		sl.lbl.Parent = row
		local track = Instance.new("Frame")
		track.Position, track.Size = UDim2.new(0, 56, 0.5, -3), UDim2.new(1, -122, 0, 6)
		track.BackgroundColor3, track.BorderSizePixel = C.btn, 0
		track.Parent = row
		local knob = Instance.new("Frame")
		knob.AnchorPoint, knob.Size = Vector2.new(0.5, 0.5), UDim2.new(0, 12, 0, 18)
		knob.BackgroundColor3, knob.BorderSizePixel = C.sel, 0
		knob.Position = UDim2.new(0.5, 0, 0.5, 0)
		knob.Parent = track
		local hit = Instance.new("TextButton")
		hit.Text, hit.AutoButtonColor, hit.BackgroundTransparency = "", false, 1
		hit.Position, hit.Size = UDim2.new(0, 50, 0, 0), UDim2.new(1, -116, 1, 0)
		hit.Parent = row
		local box = Instance.new("TextBox")
		box.Position, box.Size = UDim2.new(1, -56, 0, 1), UDim2.new(0, 56, 0, 20)
		box.BackgroundColor3, box.BorderSizePixel = C.code, 0
		box.Font, box.TextSize, box.TextColor3 = Th.font, 14, C.text
		box.ClearTextOnFocus = false
		box.Parent = row
		function sl.set(v, silent)
			v = math.clamp(v, sl.min, sl.max)
			sl.value = v
			knob.Position = UDim2.new((v - sl.min) / (sl.max - sl.min), 0, 0.5, 0)
			box.Text = string.format("%.1f", v)
			if not silent and S.sel then
				local p = curPose()[S.sel]
				p[S.mode == "rot" and i or 3 + i] = v
				refreshPose()
			end
		end
		local dragging = false
		local function fromInput(input)
			local a = math.clamp((input.Position.X - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
			sl.set(sl.min + a * (sl.max - sl.min))
		end
		hit.InputBegan:Connect(function(input)
			if K.isPress(input) then dragging = true fromInput(input) end
		end)
		table.insert(S.conns, UserInputService.InputChanged:Connect(function(input)
			if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then fromInput(input) end
		end))
		table.insert(S.conns, UserInputService.InputEnded:Connect(function(input)
			if K.isPress(input) then dragging = false end
		end))
		box.FocusLost:Connect(function()
			local n = tonumber(box.Text)
			if n then sl.set(n) else sl.set(sl.value, true) end
		end)
		sliders[i] = sl
	end
	mkSlider(1, 148) mkSlider(2, 172) mkSlider(3, 196)

	local function commit()
		local tracks, length = build()
		local js, ms = {}, {}
		for k, m in ipairs(joints) do
			js[#js + 1] = { name = m.Name, part0 = m.Part0.Name, part1 = m.Part1.Name, frames = tracks[k] }
			ms[#ms + 1] = { name = m.Part1.Name, parent = m.Part0.Name, samples = tracks[k] }
		end
		if not S.id then
			X.newAnimCount = (X.newAnimCount or 0) + 1
			S.id = "custom_" .. os.time() .. "_" .. X.newAnimCount
		end
		local id = S.id
		details[id] = {
			rig = rigName, length = length, looped = S.looped, joints = js, allMotors = ms,
			priorityValue = Enum.AnimationPriority.Action.Value, cache = {}, rawFrames = #tracks[1], source = "custom",
		}
		animInfo[id] = { priority = "Action", looped = S.looped, speed = 1 }
		animLabel[id] = S.name
		X.lens[id] = length
		X.aeData[id] = nil
		X.aeOpen(id)
	end
	local openBtn = K.newButton(ctl, "Open in Anim Editor (edit more / preview / save)", C.green)
	openBtn.Position, openBtn.Size = UDim2.new(0, 6, 0, 224), UDim2.new(1, -12, 0, 28)
	openBtn.MouseButton1Click:Connect(function()
		stopPlay()
		local ok, e = pcall(commit)
		if not ok then out("Could not open the Anim Editor: " .. tostring(e)) end
	end)
	showFrame()
	select(nil)
end

do
	local Lg = (getgenv and getgenv() or _G).__RPP_Logger
	if Lg then
		local function lastId()
			local P = X.pv
			return (X.ed and X.ed.id) or (X.ae and X.ae.id) or (P and P.id) or (X.lastAnim and X.lastAnim.id)
		end
		Lg.openTab = function(name)
			pcall(function() mainWin.setMinimized(false) end)
			setTab(name)
		end
		Lg.openSaved = function() Lg.openTab("Saved") end
		Lg.openDesign = function() Lg.openTab("Design") end
		Lg.openVfx = function() if X.vfxEditorOpen then X.vfxEditorOpen() end end
		Lg.createAnim = function() X.prompt("Name your new animation", "My animation", function(name) X.animCreator(name) end) end
		Lg.openSfx = function() X.sfxOpen() end
		Lg.editSfx = function(list) pcall(function() mainWin.setMinimized(false) end) X.sfxOpen(list and list[1]) end
		Lg.editObjects = function(list) pcall(function() mainWin.setMinimized(false) end) X.vfxEditorOpen(list) end
		Lg.editAnimId = function(id) pcall(function() mainWin.setMinimized(false) end) X.aeOpen(id) end
		Lg.openLib = function() if X.libOpen then X.libOpen() end end
		Lg.openFx = function()
			local id = lastId()
			if id then X.edOpen(id) else out("Play an animation first (or pick one in the Animations tab), then open the FX Editor.") end
		end
		Lg.openAnim = function()
			local id = lastId()
			if id then X.aeOpen(id) else out("Play an animation first (or pick one in the Animations tab), then open the Anim Editor.") end
		end
		task.defer(function()
			local R = getgenv and getgenv().__RPP
			if R and R.ApplyTheme then pcall(R.ApplyTheme, Th.cur) end
		end)
	end
end

do
	local page = newPage("Settings")
	local sf = newList(page, UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 1, 0))
	local order = 0

	local function section(title)
		order += 1
		local l = Instance.new("TextLabel")
		l.Size = UDim2.new(1, -6, 0, 30)
		l.BackgroundColor3 = C.title
		l.BorderSizePixel = 0
		l.LayoutOrder = order
		l.Text = title
		l.TextColor3 = C.text
		l.Font = Th.bold
		l.TextSize = 16
		l.TextXAlignment = Enum.TextXAlignment.Left
		local p = Instance.new("UIPadding")
		p.PaddingLeft = UDim.new(0, 8)
		p.Parent = l
		l.Parent = sf
	end

	local function row(label, desc, btnWidth)
		order += 1
		local r = Instance.new("Frame")
		r.Size = UDim2.new(1, -6, 0, 58)
		r.BackgroundColor3 = order % 2 == 0 and C.row1 or C.row2
		r.BorderSizePixel = 0
		r.LayoutOrder = order
		r.Parent = sf

		local t = Instance.new("TextLabel")
		t.Position = UDim2.new(0, 8, 0, 4)
		t.Size = UDim2.new(1, -(btnWidth + 20), 0, 22)
		t.BackgroundTransparency = 1
		t.Text = label
		t.TextColor3 = C.text
		t.Font = Th.bold
		t.TextSize = 16
		t.TextXAlignment = Enum.TextXAlignment.Left
		t.Parent = r

		local d = Instance.new("TextLabel")
		d.Position = UDim2.new(0, 8, 0, 26)
		d.Size = UDim2.new(1, -(btnWidth + 20), 0, 30)
		d.BackgroundTransparency = 1
		d.Text = desc
		d.TextColor3 = C.sub
		d.Font = Th.font
		d.TextSize = 14
		d.TextXAlignment = Enum.TextXAlignment.Left
		d.TextWrapped = true
		d.TextYAlignment = Enum.TextYAlignment.Top
		d.Parent = r

		local b = K.newButton(r, "", C.btn)
		b.Size = UDim2.new(0, btnWidth, 0, 32)
		b.Position = UDim2.new(1, -(btnWidth + 8), 0, 13)
		return b, d
	end

	local function toggleRow(label, desc, get, set)
		local b = row(label, desc, 84)
		local function sync()
			b.Text = get() and "On" or "Off"
			K.paint(b, get() and C.sel or C.btn)
		end
		b.MouseButton1Click:Connect(function()
			set(not get())
			K.syncUI()
		end)
		syncFns[#syncFns + 1] = sync
		sync()
	end

	section("Appearance")
	do
		order += 1
		local holder = Instance.new("Frame")
		holder.Size = UDim2.new(1, -6, 0, 0)
		holder.AutomaticSize = Enum.AutomaticSize.Y
		holder.BackgroundColor3 = C.row2
		holder.BorderSizePixel = 0
		holder.LayoutOrder = order
		holder.Parent = sf
		local holderLayout = Instance.new("UIListLayout")
		holderLayout.Padding = UDim.new(0, 4)
		holderLayout.SortOrder = Enum.SortOrder.LayoutOrder
		holderLayout.Parent = holder
		local holderPad = Instance.new("UIPadding")
		holderPad.PaddingLeft = UDim.new(0, 8)
		holderPad.PaddingRight = UDim.new(0, 8)
		holderPad.PaddingTop = UDim.new(0, 6)
		holderPad.PaddingBottom = UDim.new(0, 8)
		holderPad.Parent = holder

		local cap = Instance.new("TextLabel")
		cap.Size = UDim2.new(1, 0, 0, 22)
		cap.BackgroundTransparency = 1
		cap.LayoutOrder = 1
		cap.Text = "Theme - applies instantly and is saved"
		cap.TextColor3 = C.sub
		cap.Font = Th.font
		cap.TextSize = 14
		cap.TextXAlignment = Enum.TextXAlignment.Left
		cap.Parent = holder

		local grid = Instance.new("Frame")
		grid.Size = UDim2.new(1, 0, 0, 0)
		grid.AutomaticSize = Enum.AutomaticSize.Y
		grid.BackgroundTransparency = 1
		grid.LayoutOrder = 2
		grid.Parent = holder
		local gridLayout = Instance.new("UIGridLayout")
		gridLayout.CellSize = UDim2.new(0.5, -3, 0, 34)
		gridLayout.CellPadding = UDim2.new(0, 6, 0, 6)
		gridLayout.SortOrder = Enum.SortOrder.LayoutOrder
		gridLayout.Parent = grid

		local themeBtns = {}
		for i, t in ipairs(Th.list) do
			local b = K.newButton(grid, t.name, C.btn)
			b.LayoutOrder = i
			themeBtns[t.name] = b
			b.MouseButton1Click:Connect(function()
				Th.apply(t.name)
				setTab(currentTab)
				refreshAll()
				K.syncUI()
			end)
		end
		syncFns[#syncFns + 1] = function()
			for name, b in pairs(themeBtns) do
				K.paint(b, name == Th.cur.name and C.sel or C.btn)
			end
		end

		local cap2 = Instance.new("TextLabel")
		cap2.Size = UDim2.new(1, 0, 0, 0)
		cap2.AutomaticSize = Enum.AutomaticSize.Y
		cap2.BackgroundTransparency = 1
		cap2.LayoutOrder = 3
		cap2.Text = "GUI size - the windows and the letters. Big is the default. Pick Small or Tiny if the logger covers too much of the game. Applies instantly and is saved."
		cap2.TextColor3 = C.sub
		cap2.Font = Th.font
		cap2.TextSize = 14
		cap2.TextWrapped = true
		cap2.TextXAlignment = Enum.TextXAlignment.Left
		cap2.TextYAlignment = Enum.TextYAlignment.Top
		cap2.Parent = holder

		local grid2 = Instance.new("Frame")
		grid2.Size = UDim2.new(1, 0, 0, 0)
		grid2.AutomaticSize = Enum.AutomaticSize.Y
		grid2.BackgroundTransparency = 1
		grid2.LayoutOrder = 4
		grid2.Parent = holder
		local gl2 = Instance.new("UIGridLayout")
		gl2.CellSize = UDim2.new(1 / 3, -4, 0, 34)
		gl2.CellPadding = UDim2.new(0, 6, 0, 6)
		gl2.SortOrder = Enum.SortOrder.LayoutOrder
		gl2.Parent = grid2
		local sizeBtns = {}
		for i, it in ipairs({ { "big", "Big" }, { "small", "Small" }, { "tiny", "Tiny" } }) do
			local b = K.newButton(grid2, it[2], C.btn)
			b.LayoutOrder = i
			sizeBtns[it[1]] = b
			b.MouseButton1Click:Connect(function()
				X.setGuiSize(it[1])
				K.syncUI()
			end)
		end
		syncFns[#syncFns + 1] = function()
			for id, b in pairs(sizeBtns) do
				K.paint(b, id == X.guiSize and C.sel or C.btn)
			end
		end
	end

	section("What gets logged")
	toggleRow("Only my character", "ON: only you. OFF: every player and NPC around you is logged too.",
		function() return ownOnly end, function(v) ownOnly = v end)
	toggleRow("Log each move once", "ON: a move shows up one time. OFF: it is listed again every time it plays.",
		function() return uniqueOnly end, function(v) uniqueOnly = v end)
	toggleRow("Log move variants", "OFF (default): only the move you actually did. ON: also its variants (Slash2, SlashAlt, tracks played with no weight).",
		function() return X.variants end, function(v)
			X.variants = v
			table.clear(fxWindows.related)
		end)
	toggleRow("Only this move's own effects", "ON (default): effects and sounds must come from your character, near you. The hit on the other player is left out. OFF: anything within 60 studs counts.",
		function() return X.strict end, function(v) X.strict = v end)
	toggleRow("Log EVERYTHING during a move", "ON (default): every effect and sound that plays while an animation runs is attached to it, wherever it is (hits on enemies, projectiles, far away effects, sounds played by the game). OFF: only the move's own effects (see the option above).",
		function() return X.fxAll end, function(v) X.fxAll = v end)
	toggleRow("Log cutscenes", "ON (default): animations on other rigs are logged when they are a cutscene (named cutscene / cinematic / intro / outro..., or the game took over your camera). OFF: only your own character.",
		function() return X.cutscenes end, function(v) X.cutscenes = v end)
	toggleRow("Log movement", "ON (default): records how you moved (dash, rise...) while a move plays, so it can be replayed. OFF: no movement is logged and the \"Logged movement\" lines stop. Moves you already logged are kept.",
		function() return X.logMove end, function(v) X.logMove = v end)
	toggleRow("Auto-combine animations", "ON: when one of your animations starts right after another one ends (a move split into parts), they are joined into one animation and saved in Saved > Saved edits. Excluded animations are ignored. The gap and a manual Combine recent button are at the left of the folder row in the Saved tab.",
		function() return X.combo ~= nil and X.combo.on end, function(v) if X.combo then X.combo.on = v end end)
	toggleRow("Pause logging", "ON: nothing new is added to the lists (same as the Pause button).",
		function() return paused end, function(v) paused = v end)
	toggleRow("Compact mode", "ON: one line per entry, only the main buttons.",
		function() return X.compact end, function(v) X.setCompact(v) end)

	section("Player filter")
	do
		local b = row("Player filter", "Only log this player (name or display name, part of it is fine). Empty = use \"Own character only\".", 170)
		local tb = Instance.new("TextBox")
		tb.Size = b.Size
		tb.Position = b.Position
		tb.BackgroundColor3 = C.code
		tb.BorderSizePixel = 0
		tb.PlaceholderText = "everyone"
		tb.PlaceholderColor3 = C.sub
		tb.Text = X.filter
		tb.TextColor3 = C.text
		tb.Font = Th.font
		tb.TextSize = 16
		tb.ClearTextOnFocus = false
		tb.Parent = b.Parent
		b:Destroy()
		tb.FocusLost:Connect(function()
			local t = tb.Text:gsub("^%s+", "")
			t = t:gsub("%s+$", "")
			X.filter = t
			K.syncUI()
		end)
		syncFns[#syncFns + 1] = function()
			if not tb:IsFocused() then tb.Text = X.filter end
		end

		order += 1
		local holder = Instance.new("Frame")
		holder.Size = UDim2.new(1, -6, 0, 0)
		holder.AutomaticSize = Enum.AutomaticSize.Y
		holder.BackgroundColor3 = C.row2
		holder.BorderSizePixel = 0
		holder.LayoutOrder = order
		holder.Parent = sf
		local hp = Instance.new("UIPadding")
		hp.PaddingLeft = UDim.new(0, 8)
		hp.PaddingRight = UDim.new(0, 8)
		hp.PaddingTop = UDim.new(0, 8)
		hp.PaddingBottom = UDim.new(0, 8)
		hp.Parent = holder
		local grid = Instance.new("Frame")
		grid.Size = UDim2.new(1, 0, 0, 0)
		grid.AutomaticSize = Enum.AutomaticSize.Y
		grid.BackgroundTransparency = 1
		grid.Parent = holder
		local gl = Instance.new("UIGridLayout")
		gl.CellSize = UDim2.new(0.5, -3, 0, 30)
		gl.CellPadding = UDim2.new(0, 6, 0, 6)
		gl.SortOrder = Enum.SortOrder.LayoutOrder
		gl.Parent = grid

		local pbtns = {}
		local function rebuild()
			for _, c in ipairs(grid:GetChildren()) do
				if c:IsA("GuiButton") then c:Destroy() end
			end
			table.clear(pbtns)
			local list = { { label = "Everyone", name = "" } }
			for _, p in ipairs(Players:GetPlayers()) do
				list[#list + 1] = {
					label = p.DisplayName == p.Name and p.Name or (p.DisplayName .. " (@" .. p.Name .. ")"),
					name = p.Name,
				}
			end
			for i, it in ipairs(list) do
				if i > 41 then break end
				local pb = K.newButton(grid, it.label, C.btn)
				pb.LayoutOrder = i
				pb.TextTruncate = Enum.TextTruncate.AtEnd
				pb.MouseButton1Click:Connect(function()
					X.filter = it.name
					K.syncUI()
				end)
				pbtns[#pbtns + 1] = { pb, it.name }
			end
			K.syncUI()
		end
		syncFns[#syncFns + 1] = function()
			for _, it in ipairs(pbtns) do
				if it[1].Parent then K.paint(it[1], X.filter:lower() == it[2]:lower() and C.sel or C.btn) end
			end
		end
		table.insert(Run.conns, Players.PlayerAdded:Connect(function() task.defer(rebuild) end))
		table.insert(Run.conns, Players.PlayerRemoving:Connect(function() task.defer(rebuild) end))
		rebuild()
	end

	section("Effects and sounds")
	toggleRow("Catch Emit() / Play() calls", "ON: also catches particles and sounds the game fires by code. Needs an executor with hookmetamethod. Takes effect next time you run the script. Also needed for Block to stop them.",
		function() return X.deep end, function(v) X.deep = v end)
	toggleRow("Include hidden emitters", "ON: also adds particle emitters on your character that wait for the animation to fire them (they have an EmitCount attribute).",
		function() return X.thorough end, function(v) X.thorough = v end)
	toggleRow("Guess related effects", "ON: Full-FX-CUTSCENE also adds effects and sounds found in the same tool / folder as the animation or named like it. It is a guess, so it can add too much. Variants are left out unless \"Log move variants\" is ON.",
		function() return X.guess end, function(v) X.guess = v end)
	toggleRow("Log spawned objects + cutscene camera", "ON: records swords, dummies and parts that appear while a move plays, and cutscene camera moves. They appear in the FX Editor and in Full-FX-CUTSCENE.",
		function() return X.objOn end, function(v) X.objOn = v end)
	toggleRow("Log 2D cutscenes / GUI", "ON: records full-screen images, flashes, black bars, titles and other GUI that pops up during a move or cutscene (needs the option above). They are replayed by Full-FX-CUTSCENE.",
		function() return X.gui2d end, function(v) X.gui2d = v end)
	do
		local b, d = row("Look-back time", "How many seconds of effects before a move is detected still count as part of that move.", 100)
		b.MouseButton1Click:Connect(function()
			local opts = { 1, 2, 3, 5, 8, 10 }
			local i = table.find(opts, X.pre) or 0
			X.pre = opts[i % #opts + 1]
			K.syncUI()
		end)
		syncFns[#syncFns + 1] = function() b.Text = X.pre .. " s" end
	end

	section("Lag protection")
	toggleRow("Auto-protect", "ON: if the logger makes the game lag, it switches off the busiest part and tells you. OFF: it never switches anything off.",
		function() return X.guardOn end, function(v) X.guardOn = v end)
	for _, k in ipairs(X.GUARD_ORDER) do
		toggleRow(X.GUARD[k], "On = logging this. If Auto-protect turned it off, switch it back on here (or tap the red bar at the top).",
			function() return not X.off[k] end,
			function(v)
				if v then
					X.guardBack(k)
				else
					X.off[k], X.offWhy[k] = true, "turned off by you"
					X.guardBanner()
				end
			end)
	end

	section("Window")
	do
		local presets = { { "Small", 360, 300 }, { "Medium", 440, 380 }, { "Large", 720, 760 }, { "Fit screen" } }
		local b = row("Window size", "Drag the grip in the bottom-right corner to resize freely, or cycle through presets.", 130)
		syncFns[#syncFns + 1] = function() b.Text = presets[X.sizeIdx][1] end
		b.MouseButton1Click:Connect(function()
			X.sizeIdx = X.sizeIdx % #presets + 1
			local p = presets[X.sizeIdx]
			local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(900, 600)
			local w = p[2] or (vp.X - 20)
			local h = p[3] or (vp.Y - 20)
			w, h = math.min(w, vp.X - 10), math.min(h, vp.Y - 10)
			if not mainWin.hosted then
				mainWin.frame.Size = UDim2.fromOffset(w, h)
				mainWin.frame.Position = UDim2.fromOffset(math.max((vp.X - w) / 2, 0), math.max((vp.Y - h) / 2, 0))
			end
			K.syncUI()
		end)
	end

	section("Animation frames")
	toggleRow("Prepare frames automatically", "ON: builds the frame-by-frame data of every new move in the background, so Copy is instant.",
		function() return detailedMode end, function(v) detailedMode = v end)
	do
		local b, d = row("Script size / quality", QUALITY_INFO[QUALITY], 100)
		b.MouseButton1Click:Connect(cycleQuality)
		syncFns[#syncFns + 1] = function()
			b.Text = QUALITY
			d.Text = QUALITY_INFO[QUALITY] .. " - changes the next script you copy / view"
		end
	end

	section("Export")
	do
		local b = row("Download log", "Save the whole log + generated scripts to a .txt in your workspace folder.", 100)
		b.Text = "Download"
		b.MouseButton1Click:Connect(function()
			local lines = { "ANIM / VFX / SFX LOG - " .. os.date("%Y-%m-%d %H:%M:%S"), "" }
			for _, kind in ipairs({ "Anim", "VFX", "SFX", "OBJ" }) do
				table.insert(lines, "=== " .. kind:upper() .. " ===")
				for i, e in ipairs(exportLog[kind]) do
					table.insert(lines, string.format("[%d] %s\n%s\n", i, e.title, e.detail))
				end
				table.insert(lines, "")
			end
			local text = table.concat(lines, "\n")
			local name = "AnimVFX_Log_" .. os.date("%Y%m%d_%H%M%S") .. ".txt"
			if writefile then
				local ok, err = pcall(writefile, name, text)
				out(ok and ("Saved " .. name .. " (in your executor's workspace folder)") or ("Save failed: " .. tostring(err)))
				K.flash(b, ok and "Saved!" or "Fail")
			else
				toClip(text, "the log")
				K.flash(b, "Copied!")
			end
		end)
	end

	section("Reset")
	do
		local b = row("Reset Filters tab", "Brings back everything you excluded or blocked (animations, VFX and SFX).", 100)
		b.Text = "Reset"
		b.MouseButton1Click:Connect(function()
			table.clear(excluded)
			table.clear(excludedVFX)
			table.clear(excludedSFX)
			table.clear(blocked)
			table.clear(blockedLogged)
			table.clear(X.blockV)
			table.clear(X.blockS)
			task.spawn(function() pcall(X.blockApply) end)
			refreshAll()
			K.flash(b, "Done!")
		end)
	end
	do
		local b = row("Reset window", "Put this window back in the middle of the screen at its default size.", 100)
		b.Text = "Reset"
		b.MouseButton1Click:Connect(function()
			if not mainWin.hosted then
				mainWin.frame.Size = UDim2.fromOffset(440, 380)
				mainWin.frame.Position = UDim2.new(0.5, -220, 0.5, -190)
			end
			K.flash(b, "Done!")
		end)
	end
end

syncFns[#syncFns + 1] = function()
	for _, b in ipairs(X.compactButtons) do K.paint(b, X.compact and C.sel or C.btn) end
end

syncFns[#syncFns + 1] = function()
	for _, b in ipairs(pauseButtons) do
		b.Text = paused and "Resume" or "Pause"
		K.paint(b, paused and C.sel or C.btn)
	end
end

local function rebuildFilters()
	local sf = lists.Filters
	for _, c in ipairs(sf:GetChildren()) do
		if c:IsA("GuiObject") then c:Destroy() end
	end

	local order = 0
	local function header(text)
		order += 1
		local l = Instance.new("TextLabel")
		l.Size = UDim2.new(1, -6, 0, 28)
		l.BackgroundColor3 = C.title
		l.BorderSizePixel = 0
		l.LayoutOrder = order
		l.Text = text
		l.TextColor3 = C.text
		l.Font = Th.bold
		l.TextSize = 16
		l.TextXAlignment = Enum.TextXAlignment.Left
		local p = Instance.new("UIPadding")
		p.PaddingLeft = UDim.new(0, 8)
		p.Parent = l
		l.Parent = sf
	end

	local function addRow(kindColor, title, subtitle, btnText, onClick)
		order += 1
		local row = Instance.new("Frame")
		row.Size = UDim2.new(1, -6, 0, 52)
		row.BackgroundColor3 = order % 2 == 0 and C.row1 or C.row2
		row.BorderSizePixel = 0
		row.LayoutOrder = order
		row.Parent = sf

		local lbl = Instance.new("TextLabel")
		lbl.Size = UDim2.new(1, -92, 1, 0)
		lbl.BackgroundTransparency = 1
		lbl.RichText = true
		lbl.TextWrapped = true
		lbl.TextXAlignment = Enum.TextXAlignment.Left
		lbl.TextYAlignment = Enum.TextYAlignment.Top
		lbl.Font = Th.font
		lbl.TextSize = 16
		lbl.TextColor3 = C.text
		lbl.Text = string.format(
			'<font color="%s"><b>%s</b></font>\n<font color="%s">%s</font>',
			K.hex(kindColor), K.esc(title ~= "" and title or "(unnamed)"), K.hex(C.sub), K.esc(subtitle)
		)
		local pad = Instance.new("UIPadding")
		pad.PaddingLeft = UDim.new(0, 8)
		pad.PaddingTop = UDim.new(0, 3)
		pad.Parent = lbl
		lbl.Parent = row

		local b = K.newButton(row, btnText, C.btn)
		b.Size = UDim2.new(0, 82, 0, 32)
		b.Position = UDim2.new(1, -88, 0, 10)
		b.MouseButton1Click:Connect(onClick)
	end

	local total = K.countKeys(excluded) + K.countKeys(excludedVFX) + K.countKeys(excludedSFX) + K.countKeys(blocked)
		+ K.countKeys(X.blockV) + K.countKeys(X.blockS)
	if total == 0 then
		header("Nothing excluded or blocked")
		return
	end

	order += 1
	local resetAll = K.newButton(sf, "Reset all (unexclude + unblock everything)", C.danger)
	resetAll.Size = UDim2.new(1, -6, 0, 32)
	resetAll.LayoutOrder = order
	resetAll.MouseButton1Click:Connect(function()
		table.clear(excluded)
		table.clear(excludedVFX)
		table.clear(excludedSFX)
		table.clear(blocked)
		table.clear(blockedLogged)
		table.clear(X.blockV)
		table.clear(X.blockS)
		task.spawn(function() pcall(X.blockApply) end)
		refreshAll()
	end)

	if K.countKeys(excluded) > 0 then
		header("Excluded animations (" .. K.countKeys(excluded) .. ")")
		for id in pairs(excluded) do
			addRow(C.anim, animLabel[id] or "", id, "Unexcl", function()
				excluded[id] = nil
				refreshAll()
			end)
		end
	end
	if K.countKeys(blocked) > 0 then
		header("Blocked animations (" .. K.countKeys(blocked) .. ")")
		for id in pairs(blocked) do
			addRow(C.anim, animLabel[id] or "", id, "Unblock", function()
				blocked[id] = nil
				blockedLogged[id] = nil
				refreshAll()
			end)
		end
	end
	if K.countKeys(X.blockV) > 0 then
		header("Blocked VFX (" .. K.countKeys(X.blockV) .. ")  -  switched off in-game, left out of every script")
		for key in pairs(X.blockV) do
			addRow(C.vfx, vfxLabel[key] or key, key, "Unblock", function() X.blockToggle("v", key) end)
		end
	end
	if K.countKeys(X.blockS) > 0 then
		header("Blocked SFX (" .. K.countKeys(X.blockS) .. ")  -  stopped in-game, left out of every script")
		for id in pairs(X.blockS) do
			addRow(C.sfx, sfxLabel[id] or "", id, "Unblock", function() X.blockToggle("s", id) end)
		end
	end
	if K.countKeys(excludedVFX) > 0 then
		header("Excluded VFX (" .. K.countKeys(excludedVFX) .. ")")
		for key in pairs(excludedVFX) do
			addRow(C.vfx, vfxLabel[key] or key, key, "Unexcl", function()
				excludedVFX[key] = nil
				refreshAll()
			end)
		end
	end
	if K.countKeys(excludedSFX) > 0 then
		header("Excluded SFX (" .. K.countKeys(excludedSFX) .. ")")
		for id in pairs(excludedSFX) do
			addRow(C.sfx, sfxLabel[id] or "", id, "Unexcl", function()
				excludedSFX[id] = nil
				refreshAll()
			end)
		end
	end
end

refreshAll = function()
	for i = #updaters, 1, -1 do
		if not updaters[i]() then table.remove(updaters, i) end
	end
	local ex = K.countKeys(excluded) + K.countKeys(excludedVFX) + K.countKeys(excludedSFX)
	local bl = K.countKeys(blocked) + K.countKeys(X.blockV) + K.countKeys(X.blockS)
	tabButtons.Filters.Text = (ex + bl) > 0 and string.format("Filters (%d/%d)", ex, bl) or "Filters"
	rebuildFilters()
end

local selectedRow

local function addEntry(kind, key, title, detail, copyText, actions, titleColor)
	if not Run.alive or (paused and kind ~= "Search") then return end
	if uniqueOnly then
		if seenKeys[kind][key] then return end
		seenKeys[kind][key] = true
	end

	counter += 1

	local log = exportLog[kind]
	table.insert(log, { title = title, detail = detail, copy = copyText })
	if #log > MAX_EXPORT then table.remove(log, 1) end

	local base = counter % 2 == 0 and C.row1 or C.row2
	local row = Instance.new("Frame")
	row.Size = UDim2.new(1, -6, 0, 0)
	row.AutomaticSize = Enum.AutomaticSize.Y
	row.BackgroundColor3 = base
	row.BorderSizePixel = 0
	row.LayoutOrder = kind == "Search" and counter or -counter
	rowBase[row] = base
	searchOf[row] = (title .. " " .. detail):lower()
	row.Parent = lists[kind]
	local rowLayout = Instance.new("UIListLayout")
	rowLayout.Padding = UDim.new(0, 4)
	rowLayout.SortOrder = Enum.SortOrder.LayoutOrder
	rowLayout.Parent = row
	local rowPad = Instance.new("UIPadding")
	rowPad.PaddingBottom = UDim.new(0, 5)
	rowPad.Parent = row

	local label = Instance.new("TextButton")
	label.AutoButtonColor = false
	label.Size = UDim2.new(1, 0, 0, 0)
	label.AutomaticSize = Enum.AutomaticSize.Y
	label.BackgroundTransparency = 1
	label.RichText = true
	label.TextWrapped = true
	label.TextXAlignment = Enum.TextXAlignment.Left
	label.TextYAlignment = Enum.TextYAlignment.Top
	label.Font = Th.font
	label.TextSize = 16
	label.TextColor3 = C.text
	label.LayoutOrder = 1
	local labelPad = Instance.new("UIPadding")
	labelPad.PaddingLeft = UDim.new(0, 6)
	labelPad.PaddingTop = UDim.new(0, 4)
	labelPad.Parent = label
	label.Parent = row

	label.MouseButton1Click:Connect(function()
		if selectedRow and selectedRow.Parent then selectedRow.BackgroundColor3 = rowBase[selectedRow] end
		selectedRow = row
		row.BackgroundColor3 = C.sel
	end)

		local lastExtra, badge
	local lineFrames = {}
	local function render(extra)
		lastExtra = extra
		local tcol = K.hex(titleColor and Th.remap(titleColor) or C.text)
		local ttl = K.esc(title) .. (badge and string.format('  <font color="#8fd3ff">[%s]</font>', K.esc(badge)) or "")
		local text
		if X.compact then
			local first = detail:match("^[^\n]*") or detail
			text = string.format('<font color="%s"><b>%s</b></font>  <font color="%s">%s</font>', tcol, ttl, K.hex(C.sub), K.esc(first))
		else
			text = string.format(
				'<font color="%s"><b>%s</b></font>\n<font color="%s">%s</font>',
								tcol, ttl, K.hex(C.sub), K.esc(detail)
			)
			if extra then
				text ..= string.format('\n<font color="#8fd3ff">%s</font>', K.esc(extra))
			end
		end
		label.TextWrapped = not X.compact
		label.TextTruncate = X.compact and Enum.TextTruncate.AtEnd or Enum.TextTruncate.None
		label.Text = text
		for ln, f in pairs(lineFrames) do f.Visible = (not X.compact) or ln == 1 end
	end
	render()
	table.insert(Th.rerender, function()
		if not label.Parent then return false end
		render(lastExtra)
		return true
	end)

	local btnHost = Instance.new("Frame")
	btnHost.Size = UDim2.new(1, -8, 0, 0)
	btnHost.AutomaticSize = Enum.AutomaticSize.Y
	btnHost.BackgroundTransparency = 1
	btnHost.LayoutOrder = 2
	btnHost.Parent = row
	local hostLayout = Instance.new("UIListLayout")
	hostLayout.Padding = UDim.new(0, 4)
	hostLayout.SortOrder = Enum.SortOrder.LayoutOrder
	hostLayout.Parent = btnHost
	local hostPad = Instance.new("UIPadding")
	hostPad.PaddingLeft = UDim.new(0, 6)
	hostPad.Parent = btnHost

	local groups, lineNos = {}, {}
	for _, a in ipairs(actions) do
		local ln = a.line or 1
		if not groups[ln] then
			groups[ln] = {}
			lineNos[#lineNos + 1] = ln
		end
		table.insert(groups[ln], a)
	end
	table.sort(lineNos)

	for _, ln in ipairs(lineNos) do
		local list = groups[ln]
		local total = 0
		for _, a in ipairs(list) do total += (a.w or 1) end
		local gaps = 4 * (#list - 1)

		local lineFrame = Instance.new("Frame")
		lineFrame.Size = UDim2.new(1, 0, 0, 30)
		lineFrame.BackgroundTransparency = 1
		lineFrame.LayoutOrder = ln
		lineFrames[ln] = lineFrame
		lineFrame.Parent = btnHost
		local lineLayout = Instance.new("UIListLayout")
		lineLayout.FillDirection = Enum.FillDirection.Horizontal
		lineLayout.SortOrder = Enum.SortOrder.LayoutOrder
		lineLayout.Padding = UDim.new(0, 4)
		lineLayout.Parent = lineFrame

		for i, a in ipairs(list) do
			local frac = (a.w or 1) / total
			local b = K.newButton(lineFrame, a.text or "", a.color or C.btn)
			b.LayoutOrder = i
			b.Size = UDim2.new(frac, -gaps * frac, 1, 0)
			b.TextScaled = true
			local limit = Instance.new("UITextSizeConstraint")
			limit.MaxTextSize = 16
			limit.MinTextSize = 10
			limit.Parent = b

			if a.state then
				local function upd()
					if not b.Parent then return false end
					local txt, on = a.state()
					b.Text = txt
					K.paint(b, on and C.danger or Th.remap(a.color or C.btn))
					return true
				end
				upd()
				table.insert(updaters, upd)
			end

			b.MouseButton1Click:Connect(function()
				local ok, err = pcall(a.fn, b)
				if not ok then
					out("Error: " .. tostring(err))
					K.flash(b, "Fail")
				end
			end)
		end
	end

	render(lastExtra)

	local q = queues[kind]
	table.insert(q, row)
	if #q > (kind == "Search" and 8000 or MAX_ENTRIES) then
		table.remove(q, 1):Destroy()
	end
	updateTabText(kind)
	applyFilter(kind)

		return {
		setExtra = function(extra) if label.Parent then render(extra) end end,
		setBadge = function(b) if label.Parent and b ~= badge then badge = b render(lastExtra) end end,
	}
end

local function act(text, fn, color, line, w)
	return { text = text, fn = fn, color = color, line = line, w = w }
end

local function copyAct(text, getText, what, line, w)
	return act(text, function(btn)
		toClip(getText(), what)
		K.flash(btn, "Copied!")
	end, nil, line, w)
end

local function runAct(runFn, line, w)
	return act("Run", function(btn)
		local ok, err = pcall(runFn)
		if not ok then out("Run failed: " .. tostring(err)) end
		K.flash(btn, ok and "Ran!" or "Fail")
	end, C.green, line, w)
end

local function extraFor(id)
	local parts = {}
	if details[id] then
		local ok, s = pcall(K.summaryFor, id)
		if ok then parts[#parts + 1] = s end
	elseif detailErr[id] then
		parts[#parts + 1] = "Frame-by-frame failed: " .. detailErr[id]
	end
	local fx = animFX[id]
	if fx and #fx > 0 then
		local v, s, o = 0, 0, 0
		for _, e in ipairs(fx) do
			if e.kind == "vfx" then v += 1 elseif e.kind == "sfx" then s += 1 elseif e.kind == "obj" or e.kind == "gui" then o += 1 end
		end
		parts[#parts + 1] = string.format("FX seen with this anim: %d VFX, %d SFX%s", v, s, o > 0 and (", " .. o .. " objects") or "")
	end
	return #parts > 0 and table.concat(parts, "\n") or nil
end

X.fxN = X.fxN or {}
local function badgeFor(id)
	local v, s, o = 0, 0, 0
	local fx = animFX[id]
	if fx and #fx > 0 then
		for _, e in ipairs(fx) do
			if e.kind == "vfx" then v += 1 elseif e.kind == "sfx" then s += 1 elseif e.kind == "obj" or e.kind == "gui" then o += 1 end
		end
	elseif X.fxN[id] then
		v, s = X.fxN[id].v, X.fxN[id].s
	else
		return nil
	end
	if o > 0 then return string.format("%d fx: %d vfx, %d sfx, %d obj", v + s + o, v, s, o) end
	return string.format("%d fx: %d vfx, %d sfx", v + s, v, s)
end

local function refreshExtra(id)
	local text = extraFor(id)
	local b = badgeFor(id)
	for _, ent in ipairs(entriesById[id] or {}) do
		if b and ent.setBadge then pcall(ent.setBadge, b) end
		if text then pcall(ent.setExtra, text) end
	end
end

local function sendProgress(id, text)
	for _, f in ipairs(progressListeners[id] or {}) do pcall(f, text) end
end

local function requestDetail(id, cb, progress)
	if details[id] then
		if cb then cb(true, details[id]) end
		return
	end
	local savedSrc = (X.skipSaved ~= id) and (X.eds.items[id] or X.kept[id]) or nil
	if savedSrc and X.edsApply then
		pcall(X.edsApply, id, savedSrc)
		if details[id] then
			if cb then cb(true, details[id]) end
			return
		end
	end
	if progress then
		progressListeners[id] = progressListeners[id] or {}
		table.insert(progressListeners[id], progress)
		progress("Waiting...")
	end
	local job = detailJobs[id]
	if job then
		if cb then table.insert(job, cb) end
		return
	end
	detailJobs[id] = { cb }
	table.insert(detailQueue, id)

	if detailWorking then return end
	detailWorking = true
	task.spawn(function()
		while #detailQueue > 0 do
			local nextId = table.remove(detailQueue, 1)
			local ok, res = pcall(K.captureDetail, nextId, function(t) sendProgress(nextId, t) end)
			local callbacks = detailJobs[nextId]
			detailJobs[nextId] = nil
			if ok then
				details[nextId] = res
				detailErr[nextId] = nil
				if X.origRemember then pcall(X.origRemember, nextId) end
				sendProgress(nextId, "Simplifying frames...")
				pcall(K.simplified, nextId)
			else
				detailErr[nextId] = tostring(res)
			end
			progressListeners[nextId] = nil
			refreshExtra(nextId)
			for _, f in ipairs(callbacks or {}) do pcall(f, ok, res) end
		end
		detailWorking = false
	end)
end

local function requestRbxmx(id, cb)
	requestDetail(id, function(ok, res)
		if not ok then return cb(false, res) end
		local cached = rbxmxCache[id]
		if cached then return cb(true, cached.xml, cached.source) end
		local okX, xml = pcall(K.rbxmxFromCapture, "Anim_" .. (id:match("%d+") or "x"), res.looped, res.priorityValue, res.allMotors)
		if not okX then return cb(false, xml) end
		rbxmxCache[id] = { xml = xml, source = "captured" }
		cb(true, xml, "captured")
	end)
end

local FX_POST = 2.5
fxWindows.buf = {}
fxWindows.related = {}
fxWindows.pend = setmetatable({}, { __mode = "k" })
fxWindows.dflt = setmetatable({}, { __mode = "k" })

fxWindows.pos = function(inst)
	if inst:IsA("Model") then
		local okM, cf = pcall(inst.GetPivot, inst)
		if okM and cf then return cf.Position end
	elseif inst:IsA("Tool") or inst:IsA("Accoutrement") then
		local h = inst:FindFirstChild("Handle")
		if h and h:IsA("BasePart") then return h.Position end
	end
	local part = inst:IsA("BasePart") and inst or inst:FindFirstAncestorWhichIsA("BasePart")
	if part then return part.Position end
	local m = inst:FindFirstAncestorOfClass("Model")
	if m then
		local ok, p = pcall(m.GetPivot, m)
		if ok then return p.Position end
	end
	return nil
end

function X.noteBig(w, inst)
	local mag = 0
	if inst:IsA("BasePart") then
		mag = inst.Size.Magnitude
	elseif inst:IsA("Model") then
		local ok, _, sz = pcall(inst.GetBoundingBox, inst)
		if ok and sz then mag = sz.Magnitude end
	end
	if mag > 40 and #w.big < 12 then w.big[#w.big + 1] = inst end
end

local function insideBig(w, inst, pos)
	for i = 1, #w.big do
		local b = w.big[i]
		if b.Parent then
			if inst ~= b and inst:IsDescendantOf(b) then return true end
			if pos then
				local cf, size
				if b:IsA("BasePart") then
					cf, size = b.CFrame, b.Size
				elseif b:IsA("Model") then
					local ok, c2, s2 = pcall(b.GetBoundingBox, b)
					if ok then cf, size = c2, s2 end
				end
				if cf and size then
					local rel = cf:PointToObjectSpace(pos)
					if math.abs(rel.X) <= size.X / 2 + 3 and math.abs(rel.Y) <= size.Y / 2 + 3 and math.abs(rel.Z) <= size.Z / 2 + 3 then return true end
				end
			end
		end
	end
	return false
end

local function fxBelongs(inst, w, pos)
	if inst:IsDescendantOf(w.model) then return true end
	if w.looped and not w.cut then return false end
	if w.big and #w.big > 0 then
		if pos == nil then pos = fxWindows.pos(inst) end
		if insideBig(w, inst, pos) then return true end
	end
	if inst:IsA("GuiBase2d") then return w.model == lp.Character or w.cut == true end
	if X.fxAll then
		if w.cut then return true end
		if inst:IsA("Sound") then
			local okL, lp2 = pcall(function() return inst.Looped end)
			if okL and lp2 then return false end
		end
		local m = inst:FindFirstAncestorOfClass("Model")
		while m do
			if m ~= w.model then
				local pl = Players:GetPlayerFromCharacter(m)
				if pl then return false end
			end
			m = m.Parent and m.Parent:FindFirstAncestorOfClass("Model")
		end
		if pos == nil then pos = fxWindows.pos(inst) end
		local root = w.model:FindFirstChild("HumanoidRootPart")
		if pos ~= nil and root and (pos - root.Position).Magnitude > 250 then return false end
		if pos == nil and inst:IsA("Sound") then
			local okT, tl = pcall(function() return inst.TimeLength end)
			if okT and tl > 12 then return false end
		end
		return true
	end
	if X.strict then
		local m = inst:FindFirstAncestorOfClass("Model")
		while m do
			if m ~= w.model and m:FindFirstChildOfClass("Humanoid") then return false end
			m = m.Parent and m.Parent:FindFirstAncestorOfClass("Model")
		end
	end
	if pos == nil then pos = fxWindows.pos(inst) end
	if pos == nil then return (inst:IsA("Sound") or inst:IsA("PostEffect") or inst:IsA("Atmosphere")) and w.model == lp.Character end
	local root = w.model:FindFirstChild("HumanoidRootPart")
	if not root then return false end
	local d = (pos - root.Position).Magnitude
	local isObj = inst:IsA("Model") or inst:IsA("BasePart") or inst:IsA("Tool") or inst:IsA("Accoutrement") or inst:IsA("Folder")
	local lim = X.strict and 16 or (isObj and 150 or 60)
	if d > lim then return false end
	local near = X.strict and 8 or 30
	for _, p in ipairs(Players:GetPlayers()) do
		local ch = p.Character
		local r = ch and ch ~= w.model and ch:FindFirstChild("HumanoidRootPart")
		if r then
			local od = (pos - r.Position).Magnitude
			if od < d and od < near then return false end
		end
	end
	return true
end

fxWindows.dur = function(inst, ev, since)
	if ev.kind ~= "vfx" or not ev.enabled or ev.dur then return end
	local function ended()
		if not ev.dur or fxWindows.dflt[ev] then
			ev.dur = math.max(os.clock() - since, 0.1)
			fxWindows.dflt[ev] = nil
		end
	end
	inst.Destroying:Connect(ended)
	pcall(function()
		inst:GetPropertyChangedSignal("Enabled"):Connect(function()
			if not inst.Enabled then ended() end
		end)
	end)
end

fxWindows.durSfx = function(inst, ev, since)
	if not ev.dur then
		task.spawn(function()
			for _ = 1, 40 do
				local ok, len = pcall(function() return inst.TimeLength end)
				if ok and len and len > 0 then
					if not ev.dur then
						local okL, looped = pcall(function() return inst.Looped end)
						if not (okL and looped) then
							local sp, pos = 1, 0
							pcall(function() sp = math.max(inst.PlaybackSpeed, 0.1) end)
							pcall(function() pos = math.min(inst.TimePosition, len) end)
							ev.dur = math.max((len - pos) / sp, 0.05)
						end
					end
					return
				end
				task.wait(0.1)
			end
		end)
	end
	local conns = {}
	local function done()
		for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
		local d = os.clock() - since
		if d > 0.05 and (not ev.dur or d < ev.dur or fxWindows.dflt[ev]) then
			ev.dur = d
			fxWindows.dflt[ev] = nil
		end
	end
	pcall(function() conns[#conns + 1] = inst.Stopped:Connect(done) end)
	pcall(function() conns[#conns + 1] = inst.Ended:Connect(done) end)
	pcall(function() conns[#conns + 1] = inst.Destroying:Connect(done) end)
end

function X.fxAlive(w)
	if w.looped and not w.cut then return false end
	for _, it in ipairs(w.live) do
		local inst, ev = it.inst, it.ev
		if inst and inst.Parent then
			if ev.kind == "vfx" then
				local ok, en = pcall(function() return inst.Enabled end)
				if ok and en == true and not ev.dur then return true end
			elseif ev.kind == "obj" then
				if not ev.dur and not inst:IsDescendantOf(w.model) and not inst:IsA("Tool") and not inst:IsA("Accoutrement") then return true end
			elseif ev.kind == "sfx" then
				local ok, pl = pcall(function() return inst.IsPlaying and not inst.Looped end)
				if ok and pl then return true end
			end
		end
	end
	return false
end

local function evKey(e)
	if e.kind == "cam" then return "cam|" .. tostring(e.segId or math.floor(e.t * 2 + 0.5)) end
	local id = ""
	for _, p in ipairs(e.props or {}) do
		if p[1] == "SoundId" or p[1] == "Texture" then
			id = p[2]
			break
		end
	end
	local bucket = (e.emit and not e.enabled) and 20 or 2
	local mk = ""
	if e.mount and e.mount.cf then
		local mp = e.mount.cf.Position
		mk = (e.mount.part or "w") .. "@" .. math.floor(mp.X + 0.5) .. "," .. math.floor(mp.Y + 0.5) .. "," .. math.floor(mp.Z + 0.5)
	end
	return string.format("%s|%s|%s|%s|%s|%d", e.kind, tostring(e.class), tostring(e.name), id, mk, math.floor(e.t * bucket + 0.5))
end

fxWindows.merge = function(...)
	local out, seen, ncam, near = {}, {}, 0, {}
	for i = 1, select("#", ...) do
		local list = select(i, ...)
		for _, e in ipairs(list or {}) do
			local k = evKey(e)
			local isCam = e.kind == "cam"
			local base, dupNear = (k:gsub("|%-?%d+$", "")), false
			if not isCam and not (e.emit and not e.enabled) then
				for _, tt in ipairs(near[base] or {}) do
					if math.abs(tt - (e.t or 0)) < 0.35 then dupNear = true break end
				end
			end
			if not seen[k] and not dupNear and (isCam and ncam < 16 or (not isCam and #out - ncam < 800)) and (not isCam or K.camKeep(e)) then
				seen[k] = true
				near[base] = near[base] or {}
				near[base][#near[base] + 1] = e.t or 0
				if isCam then ncam += 1 end
				local c = table.clone(e)
				local src = fxWindows.pend[e] or e
				if (not c.dur or fxWindows.dflt[e]) and src.dur then
					c.dur = src.dur
				elseif not c.dur or fxWindows.dflt[e] then
					fxWindows.pend[c] = src
					fxWindows.dflt[c] = true
				end
				if not c.dur then c.dur = c.kind == "sfx" and 3 or (c.kind == "obj" and 2.5 or (c.enabled and 1.5 or 1)) end
				if c.kind == "cam" and c.cam and #c.cam > 0 then c.dur = c.cam[#c.cam][1] end
				if c.kind == "gui" and c.gui then c.dur = math.max(c.gui.dur or 3, 0.3) end
				out[#out + 1] = c
			end
		end
	end
	table.sort(out, function(x, y) return x.t < y.t end)
	return out
end

fxWindows.rawFor = function(id)
	local old, rel, extra = animFX[id], fxWindows.related[id], {}
	for _, w in ipairs(fxWindows) do
		if w.id == id and #w.events > 0 then extra[#extra + 1] = w.events end
	end
	if not old and #extra == 0 and not (rel and #rel > 0) then return nil end
	return fxWindows.merge(old, rel, table.unpack(extra))
end

fxWindows.liveFor = function(id)
	local src = X.fxEdit[id] or fxWindows.rawFor(id)
	if not src then return nil end
	local out = {}
	for _, e in ipairs(src) do
		if not e.off and not X.fxBlocked(e) then out[#out + 1] = e end
	end
	return #out > 0 and out or nil
end

fxWindows.durObj = function(inst, ev, since)
	local function ended()
		if not ev.dur or fxWindows.dflt[ev] then
			ev.dur = math.max(os.clock() - since, 0.1)
			fxWindows.dflt[ev] = nil
		end
	end
	inst.Destroying:Connect(ended)
	inst.AncestryChanged:Connect(function(_, parent)
		if not parent then ended() end
	end)
	if (ev.mount and ev.mount.part) or not ev._root0 then return end
	local root0 = ev._root0
	local path = { { 0, ev.rel } }
	ev.path = path
	task.spawn(function()
		local t0 = os.clock()
		while inst.Parent and not ev.dur and os.clock() - t0 < 10 and #path < 200 do
			task.wait(0.05)
			local pv = inst.Parent and K.objPivot(inst)
			if pv then
				local rel = root0:ToObjectSpace(pv)
				if (rel.Position - path[#path][2].Position).Magnitude > 0.2 or (rel.LookVector - path[#path][2].LookVector).Magnitude > 0.1 then path[#path + 1] = { os.clock() - t0, rel } end
			end
		end
	end)
end

local function recordFX(kind, inst, extra, at)
	if kind == "sfx" and tostring(inst.SoundId):find("^rbxasset://sounds/") then return end
	if kind == "sfx" and X.blockS[inst.SoundId] then return end
	if kind == "vfx" and next(X.blockV) ~= nil then
		local okK, bk = pcall(X.vfxBlockKey, inst)
		if okK and bk and X.blockV[bk] then return end
	end
	local now = at or os.clock()
	local build = kind == "vfx" and K.buildVFXEvent or (kind == "obj" and K.buildObjEvent or (kind == "gui" and K.buildGuiEvent or K.buildSFXEvent))
	local function applyExtra(ev)
		if extra then
			for k, v in pairs(extra) do ev[k] = v end
		end
	end

	local root = K.getRoot()
	local pos = fxWindows.pos(inst)
	if root and (X.fxAll or kind == "gui" or (pos and (pos - root.Position).Magnitude < 150) or (pos == nil and kind == "sfx")) then
		local mdl = inst:FindFirstAncestorOfClass("Model") or lp.Character
		local ok, ev = pcall(build, inst, mdl, 0)
		if ok and ev then
			applyExtra(ev)
			fxWindows.dur(inst, ev, now)
			if kind == "obj" then fxWindows.durObj(inst, ev, now) end
			if kind == "sfx" then fxWindows.durSfx(inst, ev, now) end
			local buf = fxWindows.buf
			buf[#buf + 1] = { kind = kind, ev = ev, at = now, pos = pos, inst = inst }
			while #buf > 800 or (buf[1] and now - buf[1].at > X.pre + 3) do table.remove(buf, 1) end
		end
	end

	if #fxWindows == 0 then return end
	for _, w in ipairs(fxWindows) do
		if now >= w.opened and now <= w.finish and fxBelongs(inst, w, pos) then
			local ok, ev = pcall(build, inst, w.model, math.max(now - w.start, 0))
			if ok and ev then
				applyExtra(ev)
				table.insert(w.events, ev)
				fxWindows.dur(inst, ev, now)
				if kind == "obj" then
					fxWindows.durObj(inst, ev, now)
					X.noteBig(w, inst)
				end
				if kind == "sfx" then fxWindows.durSfx(inst, ev, now) end
				if #w.live < 600 then w.live[#w.live + 1] = { inst = inst, ev = ev } end
			end
		end
	end
end

local function finalizeFX(w)
	if w.conn then pcall(function() w.conn:Disconnect() end) end
	if w.camConn then pcall(function() w.camConn:Disconnect() end) end
	for _, it in ipairs(w.live or {}) do
		local ev = it.ev
		if not ev.dur and it.inst and it.inst.Parent then
			ev.dur = math.max(os.clock() - (w.start + (ev.t or 0)), 0.3)
			fxWindows.dflt[ev] = true
		end
	end
	if #w.keys > 0 then
		local have = X.markers[w.id]
		if not have or #w.keys > #have then X.markers[w.id] = w.keys end
	end
	if #w.events == 0 then return end
	animFX[w.id] = fxWindows.merge(animFX[w.id], w.events)
	refreshExtra(w.id)
end

local function openFXWindow(id, animator, track)
	local model = animator:FindFirstAncestorOfClass("Model") or (animator.Parent and animator.Parent.Parent) or animator.Parent
	if not model or #fxWindows >= 20 then return end
	local now = os.clock()
	local len = math.min(math.max(track.Length, 0.5), 15)
	X.lens[id] = track.Length
	local into = 0
	pcall(function() into = math.clamp(track.TimePosition, 0, len) end)
	local w = {
		id = id, model = model, events = {}, keys = {},
		looped = track.Looped == true, cut = X.cutIds[id] == true,
		start = now - into,
		opened = now,
		finish = now + math.max(len - into, 0) + (X.fxAll and 6 or FX_POST),
		live = {}, big = {},
	}
	table.insert(fxWindows, w)
	X.lastAnim = { id = id, start = w.start }
	X.winLog[#X.winLog + 1] = { id = id, start = w.start, finish = w.finish }
	while #X.winLog > 16 do table.remove(X.winLog, 1) end
	if X.objOn then
		for _, sg in ipairs(X.camSegs) do
			if sg.start >= w.start - X.pre - 1 and sg.start <= w.finish then
				sg.attached = true
				local cl = table.clone(sg.ev)
				cl.t = math.max(sg.start - w.start, 0)
				table.insert(w.events, cl)
			end
		end
	end
	pcall(function()
		w.conn = track.KeyframeReached:Connect(function(name)
			w.keys[#w.keys + 1] = { name, os.clock() - w.start }
		end)
	end)

	for _, item in ipairs(fxWindows.buf) do
		if item.at >= w.start - 0.3 and item.at < now and fxBelongs(item.inst, w, item.pos) then
			local ev = table.clone(item.ev)
			ev.t = math.max(item.at - w.start, 0)
			table.insert(w.events, ev)
			fxWindows.pend[ev] = fxWindows.pend[item.ev] or item.ev
			w.live[#w.live + 1] = { inst = item.inst, ev = ev }
			if item.kind == "obj" then X.noteBig(w, item.inst) end
		end
	end

	local n = w.looped and 60 or 0
	for _, d in ipairs(model:GetDescendants()) do
		if n >= 60 then break end
		local cls = d.ClassName
		if d:GetAttribute("_LoggerClone") or d:GetAttribute("_Replay") then
		elseif cls == "Sound" then
			local okS, playing = pcall(function() return d.Playing and not d.Looped and d.SoundId ~= "" and not d.SoundId:find("^rbxasset://sounds/") and d.TimePosition <= into + 0.6 end)
			if okS and playing then
				local ok, ev = pcall(K.buildSFXEvent, d, model, 0)
				if ok and ev then
					n += 1
					table.insert(w.events, ev)
					fxWindows.durSfx(d, ev, now)
					w.live[#w.live + 1] = { inst = d, ev = ev }
				end
			end
		elseif VFX_CLASSES[cls] then
			local okE, en = pcall(function() return d.Enabled end)
			if okE and en and X.fxAll then
				local ok, ev = pcall(K.buildVFXEvent, d, model, 0)
				if ok and ev then
					n += 1
					fxWindows.dur(d, ev, now)
					table.insert(w.events, ev)
					w.live[#w.live + 1] = { inst = d, ev = ev }
				end
			elseif cls == "ParticleEmitter" and X.thorough and d:GetAttribute("EmitCount") then
				local ok, ev = pcall(K.buildVFXEvent, d, model, tonumber(d:GetAttribute("EmitDelay")) or 0)
				if ok and ev then
					n += 1
					table.insert(w.events, ev)
				end
			end
		end
	end

	task.spawn(function()
		while Run.alive do
			task.wait(0.25)
			local t = os.clock()
			if t >= w.finish then
				if t - w.start < 120 and X.fxAlive(w) then w.finish = t + 0.8 else break end
			end
		end
		task.wait(0.3)
		local i = table.find(fxWindows, w)
		if i then table.remove(fxWindows, i) end
		finalizeFX(w)
	end)
end

function X.inWindow()
	for _, w in ipairs(fxWindows) do
		if not (w.looped and not w.cut) then return true end
	end
	return false
end

function X.inCutscene()
	if X.camSeg then return true end
	for _, w in ipairs(fxWindows) do
		if w.cut then return true end
	end
	return false
end

function X.guiWatchStart()
	local pg = lp:WaitForChild("PlayerGui")
	local wired = setmetatable({}, { __mode = "k" })
	local pending = setmetatable({}, { __mode = "k" })
	local recent = setmetatable({}, { __mode = "k" })
	local nconn = 0
	local function keep(c)
		nconn += 1
		if nconn < 3000 then table.insert(Run.conns, c) end
		return c
	end
	local function mine(o)
		if o == gui or o:IsDescendantOf(gui) then return true end
		local sgA = o:IsA("ScreenGui") and o or o:FindFirstAncestorOfClass("ScreenGui")
		if sgA and (sgA:GetAttribute("_Replay") or sgA:GetAttribute("_LoggerClone")) then return true end
		return false
	end
	local function appeared(target)
		if not (X.gui2d and X.objOn) or pending[target] or not target.Parent then return end
		if mine(target) then return end
		local now = os.clock()
		local p = target.Parent
		for _ = 1, 8 do
			if not p or p == pg then break end
			if recent[p] and now - recent[p] < 1.5 then return end
			p = p.Parent
		end
		recent[target] = now
		pending[target] = true
		task.delay(0.3, function() pending[target] = nil end)
		task.defer(function()
			if not target.Parent then return end
			X.guiCache[target] = nil
			pcall(recordFX, "gui", target, nil, now)
		end)
	end
	local function wire(o, depth)
		if wired[o] then return end
		wired[o] = true
		keep(o:GetPropertyChangedSignal("Visible"):Connect(function()
			if o.Visible then appeared(o) end
		end))
		if depth < 3 then
			for _, ch in ipairs(o:GetChildren()) do
				if ch:IsA("GuiObject") then wire(ch, depth + 1) end
			end
			keep(o.ChildAdded:Connect(function(ch)
				if ch:IsA("GuiObject") then
					wire(ch, depth + 1)
					appeared(ch)
				end
			end))
		end
	end
	local function wireSg(sg, fresh)
		if not sg:IsA("ScreenGui") or wired[sg] then return end
		wired[sg] = true
		keep(sg:GetPropertyChangedSignal("Enabled"):Connect(function()
			if sg.Enabled then appeared(sg) end
		end))
		for _, ch in ipairs(sg:GetChildren()) do
			if ch:IsA("GuiObject") then wire(ch, 1) end
		end
		keep(sg.ChildAdded:Connect(function(ch)
			if ch:IsA("GuiObject") then
				wire(ch, 1)
				appeared(ch)
			end
		end))
		if fresh and sg.Enabled then appeared(sg) end
	end
	for _, sg in ipairs(pg:GetChildren()) do wireSg(sg, false) end
	keep(pg.ChildAdded:Connect(function(ch) wireSg(ch, true) end))
end
task.spawn(function() pcall(X.guiWatchStart) end)

local watched = {}

local function stopAnimId(id)
	local n = 0
	for animator in pairs(watched) do
		for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
			if tr.Animation and tr.Animation.AnimationId == id then
				tr:Stop(0)
				n += 1
			end
		end
	end
	return n
end

stopMineFn = function()
	local n = 0
	local char = lp.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	local animator = hum and hum:FindFirstChildOfClass("Animator")
	if animator then
		for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
			if ownTracks[tr] then
				tr:Stop(0)
				n += 1
			end
		end
	end
	if _G.StopRecreatedAnim then
		if pcall(_G.StopRecreatedAnim) then n += 1 end
		_G.StopRecreatedAnim = nil
	end
	return n
end

do
	local Lg = (getgenv and getgenv() or _G).__RPP_Logger
	if Lg then
