local function openAnimViewer(id)
	local live = fxWindows.liveFor(id)
	local hasFX = live and #live > 0
	local function variant(name, mode, w)
		return { name = name, w = w, get = function(cb, setStatus)
			requestDetail(id, function(ok, res)
				if ok then
					local okC, code = pcall(K.buildAnimCode, id, mode)
					if okC then cb(code) else cb(nil, code) end
				else
					cb(nil, res)
				end
			end, setStatus)
		end }
	end
	openViewer("Anim - " .. (animLabel[id] or id), {
		variant("Frame by frame", nil, 112),
		variant("Full - VFX", "vfx", 84),
		variant("Full - SFX", "sfx", 84),
		variant("Full - FX", "fx", 78),
		variant("Full - Camera", "cam", 100),
		variant("Full - Objects", "obj", 100),
		variant("Full - GUI", "gui", 90),
		variant("Full-FX-Cutscenes", "cut", 138),
		variant("Full-Everything", "all", 122),
		variant("Loop (repeat forever)", "loop", 140),
		variant("Exact steps (no blend)", "exact", 140),
		{ name = "Move only", w = 90, get = function(cb)
			local ok, code = pcall(X.genMoveOnly, id)
			if ok then cb(code) else cb(nil, "No movement logged for this animation. Do the move (dash, rise...) while it plays, then reopen this.") end
		end },
		{ name = "Simple", w = 66, get = function(cb) cb(K.simpleCode(id)) end },
	}, hasFX and 4 or 1, id)
end

