	tl.Parent = tools
	local pad = Instance.new("UIPadding")
	pad.PaddingLeft, pad.PaddingRight, pad.PaddingTop, pad.PaddingBottom = UDim.new(0, 6), UDim.new(0, 6), UDim.new(0, 4), UDim.new(0, 6)
	pad.Parent = tools

	local ord = 0
	local function section(tab, title, hint)
		ord += 1
		local h = Instance.new("TextLabel")
		h.Size = UDim2.new(1, 0, 0, hint and 34 or 20)
		h.BackgroundTransparency = 1
		h.RichText = true
		h.Text = string.format("<b>%s</b>%s", title, hint and ('\n<font color="' .. K.hex(C.sub) .. '">' .. hint .. "</font>") or "")
		h.TextColor3 = C.anim
		h.Font = Th.font
		h.TextSize = 15
		h.TextXAlignment = Enum.TextXAlignment.Left
		h.TextWrapped = true
		h.LayoutOrder = ord
		h.Parent = tools
		A.tabs[tab] = A.tabs[tab] or {}
		table.insert(A.tabs[tab], h)
		ord += 1
		local g = Instance.new("Frame")
		g.Size = UDim2.new(1, 0, 0, 0)
		g.AutomaticSize = Enum.AutomaticSize.Y
		g.BackgroundTransparency = 1
		g.LayoutOrder = ord
		g.Parent = tools
		table.insert(A.tabs[tab], g)
		local gl = Instance.new("UIGridLayout")
		gl.CellSize = UDim2.new(0.5, -3, 0, 34)
		gl.CellPadding = UDim2.new(0, 6, 0, 6)
