	end

	local g = section("Clips", "Clips (like CapCut)", "1) Tap the timeline to put the red playhead where you want to cut. 2) Press Split. 3) Tap a clip to select it, drag it to re-order, drag its white edges to trim. Delete / reverse / speed apply to the selected clip.")
	tool(g, "Split at playhead", C.sel, function() X.aeSplit(A) end)
