	g = section("Cut", "Quick cut", "Set Start / End with the boxes above (or tap the timeline and press Set [ / Set ]). Thin lines on the timeline mark them.")
	tool(g, "Keep selection only", C.sel, function() X.aeTrim(A, A.a, A.b) end)
	tool(g, "Delete selection", C.danger, function() X.aeCutOut(A, A.a, A.b) end)
	tool(g, "Cut everything before playhead", C.btn, function() X.aeTrim(A, A.head, A.len) end)
	tool(g, "Cut everything after playhead", C.btn, function() X.aeTrim(A, 0, A.head) end)
	tool(g, "Play selection", C.green, function() X.aePlay(A, A.a, A.b) end)
	tool(g, "Select all", C.btn, function()
		A.a, A.b = 0, A.len
