-- ===== v4: file download, saved folders, NPC hit capture =====

function X.saveScriptFile(code, defaultName, btn)
	if not writefile then
		toClip(code, "the script (this executor cannot save files)")
		if btn and btn.Parent then K.flash(btn, "Copied") end
		return
	end
	X.prompt("Name for the file", defaultName or "Script", function(text)
		local nm = tostring(text or ""):gsub("[^%w%-_ %.]", ""):gsub("^%s+", ""):gsub("%s+$", "")
		nm = nm:gsub("%.lua$", ""):gsub("%.txt$", "")
		if nm == "" then nm = defaultName or "Script" end
		local dir = "RecorderPP_Scripts"
		pcall(function()
			if makefolder and not (isfolder and isfolder(dir)) then makefolder(dir) end
		end)
		local path = dir .. "/" .. nm .. ".lua"
		if isfile then
			local n = 1
			while isfile(path) and n < 500 do
				n += 1
				path = dir .. "/" .. nm .. " (" .. n .. ").lua"
			end
		end
		local ok, err = pcall(writefile, path, code)
		out(ok and ("Saved " .. path .. " (in your executor's workspace folder)") or ("Save failed: " .. tostring(err)))
		if btn and btn.Parent then K.flash(btn, ok and "Saved!" or "Fail") end
		if ok then
			pcall(X.confirm, "File saved", "Your executor's workspace folder, inside:\n" .. path .. "\n(Not your phone Downloads. Press Copy script if you can't find it.)", function()
				toClip(code, "the script")
			end, "Copy script")
		end
	end)
end

-- ---------- edit a saved animation in the Anim Editor ----------
function X.svEditAnim(id, btn)
	local src = X.eds.items[id] or X.kept[id]
	if src and src.anim then pcall(X.edsApply, id, src) end
	if btn and btn.Parent then K.flash(btn, "Opening") end
	X.aeOpen(id)
end

-- ---------- saved folders ----------
X.sv.folders = X.sv.folders or {}

function X.svFolderClean(name)
	name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
	return name:sub(1, 24)
end

function X.svFolderExists(name)
	for _, f in ipairs(X.sv.folders) do
		if f == name then return true end
	end
	return false
end

function X.svFolderAdd(name)
	name = X.svFolderClean(name)
	if name == "" then return nil end
	if not X.svFolderExists(name) then table.insert(X.sv.folders, name) end
	X.svAfter()
	return name
end

function X.svFolderOk(r)
	local f = X.svFolder
	if f == nil then return true end
	if f == "" then return r.folder == nil or r.folder == "" end
	return r.folder == f
end

function X.svMove(r, folder)
	if folder == "" then folder = nil end
	r.folder = folder
	X.svAfter()
end

function X.svFolderRename(old, new)
	new = X.svFolderClean(new)
	if new == "" or new == old or X.svFolderExists(new) then return end
	for i, f in ipairs(X.sv.folders) do
		if f == old then X.sv.folders[i] = new end
	end
	for _, r in ipairs(X.sv.list) do
		if r.folder == old then r.folder = new end
	end
	if X.svFolder == old then X.svFolder = new end
	X.svAfter()
end

function X.svFolderDelete(old)
	local i = table.find(X.sv.folders, old)
	if i then table.remove(X.sv.folders, i) end
	for _, r in ipairs(X.sv.list) do
		if r.folder == old then r.folder = nil end
	end
	if X.svFolder == old then X.svFolder = nil end
	X.svAfter()
end

function X.svFolderBarBuild(page)
	if not (X.svFolderBar and X.svFolderBar.Parent) then
		X.svFolderBar = X.mkBar(page, 30, 28)
	end
	local bar = X.svFolderBar
	for _, c in ipairs(bar:GetChildren()) do
		if c:IsA("GuiObject") then c:Destroy() end
	end
	local counts, none = {}, 0
	for _, r in ipairs(X.sv.list) do
		if r.folder and r.folder ~= "" then
			counts[r.folder] = (counts[r.folder] or 0) + 1
		else
			none += 1
		end
	end
	X.mkTool(bar, X.svSelMode and "Select: ON" or "Select: OFF", 100, X.svSelMode and C.sel or C.btn, function()
		X.svSelMode = not X.svSelMode
		X.svRender()
	end)
	if X.svSelMode then
		X.mkTool(bar, "Select all", 92, C.btn, function()
			for _, id in ipairs(X.svVisible) do X.svSel[id] = true end
			X.svRender()
		end)
		X.mkTool(bar, "Clear picks", 96, C.btn, function()
			X.svSel = {}
			X.svRender()
		end)
		X.svDlBtn = X.mkTool(bar, "Download tools (" .. X.svSelCount() .. ")", 160, C.green, function(b) X.svToolPack(b) end)
	end
	local cb = X.combo
	if cb then
		X.mkTool(bar, cb.on and "Auto-combine: ON" or "Auto-combine: OFF", 140, cb.on and C.sel or C.btn, function()
			cb.on = not cb.on
			X.svRender()
		end)
		X.mkTool(bar, "Combine recent", 122, C.green, function(b) cb.manual(b) end)
		X.mkTool(bar, "Gap " .. cb.gap .. "s", 76, C.btn, function()
			local steps = { 0.25, 0.5, 1, 2 }
			local nxt = steps[1]
			for i, v in ipairs(steps) do
				if v == cb.gap then
					nxt = steps[i % #steps + 1]
					break
				end
			end
			cb.gap = nxt
			X.svRender()
		end)
	end
	local function chip(text, key)
		local w = math.max(64, #text * 8 + 18)
		X.mkTool(bar, text, w, (X.svFolder == key) and C.sel or C.btn, function()
			X.svFolder = key
			X.svRender()
		end)
	end
	chip("All folders", nil)
	chip("No folder (" .. none .. ")", "")
	for _, f in ipairs(X.sv.folders) do
		chip(f .. " (" .. (counts[f] or 0) .. ")", f)
	end
	X.mkTool(bar, "+ Folder", 80, C.green, function()
		X.prompt("New folder name", "", function(text)
			local f = X.svFolderAdd(text)
			if f then X.svFolder = f end
			X.svRender()
		end)
	end)
	if X.svFolder and X.svFolder ~= "" and X.svFolderExists(X.svFolder) then
		local cur = X.svFolder
		X.mkTool(bar, "Rename folder", 108, C.btn, function()
			X.prompt("Rename folder", cur, function(text) X.svFolderRename(cur, text) end)
		end)
		X.mkTool(bar, "Delete folder", 104, C.danger, function()
			X.confirm("Delete folder \"" .. cur .. "\"?", "The animations inside are kept, they just go back to No folder.", function()
				X.svFolderDelete(cur)
			end)
		end)
	end
end

function X.svFolderPick(r)
	local page = lists.Saved and lists.Saved.Parent
