	local list = newList(ov, UDim2.new(0, 4, 0, 34), UDim2.new(1, -8, 1, -38))
	list.ZIndex = 51
	local n = 0
	local function add(text, color, fn)
		n += 1
		local b = K.newButton(list, text, color)
		b.Size = UDim2.new(1, -6, 0, 34)
		b.LayoutOrder = n
		b.ZIndex = 52
		b.TextXAlignment = Enum.TextXAlignment.Left
		b.MouseButton1Click:Connect(function()
			ov:Destroy()
			fn()
