	add("No folder", C.row1, function() X.svMove(r, nil) end)
	for _, f in ipairs(X.sv.folders) do
		add((r.folder == f and "* " or "") .. f, C.row2, function() X.svMove(r, f) end)
	end
	add("+ New folder...", C.green, function()
		X.prompt("New folder name", "", function(text)
			local f = X.svFolderAdd(text)
			if f then X.svMove(r, f) end
		end)
	end)
end

-- movement (root samples) of a saved animation, kept small so the save file stays light
function X.svRootEnc(id)
	local rr = X.rootRec[X.rootKey(id)]
	if not (rr and rr.samples and #rr.samples >= 3) then return nil end
	local s = rr.samples
	local step = math.max(1, math.ceil(#s / 60))
	local rows = {}
	local function row(smp)
		local c = { smp[2]:GetComponents() }
		local out2 = { math.floor(smp[1] * 1000 + 0.5) / 1000 }
		for i = 1, 12 do out2[i + 1] = math.floor(c[i] * 10000 + 0.5) / 10000 end
		return out2
	end
	for i = 1, #s, step do rows[#rows + 1] = row(s[i]) end
	if (#s - 1) % step ~= 0 then rows[#rows + 1] = row(s[#s]) end
	return rows
end

function X.svRootDec(rt)
	local samples, maxH, maxUp = {}, 0, 0
	for _, row in ipairs(rt) do
		if type(row) == "table" and #row >= 13 then
			local ok, cf = pcall(CFrame.new, table.unpack(row, 2, 13))
			if ok and cf then
				samples[#samples + 1] = { tonumber(row[1]) or 0, cf }
				local p = cf.Position
				maxH = math.max(maxH, Vector3.new(p.X, 0, p.Z).Magnitude)
				maxUp = math.max(maxUp, p.Y)
			end
		end
	end
	if #samples < 3 then return nil end
	return { samples = samples, maxH = maxH, maxHoriz = maxH, maxUp = maxUp }
end

-- ---------- NPC hit capture ----------
do
	local N = {
		on = true, range = 60, needAttack = true, players = true, lastInput = -99, before = 3, after = 1.2, hits = 0,
		caps = {}, order = {}, active = 0, lastAttack = -99,
		recent = setmetatable({}, { __mode = "k" }),
		state = setmetatable({}, { __mode = "k" }),
		seen = setmetatable({}, { __mode = "k" }),
	}
	X.npc = N

	local function swap(s, a, b)
		local i, j = s:find(a, 1, true)
		if not i then return s end
		return s:sub(1, i - 1) .. b .. s:sub(j + 1)
	end

	-- a "target" is anything with a Humanoid that is not me: NPCs and (optionally) other players
	function N.isNpc(model)
		if model == nil or not model:IsA("Model") or model == lp.Character then return false end
		if Players:GetPlayerFromCharacter(model) then return N.players end
		return true
	end

	function N.rootOf(model)
		return model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
	end

	function N.dist(model)
		local mine = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
		local r = N.rootOf(model)
		if not (mine and r and r:IsA("BasePart")) then return math.huge end
		return (mine.Position - r.Position).Magnitude
	end

	-- idle / walk loops are not interesting, attacks and hit reactions are
	function N.useful(track)
		local p = track.Priority
		if p == Enum.AnimationPriority.Core then return false end
		if not track.Looped then return true end
		return p ~= Enum.AnimationPriority.Idle and p ~= Enum.AnimationPriority.Movement
	end

	-- how the NPC moved while the animation played (same sampling as the player's movement log)
	function N.recRoot(entry, model, track)
		local root = N.rootOf(model)
		if not (root and root:IsA("BasePart")) or N.active >= 8 or track.Looped then return end
		N.active += 1
		entry.rootBusy = true
		task.spawn(function()
			local origin = root.CFrame
			local t0 = os.clock()
			local samples = { { 0, CFrame.new() } }
			local lastT, stoppedAt = 0, nil
			while Run.alive and root.Parent do
				local now = os.clock() - t0
				if now > 8 then break end
				if not track.IsPlaying then
					stoppedAt = stoppedAt or now
					if now - stoppedAt > 0.6 then break end
				end
				if now - lastT >= 1 / 30 then
					lastT = now
					samples[#samples + 1] = { now, origin:ToObjectSpace(root.CFrame) }
					local n = #samples
					if stoppedAt and n >= 6 then
						local a, b = samples[n - 5][2].Position, samples[n][2].Position
						if (a - b).Magnitude < 0.05 then break end
					end
				end
				RunService.Heartbeat:Wait()
			end
			N.active -= 1
			entry.rootBusy = false
			if #samples < 3 then return end
			local lastP = samples[#samples][2].Position
			local keep = #samples
			while keep > 2 and (samples[keep - 1][2].Position - lastP).Magnitude < 0.03 do keep -= 1 end
			for i = #samples, keep + 1, -1 do samples[i] = nil end
			local maxH, maxUp, maxAbsY, maxRot = 0, 0, 0, 0
			for _, smp in ipairs(samples) do
				local pos = smp[2].Position
				maxH = math.max(maxH, Vector3.new(pos.X, 0, pos.Z).Magnitude)
				maxUp = math.max(maxUp, pos.Y)
				maxAbsY = math.max(maxAbsY, math.abs(pos.Y))
				local _, ang = smp[2]:ToAxisAngle()
				maxRot = math.max(maxRot, math.abs(ang))
			end
			if maxH < 0.75 and maxAbsY < 0.75 and maxRot < 0.5 then return end
			entry.root = { samples = samples, maxH = maxH, maxHoriz = maxH, maxUp = maxUp }
		end)
	end

	function N.track(model, hum)
		if N.seen[hum] then return end
		N.seen[hum] = true
		N.state[hum] = { hp = hum.Health, cool = -99 }
		local list = {}
		N.recent[model] = list
		local seenTracks = setmetatable({}, { __mode = "k" })
		local function onPlayed(track)
			if seenTracks[track] or ownTracks[track] or not Run.alive then return end
			seenTracks[track] = true
			if not N.useful(track) then return end
			local anim = track.Animation
			local id = anim and anim.AnimationId or ""
			if id == "" then return end
			local e = {
				track = track, id = id, name = track.Name, t = os.clock(), length = track.Length,
				priority = track.Priority.Name, looped = track.Looped,
			}
			list[#list + 1] = e
			while #list > 14 do table.remove(list, 1) end
			if not N.caps[id] then
				pcall(openFXWindow, id, hum:FindFirstChildOfClass("Animator") or hum, track)
			end
			N.recRoot(e, model, track)
		end
		pcall(function() hum.AnimationPlayed:Connect(onPlayed) end)
		local function hookAnimator(a)
			if a:IsA("Animator") then
				pcall(function() a.AnimationPlayed:Connect(onPlayed) end)
			end
		end
		for _, c in ipairs(hum:GetChildren()) do hookAnimator(c) end
		hum.ChildAdded:Connect(hookAnimator)
		hum.HealthChanged:Connect(function(h)
			local st = N.state[hum]
			if not st then return end
			local prev = st.hp
			st.hp = h
			if h < prev and N.on then N.onHit(model, hum) end
		end)
	end

	do
		local uis = game:GetService("UserInputService")
		table.insert(Run.conns, uis.InputBegan:Connect(function(input)
			local t = input.UserInputType
			if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch
				or (t == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.W and input.KeyCode ~= Enum.KeyCode.A
					and input.KeyCode ~= Enum.KeyCode.S and input.KeyCode ~= Enum.KeyCode.D and input.KeyCode ~= Enum.KeyCode.Space) then
				N.lastInput = os.clock()
			end
		end))
	end

	function N.hookMe(ch)
		local hum = ch:WaitForChild("Humanoid", 10)
		if not hum then return end
		hum.AnimationPlayed:Connect(function(tr)
			if ownTracks[tr] or tr.Looped or tr.Priority == Enum.AnimationPriority.Core then return end
			N.lastAttack = os.clock()
		end)
	end

	function N.onHit(model, hum)
		local st = N.state[hum]
		if not st then return end
		local now = os.clock()
		if now - st.cool < 1.5 then return end
		if N.dist(model) > N.range then return end
		if N.needAttack and now - N.lastAttack > 2 and now - N.lastInput > 1.5 then return end
		st.cool = now
		N.hits += 1
		task.spawn(function()
			task.wait(N.after)
			if Run.alive then pcall(N.collect, model, hum, now, true) end
		end)
	end

	function N.collect(model, hum, hitTime, auto)
		local picked, order = {}, {}
		local function take(e)
			if not picked[e.id] then
				picked[e.id] = e
				order[#order + 1] = e.id
			end
		end
		for _, e in ipairs(N.recent[model] or {}) do
			if e.t >= hitTime - N.before then take(e) end
		end
		local animator = hum:FindFirstChildOfClass("Animator")
		if animator then
			for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
				local anim = tr.Animation
				local id = anim and anim.AnimationId or ""
				if id ~= "" and not picked[id] and N.useful(tr) and not ownTracks[tr] then
					take({
						track = tr, id = id, name = tr.Name, t = os.clock(), length = tr.Length,
						priority = tr.Priority.Name, looped = tr.Looped,
					})
				end
			end
		end
		local n = 0
		for _, id in ipairs(order) do
			if N.capture(id, picked[id], model) then n += 1 end
		end
		if n == 0 and not auto then
			out("NPC capture: nothing new on " .. model.Name .. " (it has to play an animation first)")
		end
		N.render()
	end

	function N.capture(id, e, model)
		local cap = N.caps[id]
		if cap then
			cap.hits += 1
			cap.t = os.time()
			cap.npc = model.Name
			return false
		end
		local hum = model:FindFirstChildOfClass("Humanoid")
		cap = {
			id = id, name = e.name, npc = model.Name, t = os.time(), hits = 1, length = e.length,
			priority = e.priority, looped = e.looped, state = "capturing",
			rig = hum and hum.RigType.Name or "?",
		}
		N.caps[id] = cap
		table.insert(N.order, 1, id)
		while #N.order > 40 do
			local old = table.remove(N.order)
			N.caps[old] = nil
		end
		X.keepRig(id, model)
		animLabel[id] = e.name .. " / " .. model.Name
		animInfo[id] = animInfo[id] or { priority = e.priority, looped = e.looped, speed = 1 }
		pcall(function() X.animInstOf[id] = e.track.Animation end)
		task.spawn(function()
			local t0 = os.clock()
			while e.rootBusy and os.clock() - t0 < 9 do task.wait(0.1) end
			if e.root then
				X.rootRec[X.rootKey(id)] = e.root
				cap.move = X.rootShort(e.root)
			end
			requestDetail(id, function(ok, res)
				cap.state = ok and "ready" or "failed"
				cap.err = (not ok) and tostring(res) or nil
				N.render()
				if ok then
					out(string.format("NPC hit: got %s from %s. Open the NPC Hit tab for the code.", e.name, model.Name))
				else
					out("NPC capture failed: " .. tostring(res))
				end
			end)
		end)
		return true
	end

	function N.manual()
		local best, bestHum, bd
		for _, d in ipairs(workspace:GetDescendants()) do
			if d:IsA("Humanoid") and d.Health > 0 then
				local m = d.Parent
				if N.isNpc(m) and N.rootOf(m) then
					local dist = N.dist(m)
					if dist <= 200 and (not bd or dist < bd) then
						best, bestHum, bd = m, d, dist
					end
				end
			end
		end
		if not best then return out("NPC capture: nobody within 200 studs of you") end
		pcall(N.track, best, bestHum)
		N.collect(best, bestHum, os.clock(), false)
	end

	function N.scan()
		for _, d in ipairs(workspace:GetDescendants()) do
			if d:IsA("Humanoid") and N.isNpc(d.Parent) then pcall(N.track, d.Parent, d) end
		end
	end

	-- the script that plays the captured frames on an NPC
	N.PLAY = [==[
if _G.StopNpcAnim then pcall(_G.StopNpcAnim) end

local function notify(text)
	print("[NpcAnim] " .. text)
	pcall(function()
		game:GetService("StarterGui"):SetCore("SendNotification", {
			Title = "NPC anim", Text = text, Duration = 3,
		})
	end)
end

local playing, watched, ctrlConns = {}, {}, {}
local shutdown = false

local function isNpc(m)
	if not (m and m:IsA("Model")) or m == lp.Character then return false end
	if Players:GetPlayerFromCharacter(m) then return TARGET_PLAYERS end
	return true
end

local function rigOk(h)
	return RIG == "Custom" or h.RigType.Name == RIG
end

local function myPos()
	local r = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
	return r and r.Position
end

local function inRange(m)
	local hrp = m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
	local me = myPos()
	if not (hrp and me) then return false end
	return (hrp.Position - me).Magnitude <= TARGET_RANGE
end

local function nameOk(m)
	return TARGET_NAME == "" or m.Name == TARGET_NAME
end

-- plays the captured frames (and movement) on one NPC
local function playOn(npc)
	if shutdown or playing[npc] then return end
	local hum = npc:FindFirstChildOfClass("Humanoid")
	if not hum or hum.Health <= 0 or not rigOk(hum) then return end

	local motors, count = {}, 0
	for _, d in ipairs(npc:GetDescendants()) do
		if d:IsA("Motor6D") and JOINTS[d.Name] and d.Part1 and not motors[d.Name] then
			motors[d.Name] = d
			count += 1
		end
	end
	if count == 0 then return end

	local function apply(pose)
		for name, cf in pairs(pose) do
			local m = motors[name]
			if m then m.Transform = cf end
		end
	end

	local animate = npc:FindFirstChild("Animate")
	local animateWasDisabled = animate and animate.Disabled
	local detached = {}
	local function detachAnimators()
		for _, d in ipairs(hum:GetChildren()) do
			if d:IsA("Animator") then
				detached[#detached + 1] = d
				d.Parent = nil
			end
		end
	end
	if DISABLE_DEFAULT_ANIMATE then
		if animate then pcall(function() animate.Disabled = true end) end
		detachAnimators()
	end

	local accumulated, index, elapsed = 0, 1, 0
	local lastFrame
	local conns = {}
	local stopped = false

	local rootPart = npc:FindFirstChild("HumanoidRootPart") or npc.PrimaryPart
	local rootOrigin = rootPart and rootPart.CFrame
	local rootIdx = 0
	local useRoot = MOVE_ROOT and ROOT ~= nil and rootPart ~= nil

	local function rootOffset(t)
		while ROOT[rootIdx + 1] and ROOT[rootIdx + 1].t <= t do rootIdx += 1 end
		local prev, nxt = ROOT[rootIdx], ROOT[rootIdx + 1]
		local pt, pcf = 0, CFrame.new()
		if prev then pt, pcf = prev.t, prev.cf end
		local o = pcf
		if nxt then o = pcf:Lerp(nxt.cf, math.clamp((t - pt) / math.max(nxt.t - pt, 1e-6), 0, 1)) end
		if MOVE_SCALE ~= 1 then o = CFrame.new(o.Position * MOVE_SCALE) * (o - o.Position) end
		return o
	end

	local function stop()
		if stopped then return end
		stopped = true
		playing[npc] = nil
		for _, c in ipairs(conns) do c:Disconnect() end
		table.clear(conns)
		for _, m in pairs(motors) do m.Transform = CFrame.new() end
		if useRoot and rootPart.Parent then rootPart.AssemblyLinearVelocity = Vector3.zero end
		if #detached > 0 then
			for _, a in ipairs(hum:GetChildren()) do
				if a:IsA("Animator") then a:Destroy() end
			end
			for _, a in ipairs(detached) do a.Parent = hum end
		end
		if animate and DISABLE_DEFAULT_ANIMATE then pcall(function() animate.Disabled = animateWasDisabled end) end
	end
	playing[npc] = stop
	if runFX and rootPart then task.spawn(runFX, npc, rootPart) end

	table.insert(conns, hum.Died:Connect(stop))
	table.insert(conns, npc.AncestryChanged:Connect(function()
		if not npc:IsDescendantOf(game) then stop() end
	end))
	table.insert(conns, RunService.Heartbeat:Connect(function(dt)
		if stopped then return end
		accumulated += dt * SPEED
		elapsed += dt * SPEED
		if DISABLE_DEFAULT_ANIMATE then detachAnimators() end
		if useRoot and rootPart.Parent then
			rootPart.CFrame = rootOrigin * rootOffset(math.min(elapsed, ROOT_END))
			rootPart.AssemblyLinearVelocity = Vector3.zero
			rootPart.AssemblyAngularVelocity = Vector3.zero
		end
		local rootDone = not useRoot or elapsed >= ROOT_END

		while frames[index] and accumulated >= frames[index].dt do
			accumulated -= frames[index].dt
			lastFrame = frames[index]
			index += 1
		end

		local nextFrame = frames[index]
		if not nextFrame then
			if lastFrame then apply(lastFrame.j) end
			if not rootDone then return end
			if LOOP_FOREVER then
				index, accumulated, elapsed, rootIdx = 1, 0, 0, 0
				if useRoot then rootOrigin = rootPart.CFrame end
				if runFX and rootPart then task.spawn(runFX, npc, rootPart) end
			else
				stop()
			end
			return
		end

		if lastFrame and SMOOTH then
			local alpha = math.clamp(accumulated / math.max(nextFrame.dt, 1e-6), 0, 1)
			for name, cf in pairs(nextFrame.j) do
				local m = motors[name]
				local from = lastFrame.j[name]
				if m and from then m.Transform = from:Lerp(cf, alpha) end
			end
		elseif lastFrame then
			apply(lastFrame.j)
		end
	end))
end

local function nearestNpc()
	local best, bestDist
	local me = myPos()
	for _, d in ipairs(workspace:GetDescendants()) do
		if d:IsA("Humanoid") and d.Health > 0 and isNpc(d.Parent) and rigOk(d) and nameOk(d.Parent) then
			local hrp = d.Parent:FindFirstChild("HumanoidRootPart") or d.Parent.PrimaryPart
			if hrp then
				local dist = me and (hrp.Position - me).Magnitude or 0
				if dist <= TARGET_RANGE and (not bestDist or dist < bestDist) then
					best, bestDist = d.Parent, dist
				end
			end
		end
	end
	return best
end

-- AUTO: every NPC or player you hit (health drops while you are near) plays the animation
local function watch(hum)
	local m = hum.Parent
	if watched[hum] or not isNpc(m) or not nameOk(m) or not rigOk(hum) then return end
	watched[hum] = true
	local last = hum.Health
	table.insert(ctrlConns, hum.HealthChanged:Connect(function(h)
		local dropped = h < last
		last = h
		if dropped and h > 0 and inRange(m) then playOn(m) end
	end))
end

local function stopAll()
	shutdown = true
	for _, c in ipairs(ctrlConns) do c:Disconnect() end
	table.clear(ctrlConns)
	local list = {}
	for _, fn in pairs(playing) do list[#list + 1] = fn end
	for _, fn in ipairs(list) do pcall(fn) end
	_G.StopNpcAnim = nil
end
_G.StopNpcAnim = stopAll

if AUTO then
	for _, d in ipairs(workspace:GetDescendants()) do
		if d:IsA("Humanoid") then watch(d) end
	end
	table.insert(ctrlConns, workspace.DescendantAdded:Connect(function(d)
		if d:IsA("Humanoid") then
			task.defer(function() if d.Parent then watch(d) end end)
		end
	end))
	notify("Auto mode on: hit an NPC or player and it plays the animation (" .. string.format("%.2fs", LENGTH) .. ")")
end

if PLAY_ON_START or not AUTO then
	local npc = TARGET_MODEL or nearestNpc()
	if npc then
		playOn(npc)
		if not AUTO then notify("Playing on " .. npc.Name) end
	else
		notify("No matching NPC near you (" .. RIG .. "). " .. (AUTO and "Waiting for a hit." or "Stand closer or raise TARGET_RANGE."))
		if not AUTO then shutdown = true end
	end
end
-- call _G.StopNpcAnim() to stop everything (client-side only: only you see it)
]==]

	-- sfx/vfx recorded while the NPC did the animation, replayed on whichever NPC plays it
	function N.fxBlock(id)
		local fx = K.fxFilter(fxWindows.liveFor(id), "fx")
		if not fx or #fx == 0 then return "local runFX = nil -- no sfx/vfx were recorded for this animation\n\n", 0 end
		local L = {}
		L[#L + 1] = "-- SFX / VFX rebuilt from properties (" .. #fx .. " events). Replayed on every NPC the animation plays on."
		L[#L + 1] = "-- Private audio can't load outside its game: it warns once and stays silent unless you map it in SFX_SWAP (see the runtime header)."
		L[#L + 1] = "local function runFX(fxChar, fxRoot)"
		L[#L + 1] = "\tlocal ok, err = pcall(function()"
		L[#L + 1] = "\t\tlocal FX = {"
		for _, ev in ipairs(fx) do
			L[#L + 1] = K.indentLines(K.evStr(ev), "\t\t\t") .. ","
		end
		L[#L + 1] = "\t\t}"
		local rt = swap(FX_RUNTIME, 'local fxChar = lp.Character or lp.CharacterAdded:Wait()\nlocal fxRoot = fxChar:WaitForChild("HumanoidRootPart")\n', "")
		L[#L + 1] = K.indentLines(rt, "\t\t")
		L[#L + 1] = "\tend)"
		L[#L + 1] = '\tif not ok then warn("[FX] failed (animation unaffected):", err) end'
		L[#L + 1] = "end"
		L[#L + 1] = ""
		return table.concat(L, "\n") .. "\n", #fx
	end

	function N.genCode(id)
		local d = details[id]
		if not d then error("the frames are not captured yet") end
		local cap = N.caps[X.rootKey(id)]
		local rec = X.sv.map[X.rootKey(id)]
		local npcName = (cap and cap.npc) or (rec and rec.npc) or ""
		local oldQ = QUALITY
		QUALITY = "Full" -- every captured frame, so it plays like the original
		local okG, code = pcall(function()
			local c = K.simplified(id)
			local note = string.format("Frames: %d kept of %d sampled (quality: %s)", c.kept, c.total, QUALITY)
			return K.genDetailedCode(id, d.rig, d.length, d.looped, c.joints, nil, note)
		end)
		QUALITY = oldQ
		if not okG then error(code) end
		local fxText = N.fxBlock(id)
		code = swap(code, PLAYBACK_CODE, fxText .. N.PLAY)
		local cfg = "local AUTO = true -- true: stays active in ANY game and plays on every NPC or player you hit; false: plays once on the nearest NPC\n"
			.. "local TARGET_PLAYERS = true -- also play on other players' characters (client-side, only you see it)\n"
			.. "local PLAY_ON_START = true -- also play once on the nearest NPC the moment you run it\n"
			.. "local TARGET_NAME = \"\" -- \"\" = any NPC, or a name to only affect NPCs with that name"
			.. (npcName ~= "" and (" (captured from \"" .. npcName .. "\")") or "") .. "\n"
			.. "local TARGET_RANGE = 100 -- studs: NPCs farther than this from you are ignored\n"
			.. "local TARGET_MODEL = nil -- or put an NPC model here, e.g. workspace.Bandit\n"
		code = swap(code, "local SPEED = 1\n", "local SPEED = 1\n" .. cfg)
		local L = {}
		L[1] = "-- NPC SCRIPT: plays this animation frame by frame on an NPC"
			.. (npcName ~= "" and (" (captured from " .. npcName .. ")") or "")
		for line in (code .. "\n"):gmatch("([^\n]*)\n") do
			if line:find("^local CANCEL_ON_MOVE") then
				-- not used on NPCs
			elseif line:find("^local DISABLE_DEFAULT_ANIMATE") then
				L[#L + 1] = "local DISABLE_DEFAULT_ANIMATE = true -- stops the NPC's own animations while this plays, restored after"
			elseif line:find("^local MOVE_ROOT = true") then
				L[#L + 1] = "local MOVE_ROOT = true -- also replays how the NPC moved while it did the animation"
			elseif line:find("^%-%- how you moved while the animation played") then
				L[#L + 1] = "-- how the NPC moved while the animation played: t = seconds since it started,"
			elseif line:find("^%-%- cf = where your root went") then
				L[#L + 1] = "-- cf = where the NPC root went relative to where it stood (facing = start)"
			else
				L[#L + 1] = line
			end
		end
		return table.concat(L, "\n")
	end

	function N.withCode(id, btn, fn)
		local orig = btn and btn.Text
		local function reset(t)
			if btn and btn.Parent then
				btn.Text = t or orig
				task.delay(1.2, function() if btn.Parent then btn.Text = orig end end)
			end
		end
		local function go()
			local ok, code = pcall(N.genCode, id)
			if ok then
				fn(code)
				reset("Done")
			else
				out("NPC code failed: " .. tostring(code))
				reset("Fail")
			end
		end
		if details[id] then return go() end
		if btn then btn.Text = "Working..." end
		requestDetail(id, function(ok, res)
			if ok then
				go()
			else
				out("Frame capture failed: " .. tostring(res))
				reset("Fail")
			end
		end, function(t) if btn and btn.Parent then btn.Text = tostring(t):sub(1, 16) end end)
	end

	function X.npcCodeFor(id, btn)
		N.withCode(id, btn, function(code) toClip(code, "the NPC script") end)
	end

	function X.npcFileFor(id, btn)
		N.withCode(id, btn, function(code)
			local nm = "NPC_" .. tostring(K.animName(id)):gsub("[^%w_]", "")
			X.saveScriptFile(code, nm)
		end)
	end

	function X.npcGenAsync(id, cb)
		local function go()
			local ok, code = pcall(N.genCode, id)
			if ok then cb(code) else cb(nil, tostring(code)) end
		end
		if details[id] then return go() end
		requestDetail(id, function(ok, res)
			if ok then go() else cb(nil, tostring(res)) end
		end)
	end

