	function N.render()
		local sf = N.list
		if not (sf and sf.Parent) then return end
		for _, c in ipairs(sf:GetChildren()) do
			if c:IsA("GuiObject") then c:Destroy() end
		end
		N.info.Text = string.format("%s. %d captured, %d hit(s) seen. Hit an NPC or player and its animation lands here.",
			N.on and "Watching" or "Paused", #N.order, N.hits)
		N.btnAuto.Text = N.on and "Auto: ON" or "Auto: OFF"
		K.paint(N.btnAuto, N.on and C.sel or C.btn)
		N.btnAtk.Text = N.needAttack and "Attack-only: ON" or "Attack-only: OFF"
		K.paint(N.btnAtk, N.needAttack and C.sel or C.btn)
		N.btnRange.Text = "Range: " .. N.range
		N.btnPl.Text = N.players and "Players: ON" or "Players: OFF"
		K.paint(N.btnPl, N.players and C.sel or C.btn)
		if #N.order == 0 then
			local l = Instance.new("TextLabel")
			l.Size = UDim2.new(1, -6, 0, 76)
			l.BackgroundTransparency = 1
			l.TextWrapped = true
			l.Text = "Nothing yet. Hit an NPC or player (or press Capture nearest) and its animation, sound and movement are captured here as a script that works on any NPC or player in any game."
			l.TextColor3 = C.sub
			l.Font = Th.font
			l.TextSize = 15
			l.Parent = sf
			return
		end
		for i, id in ipairs(N.order) do
			local cap = N.caps[id]
			if cap then
				local row = Instance.new("Frame")
				row.Size = UDim2.new(1, -6, 0, 78)
				row.BackgroundColor3 = i % 2 == 1 and C.row1 or C.row2
				row.BorderSizePixel = 0
				row.LayoutOrder = i
				row.Parent = sf
				local lbl = Instance.new("TextLabel")
				lbl.Position = UDim2.new(0, 8, 0, 2)
				lbl.Size = UDim2.new(1, -16, 0, 36)
				lbl.BackgroundTransparency = 1
				lbl.RichText = true
				lbl.TextXAlignment = Enum.TextXAlignment.Left
				lbl.TextTruncate = Enum.TextTruncate.AtEnd
				lbl.Font = Th.font
				lbl.TextSize = 15
				lbl.TextColor3 = C.text
				local stateText = cap.state == "ready" and "frames ready" or (cap.state == "failed" and ("failed: " .. tostring(cap.err):sub(1, 40)) or "capturing...")
				local fxN = 0
				pcall(function()
					local fl = K.fxFilter(fxWindows.liveFor(id), "fx")
					fxN = fl and #fl or 0
				end)
				lbl.Text = string.format('<b>%s</b>  (NPC: %s)\n<font color="%s">%s | %.2fs | hit x%d | sfx/vfx %d%s</font>',
					K.esc(cap.name), K.esc(cap.npc), K.hex(C.sub), stateText, cap.length or 0, cap.hits, fxN,
					cap.move and (" | moved " .. K.esc(cap.move)) or "")
				lbl.Parent = row
				local bar = X.mkBar(row, 40, 34)
				X.mkTool(bar, "Copy NPC code", 112, C.sel, function(b) X.npcCodeFor(id, b) end)
				X.mkTool(bar, "Download", 84, C.green, function(b) X.npcFileFor(id, b) end)
				X.mkTool(bar, "View", 52, C.btn, function(b)
					N.withCode(id, b, function(code)
						openViewer("NPC script - " .. cap.name, { { name = "Script", get = function(cb) cb(code) end } }, 1)
					end)
				end)
				X.mkTool(bar, "Preview", 66, C.green, function() X.pvOpen(id, { id = id, name = cap.name }) end)
				X.mkTool(bar, X.sv.map[id] and "Saved" or "Save", 60, C.btn, function()
					if not X.sv.map[id] then
						X.svToggle(id, cap.name)
						local r = X.sv.map[id]
						if r then
							r.npc = cap.npc
							r.folder = X.svFolderAdd("NPC")
							X.svAfter()
						end
					end
					N.render()
				end)
				X.mkTool(bar, "Remove", 66, C.danger, function()
					N.caps[id] = nil
					local at = table.find(N.order, id)
					if at then table.remove(N.order, at) end
					N.render()
				end)
			end
		end
	end

	do
		local Lg = (getgenv and getgenv() or _G).__RPP_Logger
		if Lg then Lg.openNpc = function() Lg.openTab("NPC") end end
	end

	if lp.Character then task.spawn(N.hookMe, lp.Character) end
	table.insert(Run.conns, lp.CharacterAdded:Connect(function(ch) task.spawn(N.hookMe, ch) end))
	table.insert(Run.conns, workspace.DescendantAdded:Connect(function(d)
		if N.on and d:IsA("Humanoid") then
			task.defer(function()
				local m = d.Parent
				if m and N.isNpc(m) then pcall(N.track, m, d) end
			end)
		end
	end))
	task.spawn(function()
		task.wait(2)
		pcall(N.scan)
		N.render()
	end)
end

-- ---------- auto-combine: animations that are the continuation of another one ----------
do
	local CB = { on = true, gap = 1, chain = nil, made = {}, count = 0, recent = {}, seen = setmetatable({}, { __mode = "k" }) }
	X.combo = CB
	if X.comboLoad then
		if type(X.comboLoad.on) == "boolean" then CB.on = X.comboLoad.on end
		if type(X.comboLoad.gap) == "number" then CB.gap = X.comboLoad.gap end
	end

	local function nm(id) return tostring(K.animName(id)) end

	CB.autoDup = true      -- auto-off the same sfx when it is in more than one part (kept in the longest part)
	CB.fxOverride = {}     -- manual choice per fx: true = forced OFF, false = forced ON, nil = automatic

	function CB.assetOf(e)
		for _, p in ipairs(e.props or {}) do
			if p[1] == "SoundId" or p[1] == "Texture" then
				local v = tostring(p[2])
				return v:match("%d+") or v
			end
		end
		return ""
	end
	function CB.fxKey(e)
		return string.format("%s|%s|%s|%s|%d", tostring(e.kind), tostring(e.class), tostring(e.name), CB.assetOf(e), math.floor((e.t or 0) * 20 + 0.5))
	end
	function CB.fxGroup(e)
		if e.kind == "sfx" then
			local a = CB.assetOf(e)
			return a ~= "" and ("sfx|" .. a) or nil
		elseif e.kind == "vfx" then
			return string.format("vfx|%s|%s|%s", tostring(e.class), tostring(e.name), CB.assetOf(e))
		end
		return nil
	end
	-- parts = { {id=, len=, list={events}, keys={optional}} ... }
	-- returns groups (same sfx/vfx in 2+ parts), autoOff[e] (sfx outside the longest part), groupOf[e]
	function CB.analyze(parts)
		local byGroup, order = {}, {}
		for i, P in ipairs(parts) do
			for j, e in ipairs(P.list) do
				local g = CB.fxGroup(e)
				if g then
					local G = byGroup[g]
					if not G then
						G = { kind = e.kind, name = tostring(e.name), asset = CB.assetOf(e), items = {}, partsSet = {}, nparts = 0 }
						byGroup[g] = G
						order[#order + 1] = g
					end
					G.items[#G.items + 1] = { part = i, e = e, key = P.keys and P.keys[j] or (tostring(P.id) .. "#" .. CB.fxKey(e)) }
					if not G.partsSet[i] then G.partsSet[i] = true G.nparts += 1 end
				end
			end
		end
		local groups, autoOff, groupOf = {}, {}, {}
		for _, g in ipairs(order) do
			local G = byGroup[g]
			if G.nparts >= 2 then
				local best
				for i = 1, #parts do
					if G.partsSet[i] and (not best or (parts[i].len or 0) > (parts[best].len or 0)) then best = i end
				end
				G.best = best
				for _, it in ipairs(G.items) do
					groupOf[it.e] = G
					if it.e.kind == "sfx" and it.part ~= best then autoOff[it.e] = true end
				end
				groups[#groups + 1] = G
			end
		end
		return groups, autoOff, groupOf
	end
	function CB.stateOff(e, key, autoOff)
		local o = CB.fxOverride[key]
		if o ~= nil then return o end
		return CB.autoDup and autoOff[e] == true or false
	end

	-- movement only counts while the animation itself runs: the next part starts when this one's length is over
	local function clampRoot(samples, len)
		local out2 = {}
		for _, s in ipairs(samples) do
			if s[1] <= len then
				out2[#out2 + 1] = s
			else
				local prev = out2[#out2]
				if prev and prev[1] < len then
					local f = (len - prev[1]) / math.max(s[1] - prev[1], 1e-6)
					out2[#out2 + 1] = { len, prev[2]:Lerp(s[2], f) }
				end
				break
			end
		end
		return out2
	end

	function CB.build(ids)
		local first = details[ids[1]]
		local rig = first.rig
		local order, meta = {}, {}
		for _, id in ipairs(ids) do
			local d = details[id]
			if not (d and d.joints and #d.joints > 0) then error("no frames for " .. nm(id)) end
			if d.rig ~= rig then error("different rig types (" .. tostring(rig) .. " / " .. tostring(d.rig) .. ")") end
			for _, j in ipairs(d.joints) do
				if not meta[j.name] then
					meta[j.name] = j
					order[#order + 1] = j.name
				end
			end
		end
		local merged = {}
		for _, n in ipairs(order) do merged[n] = {} end
		local off, lastT = 0, 0
		local root, cum, anyRoot = {}, CFrame.new(), false
		local fxAll = {}
		local partOf, partLen, keyOf = {}, {}, {}
		for pi, id in ipairs(ids) do
			local d = details[id]
			local times = d.joints[1].frames
			partLen[pi] = times[#times][1]
			local byName = {}
			for _, j in ipairs(d.joints) do byName[j.name] = j end
			for _, n in ipairs(order) do
				local j, dst = byName[n], merged[n]
				for i = 1, #times do
					dst[#dst + 1] = { times[i][1] + off, j and j.frames[i] and j.frames[i][2] or CFrame.new() }
				end
			end
			lastT = times[#times][1] + off
			local rr = X.rootRec[X.rootKey(id)]
			local rs = rr and rr.samples and clampRoot(rr.samples, times[#times][1]) or nil
			if rs and #rs >= 2 then
				anyRoot = true
				for _, s in ipairs(rs) do root[#root + 1] = { s[1] + off, cum * s[2] } end
				cum = cum * rs[#rs][2]
			else
				root[#root + 1] = { off, cum }
			end
			local fx = fxWindows.liveFor(id)
			if fx then
				for _, e in ipairs(fx) do
					local c = table.clone(e)
					c.t = (e.t or 0) + off
					partOf[c] = pi
					keyOf[c] = tostring(id) .. "#" .. CB.fxKey(e)
					fxAll[#fxAll + 1] = c
				end
			end
			off = lastT + 0.001
		end

		-- duplicated sfx (same sound in 2+ parts): auto-off in the shorter parts if Auto-off is ON.
		-- your manual ON/OFF choices (CB.fxOverride) always win over the automatic one.
		do
			local parts = {}
			for i, id in ipairs(ids) do parts[i] = { id = id, len = partLen[i], list = {}, keys = {} } end
			for _, e in ipairs(fxAll) do
				local P = parts[partOf[e]]
				P.list[#P.list + 1] = e
				P.keys[#P.keys + 1] = keyOf[e]
			end
			local _, autoOff = CB.analyze(parts)
			local removed, manual = 0, 0
			for _, P in ipairs(parts) do
				for j, e in ipairs(P.list) do
					local k = P.keys[j]
					if CB.stateOff(e, k, autoOff) then
						e.off = true
						if CB.fxOverride[k] == nil then removed += 1 else manual += 1 end
					end
				end
			end
			if removed > 0 then
				out(string.format("Combine: auto-off turned off %d duplicated sound(s) in the shorter animation(s) (they show as OFF, you can turn them ON)", removed))
			end
			if manual > 0 then
				out(string.format("Combine: %d fx turned off by you", manual))
			end
		end

		local names = {}
		for _, id in ipairs(ids) do names[#names + 1] = nm(id) end
		local name = table.concat(names, " + "):sub(1, 60)
		local digits = {}
		for _, id in ipairs(ids) do digits[#digits + 1] = tostring(id):match("%d+") or "x" end
		local cid = "combo:" .. table.concat(digits, "+")

		local joints = {}
		for _, n in ipairs(order) do
			joints[#joints + 1] = { name = n, part0 = meta[n].part0, part1 = meta[n].part1, frames = merged[n] }
		end
		details[cid] = {
			rig = rig, length = lastT, looped = false, joints = joints, allMotors = {},
			priorityValue = first.priorityValue, cache = {}, rawFrames = #joints[1].frames,
			source = "auto-combined", fromSaved = true,
		}
		animLabel[cid] = name
		animInfo[cid] = { priority = "Action", looped = false, speed = 1 }
		X.lens[cid] = lastT
		X.aeData[cid] = nil
		pcall(function() rbxmxCache[cid] = nil end)
		X.fxEdit[cid] = #fxAll > 0 and fxAll or nil
		if anyRoot then
			local maxH, maxUp = 0, 0
			local samples = {}
			for _, s in ipairs(root) do
				samples[#samples + 1] = s
				local p = s[2].Position
				maxH = math.max(maxH, Vector3.new(p.X, 0, p.Z).Magnitude)
				maxUp = math.max(maxUp, p.Y)
			end
			X.rootRec[X.rootKey(cid)] = { samples = samples, maxH = maxH, maxHoriz = maxH, maxUp = maxUp }
		end
		pcall(refreshExtra, cid)
		return cid, name, #ids, lastT
	end

	function CB.make(ids, force, onDone)
		local sig = table.concat(ids, "|")
		if not force and (CB.made[sig] or CB.count >= 30) then return end
		CB.made[sig] = true
		task.spawn(function()
			for _, id in ipairs(ids) do
				if not details[id] then
					local done, good = false, false
					requestDetail(id, function(ok)
						good = ok
						done = true
					end)
					local t0 = os.clock()
					while not done and os.clock() - t0 < 25 do task.wait(0.1) end
					if not good then
						out("Auto-combine: could not capture " .. nm(id) .. ", skipped this chain")
						return
					end
				end
			end
			local ok, cid, name, n, len = pcall(CB.build, ids)
			if not ok then
				out("Auto-combine failed: " .. tostring(cid))
				return
			end
			CB.count += 1
			CB.srcIds = CB.srcIds or {}
			CB.srcIds[cid] = table.clone(ids)
			X.edsSave(cid)
			out(string.format("Combined %d animations into \"%s\" (%.2fs). It is in Saved > Saved edits.", n, name, len))
			if onDone then onDone(cid, name) end
		end)
	end

	local function onTrack(track)
		if not Run.alive or CB.seen[track] then return end
		CB.seen[track] = true
		if ownTracks[track] or track.Looped or track.Priority == Enum.AnimationPriority.Core then return end
		local anim = track.Animation
		local id = anim and anim.AnimationId or ""
		if id == "" or excluded[id] or blocked[id] then return end
		local now = os.clock()
		local dur = math.max(track.Length, 0.1) / math.max(track.Speed, 0.05)
		local rec = { id = id, t = now, endT = now + dur }
		CB.recent[#CB.recent + 1] = rec
		while #CB.recent > 12 do table.remove(CB.recent, 1) end
		pcall(function()
			track.Stopped:Connect(function() rec.endT = os.clock() end)
		end)
		if not CB.on then return end
		local ch = CB.chain
		local d = ch and (now - ch.last.endT) or nil
		if ch and d <= CB.gap and d >= -0.5 and ch.last.id ~= id and #ch.ids < 6 then
			ch.ids[#ch.ids + 1] = id
			ch.last = rec
			ch.stamp += 1
			if #ch.ids == 2 then out("Auto-combine: chaining " .. nm(ch.ids[1]) .. " + " .. nm(id) .. " ...") end
		else
			ch = { ids = { id }, last = rec, stamp = 1 }
			CB.chain = ch
		end
		local stamp = ch.stamp
		task.delay(dur + CB.gap + 0.3, function()
			if CB.chain == ch and ch.stamp == stamp then
				CB.chain = nil
				if #ch.ids >= 2 then CB.make(ch.ids) end
			end
		end)
	end

	function CB.manual(btn)
		local ids, lastId = {}, nil
		local now = os.clock()
		for _, r in ipairs(CB.recent) do
			if now - r.t <= 15 and r.id ~= lastId and not excluded[r.id] and not blocked[r.id] then
				ids[#ids + 1] = r.id
				lastId = r.id
			end
		end
		while #ids > 6 do table.remove(ids, 1) end
		if #ids < 2 then
			out("Auto-combine: play at least 2 different animations first (it remembers the last 15 seconds, excluded ones are skipped)")
			if btn and btn.Parent then K.flash(btn, "Need 2") end
			return
		end
		CB.make(ids, true)
		if btn and btn.Parent then K.flash(btn, "Combining") end
	end

	local function hook(ch)
		local hum = ch:WaitForChild("Humanoid", 10)
		if not hum then return end
		pcall(function() hum.AnimationPlayed:Connect(onTrack) end)
		local function hookAnimator(a)
			if a:IsA("Animator") then
				pcall(function() a.AnimationPlayed:Connect(onTrack) end)
			end
		end
		for _, x in ipairs(hum:GetChildren()) do hookAnimator(x) end
		hum.ChildAdded:Connect(hookAnimator)
	end
	if lp.Character then task.spawn(hook, lp.Character) end
	table.insert(Run.conns, lp.CharacterAdded:Connect(function(ch) task.spawn(hook, ch) end))
end

-- ---------- manual combine window (opened from the Logged animations tab) ----------
do
	local function nm(id) return tostring(K.animName(id)) end
	local function lenOf(id)
		local l = X.lens[id] or (details[id] and details[id].length)
		return tonumber(l) or 0
	end

	local function loadTrack(id)
		local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
		if not hum then return nil end
		local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
		local a = Instance.new("Animation")
		a.AnimationId = id
		local ok, tr = pcall(function() return animator:LoadAnimation(a) end)
		if ok and tr then
			ownTracks[tr] = true
			return tr
		end
		return nil
	end

	function X.combo.stopSeq()
		local CB = X.combo
		CB.seqToken = (CB.seqToken or 0) + 1
		if CB.curTrack then
			pcall(function() CB.curTrack:Stop(0.1) end)
			CB.curTrack = nil
		end
	end

	-- plays the animations one after another; the next one starts when the previous one's LENGTH is over
	-- (it does not wait for sfx, vfx or movement)
	function X.combo.playSeq(ids, onStep)
		local CB = X.combo
		CB.stopSeq()
		local my = CB.seqToken
		task.spawn(function()
			for i, id in ipairs(ids) do
				if CB.seqToken ~= my then return end
				local tr = loadTrack(id)
				if not tr then
					out("Combine: could not play " .. nm(id))
					break
				end
				CB.curTrack = tr
				local t0 = os.clock()
				while tr.Length == 0 and os.clock() - t0 < 4 do task.wait() end
				tr:Play()
				if onStep then onStep(i) end
				local dur = math.max(tr.Length, 0.1) / math.max(tr.Speed, 0.05)
				local t1 = os.clock()
				while CB.seqToken == my and os.clock() - t1 < dur do task.wait() end
				if CB.seqToken ~= my then return end
				pcall(function() tr:Stop(0.05) end)
			end
			CB.curTrack = nil
			if onStep then onStep(nil) end
		end)
	end

	-- fx viewer: per animation (sfx / vfx) or all duplicates across the animations of the combo
	function X.combo.fxView(mode, partIdx)
		local CB = X.combo
		CB.sel = CB.sel or {}
		if X.cmbFxWin then pcall(X.cmbFxWin.destroy) end
		local title
		if mode == "dups" then
			title = "Duplicated fx"
		else
			title = string.upper(mode) .. " of " .. (CB.sel[partIdx] and nm(CB.sel[partIdx]) or "?")
		end
		local win = createWindow({
			title = title:sub(1, 40),
			size = Vector2.new(480, 440),
			pos = UDim2.new(0.5, -240, 0.5, -220),
			minSize = Vector2.new(320, 260),
			miniText = "FX",
			onClose = function() X.cmbFxWin = nil end,
		})
		X.cmbFxWin = win
		local content = win.content
		local info = Instance.new("TextLabel")
		info.Position = UDim2.new(0, 6, 0, 2)
		info.Size = UDim2.new(1, -12, 0, 22)
		info.BackgroundTransparency = 1
		info.TextColor3 = C.sub
		info.Font = Th.font
		info.TextSize = 13
		info.TextXAlignment = Enum.TextXAlignment.Left
		info.TextTruncate = Enum.TextTruncate.AtEnd
		info.Text = "ON/OFF here is your choice and beats auto-off. It is used when you press Complete."
		info.Parent = content
		local list = newList(content, UDim2.new(0, 4, 0, 26), UDim2.new(1, -8, 1, -30))

		local render
		render = function()
			for _, c in ipairs(list:GetChildren()) do
				if c:IsA("GuiObject") then c:Destroy() end
			end
			local parts = {}
			for i, id in ipairs(CB.sel) do
				parts[i] = { id = id, len = lenOf(id), list = fxWindows.liveFor(id) or {} }
			end
			local groups, autoOff, groupOf = CB.analyze(parts)
			local n = 0
			local function item(it, text)
				n += 1
				local e, key = it.e, it.key
				local off = CB.stateOff(e, key, autoOff)
				local ov = CB.fxOverride[key]
				local row = Instance.new("Frame")
				row.Size = UDim2.new(1, -6, 0, 58)
				row.BackgroundColor3 = n % 2 == 1 and C.row1 or C.row2
				row.BorderSizePixel = 0
				row.LayoutOrder = n
				row.Parent = list
				local lbl = Instance.new("TextLabel")
				lbl.Position = UDim2.new(0, 8, 0, 2)
				lbl.Size = UDim2.new(1, -16, 0, 22)
				lbl.BackgroundTransparency = 1
				lbl.TextXAlignment = Enum.TextXAlignment.Left
				lbl.TextTruncate = Enum.TextTruncate.AtEnd
				lbl.Font = Th.font
				lbl.TextSize = 14
				lbl.TextColor3 = off and C.sub or C.text
				lbl.Text = text .. (ov ~= nil and "  (your choice)" or (off and "  (auto off)" or ""))
				lbl.Parent = row
				local bar = X.mkBar(row, 26, 28)
				X.mkTool(bar, off and "OFF" or "ON", 56, off and C.danger or C.green, function()
					CB.fxOverride[key] = not off
					render()
				end)
				if ov ~= nil then
					X.mkTool(bar, "Auto", 56, C.btn, function()
						CB.fxOverride[key] = nil
						render()
					end)
				end
			end

			if mode == "dups" then
				info.Text = string.format("%d duplicated fx. Auto-off keeps sfx in the longest part. ON/OFF = your choice.", #groups)
				for _, G in ipairs(groups) do
					local h = Instance.new("TextLabel")
					h.Size = UDim2.new(1, -6, 0, 24)
					h.BackgroundColor3 = C.title
					h.BorderSizePixel = 0
					h.LayoutOrder = n + 0.5
					h.Font = Th.bold
					h.TextSize = 13
					h.TextColor3 = C.text
					h.TextXAlignment = Enum.TextXAlignment.Left
					h.TextTruncate = Enum.TextTruncate.AtEnd
					h.Text = string.format("  %s  %s  %s  - in %d parts (longest: part %d)", string.upper(G.kind), G.name, G.asset, G.nparts, G.best or 0)
					h.Parent = list
					n += 1
					h.LayoutOrder = n
					for _, it in ipairs(G.items) do
						item(it, string.format("Part %d: %s   t=%.2fs", it.part, nm(parts[it.part].id), it.e.t or 0))
					end
				end
			else
				local P = parts[partIdx]
				if P then
					local cnt = 0
					for j, e in ipairs(P.list) do
						if e.kind == mode then
							cnt += 1
							local G = groupOf[e]
							item({ e = e, key = tostring(P.id) .. "#" .. CB.fxKey(e) }, string.format("%s   t=%.2fs%s", tostring(e.name), e.t or 0, G and ("   DUPLICATED in " .. G.nparts .. " parts") or ""))
						end
					end
					info.Text = string.format("%d %s in this animation", cnt, mode)
				end
			end
			if n == 0 then
				local l = Instance.new("TextLabel")
				l.Size = UDim2.new(1, -6, 0, 40)
				l.BackgroundTransparency = 1
				l.TextWrapped = true
				l.Text = mode == "dups" and "No duplicated fx between these animations." or ("No " .. mode .. " recorded for this animation.")
				l.TextColor3 = C.sub
				l.Font = Th.font
				l.TextSize = 14
				l.Parent = list
			end
		end
		render()
	end

	function X.cmbOpen()
		local CB = X.combo
		CB.sel = CB.sel or {}
		if X.cmbWin then pcall(X.cmbWin.destroy) end
		local win = createWindow({
			title = "Combine animations",
			size = Vector2.new(520, 520),
			pos = UDim2.new(0.5, -260, 0.5, -260),
			minSize = Vector2.new(340, 340),
			miniText = "CMB",
			onClose = function()
				CB.stopSeq()
				X.cmbWin = nil
			end,
		})
		X.cmbWin = win
		local content = win.content

		local info = Instance.new("TextLabel")
		info.Position = UDim2.new(0, 6, 0, 2)
		info.Size = UDim2.new(1, -92, 0, 22)
		info.BackgroundTransparency = 1
		info.Text = "Logged animations: Play to find the part, then + Add in order"
		info.TextColor3 = C.sub
		info.Font = Th.font
		info.TextSize = 13
		info.TextXAlignment = Enum.TextXAlignment.Left
		info.TextTruncate = Enum.TextTruncate.AtEnd
		info.Parent = content

		local box = Instance.new("TextBox")
		box.Position = UDim2.new(0, 4, 0, 26)
		box.Size = UDim2.new(1, -8, 0, 26)
		box.BackgroundColor3 = C.code
		box.BorderSizePixel = 0
		box.PlaceholderText = "Search logged animations..."
		box.PlaceholderColor3 = C.sub
		box.Text = ""
		box.TextColor3 = C.text
		box.ClearTextOnFocus = false
		box.Font = Th.font
		box.TextSize = 14
		box.TextXAlignment = Enum.TextXAlignment.Left
		box.Parent = content
		local bp = Instance.new("UIPadding")
		bp.PaddingLeft = UDim.new(0, 6)
		bp.Parent = box

		local libList = newList(content, UDim2.new(0, 4, 0, 54), UDim2.new(1, -8, 0.38, 0))

		local hdr = Instance.new("TextLabel")
		hdr.Position = UDim2.new(0, 4, 0.38, 58)
		hdr.Size = UDim2.new(1, -8, 0, 22)
		hdr.BackgroundColor3 = C.title
		hdr.BorderSizePixel = 0
		hdr.TextColor3 = C.text
		hdr.Font = Th.bold
		hdr.TextSize = 13
		hdr.TextXAlignment = Enum.TextXAlignment.Left
		hdr.TextTruncate = Enum.TextTruncate.AtEnd
		hdr.Text = ""
		hdr.Parent = content

		local selList = newList(content, UDim2.new(0, 4, 0.38, 82), UDim2.new(1, -8, 0.62, -148))

		local function clearList(l)
			for _, c in ipairs(l:GetChildren()) do
				if c:IsA("GuiObject") then c:Destroy() end
			end
		end

		local function mkRow(parent, order, text, tools, hot)
			local row = Instance.new("Frame")
			row.Size = UDim2.new(1, -6, 0, 58)
			row.BackgroundColor3 = hot and C.sel or (order % 2 == 1 and C.row1 or C.row2)
			row.BorderSizePixel = 0
			row.LayoutOrder = order
			row.Parent = parent
			local lbl = Instance.new("TextLabel")
			lbl.Position = UDim2.new(0, 8, 0, 2)
			lbl.Size = UDim2.new(1, -16, 0, 22)
			lbl.BackgroundTransparency = 1
			lbl.TextXAlignment = Enum.TextXAlignment.Left
			lbl.TextTruncate = Enum.TextTruncate.AtEnd
			lbl.Font = Th.font
			lbl.TextSize = 14
			lbl.TextColor3 = C.text
			lbl.Text = text
			lbl.Parent = row
			local bar = X.mkBar(row, 26, 28)
			for _, t in ipairs(tools) do X.mkTool(bar, t[1], t[2], t[3], t[4]) end
		end

		local renderSel

		local function renderLib()
			clearList(libList)
			local ids, seen = {}, {}
			for _, r in ipairs(CB.recent) do
				if not seen[r.id] then
					seen[r.id] = true
					ids[#ids + 1] = r.id
				end
			end
			local rest = {}
			for id in pairs(entriesById) do
				if not seen[id] then
					seen[id] = true
					rest[#rest + 1] = id
				end
			end
			table.sort(rest, function(a, b) return nm(a):lower() < nm(b):lower() end)
			for _, id in ipairs(rest) do ids[#ids + 1] = id end
			local q = box.Text:lower()
			local n = 0
			for _, id in ipairs(ids) do
				local label = nm(id)
				if q == "" or (label .. " " .. id):lower():find(q, 1, true) then
					n += 1
					local l = lenOf(id)
					mkRow(libList, n, string.format("%s   %s%s", label, l > 0 and string.format("%.2fs", l) or "", excluded[id] and "  (excluded)" or ""), {
						{ "Play", 56, C.green, function()
							CB.playSeq({ id })
						end },
						{ "Stop", 56, C.danger, function()
							CB.stopSeq()
							stopAnimId(id)
						end },
						{ "+ Add", 66, C.sel, function(b)
							table.insert(CB.sel, id)
							renderSel()
							K.flash(b, "Added")
						end },
					})
				end
			end
			if n == 0 then
				local l = Instance.new("TextLabel")
				l.Size = UDim2.new(1, -6, 0, 40)
				l.BackgroundTransparency = 1
				l.Text = "No logged animations yet. Do a move, then press Refresh."
				l.TextColor3 = C.sub
				l.Font = Th.font
				l.TextSize = 14
				l.Parent = libList
			end
		end

		renderSel = function()
			clearList(selList)
			local total = 0
			if #CB.sel == 0 then
				local l = Instance.new("TextLabel")
				l.Size = UDim2.new(1, -6, 0, 40)
				l.BackgroundTransparency = 1
				l.TextWrapped = true
				l.Text = "Nothing yet. Press + Add on the animations above, in the order they should play."
				l.TextColor3 = C.sub
				l.Font = Th.font
				l.TextSize = 14
				l.Parent = selList
			end
			for i, id in ipairs(CB.sel) do
				total += lenOf(id)
				mkRow(selList, i, string.format("%d. %s   %.2fs", i, nm(id), lenOf(id)), {
					{ "Up", 44, C.btn, function()
						if i > 1 then
							CB.sel[i], CB.sel[i - 1] = CB.sel[i - 1], CB.sel[i]
							renderSel()
						end
					end },
					{ "Down", 54, C.btn, function()
						if i < #CB.sel then
							CB.sel[i], CB.sel[i + 1] = CB.sel[i + 1], CB.sel[i]
							renderSel()
						end
					end },
					{ "Play", 56, C.green, function()
						CB.playSeq({ id })
					end },
					{ "SFX", 50, C.btn, function() CB.fxView("sfx", i) end },
					{ "VFX", 50, C.btn, function() CB.fxView("vfx", i) end },
					{ "Remove", 70, C.danger, function()
						table.remove(CB.sel, i)
						renderSel()
					end },
				}, CB.cur == i)
			end
			hdr.Text = string.format("  Combo order: %d animations, %.2fs. The next one starts when the previous one's length is over", #CB.sel, total)
		end

		local function bottomBtn(i, text, color, fn, row, cols)
			cols, row = cols or 4, row or 1
			local b = K.newButton(content, text, color)
			b.Size = UDim2.new(1 / cols, -6, 0, 28)
			b.Position = UDim2.new((i - 1) / cols, 4, 1, -32 - (row - 1) * 32)
			b.MouseButton1Click:Connect(function() fn(b) end)
			return b
		end
		bottomBtn(1, "Play all", C.green, function()
			if #CB.sel == 0 then return out("Combine: add animations first") end
			CB.playSeq(table.clone(CB.sel), function(i)
				CB.cur = i
				if X.cmbWin then renderSel() end
			end)
		end)
		bottomBtn(2, "Stop", C.danger, function()
			CB.stopSeq()
			CB.cur = nil
			renderSel()
		end)
		bottomBtn(3, "Complete", C.sel, function(b)
			if #CB.sel < 2 then
				out("Combine: add at least 2 animations")
				return K.flash(b, "Need 2")
			end
			CB.make(table.clone(CB.sel), true, function(cid) X.cmbResult(cid) end)
			K.flash(b, "Working")
		end)
		bottomBtn(4, "Clear", C.btn, function()
			CB.sel = {}
			CB.fxOverride = {}
			renderSel()
		end)
		local function autoText() return CB.autoDup and "Auto-off dup sfx: ON" or "Auto-off dup sfx: OFF" end
		bottomBtn(1, autoText(), CB.autoDup and C.green or C.btn, function(b)
			CB.autoDup = not CB.autoDup
			b.Text = autoText()
			K.paint(b, CB.autoDup and C.green or C.btn)
		end, 2, 2)
		bottomBtn(2, "Show duplicates", C.sel, function()
			if #CB.sel < 2 then return out("Combine: add at least 2 animations") end
			CB.fxView("dups")
		end, 2, 2)

		local rf = K.newButton(content, "Refresh", C.btn)
		rf.Size = UDim2.new(0, 80, 0, 22)
		rf.Position = UDim2.new(1, -84, 0, 2)
		rf.TextSize = 13
		rf.MouseButton1Click:Connect(renderLib)
		box:GetPropertyChangedSignal("Text"):Connect(renderLib)

		renderLib()
		renderSel()
	end
end

-- ---------- result window for a combined animation: sfx/vfx on-off, edit, full code ----------
do
	local function counts(cid)
		local v, s = 0, 0
		for _, e in ipairs(X.fxEdit[cid] or {}) do
			if e.kind == "vfx" then v += 1 elseif e.kind == "sfx" then s += 1 end
		end
		return v, s
	end

	local function persist(cid)
		local okP, it = pcall(X.edsPack, cid)
		if not (okP and it) then return end
		it.sig = X.itemSig(it)
		X.eds.items[cid] = it
		if not table.find(X.eds.order, cid) then table.insert(X.eds.order, 1, cid) end
		X.edsWrite()
	end

	function X.cmbCode(cid)
		local it = X.eds.items[cid]
		if it and it.code and it.code ~= "" then return it.code end
		return K.buildAnimCode(cid, "fx")
	end

	function X.cmbResult(cid)
		if not details[cid] then pcall(X.edsApply, cid) end
		if not details[cid] then return out("Combine: this combo has no frames to open") end
		local CB = X.combo
		local name = tostring(K.animName(cid))
		if X.cmbResWin then pcall(X.cmbResWin.destroy) end
		local win = createWindow({
			title = "Combined: " .. name:sub(1, 30),
			size = Vector2.new(480, 440),
			pos = UDim2.new(0.5, -240, 0.5, -220),
			minSize = Vector2.new(320, 300),
			miniText = "CMB",
			onClose = function() X.cmbResWin = nil end,
		})
		X.cmbResWin = win
		local content = win.content

		local info = Instance.new("TextLabel")
		info.Position = UDim2.new(0, 6, 0, 2)
		info.Size = UDim2.new(1, -12, 0, 44)
		info.BackgroundTransparency = 1
		info.TextWrapped = true
		info.TextXAlignment = Enum.TextXAlignment.Left
		info.TextYAlignment = Enum.TextYAlignment.Top
		info.TextColor3 = C.sub
		info.Font = Th.font
		info.TextSize = 13
		info.Parent = content

		local list = newList(content, UDim2.new(0, 4, 0, 50), UDim2.new(1, -8, 1, -54))
		local n = 0
		local function add(text, color, fn)
			n += 1
			local b = K.newButton(list, text, color)
			b.Size = UDim2.new(1, -6, 0, 36)
			b.LayoutOrder = n
			b.TextXAlignment = Enum.TextXAlignment.Left
			b.TextSize = 15
			local pad = Instance.new("UIPadding")
			pad.PaddingLeft = UDim.new(0, 10)
			pad.Parent = b
			b.MouseButton1Click:Connect(function() fn(b) end)
			return b
		end
		local function safe(fn)
			local ok, res = pcall(fn)
			if not ok then out("Combine: " .. tostring(res)) end
			return ok, res
		end

		local btnV, btnS
		local function refresh()
			local d = details[cid]
			local v, s = counts(cid)
			local vOn, sOn = false, false
			for _, e in ipairs(X.fxEdit[cid] or {}) do
				if e.kind == "vfx" and not e.off then vOn = true end
				if e.kind == "sfx" and not e.off then sOn = true end
			end
			info.Text = string.format("%s\n%.2fs | %d joints | %d vfx, %d sfx events. Each part switches to the next when its animation length is over.",
				name, d.length or 0, #d.joints, v, s)
			btnV.Text = string.format("VFX: %s  (%d events)", (v == 0) and "none recorded" or (vOn and "ON" or "OFF"), v)
			btnS.Text = string.format("SFX: %s  (%d events)", (s == 0) and "none recorded" or (sOn and "ON" or "OFF"), s)
			K.paint(btnV, vOn and C.sel or C.btn)
			K.paint(btnS, sOn and C.sel or C.btn)
		end
		local function toggle(kind)
			local list2 = X.fxEdit[cid] or {}
			local anyOn = false
			for _, e in ipairs(list2) do
				if e.kind == kind and not e.off then anyOn = true end
			end
			for _, e in ipairs(list2) do
				if e.kind == kind then e.off = anyOn or nil end
			end
			persist(cid)
			refresh()
		end

		btnV = add("VFX", C.btn, function() toggle("vfx") end)
		btnS = add("SFX", C.btn, function() toggle("sfx") end)
		add("View full code", C.sel, function()
			safe(function()
				local code = X.cmbCode(cid)
				openViewer("Combined - " .. name, { { name = "Script", get = function(cb) cb(code) end } }, 1)
			end)
		end)
		add("Copy code", C.sel, function(b)
			local ok, code = safe(function() return X.cmbCode(cid) end)
			if ok then
				toClip(code, "the combined script")
				K.flash(b, "Copied!")
			end
		end)
		add("Download file (name it)", C.green, function(b)
			local ok, code = safe(function() return X.cmbCode(cid) end)
			if ok then X.saveScriptFile(code, "Combo_" .. name:gsub("[^%w]+", "_"):sub(1, 30), b) end
		end)
		add("Edit code", C.btn, function()
			safe(function()
				local it = X.eds.items[cid]
				if not it then
					persist(cid)
					it = X.eds.items[cid]
				end
				X.codeEdit("Edit code - " .. name, X.cmbCode(cid), function(text)
					it.code = text
					X.edsWrite()
				end, function()
					it.code = nil
					X.edsWrite()
					return X.cmbCode(cid)
				end)
			end)
		end)
		add("Edit animation (timeline)", C.btn, function()
			safe(function() X.aeOpen(cid) end)
		end)
		add("Edit effects (FX editor)", C.btn, function()
			safe(function() X.edOpen(cid) end)
		end)
		add("Preview", C.green, function()
			safe(function() X.pvOpen(cid, { id = cid, name = name }) end)
		end)
		add("Play the original parts in order", C.green, function()
			local src = CB.srcIds and CB.srcIds[cid]
			if not src then return out("Combine: the original parts are only remembered until you close the game. Use Preview.") end
			CB.playSeq(table.clone(src))
		end)
		add("Copy NPC / player version", C.btn, function(b) X.npcCodeFor(cid, b) end)
		add("Save changes", C.sel, function(b)
			persist(cid)
			K.flash(b, "Saved!")
			if X.svReady then X.svRender() end
		end)
		refresh()
	end
end
X.SAVED_FILE = "AnimLogger_saved.json"
X.KEY_FILE = "AnimLogger_key.txt"

function X.svLoad()
	if not (isfile and readfile) then return end
	local ok, data = pcall(function()
		if isfile(X.SAVED_FILE) then return HttpService:JSONDecode(readfile(X.SAVED_FILE)) end
	end)
	if not (ok and type(data) == "table") then return end
	for _, e in ipairs(type(data.a) == "table" and data.a or {}) do
		if type(e) == "table" and e.i and #X.sv.list < 500 then
			local id = tostring(e.i)
			if id:match("^%d+$") then id = "rbxassetid://" .. id end
			if not X.sv.map[id] then
				local r = { id = id, name = tostring(e.n or id):sub(1, 60), fav = e.f == 1, t = tonumber(e.t) or 0 }
				if type(e.g) == "string" and e.g ~= "" then
					r.folder = X.svFolderClean(e.g)
					if r.folder == "" then r.folder = nil end
				end
				if type(e.np) == "string" and e.np ~= "" then r.npc = e.np:sub(1, 60) end
				if type(e.rt) == "table" and not X.rootRec[X.rootKey(id)] then
					local okR, rr = pcall(X.svRootDec, e.rt)
					if okR and rr then X.rootRec[X.rootKey(id)] = rr end
				end
				table.insert(X.sv.list, r)
				X.sv.map[id] = r
			end
		end
	end
	if type(data.fo) == "table" then
		for _, f in ipairs(data.fo) do
			local fn = X.svFolderClean(f)
			if fn ~= "" and not X.svFolderExists(fn) then table.insert(X.sv.folders, fn) end
		end
	end
	for _, r in ipairs(X.sv.list) do
		if r.folder and not X.svFolderExists(r.folder) then table.insert(X.sv.folders, r.folder) end
	end
	if type(data.j) == "table" then X.ds.joy = X.joyNew(data.j) end
	if type(data.jp) == "table" then X.ds.jump = X.jumpNew(data.jp) end
	if type(data.d) == "table" then
		for _, b in ipairs(data.d) do
			if type(b) == "table" and #X.ds.buttons < 30 then X.dsNew(b, true) end
		end
	end
end

function X.svWrite()
	if not writefile then return end
	local a = {}
	for i, r in ipairs(X.sv.list) do
		local okRt, rt = pcall(X.svRootEnc, r.id)
		a[i] = { i = r.id:match("^rbxassetid://(%d+)$") or r.id, n = r.name, f = r.fav and 1 or nil, t = r.t,
			g = (r.folder and r.folder ~= "") and r.folder or nil, np = r.npc, rt = okRt and rt or nil }
	end
	local d = {}
	for i, b in ipairs(X.ds.buttons) do d[i] = b end
	local ok, json = pcall(function() return HttpService:JSONEncode({ v = 1, a = a, fo = X.sv.folders, d = d, j = X.ds.joy, jp = X.ds.jump }) end)
	if ok then pcall(writefile, X.SAVED_FILE, json) end
end

function X.svAfter()
	X.svDirty = true
	if X.svReady then X.svRender() end
end

function X.svToggle(id, name)
	local r = X.sv.map[id]
	if r then
		table.remove(X.sv.list, table.find(X.sv.list, r))
		X.sv.map[id] = nil
		if X.kept[id] then
			X.kept[id] = nil
			X.keptDirty = true
		end
	elseif #X.sv.list < 500 then
		r = { id = id, name = tostring(name or id):sub(1, 60), fav = false, t = os.time() }
		table.insert(X.sv.list, r)
		X.sv.map[id] = r
		if X.keepFrames then X.keepFrames(id) end
	end
	X.svAfter()
end

function X.svFav(id, name)
	local r = X.sv.map[id]
	if not r then
		X.svToggle(id, name)
		r = X.sv.map[id]
	end
	if r then r.fav = not r.fav end
	X.svAfter()
end

X.TOOLPACK_RT = [==[
local Players = game:GetService("Players")
local UIS = game:GetService("UserInputService")
local CAS = game:GetService("ContextActionService")
local RunService = game:GetService("RunService")
local StarterGui = game:GetService("StarterGui")
local lp = Players.LocalPlayer
local mouse = lp:GetMouse()

local SWITCH_KEY = Enum.KeyCode.R -- switch a tool between "Me" and "NPC" (also an on-screen button on phones)
local RANGE = 120 -- studs: NPC mode without clicking an NPC picks the nearest one inside this range

local env = (getgenv and getgenv()) or _G
if env.__ToolPackStop then pcall(env.__ToolPackStop) end

local tools, conns = {}, {}
local compiled = {}

local function notify(text)
	print("[ToolPack] " .. text)
	pcall(function()
		StarterGui:SetCore("SendNotification", { Title = "Tool Pack", Text = text, Duration = 2.5 })
	end)
end

local function getFn(i)
	if compiled[i] then return compiled[i] end
	local f, err = loadstring(PACK[i].code)
	if not f then
		warn("[ToolPack] could not load " .. PACK[i].name .. ": " .. tostring(err))
		notify("Could not load " .. PACK[i].name)
		return nil
	end
	compiled[i] = f
	return f
end

-- network ownership + SimulationRadius trick: keeps the NPC simulated by you so the animation and movement show up
local function keepOwnership(model, seconds)
	local stopAt = os.clock() + seconds + 1.5
	task.spawn(function()
		while os.clock() < stopAt and model.Parent do
			pcall(function() sethiddenproperty(lp, "SimulationRadius", 1e9) end)
			pcall(function() sethiddenproperty(lp, "MaximumSimulationRadius", 1e9) end)
			pcall(function() lp.SimulationRadius = 1e9 end)
			RunService.Heartbeat:Wait()
		end
	end)
end

local function humOf(model)
	return model and model:FindFirstChildOfClass("Humanoid")
end

local function playOn(i, model)
	local e = PACK[i]
	local hum = humOf(model)
	if not hum then return notify("No humanoid to animate") end
	if e.rig ~= "Custom" and hum.RigType.Name ~= e.rig then
		return notify(e.name .. " is made for " .. e.rig .. ", this target is " .. hum.RigType.Name)
	end
	local f = getFn(i)
	if not f then return end
	task.spawn(function()
		if model ~= lp.Character then
			keepOwnership(model, e.len)
			local hrp = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
			local t0 = os.clock()
			if isnetworkowner and hrp then
				while not isnetworkowner(hrp) and os.clock() - t0 < 1.5 do task.wait(0.05) end
			end
		end
		env.__ToolAnimTarget = model
		_G.__ToolAnimTarget = model
		local ok, err = pcall(f)
		env.__ToolAnimTarget = nil
		_G.__ToolAnimTarget = nil
		if not ok then warn("[ToolPack] " .. tostring(err)) end
	end)
end
env.ToolPack = { play = function(name, model)
	for i, e in ipairs(PACK) do
		if e.name == name then return playOn(i, model or lp.Character) end
	end
end }

local function npcModel(m)
	return m and m:IsA("Model") and m ~= lp.Character and humOf(m) and not Players:GetPlayerFromCharacter(m)
end

local function npcUnderMouse()
	local cur = mouse.Target
	while cur and cur ~= workspace do
		if cur:IsA("Model") and humOf(cur) then
			return npcModel(cur) and cur or nil
		end
		cur = cur.Parent
	end
	return nil
end

local function nearestNpc()
	local root = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
	if not root then return nil end
	local best, bestD
	for _, d in ipairs(workspace:GetDescendants()) do
		if d:IsA("Humanoid") and d.Health > 0 and npcModel(d.Parent) then
			local hrp = d.Parent:FindFirstChild("HumanoidRootPart") or d.Parent.PrimaryPart
			if hrp then
				local dist = (hrp.Position - root.Position).Magnitude
				if dist <= RANGE and (not bestD or dist < bestD) then best, bestD = d.Parent, dist end
			end
		end
	end
	return best
end

local function makeTool(i)
	local e = PACK[i]
	local tool = Instance.new("Tool")
	tool.Name = e.name:sub(1, 40)
	tool.RequiresHandle = false
	tool.CanBeDropped = false
	local mode = "Me"
	local action = "ToolPackSwitch_" .. i
	local function describe()
		tool.ToolTip = (mode == "Me" and "Click: play on you" or "Click an NPC: play on it") .. " (" .. SWITCH_KEY.Name .. " = switch)"
	end
	describe()

	local function switch(_, state)
		if state ~= Enum.UserInputState.Begin then return end
		mode = (mode == "Me") and "NPC" or "Me"
		describe()
		pcall(function() CAS:SetTitle(action, mode) end)
		notify(e.name .. ": " .. (mode == "Me" and "plays on you" or "plays on the NPC you click"))
	end

	table.insert(conns, tool.Equipped:Connect(function()
		CAS:BindAction(action, switch, true, SWITCH_KEY)
		pcall(function() CAS:SetTitle(action, mode) end)
	end))
	table.insert(conns, tool.Unequipped:Connect(function()
		CAS:UnbindAction(action)
	end))
	table.insert(conns, tool.Destroying:Connect(function()
		CAS:UnbindAction(action)
	end))
	table.insert(conns, tool.Activated:Connect(function()
		if mode == "NPC" then
			local npc = npcUnderMouse() or nearestNpc()
			if npc then playOn(i, npc) else notify("No NPC found (click one or stand closer)") end
		else
			local holder = tool.Parent
			if not (holder and holder:IsA("Model") and humOf(holder)) then holder = lp.Character end
			playOn(i, holder)
		end
	end))
	return tool
end

local function giveAll()
	for _, t in ipairs(tools) do pcall(function() t:Destroy() end) end
	table.clear(tools)
	local bp = lp:FindFirstChildOfClass("Backpack") or lp:WaitForChild("Backpack", 10)
	if not bp then return end
	for i = 1, #PACK do
		local t = makeTool(i)
		t.Parent = bp
		tools[#tools + 1] = t
	end
end

giveAll()
table.insert(conns, lp.CharacterAdded:Connect(function()
	task.wait(1)
	giveAll()
end))

env.__ToolPackStop = function()
	for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
	table.clear(conns)
	for i = 1, #PACK do pcall(function() CAS:UnbindAction("ToolPackSwitch_" .. i) end) end
	for _, t in ipairs(tools) do pcall(function() t:Destroy() end) end
	table.clear(tools)
	if _G.StopNpcAnim then pcall(_G.StopNpcAnim) end
	env.__ToolPackStop = nil
end

notify(#PACK .. " tool(s) added to your Backpack. Click = play on you, " .. SWITCH_KEY.Name .. " = switch to NPC mode.")
]==]

-- ---------- Saved page: pick animations, download a tool pack (player + NPC) ----------
X.svSel = X.svSel or {}
X.svSelMode = X.svSelMode or false
X.svVisible = X.svVisible or {}

function X.svSelCount()
	local n = 0
	for _ in pairs(X.svSel) do n += 1 end
	return n
end

function X.svSelRefresh()
	if X.svDlBtn and X.svDlBtn.Parent and not X.svPacking then
		X.svDlBtn.Text = "Download tools (" .. X.svSelCount() .. ")"
	end
end

function X.svSelTool(bar, id)
	if not X.svSelMode then return end
	local on = X.svSel[id] == true
	X.mkTool(bar, on and "[x] Picked" or "[ ] Pick", 92, on and C.green or C.btn, function(b)
		if X.svSel[id] then X.svSel[id] = nil else X.svSel[id] = true end
		local now = X.svSel[id] == true
		b.Text = now and "[x] Picked" or "[ ] Pick"
		K.paint(b, now and C.green or C.btn)
		X.svSelRefresh()
	end)
end

function X.longStr(code)
	local n = 2
	while code:find("]" .. ("="):rep(n) .. "]", 1, true) do n += 1 end
	local eq = ("="):rep(n)
	return "[" .. eq .. "[\n" .. code .. "\n]" .. eq .. "]"
end

function X.svToolPack(btn)
	if X.svPacking then return out("Tool pack: still building, one moment") end
	local ids, seenR = {}, {}
	local function add(id)
		local rid = X.savedId(id)
		if not seenR[rid] then
			seenR[rid] = true
			ids[#ids + 1] = { id = id, rid = rid }
		end
	end
	for _, r in ipairs(X.sv.list) do
		if X.svSel[r.id] then add(r.id) end
	end
	for _, id in ipairs(X.eds.order) do
		local it = X.eds.items[id]
		if X.svSel[id] and it and it.anim then add(id) end
	end
	if #ids == 0 then
		out("Tool pack: turn Select ON and press Pick on the animations you want first")
		if btn and btn.Parent then K.flash(btn, "Pick some") end
		return
	end
	X.svPacking = true
	task.spawn(function()
		local entries, failed = {}, {}
		for n, e in ipairs(ids) do
			if btn and btn.Parent then btn.Text = string.format("Building %d/%d", n, #ids) end
			local name = (X.eds.items[e.id] and X.eds.items[e.id].name) or animLabel[e.id] or tostring(K.animName(e.id))
			name = tostring(name):sub(1, 40)
			local code, why, done = nil, nil, false
			X.npcGenAsync(e.rid, function(c, err)
				code, why, done = c, err, true
			end)
			local t0 = os.clock()
			while not done and os.clock() - t0 < 120 do task.wait(0.1) end
			if code then
				code = (code:gsub("local AUTO = true", "local AUTO = false", 1))
				code = (code:gsub("local TARGET_MODEL = nil", "local TARGET_MODEL = (getgenv and getgenv().__ToolAnimTarget) or _G.__ToolAnimTarget", 1))
				local d = details[e.rid]
				entries[#entries + 1] = string.format("\t{ name = %q, rig = %q, len = %.2f, code = %s },", name, tostring(d and d.rig or "Custom"), (d and d.length) or 3, X.longStr(code))
			else
				failed[#failed + 1] = name .. " (" .. tostring(why or "timed out"):sub(1, 40) .. ")"
			end
		end
		X.svPacking = false
		if #entries == 0 then
			out("Tool pack: nothing could be built. " .. table.concat(failed, "; "))
			if btn and btn.Parent then K.flash(btn, "Failed") end
			X.svSelRefresh()
			return
		end
		if #failed > 0 then out("Tool pack: skipped " .. table.concat(failed, "; ")) end
		local code = string.format("-- TOOL PACK made by RecorderPP: %d animation tool(s) for your Backpack.\n-- Equip one and click = plays on you. Press R (or the on-screen button) = NPC mode, then click an NPC.\n-- Client-side: only you see it. NPC mode uses the network ownership + SimulationRadius trick.\nlocal PACK = {\n%s\n}\n\n%s", #entries, table.concat(entries, "\n"), X.TOOLPACK_RT)
		X.svSelRefresh()
		X.saveScriptFile(code, "ToolPack", btn)
	end)
end

function X.svRender()
	local sf = lists.Saved
	if not (sf and sf.Parent) then return end
	pcall(X.svFolderBarBuild, sf.Parent)
	for _, c in ipairs(sf:GetChildren()) do
		if c:IsA("GuiObject") then c:Destroy() end
	end
	local items, favs = {}, 0
	for _, r in ipairs(X.sv.list) do
		if r.fav then favs += 1 end
		local q = X.svQuery or ""
		if (X.svFilter == "all" or r.fav) and X.svFolderOk(r) and (q == "" or (r.name .. " " .. r.id .. " " .. (r.folder or "")):lower():find(q, 1, true)) then items[#items + 1] = r end
	end
	table.sort(items, function(a, b)
		if a.fav ~= b.fav then return a.fav end
		return (a.t or 0) > (b.t or 0)
	end)
	X.svVisible = {}
	for _, r in ipairs(items) do X.svVisible[#X.svVisible + 1] = r.id end
	for _, eid in ipairs(X.eds.order) do
		local eit = X.eds.items[eid]
		if eit and eit.anim then X.svVisible[#X.svVisible + 1] = eid end
	end
	X.svInfo.Text = string.format("%d saved, %d favorite%s. Tap Copy to get the code. Tap More for extra tools.", #X.sv.list, favs, favs == 1 and "" or "s")
	for k, b in pairs(X.svChips) do K.paint(b, k == X.svFilter and C.sel or C.btn) end
	if X.svMoreBtn then K.paint(X.svMoreBtn, X.svMore and C.sel or C.btn) end
	pcall(X.edsRows, sf)
	if #items == 0 then
		local l = Instance.new("TextLabel")
		l.Size = UDim2.new(1, -6, 0, 60)
		l.BackgroundTransparency = 1
		l.TextWrapped = true
		l.Text = "Nothing here yet. Press Save on any animation (Animations or Search tab), or pick another folder."
		l.TextColor3 = C.sub
		l.Font = Th.font
		l.TextSize = 15
		l.Parent = sf
		return
	end
	for i, r in ipairs(items) do
		local row = Instance.new("Frame")
		row.Size = UDim2.new(1, -6, 0, 78)
		row.BackgroundColor3 = i % 2 == 1 and C.row1 or C.row2
		row.BorderSizePixel = 0
		row.LayoutOrder = i
		row.Parent = sf
		local lbl = Instance.new("TextLabel")
		lbl.Position = UDim2.new(0, 8, 0, 2)
		lbl.Size = UDim2.new(1, -16, 0, 36)
		lbl.BackgroundTransparency = 1
		lbl.RichText = true
		lbl.TextXAlignment = Enum.TextXAlignment.Left
		lbl.TextTruncate = Enum.TextTruncate.AtEnd
		lbl.Font = Th.font
		lbl.TextSize = 15
		lbl.TextColor3 = C.text
		lbl.Text = string.format('<b>%s%s</b>\n<font color="%s">%s%s</font>', r.fav and "* " or "", K.esc(r.name), K.hex(C.sub), K.esc(r.id), (X.kept[r.id] and "   [frames kept: works in any game]" or "") .. ((r.folder and r.folder ~= "") and ("   [folder: " .. K.esc(r.folder) .. "]") or ""))
		lbl.Parent = row
		local bar = X.mkBar(row, 40, 34)
		X.svSelTool(bar, r.id)
		X.mkTool(bar, r.fav and "Unfav" or "Fav", 60, C.btn, function() X.svFav(r.id, r.name) end)
		X.mkTool(bar, "Copy", 56, C.sel, function(b) X.copyAnim(X.savedId(r.id), nil, b, "Copy") end)
		X.mkTool(bar, "Copy + FX", 80, C.sel, function(b) X.copyAnim(X.savedId(r.id), "cut", b, "Copy + FX") end)
		X.mkTool(bar, "Public SFX", 88, C.green, function(b) X.pubSfx.fixSaved(r.id, b) end)
		X.mkTool(bar, "Swap SFX", 80, C.btn, function()
			local src, commit = X.pubSfx.savedOps(r.id)
			X.pubSfx.openManual(r.name or r.id, src, commit)
		end)
		X.mkTool(bar, "Edit anim", 80, C.green, function(b) X.svEditAnim(r.id, b) end)
		if X.svMore then X.mkTool(bar, "View", 52, C.sel, function() X.openAnimViewer(X.savedId(r.id)) end) end
		X.mkTool(bar, "Preview", 66, C.green, function() X.pvOpen(r.id, { id = r.id, name = r.name }) end)
		if X.svMore then X.mkTool(bar, X.convLabel(r.id), 66, C.sel, function(b) X.convCopy(X.savedId(r.id), b) end) end
		if X.svMore and not X.kept[r.id] then
			X.mkTool(bar, "Keep", 52, C.btn, function(b)
				X.keepFail[r.id] = nil
				X.keepFrames(r.id, b)
			end)
		end
		if not tostring(r.id):find("#s%d+") then X.mkTool(bar, "Run", 46, C.green, function() K.playAnim(r.id) end) end
		X.mkTool(bar, "Stop", 52, C.danger, function(b)
			local n = stopAnimId(r.id)
			local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
			local animator = hum and hum:FindFirstChildOfClass("Animator")
			if animator then
				for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
					if tr.Animation and tr.Animation.AnimationId == r.id then
						tr:Stop(0)
						n += 1
					end
				end
			end
			K.flash(b, n > 0 and "Stopped" or "None")
		end)
		X.mkTool(bar, "Rename", 70, C.btn, function()
			X.prompt("Rename animation", r.name, function(text)
				local nv = tostring(text):gsub("^%s+", ""):gsub("%s+$", "")
				if nv == "" then return end
				r.name = nv:sub(1, 60)
				animLabel[r.id] = r.name
				X.svAfter()
			end)
		end)
		if X.svMore then X.mkTool(bar, "To Design", 78, C.btn, function(b)
			X.dsNew({ anim = r.id, animName = r.name, label = tostring(r.name):sub(1, 5) })
			X.svDirty = true
			K.flash(b, "Added")
		end) end
		X.mkTool(bar, "Folder", 62, C.btn, function() X.svFolderPick(r) end)
		X.mkTool(bar, "NPC code", 78, C.green, function(b) X.npcCodeFor(X.savedId(r.id), b) end)
		X.mkTool(bar, "NPC file", 70, C.btn, function(b) X.npcFileFor(X.savedId(r.id), b) end)
		X.mkTool(bar, "Remove", 66, C.danger, function() X.svToggle(r.id) end)
	end
end

X.EDITS_FILE = "AnimLogger_edits.json"
X.eds = { items = {}, order = {} }

function X.enc(v)
	local tv = typeof(v)
	if tv == "number" then
		if v ~= v then return { __n = "nan" } end
		if v == math.huge then return { __n = "inf" } end
		if v == -math.huge then return { __n = "-inf" } end
		return math.floor(v * 1e5 + 0.5) / 1e5
	elseif tv == "string" or tv == "boolean" then
		return v
	elseif tv == "CFrame" then
		local c = { v:GetComponents() }
		for i, n in ipairs(c) do c[i] = math.floor(n * 1e6 + 0.5) / 1e6 end
		return { __cf = c }
	elseif tv == "Vector3" then
		return { __v3 = { v.X, v.Y, v.Z } }
	elseif tv == "Color3" then
		return { __c3 = { v.R, v.G, v.B } }
	elseif tv == "table" then
		local n, isArr = #v, true
		for k in pairs(v) do
			if type(k) ~= "number" then
				isArr = false
				break
			end
		end
		local out = {}
		if isArr then
			for i = 1, n do
				local e = X.enc(v[i])
				if e == nil then e = false end
				out[i] = e
			end
		else
			for k, val in pairs(v) do
				if type(k) == "string" and k:sub(1, 1) ~= "_" then
					local e = X.enc(val)
					if e ~= nil then out[k] = e end
				end
			end
		end
		return out
	end
	return nil
end

function X.dec(v)
	if type(v) ~= "table" then return v end
	if v.__cf then return CFrame.new(table.unpack(v.__cf)) end
	if v.__v3 then return Vector3.new(table.unpack(v.__v3)) end
	if v.__c3 then return Color3.new(table.unpack(v.__c3)) end
	if v.__n then return v.__n == "nan" and 0 or (v.__n == "inf" and math.huge or -math.huge) end
	local out = {}
	for k, val in pairs(v) do out[k] = X.dec(val) end
	return out
end

function X.edsLoad()
	if not (isfile and readfile) then return end
	local ok, data = pcall(function()
		if isfile(X.EDITS_FILE) then return HttpService:JSONDecode(readfile(X.EDITS_FILE)) end
	end)
	if not (ok and type(data) == "table" and type(data.items) == "table") then return end
	for id, it in pairs(data.items) do
		if type(it) == "table" then
			X.eds.items[id] = it
			X.eds.order[#X.eds.order + 1] = id
		end
	end
	table.sort(X.eds.order, function(a, b) return (X.eds.items[a].t or 0) > (X.eds.items[b].t or 0) end)
end

function X.edsWrite()
	if not writefile then return false end
	local ok, json = pcall(function() return HttpService:JSONEncode({ v = 1, items = X.eds.items }) end)
	if not ok then return false end
	return (pcall(writefile, X.EDITS_FILE, json))
end

function X.packAnim(id)
	local d = details[id]
	if not (d and d.joints and #d.joints > 0) then return nil end
	local idx, tr = {}, {}
	local function slot(arr)
		local i = idx[arr]
		if not i then
			local rows = {}
			for k, f in ipairs(arr) do
				local c = { f[2]:GetComponents() }
				local row = { math.floor(f[1] * 1e5 + 0.5) / 1e5 }
				for _, n in ipairs(c) do row[#row + 1] = math.floor(n * 1e5 + 0.5) / 1e5 end
				rows[k] = row
			end
			tr[#tr + 1] = rows
			i = #tr
			idx[arr] = i
		end
		return i
	end
	local joints, motors = {}, {}
	for i, j in ipairs(d.joints) do joints[i] = { name = j.name, part0 = j.part0, part1 = j.part1, slot = slot(j.frames) } end
	for i, m in ipairs(d.allMotors or {}) do motors[i] = { name = m.name, parent = m.parent, slot = slot(m.samples) } end
	local info = animInfo[id] or {}
	return {
		rig = d.rig, length = d.length, looped = d.looped and true or false, source = d.source or "saved",
		priorityValue = d.priorityValue, priority = info.priority or "Action", tr = tr, joints = joints, motors = motors,
	}
end

X.origPack = {}
function X.origRemember(id)
	local d = details[id]
	if X.origPack[id] or not d or d.fromSaved then return end
	local ok, pack = pcall(X.packAnim, id)
	if ok and pack then X.origPack[id] = pack end
end

function X.edsPack(id)
	local old = X.eds.items[id]
	local it = { id = id, name = K.animName(id), t = os.time(), code = old and old.code or nil }
	local anim = X.packAnim(id)
	if anim then it.anim = anim end
	local okRt, rtEnc = pcall(X.svRootEnc, id)
	if okRt and rtEnc then it.root = rtEnc end
	local list = X.fxEdit[id] or fxWindows.rawFor(id)
	if list and #list > 0 then
		local fx, nfx = {}, 0
		for _, e in ipairs(list) do
			if e.kind == "cam" or nfx < 300 then
				if e.kind ~= "cam" then nfx += 1 end
				fx[#fx + 1] = X.enc(e)
			end
		end
		it.fx = fx
	end
	it.orig = X.origPack[id] or (old and old.orig) or nil
	local raw = fxWindows.rawFor(id)
	if raw and #raw > 0 then
		local fo, nfo = {}, 0
		for _, e in ipairs(raw) do
			if e.kind == "cam" or nfo < 300 then
				if e.kind ~= "cam" then nfo += 1 end
				fo[#fo + 1] = X.enc(e)
			end
		end
		it.fxOrig = fo
	elseif old and old.fxOrig then
		it.fxOrig = old.fxOrig
	end
	return it
end

function X.renameAnim(id)
	X.prompt("Rename saved script", K.animName(id), function(text)
		local nv = tostring(text):match("^%s*(.-)%s*$")
		if nv == "" then return end
		nv = nv:sub(1, 60)
		animLabel[id] = nv
		local r = X.sv.map[id]
		if r then r.name = nv end
		local it = X.eds.items[id]
		if it then
			it.name = nv
			X.edsWrite()
		end
		out("Renamed to \"" .. nv .. "\".")
		X.svAfter()
	end)
end

function X.hashVal(v, h)
	local M = 2147483629
	local tv = type(v)
	if tv == "number" then
		if v ~= v or v == math.huge or v == -math.huge then return (h * 31 + 11) % M end
		return (h * 31 + (math.floor(v * 1e6 + 0.5) % 1000003) + 7) % M
	elseif tv == "string" then
		h = (h * 31 + #v) % M
		for i = 1, #v, 5 do h = (h * 31 + v:byte(i)) % M end
		return h
	elseif tv == "boolean" then
		return (h * 31 + (v and 3 or 5)) % M
	elseif tv == "table" then
		if #v > 0 then
			for _, x in ipairs(v) do h = X.hashVal(x, (h * 31 + 1) % M) end
		else
			local keys = {}
			for k in pairs(v) do keys[#keys + 1] = tostring(k) end
			table.sort(keys)
			for _, k in ipairs(keys) do
				h = X.hashVal(k, (h * 31 + 2) % M)
				local x = v[k]
				if x == nil then x = v[tonumber(k) or k] end
				h = X.hashVal(x, h)
			end
		end
		return h
	end
	return h
end

function X.itemSig(it)
	local ok, h = pcall(function()
		return X.hashVal(it.fx or false, X.hashVal(it.anim or false, 17))
	end)
	return ok and h or nil
end

function X.edsSave(id, btn)
	local function say(t)
		if btn and btn.Parent then K.flash(btn, t) end
	end
	local okP, it = pcall(X.edsPack, id)
	if not okP then
		out("Save failed: " .. tostring(it))
		return say("Fail")
	end
	if not it.anim and not it.fx then
		out("Nothing to save yet for this animation: capture its frames (Copy / Anim Editor) or its effects first.")
		return say("Nothing")
	end
	local old = X.eds.items[id]
	local archivedAs
	it.sig = X.itemSig(it)
	if old then
		if old.sig == nil then old.sig = X.itemSig(old) end
		if it.sig ~= nil and old.sig == it.sig then
			it.code = old.code
		else
			it.code = nil
			local stamp = tonumber(old.t) or os.time()
			local key = id .. "#s" .. tostring(stamp)
			while X.eds.items[key] do key = key .. "x" end
			old.id = key
			old.name = tostring(old.name or id):sub(1, 40) .. " (older save " .. os.date("%d/%m %H:%M:%S", stamp) .. ")"
			X.eds.items[key] = old
			local pos = table.find(X.eds.order, id)
			if pos then X.eds.order[pos] = key else table.insert(X.eds.order, key) end
			table.insert(X.eds.order, 1, id)
			archivedAs = old.name
			if #X.sv.list < 500 and not X.sv.map[key] then
				local r = { id = key, name = old.name, fav = false, t = stamp }
				table.insert(X.sv.list, r)
				X.sv.map[key] = r
			end
			if old.anim then
				local kit = table.clone(old)
				kit.kept, kit.code, kit.orig, kit.fxOrig = true, nil, nil, nil
				X.kept[key] = kit
				X.keptDirty = true
			end
			X.svDirty = true
		end
	else
		table.insert(X.eds.order, 1, id)
	end
	X.eds.items[id] = it
	if it.anim then
		local kit = table.clone(it)
		kit.kept, kit.code, kit.orig, kit.fxOrig = true, nil, nil, nil
		X.kept[id] = kit
		X.keptDirty = true
	end
	local wrote = X.edsWrite()
	out(string.format("Saved edit \"%s\" (%s%s)%s. It is in the Saved tab > Saved edits.", it.name, it.anim and "animation" or "", (it.anim and it.fx) and " + effects" or (it.fx and "effects" or ""),
		wrote and "" or " - this executor cannot write files, so it only lasts until you close the game"))
	if archivedAs then out("The earlier save was kept too: \"" .. archivedAs .. "\".") end
	say("Saved!")
	if X.svReady then X.svRender() end
end

function X.edsApply(id, src)
	local it = src or X.eds.items[id]
	if not it then return false end
	pcall(X.origRemember, id)
	if it.orig and not X.origPack[id] then X.origPack[id] = it.orig end
	if it.anim then
		local a = it.anim
		local tr = {}
		for i, rows in ipairs(a.tr) do
			local arr = {}
			for k, r in ipairs(rows) do
				arr[k] = { r[1], CFrame.new(r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9], r[10], r[11], r[12], r[13]) }
			end
			tr[i] = arr
		end
		local joints, motors = {}, {}
		for i, j in ipairs(a.joints) do joints[i] = { name = j.name, part0 = j.part0, part1 = j.part1, frames = tr[j.slot] } end
		for i, m in ipairs(a.motors or {}) do motors[i] = { name = m.name, parent = m.parent, samples = tr[m.slot] } end
		if #joints > 0 then
			details[id] = {
				rig = a.rig, length = a.length, looped = a.looped, joints = joints, allMotors = motors,
				priorityValue = a.priorityValue, cache = {}, rawFrames = #joints[1].frames, source = "saved edit", fromSaved = true,
			}
			X.aeData[id] = nil
			X.lens[id] = a.length
			rbxmxCache[id] = nil
			animInfo[id] = animInfo[id] or { priority = a.priority or "Action", looped = a.looped, speed = 1 }
		end
	end
	if it.root and not X.rootRec[X.rootKey(id)] then
		local okR, rr = pcall(X.svRootDec, it.root)
		if okR and rr then X.rootRec[X.rootKey(id)] = rr end
	end
	if it.fx then
		local list = {}
		for i, e in ipairs(it.fx) do list[i] = X.dec(e) end
		X.fxEdit[id] = list
		if X.ed and X.ed.id == id then
			X.ed.events = list
			X.ed.dirty = true
			X.edRefresh()
		end
	end
	if not animLabel[id] then animLabel[id] = it.name end
	pcall(refreshExtra, id)
	return true
end

X.shadow = {}
function X.savedId(id)
	if tostring(id):find("#saved$") then return id end
	local src = X.eds.items[id] or X.kept[id]
	if not (src and src.anim) then return id end
	local sid = id .. "#saved"
	if X.shadow[sid] ~= src or not details[sid] then
		X.shadow[sid] = src
		pcall(X.edsApply, sid, src)
		animLabel[sid] = animLabel[id] or src.name
		if X.markers then X.markers[sid] = X.markers[id] end
		if not src.fx then
			local r = fxWindows.rawFor(id)
			X.fxEdit[sid] = r and table.clone(r) or nil
		end
	end
	return details[sid] and sid or id
end

function X.edsCode(id)
	local it = X.eds.items[id]
	if not it then error("not saved") end
	if it.code and it.code ~= "" then return it.code end
	local sid = X.savedId(id)
	if sid ~= id and details[sid] then return K.buildAnimCode(sid, "all") end
	local list = {}
	for _, e in ipairs(it.fx or {}) do
		local c = X.dec(e)
		if not c.off then list[#list + 1] = c end
	end
	if #list > 0 then return K.genStandaloneFX(list, it.name) end
	error("nothing saved to build a script from")
end

function X.codeEdit(title, text, onSave, onRevert)
	if #text > 190000 then
		out("That script is too big to edit in a text box (" .. #text .. " characters). Use Copy / Export instead.")
		return
	end
	local win = createWindow({
		title = title,
		size = Vector2.new(560, 440),
		pos = UDim2.new(0.5, -280, 0.5, -220),
		minSize = Vector2.new(320, 260),
		miniText = "ED",
	})
	local bar = X.mkBar(win.content, 6, 34)
	local box = Instance.new("TextBox")
	box.Position = UDim2.new(0, 6, 0, 46)
	box.Size = UDim2.new(1, -12, 1, -52)
	box.BackgroundColor3 = C.code
	box.BorderSizePixel = 0
	box.ClearTextOnFocus = false
	box.MultiLine = true
	box.TextWrapped = false
	box.TextXAlignment = Enum.TextXAlignment.Left
	box.TextYAlignment = Enum.TextYAlignment.Top
	box.Font = Enum.Font.Code
	box.TextSize = 14
	box.TextColor3 = C.text
	box.Text = text
	box.Parent = win.content
	X.mkTool(bar, "Save", 60, C.green, function(b)
		onSave(box.Text)
		K.flash(b, "Saved!")
	end)
	X.mkTool(bar, "Copy", 60, C.sel, function(b)
		toClip(box.Text, "the script")
		K.flash(b, "Copied!")
	end)
	X.mkTool(bar, "Run", 54, C.green, function(b)
		local loader = loadstring or load
		local fn, err = loader and loader(box.Text)
		if fn then
			task.spawn(fn)
			K.flash(b, "Ran!")
		else
			out("Script error: " .. tostring(err or "no loadstring"))
			K.flash(b, "Error")
		end
	end)
	if onRevert then
		X.mkTool(bar, "Back to generated", 130, C.btn, function()
			local fresh = onRevert()
			if fresh then box.Text = fresh end
		end)
	end
	return win
end

function X.edsRows(sf)
	local base = 10000
	do
		local lb = K.newButton(sf, string.format("FX Library (%d saved effects) - open", #X.fxlib.order), C.sel)
		lb.Size = UDim2.new(1, -6, 0, 32)
		lb.LayoutOrder = base - 1
		lb.MouseButton1Click:Connect(function() X.libOpen() end)
	end
	local h = Instance.new("TextLabel")
	h.Size = UDim2.new(1, -6, 0, 28)
	h.BackgroundColor3 = C.title
	h.BorderSizePixel = 0
	h.LayoutOrder = base
	h.Text = string.format("  Saved edits (%d) - your edited animations and effects", #X.eds.order)
	h.TextColor3 = C.text
	h.Font = Th.bold
	h.TextSize = 15
	h.TextXAlignment = Enum.TextXAlignment.Left
	h.Parent = sf
	if #X.eds.order == 0 then
		local l = Instance.new("TextLabel")
		l.Size = UDim2.new(1, -6, 0, 44)
		l.BackgroundTransparency = 1
		l.LayoutOrder = base + 1
		l.TextWrapped = true
		l.Text = "Nothing yet. Edit an animation or its effects, then press Save in the Anim Editor, FX Editor or Preview window."
		l.TextColor3 = C.sub
		l.Font = Th.font
		l.TextSize = 14
		l.Parent = sf
		return
	end
	for i, id in ipairs(X.eds.order) do
		local it = X.eds.items[id]
		if it then
			local row = Instance.new("Frame")
			row.Size = UDim2.new(1, -6, 0, 78)
			row.BackgroundColor3 = i % 2 == 1 and C.row1 or C.row2
			row.BorderSizePixel = 0
			row.LayoutOrder = base + i
			row.Parent = sf
			local lbl = Instance.new("TextLabel")
			lbl.Position = UDim2.new(0, 8, 0, 2)
			lbl.Size = UDim2.new(1, -16, 0, 36)
			lbl.BackgroundTransparency = 1
			lbl.RichText = true
			lbl.TextXAlignment = Enum.TextXAlignment.Left
			lbl.TextTruncate = Enum.TextTruncate.AtEnd
			lbl.Font = Th.font
			lbl.TextSize = 15
			lbl.TextColor3 = C.text
			lbl.Text = string.format('<b>%s</b>%s\n<font color="%s">%s%s%s</font>', K.esc(it.name or id), it.code and "  (your edited code)" or "", K.hex(C.sub),
				it.anim and string.format("%.2fs animation", it.anim.length or 0) or "", (it.anim and it.fx) and " + " or "", it.fx and (#it.fx .. " effects") or "")
			lbl.Parent = row
			local bar = X.mkBar(row, 40, 34)
			if it.anim then X.svSelTool(bar, id) end
			X.mkTool(bar, "View code", 82, C.sel, function()
				openViewer("Saved - " .. tostring(it.name), { { name = "Script", get = function(cb) cb(X.edsCode(id)) end } }, 1)
			end)
			X.mkTool(bar, "Edit code", 78, C.sel, function()
				X.codeEdit("Edit code - " .. tostring(it.name), X.edsCode(id), function(text)
					it.code = text
					X.edsWrite()
					X.svRender()
				end, function()
					it.code = nil
					X.edsWrite()
					X.svRender()
					return X.edsCode(id)
				end)
			end)
			X.mkTool(bar, "Copy", 52, C.sel, function(b)
				toClip(X.edsCode(id), "the saved script")
				K.flash(b, "Copied!")
			end)
			X.mkTool(bar, "Rename", 66, C.btn, function() X.renameAnim(id) end)
			X.mkTool(bar, "Export", 62, C.btn, function(b)
				if not writefile then return out("This executor cannot write files.") end
				if makefolder and isfolder and not isfolder("AnimLogger_exports") then pcall(makefolder, "AnimLogger_exports") end
				local fname = string.format("AnimLogger_exports/%s_%s.lua", tostring(it.name):gsub("[^%w]", "_"), tostring(id):match("%d+") or "x")
				local ok = pcall(writefile, fname, Clip.stamp(X.edsCode(id)))
				out(ok and ("Exported to " .. fname .. " in your executor's workspace folder.") or "Export failed.")
				K.flash(b, ok and "Done" or "Fail")
			end)
			X.mkTool(bar, "Load", 50, C.green, function(b)
				X.edsApply(id)
				K.flash(b, "Loaded")
			end)
			X.mkTool(bar, "Edit anim", 80, C.green, function()
				if it.anim then
					X.edsApply(id)
					X.aeOpen(id)
				else
					out("This saved item only has effects. Use Preview or the FX editor.")
				end
			end)
			if tostring(id):find("^combo:") then
				X.mkTool(bar, "Combo tools", 96, C.sel, function() X.cmbResult(id) end)
			end
			X.mkTool(bar, "Preview", 66, C.green, function()
				X.edsApply(id)
				X.pvOpen(id, { id = id, name = it.name })
			end)
			X.mkTool(bar, "Anim Edit", 76, C.btn, function()
				X.edsApply(id)
				X.aeOpen(id)
			end)
			X.mkTool(bar, "FX Edit", 66, C.btn, function()
				X.edsApply(id)
				X.edOpen(id)
			end)
			if it.fx and #it.fx > 0 then X.mkTool(bar, "Public SFX", 88, C.green, function(b2) X.pubSfx.fixItem(id, b2) end) end
			if it.fx and #it.fx > 0 then X.mkTool(bar, "Swap SFX", 80, C.btn, function()
				local src, commit = X.pubSfx.itemOps(id)
				X.pubSfx.openManual(it.name or id, src, commit)
			end) end
			X.mkTool(bar, "3D", 40, C.btn, function()
				X.edsApply(id)
				X.v3Open(id)
			end)
			X.mkTool(bar, "Delete", 58, C.danger, function()
				X.eds.items[id] = nil
				table.remove(X.eds.order, table.find(X.eds.order, id))
				X.edsWrite()
				X.svRender()
			end)
		end
	end
end

-- ===== Public SFX finder =====
-- Finds recorded sounds that cannot load here (private / blocked audio) and swaps in public audio
-- that loads for everyone, picked by name and closest length. Works on saved anims and saved edits.
X.pubSfx = { cache = {}, miss = {} }

function X.pubSfx.request(url)
	local rq = request or http_request or (syn and syn.request) or (fluxus and fluxus.request)
	if not rq then return nil, "this executor has no http request" end
	local ok, res = pcall(rq, { Url = url, Method = "GET", Headers = { ["Accept"] = "application/json" } })
	if not ok or type(res) ~= "table" then return nil, "request failed" end
	if not (res.Success or res.StatusCode == 200) then return nil, "http " .. tostring(res.StatusCode) end
	local okJ, data = pcall(function() return game:GetService("HttpService"):JSONDecode(res.Body) end)
	if not okJ then return nil, "bad reply" end
	return data
end

-- true when the sound loads here, plus its length
function X.pubSfx.probe(id, timeout)
	local s = Instance.new("Sound")
	s:SetAttribute("_LoggerClone", true)
	s:SetAttribute("_Replay", true)
	s.Volume = 0
	s.SoundId = id
	s.Parent = game:GetService("SoundService")
	local t0 = os.clock()
	while os.clock() - t0 < (timeout or 3) and not (s.IsLoaded and s.TimeLength > 0) do task.wait(0.1) end
	local ok, len = (s.IsLoaded and s.TimeLength > 0), s.TimeLength
	pcall(function() s:Destroy() end)
	return ok, len
end

function X.pubSfx.soundId(ev)
	if ev.kind ~= "sfx" or type(ev.props) ~= "table" then return nil end
	for _, kv in ipairs(ev.props) do
		if kv[1] == "SoundId" then
			local id = (tostring(kv[2]):gsub('"', ""))
			if id == "" or id:find("^rbxasset://") or id == "rbxassetid://0" then return nil end
			return id
		end
	end
end

function X.pubSfx.speedOf(ev)
	for _, kv in ipairs(ev.props or {}) do
		if kv[1] == "PlaybackSpeed" then return math.max(tonumber(kv[2]) or 1, 0.1) end
	end
	return 1
end

function X.pubSfx.keywords(name)
	local base = tostring(name or "")
	base = base:gsub("(%l)(%u)", "%1 %2")
	base = base:gsub("[_%-%.%d]+", " ")
	base = base:gsub("%s+", " ")
	base = base:match("^%s*(.-)%s*$") or ""
	local kws = {}
	if #base >= 3 and base:lower() ~= "sound" then
		kws[#kws + 1] = base
		kws[#kws + 1] = base .. " sound effect"
	end
	kws[#kws + 1] = "sound effect"
	return kws
end

function X.pubSfx.search(keyword)
	local url = "https://apis.roblox.com/toolbox-service/v1/marketplace/3?keyword="
		.. game:GetService("HttpService"):UrlEncode(keyword) .. "&num=20&pageNumber=0&sortType=Relevance"
	local data, err = X.pubSfx.request(url)
	if not data then return nil, err end
	local ids = {}
	for _, it in ipairs(data.data or {}) do
		if it.id then ids[#ids + 1] = it.id end
	end
	return ids
end

function X.pubSfx.findFor(name, target)
	local lastErr
	for _, kw in ipairs(X.pubSfx.keywords(name)) do
		local ids, err = X.pubSfx.search(kw)
		lastErr = err or lastErr
		if ids and #ids > 0 then
			local n = math.min(#ids, 10)
			local res, pending = {}, n
			for i = 1, n do
				task.spawn(function()
					local ok, len = X.pubSfx.probe("rbxassetid://" .. ids[i], 3)
					res[i] = { id = ids[i], ok = ok, len = len }
					pending -= 1
				end)
			end
			local t0 = os.clock()
			while pending > 0 and os.clock() - t0 < 6 do task.wait(0.1) end
			local best, bestScore
			for i = 1, n do
				local r = res[i]
				if r and r.ok then
					local score = target and math.abs(r.len - target) or i
					if not bestScore or score < bestScore then best, bestScore = r.id, score end
				end
			end
			if best then return "rbxassetid://" .. best end
		end
	end
	return nil, lastErr
end

-- returns { [oldId] = newId } for every recorded sound that cannot play here and has a public match
function X.pubSfx.scan(list, status)
	status = status or function() end
	local groups, order = {}, {}
	for _, ev in ipairs(list or {}) do
		local id = X.pubSfx.soundId(ev)
		if id then
			if not groups[id] then
				groups[id] = { name = ev.name, target = ev.dur and (ev.dur * X.pubSfx.speedOf(ev)) or nil }
				order[#order + 1] = id
			end
		end
	end
	local map, failed, total = {}, {}, #order
	if total == 0 then return map, failed, 0, 0 end
	local blocked, pending, done = {}, total, 0
	status("Checking 0/" .. total)
	for _, id in ipairs(order) do
		if X.pubSfx.cache[id] then
			blocked[id] = true
			pending -= 1
		else
			task.spawn(function()
				local ok = X.pubSfx.probe(id, 3)
				if not ok then blocked[id] = true end
				done += 1
				pending -= 1
				status("Checking " .. done .. "/" .. total)
			end)
		end
	end
	local t0 = os.clock()
	while pending > 0 and os.clock() - t0 < 10 do task.wait(0.1) end
	local nPriv = 0
	for _, id in ipairs(order) do
		if blocked[id] then
			nPriv += 1
			status("Searching " .. nPriv)
			local g = groups[id]
			local new = X.pubSfx.cache[id]
			if not new then
				local err
				new, err = X.pubSfx.findFor(g.name, g.target)
				if new then
					X.pubSfx.cache[id] = new
				else
					failed[#failed + 1] = { id = id, name = g.name, err = err }
				end
			end
			if new then map[id] = new end
		end
	end
	return map, failed, total, nPriv
end

function X.pubSfx.apply(list, map)
	local n = 0
	for _, ev in ipairs(list or {}) do
		local id = X.pubSfx.soundId(ev)
		local new = id and map[id]
		if new then
			for _, kv in ipairs(ev.props) do
				if kv[1] == "SoundId" then
					kv[2] = string.format("%q", new)
					ev.pubFrom = ev.pubFrom or id
					n += 1
				end
			end
		end
	end
	return n
end

function X.pubSfx.cloneList(list)
	local out2 = {}
	for i, e in ipairs(list or {}) do
		local c = table.clone(e)
		if type(e.props) == "table" then
			c.props = {}
			for k, kv in ipairs(e.props) do c.props[k] = table.clone(kv) end
		end
		out2[i] = c
	end
	return out2
end

function X.pubSfx.report(map, failed, total, nPriv, applied)
	if total == 0 then return out("Public SFX: no recorded sounds in this one.") end
	if nPriv == 0 then return out("Public SFX: all " .. total .. " sounds already play here. Nothing to change.") end
	for old, new in pairs(map) do
		out("Public SFX: " .. tostring(old):gsub("rbxassetid://", "") .. " -> " .. tostring(new):gsub("rbxassetid://", ""))
	end
	for _, f in ipairs(failed) do
		out("Public SFX: no public match for \"" .. tostring(f.name) .. "\" (" .. tostring(f.id):gsub("rbxassetid://", "") .. ")" .. (f.err and (" - " .. f.err) or ""))
	end
	out(string.format("Public SFX: %d private, %d replaced (%d events), %d without a match.", nPriv, nPriv - #failed, applied or 0, #failed))
end

-- one button for any place: getList() gives the events, setList(list, map) stores the result
function X.pubSfx.button(btn, getList, commit)
	if btn:GetAttribute("busy") then return end
	btn:SetAttribute("busy", true)
	local old = btn.Text
	task.spawn(function()
		local ok, err = pcall(function()
			local list = getList()
			if not list or #list == 0 then
				btn.Text = "No SFX"
				return
			end
			local map, failed, total, nPriv = X.pubSfx.scan(list, function(t) if btn.Parent then btn.Text = t end end)
			local applied = 0
			if next(map) then applied = commit(map) or 0 end
			X.pubSfx.report(map, failed, total, nPriv, applied)
			btn.Text = (nPriv == 0 and "All public") or (applied > 0 and ("Fixed " .. applied)) or "No match"
		end)
		if not ok then
			out("Public SFX error: " .. tostring(err))
			btn.Text = "Error"
		end
		task.wait(2.5)
		if btn.Parent then
			btn.Text = old
			btn:SetAttribute("busy", nil)
		end
	end)
end

function X.pubSfx.itemOps(id)
	local it = X.eds.items[id]
	local function decoded()
		local list = {}
		for i, e in ipairs((it and it.fx) or {}) do list[i] = X.dec(e) end
		return list
	end
	local function commit(map)
		if not it then return 0 end
		local list = decoded()
		local n = X.pubSfx.apply(list, map)
		local enc = {}
		for i, e in ipairs(list) do enc[i] = X.enc(e) end
		it.fx = enc
		if it.code and it.code ~= "" then
			for old, new in pairs(map) do
				local pat = old:gsub("%p", "%%%0")
				it.code = it.code:gsub(pat, (new:gsub("%%", "%%%%")))
			end
		end
		if X.kept[id] then
			X.kept[id].fx = enc
			X.keptDirty = true
		end
		local sid = id .. "#saved"
		if X.fxEdit[sid] then
			local fresh = {}
			for i, e in ipairs(enc) do fresh[i] = X.dec(e) end
			X.fxEdit[sid] = fresh
		end
		if X.fxEdit[id] then X.pubSfx.apply(X.fxEdit[id], map) end
		X.edsWrite()
		return n
	end
	return decoded, commit
end

function X.pubSfx.savedOps(id)
	local function source()
		local sid = X.savedId(id)
		return X.fxEdit[sid] or X.fxEdit[id] or fxWindows.rawFor(id) or fxWindows.rawFor(sid)
	end
	local function commit(map)
		local sid = X.savedId(id)
		local list = X.pubSfx.cloneList(source())
		local n = X.pubSfx.apply(list, map)
		X.fxEdit[id] = list
		if sid ~= id then X.fxEdit[sid] = list end
		local src = X.kept[id]
		if src and src.fx then
			local enc = {}
			for i, e in ipairs(list) do enc[i] = X.enc(e) end
			src.fx = enc
			X.keptDirty = true
			local it = X.eds.items[id]
			if it then
				it.fx = enc
				X.edsWrite()
			end
		end
		return n
	end
	return source, commit
end

function X.pubSfx.editorOps()
	local E = X.ed
	local function source() return E and E.events or {} end
	local function commit(map)
		local n = 0
		if X.ed ~= E then return 0 end
		X.edChange(function() n = X.pubSfx.apply(E.events, map) end)
		return n
	end
	return source, commit
end

function X.pubSfx.fixItem(id, btn) X.pubSfx.button(btn, X.pubSfx.itemOps(id)) end
function X.pubSfx.fixSaved(id, btn) X.pubSfx.button(btn, X.pubSfx.savedOps(id)) end
function X.pubSfx.fixEditor(btn) X.pubSfx.button(btn, X.pubSfx.editorOps()) end

function X.pubSfx.normId(text)
	local s = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
	if s:match("^%d+$") then return "rbxassetid://" .. s end
	local n = s:match("^rbxassetid://(%d+)$") or s:match("^https?://.-/asset/%?id=(%d+)") or s:match("[?&]id=(%d+)")
	if n then return "rbxassetid://" .. n end
	return nil
end

-- manual swap window: every recorded sound with a box for the audio id you want instead
function X.pubSfx.openManual(title, getList, commit)
	local list = getList()
	local groups, order = {}, {}
	for _, ev in ipairs(list or {}) do
		local id = X.pubSfx.soundId(ev)
		if id then
			local g = groups[id]
			if not g then
				g = { name = ev.name, n = 0, target = ev.dur and (ev.dur * X.pubSfx.speedOf(ev)) or nil }
				groups[id] = g
				order[#order + 1] = id
			end
			g.n += 1
		end
	end
	if #order == 0 then return out("Swap SFX: no recorded sounds in this one.") end
	local win = createWindow({
		title = "Swap SFX - " .. tostring(title):sub(1, 30),
		size = Vector2.new(470, 400),
		pos = UDim2.new(0.5, -235, 0.5, -200),
		minSize = Vector2.new(330, 240),
		miniText = "SW",
	})
	local info = Instance.new("TextLabel")
	info.Position = UDim2.new(0, 6, 0, 4)
	info.Size = UDim2.new(1, -12, 0, 34)
	info.BackgroundTransparency = 1
	info.TextWrapped = true
	info.TextXAlignment = Enum.TextXAlignment.Left
	info.TextYAlignment = Enum.TextYAlignment.Top
	info.Font = Th.font
	info.TextSize = 14
	info.TextColor3 = C.sub
	info.Text = "Type the audio id you want for each sound (a number or rbxassetid://). Find = search a public one. Test = hear it. Apply = swap it in."
	info.Parent = win.content
	local scroll = Instance.new("ScrollingFrame")
	scroll.Position = UDim2.new(0, 4, 0, 42)
	scroll.Size = UDim2.new(1, -8, 1, -46)
	scroll.BackgroundTransparency = 1
	scroll.BorderSizePixel = 0
	scroll.ScrollBarThickness = 6
	scroll.CanvasSize = UDim2.new()
	scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
	scroll.ScrollingDirection = Enum.ScrollingDirection.Y
	scroll.Parent = win.content
	local lay = Instance.new("UIListLayout")
	lay.Padding = UDim.new(0, 4)
	lay.SortOrder = Enum.SortOrder.LayoutOrder
	lay.Parent = scroll

	for i, oldId in ipairs(order) do
		local g = groups[oldId]
		local row = Instance.new("Frame")
		row.Size = UDim2.new(1, -6, 0, 74)
		row.BackgroundColor3 = i % 2 == 1 and C.row1 or C.row2
		row.BorderSizePixel = 0
		row.LayoutOrder = i
		row.Parent = scroll
		local lbl = Instance.new("TextLabel")
		lbl.Position = UDim2.new(0, 6, 0, 2)
		lbl.Size = UDim2.new(1, -12, 0, 22)
		lbl.BackgroundTransparency = 1
		lbl.RichText = true
		lbl.TextXAlignment = Enum.TextXAlignment.Left
		lbl.TextTruncate = Enum.TextTruncate.AtEnd
		lbl.Font = Th.font
		lbl.TextSize = 14
		lbl.TextColor3 = C.text
		local shortId = tostring(oldId):gsub("rbxassetid://", "")
		local function setHead(state)
			lbl.Text = string.format("<b>%s</b>  x%d   <font color=\"%s\">%s  %s</font>", K.esc(tostring(g.name)), g.n, K.hex(C.sub), K.esc(shortId), state)
		end
		setHead("checking...")
		lbl.Parent = row
		task.spawn(function()
			local ok = X.pubSfx.probe(oldId, 3)
			if lbl.Parent then setHead(ok and "(plays here)" or "(private / blocked here)") end
		end)
		local box = X.mkBox(row, 150, "", "new audio id")
		box.Position = UDim2.new(0, 6, 0, 28)
		local bar = Instance.new("Frame")
		bar.BackgroundTransparency = 1
		bar.Position = UDim2.new(0, 162, 0, 28)
		bar.Size = UDim2.new(1, -168, 0, 28)
		bar.Parent = row
		local bl = Instance.new("UIListLayout")
		bl.FillDirection = Enum.FillDirection.Horizontal
		bl.Padding = UDim.new(0, 3)
		bl.Parent = bar
		local status = Instance.new("TextLabel")
		status.Position = UDim2.new(0, 6, 0, 58)
		status.Size = UDim2.new(1, -12, 0, 14)
		status.BackgroundTransparency = 1
		status.TextXAlignment = Enum.TextXAlignment.Left
		status.Font = Th.font
		status.TextSize = 12
		status.TextColor3 = C.sub
		status.Text = ""
		status.Parent = row
		local function say(t) if status.Parent then status.Text = t end end
		local function typed()
			local id = X.pubSfx.normId(box.Text)
			if not id then say("Type a number or rbxassetid://number.") end
			return id
		end
		X.mkTool(bar, "Find", 46, C.sel, function(b)
			if b:GetAttribute("busy") then return end
			b:SetAttribute("busy", true)
			say("Searching public audio...")
			task.spawn(function()
				local new, err = X.pubSfx.findFor(g.name, g.target)
				if new then
					box.Text = (new:gsub("rbxassetid://", ""))
					say("Found one. Press Test to hear it, Apply to use it.")
				else
					say("No public match" .. (err and (" (" .. tostring(err) .. ")") or "") .. ".")
				end
				b:SetAttribute("busy", nil)
			end)
		end)
		X.mkTool(bar, "Test", 46, C.btn, function(b)
			local id = typed()
			if not id then return end
			if b:GetAttribute("busy") then return end
			b:SetAttribute("busy", true)
			say("Loading...")
			task.spawn(function()
				local ok, len = X.pubSfx.probe(id, 4)
				if ok then
					local s = Instance.new("Sound")
					s:SetAttribute("_LoggerClone", true)
					s:SetAttribute("_Replay", true)
					s.SoundId = id
					s.Volume = 1
					s.Parent = game:GetService("SoundService")
					s:Play()
					game:GetService("Debris"):AddItem(s, math.min(len + 0.5, 8))
					say(string.format("Plays here (%.2fs)%s.", len, g.target and string.format(", original ~%.2fs", g.target) or ""))
				else
					say("That one does not load here (private or wrong id).")
				end
				b:SetAttribute("busy", nil)
			end)
		end)
		X.mkTool(bar, "Apply", 52, C.green, function(b)
			local id = typed()
			if not id then return end
			if b:GetAttribute("busy") then return end
			b:SetAttribute("busy", true)
			say("Checking...")
			task.spawn(function()
				local ok = X.pubSfx.probe(id, 4)
				if not ok then
					say("Not applied: that audio does not load here.")
				else
					local okC, n = pcall(commit, { [oldId] = id })
					if okC and (n or 0) > 0 then
						X.pubSfx.cache[oldId] = id
						say("Swapped " .. n .. " event" .. (n == 1 and "" or "s") .. " to " .. id:gsub("rbxassetid://", "") .. ".")
						out("Swap SFX: " .. shortId .. " -> " .. tostring(id):gsub("rbxassetid://", ""))
					else
						say(okC and "Nothing changed." or ("Error: " .. tostring(n)))
					end
				end
				b:SetAttribute("busy", nil)
			end)
		end)
	end
	return win
end

X.FXLIB_FILE = "AnimLogger_fxlib.json"
X.fxlib = { items = {}, order = {} }

function X.libLoad()
	if not (isfile and readfile) then return end
	local ok, data = pcall(function()
		if isfile(X.FXLIB_FILE) then return HttpService:JSONDecode(readfile(X.FXLIB_FILE)) end
	end)
	if not (ok and type(data) == "table" and type(data.items) == "table") then return end
	for key, it in pairs(data.items) do
		if type(it) == "table" and type(it.evs) == "table" then
			X.fxlib.items[key] = it
			X.fxlib.order[#X.fxlib.order + 1] = key
		end
	end
	table.sort(X.fxlib.order, function(a, b)
		local ta, tb = X.fxlib.items[a].t or 0, X.fxlib.items[b].t or 0
		if ta ~= tb then return ta > tb end
		return a < b
	end)
end

function X.libWrite()
	if not writefile then return false end
	local ok, json = pcall(function() return HttpService:JSONEncode({ v = 1, items = X.fxlib.items }) end)
	if not ok then return false end
	return (pcall(writefile, X.FXLIB_FILE, json))
end

function X.libSave(evs, name, btn)
	local function say(t)
		if btn and btn.Parent then K.flash(btn, t) end
	end
	local t0 = math.huge
	for _, e in ipairs(evs or {}) do
		if type(e) == "table" and e.kind then t0 = math.min(t0, e.t or 0) end
	end
	local list = {}
	for _, e in ipairs(evs or {}) do
		if type(e) == "table" and e.kind then
			local ok, enc = pcall(X.enc, e)
			if ok and type(enc) == "table" then
				enc.t = math.max((e.t or 0) - t0, 0)
				enc.off = nil
				list[#list + 1] = enc
			end
		end
	end
	if #list == 0 then
		out("Nothing to save to the FX library.")
		return say("Nothing")
	end
	if #X.fxlib.order >= 600 then
		out("The FX library is full (600). Delete some first.")
		return say("Full")
	end
	X.libN = (X.libN or 0) + 1
	local key = string.format("fx%d_%d", os.time(), X.libN)
	while X.fxlib.items[key] do
		X.libN += 1
		key = string.format("fx%d_%d", os.time(), X.libN)
	end
	if not name or name == "" then
		local title = X.evLines(evs[1])
		name = tostring(title)
		if #list > 1 then name = name .. string.format(" (+%d more)", #list - 1) end
	end
	local it = { key = key, name = tostring(name):sub(1, 70), t = os.time(), evs = list }
	X.fxlib.items[key] = it
	table.insert(X.fxlib.order, 1, key)
	local wrote = X.libWrite()
	out(string.format("Saved \"%s\" to the FX library (%d effect%s).%s", it.name, #list, #list == 1 and "" or "s",
		wrote and "" or " This executor cannot write files, so it only lasts until you close the game."))
	say("In library")
	if X.libList and X.libList.Parent then pcall(X.libRender) end
	if X.svReady then pcall(X.svRender) end
end

function X.libEvents(it, T)
	local list = {}
	for _, sv in ipairs(it.evs) do
		local c = X.dec(sv)
		c.t = math.max((T or 0) + (c.t or 0), 0)
		list[#list + 1] = c
	end
	return list
end

function X.libAdd(it, T, btn)
	local E = X.ed
	if not E then
		if btn and btn.Parent then K.flash(btn, "Open FX editor") end
		return out("Open the FX editor of the animation you want first (Animations tab or Saved tab > FX Edit), then press Add.")
	end
	local list = X.libEvents(it, T)
	X.edChange(function()
		for _, c in ipairs(list) do table.insert(E.events, c) end
		E.sel = list[#list]
	end)
	out(string.format("Added \"%s\" to %s at %.2fs.", it.name, K.animName(E.id), tonumber(T) or 0))
	if btn and btn.Parent then K.flash(btn, "Added") end
end

function X.libRender()
	local sf = X.libList
	if not (sf and sf.Parent) then return end
	for _, ch in ipairs(sf:GetChildren()) do
		if ch:IsA("GuiObject") then ch:Destroy() end
	end
	local q = (X.libSearch and X.libSearch.Text or ""):lower()
	local shown = 0
	for _, key in ipairs(X.fxlib.order) do
		local it = X.fxlib.items[key]
		if it then
			local hay = tostring(it.name) .. " "
			local nv, ns, no, nc = 0, 0, 0, 0
			for _, e in ipairs(it.evs) do
				hay = hay .. tostring(e.name) .. " " .. tostring(e.class or "") .. " " .. tostring(e.kind) .. " "
				for _, pr in ipairs(e.props or {}) do hay = hay .. tostring(pr[2]) .. " " end
				if e.kind == "vfx" then nv += 1 elseif e.kind == "sfx" then ns += 1 elseif e.kind == "obj" or e.kind == "gui" then no += 1 else nc += 1 end
			end
			hay = hay:lower()
			local ok = true
			for w in q:gmatch("%S+") do
				if not hay:find(w, 1, true) then
					ok = false
					break
				end
			end
			if ok then
				shown += 1
				local row = Instance.new("Frame")
				row.Size = UDim2.new(1, -6, 0, 78)
				row.BackgroundColor3 = shown % 2 == 1 and C.row1 or C.row2
				row.BorderSizePixel = 0
				row.LayoutOrder = shown
				row.Parent = sf
				local lbl = Instance.new("TextLabel")
				lbl.Position = UDim2.new(0, 8, 0, 2)
				lbl.Size = UDim2.new(1, -16, 0, 36)
				lbl.BackgroundTransparency = 1
				lbl.RichText = true
				lbl.TextXAlignment = Enum.TextXAlignment.Left
				lbl.TextTruncate = Enum.TextTruncate.AtEnd
				lbl.Font = Th.font
				lbl.TextSize = 15
				lbl.TextColor3 = C.text
				lbl.Text = string.format('<b>%s</b>\n<font color="%s">%d VFX  %d SFX  %d OBJ  %d CAM</font>', K.esc(it.name), K.hex(C.sub), nv, ns, no, nc)
				lbl.Parent = row
				local bar = X.mkBar(row, 40, 34)
				X.mkTool(bar, "Add", 50, C.green, function(b)
					X.libAdd(it, tonumber(X.libStart and X.libStart.Text) or 0, b)
				end)
				X.mkTool(bar, "Run", 46, C.green, function() K.runEvents(X.libEvents(it, 0), it.name) end)
				X.mkTool(bar, "Copy", 52, C.sel, function(b)
					toClip(K.genStandaloneFX(X.libEvents(it, 0), it.name), "the FX script")
					K.flash(b, "Copied!")
				end)
				if nv > 0 then
					X.mkTool(bar, "Edit VFX", 70, C.sel, function()
						local evs = X.libEvents(it, 0)
						X.vfxEd.fromEvents(evs, function()
							local new = {}
							for _, c in ipairs(evs) do new[#new + 1] = X.enc(c) end
							it.evs = new
							X.libWrite()
							X.libRender()
						end)
					end)
				end
				X.mkTool(bar, "Rename", 66, C.btn, function()
					X.prompt("Rename FX", it.name, function(text)
						local nv2 = tostring(text):match("^%s*(.-)%s*$")
						if nv2 == "" then return end
						it.name = nv2:sub(1, 70)
						X.libWrite()
						X.libRender()
					end)
				end)
				X.mkTool(bar, "Delete", 58, C.danger, function()
					X.fxlib.items[key] = nil
					local i = table.find(X.fxlib.order, key)
					if i then table.remove(X.fxlib.order, i) end
					X.libWrite()
					X.libRender()
					if X.svReady then pcall(X.svRender) end
				end)
			end
		end
	end
	if shown == 0 then
		local l = Instance.new("TextLabel")
		l.Size = UDim2.new(1, -6, 0, 70)
		l.BackgroundTransparency = 1
		l.TextWrapped = true
		l.Text = #X.fxlib.order == 0 and "The library is empty. Press \"To lib\" on an effect in the FX editor, or \"To library\" on a row in the VFX / SFX / OBJ / Search tabs."
			or "No saved effect matches your search."
		l.TextColor3 = C.sub
		l.Font = Th.font
		l.TextSize = 15
		l.Parent = sf
	end
end

function X.libOpen()
	if X.libWin then pcall(function() X.libWin.destroy() end) end
	local win = createWindow({
		title = "FX Library",
		size = Vector2.new(480, 420),
		pos = UDim2.new(0.5, -240, 0.5, -210),
		minSize = Vector2.new(320, 260),
		miniText = "LIB",
		onClose = function() X.libWin = nil end,
	})
	X.libWin = win
	local c = win.content
	local bar = X.mkBar(c, 6, 34)
	X.mkLabel(bar, "Add at", 46)
	X.libStart = X.mkBox(bar, 60, "0", "sec")
	X.libSearch = X.mkBox(bar, 170, "", "Search library...")
	X.mkTool(bar, "Open FX editor", 110, C.sel, function()
		local P = X.pv
		local id = (X.ed and X.ed.id) or (P and P.id) or (X.lastAnim and X.lastAnim.id)
		if id then X.edOpen(id) else out("Play an animation first, or open an animation's FX editor from the Animations / Saved tab.") end
	end)
	X.libList = newList(c, UDim2.new(0, 6, 0, 46), UDim2.new(1, -12, 1, -52))
	X.libSearch:GetPropertyChangedSignal("Text"):Connect(function() X.libRender() end)
	X.libRender()
end

X.libLoad()

function X.v3Close()
	local V = X.v3
	X.v3 = nil
	if not V then return end
	V.alive = false
	for _, c in ipairs(V.conns) do pcall(function() c:Disconnect() end) end
	pcall(X.v3World, V, false)
	pcall(function() V.win.destroy() end)
end

function X.v3World(V, on)
	local cam = workspace.CurrentCamera
	if on and not V.world and cam then
		V.world = true
		V.old = { cam.CameraType, cam.CameraSubject, cam.FieldOfView }
		cam.CameraType = Enum.CameraType.Scriptable
		V.vp.Visible = false
		local ov = Instance.new("TextButton")
		ov.AutoButtonColor = false
		ov.Text = ""
		ov.BackgroundTransparency = 1
		ov.BorderSizePixel = 0
		ov.Size = UDim2.new(1, 0, 1, 0)
		ov.ZIndex = 0
		ov.Active = true
		ov.Parent = gui
		V.ov = ov
		V.bindDrag(ov)
	elseif not on and V.world then
		V.world = false
		if cam and V.old then
			cam.CameraType = V.old[1]
			if V.old[2] and V.old[2].Parent then cam.CameraSubject = V.old[2] end
			cam.FieldOfView = V.old[3]
		end
		if V.ov then V.ov:Destroy() end
		V.ov = nil
		if V.vp.Parent then V.vp.Visible = true end
	end
end

function X.hostDex3D(title, onClose)
	local R = getgenv().__RPP
	local MV = R and R.ModelViewer
	local w = MV and MV.Window
	if not (w and w.GuiElems and w.GuiElems.Content) then return nil end
	pcall(function() if MV.StopViewModel then MV.StopViewModel() end end)
	pcall(function() w:Show() end)
	pcall(function()
		if w.GuiElems.Main.AbsoluteSize.Y < 340 then w:Resize(400, 440) end
	end)
	local content = w.GuiElems.Content
	local hidden = {}
	for _, c in ipairs(content:GetChildren()) do
		if c:IsA("GuiObject") and c.Visible then
			hidden[#hidden + 1] = c
			c.Visible = false
		end
	end
	local holder = Instance.new("Frame")
	holder.Name = "RecorderHost"
	holder.BackgroundTransparency = 1
	holder.Size = UDim2.new(1, 0, 1, 0)
	holder.Parent = content
	pcall(function() w:SetTitle(title) end)
	local win = { content = holder, frame = w.GuiElems.Main }
	local dead = false
	function win.destroy()
		if dead then return end
		dead = true
		pcall(function() holder:Destroy() end)
		for _, c in ipairs(hidden) do
			if c.Parent then c.Visible = true end
		end
		pcall(function() w:SetTitle("3D Preview") end)
	end
	function win.setMinimized(v)
		if v then pcall(function() w:Hide() end) else pcall(function() w:Show() end) end
	end
	task.spawn(function()
		task.wait(0.5)
		while not dead and Run.alive do
			if w.Closed == true or not holder.Parent then
				pcall(onClose)
				return
			end
			task.wait(0.4)
		end
	end)
	return win
end

function X.v3Open(id)
	local P = X.tpEnsure(id)
	if not P then return end
	X.v3Close()
	local win
	if getgenv and getgenv().__RPP then win = X.hostDex3D("3D Viewer - " .. K.animName(id), function() X.v3Close() end) end
	if not win then
		win = createWindow({
			title = "3D Viewer - " .. K.animName(id),
			size = Vector2.new(400, 440),
			pos = UDim2.new(0.5, -200, 0.5, -220),
			minSize = Vector2.new(300, 330),
			miniText = "3D",
			onClose = function() X.v3Close() end,
		})
	end
	local V = { id = id, win = win, conns = {}, alive = true, yaw = math.pi, pitch = 0.2, ui = {}, spin = false }
	X.v3 = V
	local content = win.content

	local vp = Instance.new("ViewportFrame")
	vp.Position = UDim2.new(0, 6, 0, 6)
	vp.Size = UDim2.new(1, -12, 1, -112)
	vp.BackgroundColor3 = Color3.fromRGB(26, 28, 34)
	vp.BorderSizePixel = 0
	vp.Ambient = Color3.fromRGB(150, 150, 160)
	vp.LightColor = Color3.fromRGB(255, 250, 240)
	vp.LightDirection = Vector3.new(-0.5, -1, -0.6)
	vp.Active = true
	vp.Parent = content
	V.vp = vp
	local wm = Instance.new("WorldModel")
	wm.Parent = vp
	local cam = Instance.new("Camera")
	cam.FieldOfView = 45
	cam.Parent = vp
	vp.CurrentCamera = cam

	local src = P.rig
	local was = src.Archivable
	src.Archivable = true
	local model = src:Clone()
	src.Archivable = was
	if not model then
		X.v3Close()
		return out("3D viewer: could not copy the dummy")
	end
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("LuaSourceContainer") or d:IsA("Sound") or d:IsA("Animator") or d:IsA("BillboardGui") or VFX_CLASSES[d.ClassName] then
			d:Destroy()
		elseif d:IsA("BasePart") then
			d.Anchored = true
			d.CanCollide = false
		end
	end
	local root = model:FindFirstChild("HumanoidRootPart")
	if not root then
		X.v3Close()
		return out("3D viewer: the dummy has no root part")
	end
	model:PivotTo(CFrame.new(0, 0, 0))
	model.Parent = wm

	local all, offsets, srcMap = {}, {}, {}
	for _, d in ipairs(src:GetDescendants()) do
		if d:IsA("Motor6D") and d.Part1 then srcMap[d.Name .. ">" .. d.Part1.Name] = d end
	end
	for _, d in ipairs(model:GetDescendants()) do
		if (d:IsA("Motor6D") or d:IsA("Weld")) and d.Part0 and d.Part1 then
			all[#all + 1] = d
		elseif d:IsA("WeldConstraint") and d.Part0 and d.Part1 then
			offsets[d] = d.Part0.CFrame:ToObjectSpace(d.Part1.CFrame)
			all[#all + 1] = d
		end
	end
	local done, ordered, pending = { [root] = true }, {}, all
	local progress = true
	while progress and #pending > 0 do
		progress = false
		local rest = {}
		for _, j in ipairs(pending) do
			if done[j.Part0] then
				if not done[j.Part1] then
					ordered[#ordered + 1] = j
					done[j.Part1] = true
				end
				progress = true
			else
				rest[#rest + 1] = j
			end
		end
		pending = rest
	end
	local srcOf = {}
	for _, j in ipairs(ordered) do
		if j:IsA("Motor6D") then srcOf[j] = srcMap[j.Name .. ">" .. j.Part1.Name] end
	end

	local bbCF, bbSize = model:GetBoundingBox()
	V.focus = bbCF.Position
	V.dist = math.max(bbSize.Magnitude * 1.3, 6)
	V.dist0 = V.dist
	local floor = Instance.new("Part")
	floor.Shape = Enum.PartType.Cylinder
	floor.Anchored = true
	floor.CanCollide = false
	floor.Material = Enum.Material.SmoothPlastic
	floor.Color = Color3.fromRGB(52, 56, 68)
	floor.Size = Vector3.new(0.15, bbSize.Magnitude * 1.6, bbSize.Magnitude * 1.6)
	floor.CFrame = CFrame.new(bbCF.Position.X, bbCF.Position.Y - bbSize.Y / 2 - 0.08, bbCF.Position.Z) * CFrame.Angles(0, 0, math.pi / 2)
	floor.Parent = wm

	local clones = {}
	local function mirror(base)
		for real, c in pairs(clones) do
			if not real.Parent then
				c.model:Destroy()
				clones[real] = nil
			end
		end
		for _, o in ipairs(workspace:GetChildren()) do
			if o:IsA("Model") and o:GetAttribute("_Replay") and not clones[o] then
				local okC, cl = pcall(function() return o:Clone() end)
				if okC and cl then
					local pairsList, ra, ca = {}, o:GetDescendants(), cl:GetDescendants()
					for i2, d in ipairs(ra) do
						if d:IsA("BasePart") and ca[i2] and ca[i2]:IsA("BasePart") then
							ca[i2].Anchored = true
							pairsList[#pairsList + 1] = { d, ca[i2] }
						end
					end
					cl.Parent = wm
					clones[o] = { model = cl, parts = pairsList }
				end
			end
		end
		for real, c in pairs(clones) do
			for _, pr in ipairs(c.parts) do
				if pr[1].Parent then pr[2].CFrame = base * pr[1].CFrame end
			end
		end
	end

	local function orbit(rootCF, focusOffset)
		return rootCF * CFrame.new(focusOffset) * CFrame.Angles(0, V.yaw, 0) * CFrame.Angles(-V.pitch, 0, 0) * CFrame.new(0, 0, V.dist)
	end
	table.insert(V.conns, RunService.RenderStepped:Connect(function(dt)
		if not V.alive then return end
		local rig = X.pv and X.pv.rig
		if not (rig and rig.Parent) then return X.v3Close() end
		if V.spin and not V.dragging then V.yaw += dt * 0.8 end
		for _, j in ipairs(ordered) do
			local p0, p1 = j.Part0, j.Part1
			if j:IsA("Motor6D") then
				local sm = srcOf[j]
				local tr = (sm and sm.Parent) and sm.Transform or j.Transform
				j.Transform = tr
				p1.CFrame = p0.CFrame * j.C0 * tr * j.C1:Inverse()
			elseif j:IsA("Weld") then
				p1.CFrame = p0.CFrame * j.C0 * j.C1:Inverse()
			else
				p1.CFrame = p0.CFrame * offsets[j]
			end
		end
		local srcRoot = rig:FindFirstChild("HumanoidRootPart")
		if srcRoot then pcall(mirror, root.CFrame * srcRoot.CFrame:Inverse()) end
		cam.CFrame = orbit(CFrame.new(V.focus), Vector3.zero)
		if V.world and srcRoot then
			local wc = workspace.CurrentCamera
			if wc then
				wc.CameraType = Enum.CameraType.Scriptable
				wc.FieldOfView = 55
				wc.CFrame = orbit(srcRoot.CFrame, Vector3.new(0, 0.5, 0))
			end
		end
	end))

	function V.bindDrag(obj)
		obj.InputBegan:Connect(function(input)
			if not K.isPress(input) then return end
			V.dragging = true
			local last = input.Position
			local conn
			conn = UserInputService.InputChanged:Connect(function(i2)
				if not isMove(i2) or V.pinching then return end
				local d = i2.Position - last
				last = i2.Position
				V.yaw -= d.X * 0.012
				V.pitch = math.clamp(V.pitch + d.Y * 0.012, -1.45, 1.45)
			end)
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					conn:Disconnect()
					V.dragging = false
				end
			end)
		end)
		obj.InputChanged:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseWheel then
				V.dist = math.clamp(V.dist * (1 - input.Position.Z * 0.1), 1.5, 200)
			end
		end)
	end
	V.bindDrag(vp)
	local lastScale = 1
	table.insert(V.conns, UserInputService.TouchPinch:Connect(function(positions, scale, _, state)
		local c = Vector2.zero
		for _, p in ipairs(positions) do c += p end
		if #positions > 0 then c /= #positions end
		local ap, as = vp.AbsolutePosition, vp.AbsoluteSize
		local inside = V.world or (c.X >= ap.X and c.X <= ap.X + as.X and c.Y >= ap.Y and c.Y <= ap.Y + as.Y)
		if not inside then return end
		if state == Enum.UserInputState.Begin then
			V.pinching, lastScale = true, 1
		elseif state == Enum.UserInputState.Change then
			V.dist = math.clamp(V.dist / math.max(scale / lastScale, 0.2), 1.5, 200)
			lastScale = scale
		else
			V.pinching = false
		end
	end))

	V.scrub = X.mkScrub(content, UDim2.new(0, 6, 1, -102), UDim2.new(1, -12, 0, 24))
	local bar = X.mkBar(content, 0, 34)
	bar.Position = UDim2.new(0, 6, 1, -72)
	V.ui.play = X.mkTool(bar, "Play", 66, C.green, function() X.tpToggle(X.pv) end)
	X.mkTool(bar, "Restart", 66, C.btn, function()
		X.tpPlay(X.pv, 0, false)
	end)
	X.mkTool(bar, "Zoom -", 60, C.btn, function() V.dist = math.clamp(V.dist * 1.25, 1.5, 200) end)
	X.mkTool(bar, "Zoom +", 60, C.btn, function() V.dist = math.clamp(V.dist / 1.25, 1.5, 200) end)
	X.mkTool(bar, "Reset view", 80, C.btn, function()
		V.yaw, V.pitch, V.dist = math.pi, 0.2, V.dist0
	end)
	X.mkTool(bar, "Auto spin: Off", 112, C.btn, function(b)
		V.spin = not V.spin
		b.Text = V.spin and "Auto spin: On" or "Auto spin: Off"
		K.paint(b, V.spin and C.sel or C.btn)
	end)
	X.mkTool(bar, "World view: Off", 118, C.btn, function(b)
		X.v3World(V, not V.world)
		b.Text = V.world and "World view: On" or "World view: Off"
		K.paint(b, V.world and C.sel or C.btn)
		V.note.Text = V.world and "World view: the whole screen is the 3D scene. Drag = spin, wheel / pinch = zoom. Every effect (particles, beams, trails) is visible." or "Drag = spin | wheel / pinch / Zoom = zoom | particles, beams and trails cannot draw inside a window: use World view to see them."
	end)
	X.mkTool(bar, "Save", 54, C.green, function(b) X.edsSave(id, b) end)
	local note = Instance.new("TextLabel")
	note.Position = UDim2.new(0, 8, 1, -34)
	note.Size = UDim2.new(1, -16, 0, 32)
	note.BackgroundTransparency = 1
	note.TextWrapped = true
	note.TextColor3 = C.sub
	note.Font = Th.font
	note.TextSize = 12
	note.TextXAlignment = Enum.TextXAlignment.Left
	note.TextYAlignment = Enum.TextYAlignment.Top
	note.Text = "Drag = spin | wheel / pinch / Zoom = zoom | particles, beams and trails cannot draw inside a window: use World view to see them."
	note.Parent = content
	V.note = note
	P.len = X.tpLen(P)
	X.tpHeads(P)
	X.tpUI(P)
end

X.edsLoad()

X.KEPT_FILE = "AnimLogger_frames.json"
X.keepFail = {}

function X.keptLoad()
	if not (isfile and readfile) then return end
	local ok, data = pcall(function()
		if isfile(X.KEPT_FILE) then return HttpService:JSONDecode(readfile(X.KEPT_FILE)) end
	end)
	if ok and type(data) == "table" and type(data.items) == "table" then
		for id, it in pairs(data.items) do
			if type(it) == "table" and type(it.anim) == "table" then X.kept[id] = it end
		end
	end
end

function X.keptWrite()
	if not writefile then return end
	local ok, json = pcall(function() return HttpService:JSONEncode({ v = 1, items = X.kept }) end)
	if ok and #json < 24000000 then pcall(writefile, X.KEPT_FILE, json) end
end

function X.keepFrames(id, btn)
	if X.kept[id] or X.keepBusy then
		if btn and btn.Parent then K.flash(btn, X.kept[id] and "Kept" or "Busy") end
		return
	end
	X.keepBusy = true
	if btn and btn.Parent then btn.Text = "Working..." end
	task.spawn(function()
		local ok, err = pcall(function()
			if not details[id] then
				local finished = false
				requestDetail(id, function() finished = true end)
				local t0 = os.clock()
				while not finished and os.clock() - t0 < 45 do task.wait(0.25) end
			end
			if not details[id] then error("this game cannot load the animation") end
			local it = X.edsPack(id)
			it.kept, it.code, it.orig, it.fxOrig = true, nil, nil, nil
			if not it.anim then error("no frames") end
			X.kept[id] = it
			X.keptDirty = true
		end)
		X.keepBusy = false
		if not ok then
			X.keepFail[id] = true
			out("Could not keep the frames of " .. tostring(animLabel[id] or id) .. ": " .. tostring(err) .. ". Open this saved anim in the game it comes from and press Keep.")
		end
		if X.svReady then X.svRender() end
	end)
end

function X.keepNext()
	for _, r in ipairs(X.sv.list) do
		if not X.kept[r.id] and details[r.id] and not X.keepFail[r.id] then return X.keepFrames(r.id) end
	end
end
X.keptLoad()

X.DS_TYPES = {
	{ key = "id", name = "AnimationId (original)" },
	{ key = "frames", name = "Frames (no original)", mode = false },
	{ key = "vfx", name = "Frames + VFX", mode = "vfx" },
	{ key = "sfx", name = "Frames + SFX", mode = "sfx" },
	{ key = "fx", name = "Full-FX (VFX + SFX)", mode = "fx" },
	{ key = "cut", name = "Full-FX + cutscene", mode = "cut" },
	{ key = "all", name = "Full-FX everything", mode = "all" },
}
X.dsTok = setmetatable({}, { __mode = "k" })

function X.dsTypeIndex(key)
	for i, t in ipairs(X.DS_TYPES) do
		if t.key == key then return i end
	end
	return 1
end

function X.saveAll(id, btn)
	local function say(t)
		if btn and btn.Parent then K.flash(btn, t) end
	end
	if not details[id] then return say("No frames") end
	do
		local okP, it = pcall(X.edsPack, id)
		if okP and it and it.anim then
			it.kept, it.code, it.orig, it.fxOrig = true, nil, nil, nil
			X.kept[id] = it
			X.keptDirty = true
		end
	end
	if not X.sv.map[id] then X.svToggle(id, animLabel[id] or K.animName(id)) end
	X.edsSave(id, btn)
end

function X.saveAllBtn(id, btn)
	if btn and btn.Parent then btn.Text = "Working..." end
	requestDetail(id, function(ok, res)
		if not ok then
			out("Save all failed: " .. tostring(res))
			if btn and btn.Parent then K.flash(btn, "Fail") end
			return
		end
		X.saveAll(id, btn)
	end, function(t)
		if btn and btn.Parent then btn.Text = t:sub(1, 16) end
	end)
end

function X.dsBuildCode(id, t, cb)
	task.spawn(function()
		local ok, res, info = pcall(function()
			local rid = X.savedId(id)
			local done, okD, resD = false, false, nil
			requestDetail(rid, function(o, r)
				done, okD, resD = true, o, r
			end)
			local t0 = os.clock()
			while not done and os.clock() - t0 < 90 do task.wait(0.2) end
			if not done then error("timed out loading the animation") end
			if not okD or not details[rid] then
				error(tostring(resD or "this game cannot load the animation (use a saved anim with kept frames)"))
			end
			local code = K.buildAnimCode(rid, t.mode)
			local fxN = 0
			if t.mode then fxN = #(K.fxFilter(fxWindows.liveFor(rid), t.mode) or {}) end
			if rid == id then pcall(X.saveAll, id) end
			return code, string.format("ready, %d KB%s", math.max(1, math.floor(#code / 1024)), t.mode and string.format(", %d effect(s)", fxN) or "")
		end)
		cb(ok, ok and res or tostring(res), info)
	end)
end

function X.dsRefreshUI()
	pcall(function()
		if X.dsWin then
			X.dsDraw()
			X.dsProps()
		end
	end)
end

function X.dsGenJump(j)
	local t = X.DS_TYPES[X.dsTypeIndex(j.type)]
	j.type = t.key
	X.svDirty = true
	j.code, j.fallCode = "", ""
	local tok = (X.dsTok[j] or 0) + 1
	X.dsTok[j] = tok
	if t.key == "id" then
		j.codeInfo = ""
		return
	end
	if j.anim == "" and j.fall == "" then
		j.codeInfo = "pick an animation first"
		return
	end
	j.codeInfo = "generating..."
	task.spawn(function()
		local made, failed = 0, {}
		for _, slot in ipairs({ { "anim", "code", "jump" }, { "fall", "fallCode", "fall" } }) do
			local id = j[slot[1]]
			if id ~= "" then
				local done = false
				X.dsBuildCode(id, t, function(ok, res)
					if X.dsTok[j] == tok then
						if ok then
							j[slot[2]] = res
							made += 1
						else
							failed[#failed + 1] = slot[3]
						end
					end
					done = true
				end)
				while not done do task.wait(0.1) end
				if X.dsTok[j] ~= tok then return end
			end
		end
		j.codeInfo = string.format("ready, %d anim(s)%s", made, #failed > 0 and (", failed: " .. table.concat(failed, ", ")) or "")
		X.svDirty = true
		X.dsRefreshUI()
	end)
end

X.JOY_KEYS = { "idle", "walk", "run", "sprint", "back", "left", "right" }

function X.dsGenJoy(j)
	local t = X.DS_TYPES[X.dsTypeIndex(j.type)]
	j.type = t.key
	X.svDirty = true
	for _, k in ipairs(X.JOY_KEYS) do j.codes[k] = "" end
	local tok = (X.dsTok[j] or 0) + 1
	X.dsTok[j] = tok
	if t.key == "id" then
		j.codeInfo = ""
		return
	end
	j.codeInfo = "generating..."
	task.spawn(function()
		local made, failed = 0, {}
		for _, key in ipairs(X.JOY_KEYS) do
			local id = j.a[key]
			if id ~= "" then
				local done = false
				X.dsBuildCode(id, t, function(ok, res)
					if X.dsTok[j] == tok then
						if ok then
							j.codes[key] = res
							made += 1
						else
							failed[#failed + 1] = key
						end
					end
					done = true
				end)
				while not done do task.wait(0.1) end
				if X.dsTok[j] ~= tok then return end
			end
		end
		if made == 0 and #failed == 0 then
			j.codeInfo = "pick animations first"
		else
			j.codeInfo = string.format("ready, %d anim(s)%s", made, #failed > 0 and (", failed: " .. table.concat(failed, ", ")) or "")
		end
		X.svDirty = true
		X.dsRefreshUI()
	end)
end

function X.dsGenCode(b)
	local t = X.DS_TYPES[X.dsTypeIndex(b.type)]
	b.type = t.key
	local tok = (X.dsTok[b] or 0) + 1
	X.dsTok[b] = tok
	X.svDirty = true
	if t.key == "id" or b.anim == "" then
		b.code, b.codeFor = "", ""
		b.codeInfo = (t.key ~= "id") and "pick an animation first" or ""
		return
	end
	local id = b.anim
	b.code, b.codeFor, b.codeInfo = "", "", "generating..."
	task.spawn(function()
		local okAll, err = pcall(function()
			local rid = X.savedId(id)
			local done, okD, resD = false, false, nil
			requestDetail(rid, function(ok, res)
				done, okD, resD = true, ok, res
			end)
			local t0 = os.clock()
			while not done and os.clock() - t0 < 90 do task.wait(0.2) end
			if not done then error("timed out loading the animation") end
			if not okD or not details[rid] then
				error(tostring(resD or "this game cannot load the animation (use a saved anim with kept frames)"))
			end
			local code = K.buildAnimCode(rid, t.mode)
			if X.dsTok[b] ~= tok then return end
			local fxN = 0
			if t.mode then fxN = #(K.fxFilter(fxWindows.liveFor(rid), t.mode) or {}) end
			b.code, b.codeFor = code, id .. "|" .. t.key
			b.codeInfo = string.format("ready, %d KB%s", math.max(1, math.floor(#code / 1024)), t.mode and string.format(", %d effect(s)", fxN) or "")
			if rid == id then pcall(X.saveAll, id) end
		end)
		if not okAll and X.dsTok[b] == tok then
			b.code, b.codeInfo = "", "failed: " .. tostring(err):sub(1, 60)
			out("Design Script: could not build the script for " .. tostring(b.label) .. ": " .. tostring(err))
		end
		X.svDirty = true
		pcall(function()
			if X.dsWin then
				X.dsDraw()
				X.dsProps()
			end
		end)
	end)
end

function X.dsNew(over, quiet)
	if #X.ds.buttons >= 30 then return nil end
	local n = #X.ds.buttons + 1
	local b = {
		label = "B" .. n, anim = "", animName = "",
		x = math.max(0.88 - ((n - 1) % 4) * 0.1, 0.08), y = math.max(0.78 - math.floor((n - 1) / 4) * 0.2, 0.1),
		size = 0.075, mode = "once", cd = 0.4, speed = 1, key = "",
		dmg = false, dmgAmt = 15, range = 8, delay = 0.25, npcOnly = true, remote = "",
		type = "id", code = "", codeFor = "", codeInfo = "",
	}
	if over then
		for k, v in pairs(over) do
			if b[k] ~= nil and type(v) == type(b[k]) then b[k] = v end
		end
	end
	if b.codeInfo == "generating..." then b.codeInfo = "" end
	table.insert(X.ds.buttons, b)
	if not quiet then
		X.ds.sel = #X.ds.buttons
		X.dsPanelOpen = false
		if not X.dsWin then
			X.dsOpen()
		elseif X.dsDraw then
			X.dsDraw()
			X.dsProps()
		end
	end
	return b
end

function X.joyNew(over)
	local j = {
		x = 0.14, y = 0.74, size = 0.17, deadzone = 0.12, runAt = 0.5, sprintAt = 0.9,
		walkSpeed = 10, runSpeed = 16, sprintSpeed = 24, animSpeed = 1, strafe = false, hideDefault = true,
		a = { idle = "", walk = "", run = "", sprint = "", back = "", left = "", right = "" },
		an = { idle = "", walk = "", run = "", sprint = "", back = "", left = "", right = "" },
		type = "id", codeInfo = "",
		codes = { idle = "", walk = "", run = "", sprint = "", back = "", left = "", right = "" },
	}
	if type(over) == "table" then
		for k, v in pairs(over) do
			if k == "a" or k == "an" or k == "codes" then
				if type(v) == "table" then
					for kk, vv in pairs(v) do
						if j[k][kk] ~= nil and type(vv) == "string" then j[k][kk] = vv end
					end
				end
			elseif j[k] ~= nil and type(v) == type(j[k]) then
				j[k] = v
			end
		end
	end
	if j.codeInfo == "generating..." then j.codeInfo = "" end
	return j
end

function X.jumpNew(over)
	local j = { x = 0.9, y = 0.55, size = 0.08, label = "Jump", height = 7.2, extra = 0, hideDefault = true, anim = "", animName = "", fall = "", fallName = "", type = "id", code = "", fallCode = "", codeInfo = "" }
	if type(over) == "table" then
		for k, v in pairs(over) do
			if j[k] ~= nil and type(v) == type(j[k]) then j[k] = v end
		end
	end
	if j.codeInfo == "generating..." then j.codeInfo = "" end
	return j
end

function X.httpPost(path, body)
	local req = request or http_request or (syn and syn.request) or (fluxus and fluxus.request)
	if not req then return nil, "this executor has no request()" end
	if X.ACCESS_URL:find("YOUR-WORKER", 1, true) then return nil, "server not set up yet: set X.ACCESS_URL in the script (design-server/README.md)" end
	local ok, res = pcall(req, {
		Url = (X.ACCESS_URL:gsub("/+$", "")) .. path, Method = "POST",
		Headers = { ["Content-Type"] = "application/json" }, Body = HttpService:JSONEncode(body),
	})
	if not ok or type(res) ~= "table" then return nil, "could not reach the server" end
	local okJ, data = pcall(function() return HttpService:JSONDecode(res.Body) end)
	if not okJ or type(data) ~= "table" then return nil, "bad answer from the server" end
	if data.ok ~= true then return nil, tostring(data.error or "denied") end
	return data
end

function X.hwid()
	local ok, v = pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
	return ok and tostring(v) or ""
end

X.access = { ok = false, key = "", name = "", msg = "" }

function X.accessVerify(key, cb)
	task.spawn(function()
		local data, err = X.httpPost("/verify", { key = key, userId = lp.UserId, hwid = X.hwid() })
		if data then
			X.access.ok, X.access.key, X.access.name, X.access.msg = true, key, tostring(data.name or ""), ""
			if writefile then pcall(writefile, X.KEY_FILE, key) end
		else
			X.access.ok, X.access.msg = false, tostring(err)
		end
		if cb then cb() end
	end)
end

function X.dsPayload()
	local list = {}
	for i, b in ipairs(X.ds.buttons) do
		list[i] = {
			label = b.label, anim = b.anim, x = b.x, y = b.y, size = b.size, mode = b.mode, cd = b.cd, speed = b.speed, key = b.key,
			dmg = b.dmg, dmgAmt = b.dmgAmt, range = b.range, delay = b.delay, npcOnly = b.npcOnly, remote = b.remote,
			type = b.type, code = b.code,
		}
	end
	return list
end

function X.dsGenerate(cb, noWait)
	if #X.ds.buttons == 0 and not X.ds.joy and not X.ds.jump then return X.dsMsg("add a button (+ Button), the joystick (+ Joystick) or the jump button (+ Jump) first") end
	local function busy()
		for _, bb in ipairs(X.ds.buttons) do
			if bb.codeInfo == "generating..." then return true end
		end
		if X.ds.jump and X.ds.jump.codeInfo == "generating..." then return true end
		if X.ds.joy and X.ds.joy.codeInfo == "generating..." then return true end
		return false
	end
	if not noWait and busy() then
		X.dsMsg("still building the button scripts, one moment...")
		task.spawn(function()
			local t0 = os.clock()
			while busy() and os.clock() - t0 < 90 do task.wait(0.3) end
			X.dsGenerate(cb, true)
		end)
		return
	end
	local noAnim = {}
	for _, b in ipairs(X.ds.buttons) do
		if b.anim == "" then noAnim[#noAnim + 1] = b.label end
	end
	if #noAnim > 0 then
		X.dsMsg("no animation yet on: " .. table.concat(noAnim, ", ") .. " (tap the button to pick one)")
	end
	local notReady = {}
	for _, bb in ipairs(X.ds.buttons) do
		if bb.type ~= "id" and bb.anim ~= "" and bb.code == "" then notReady[#notReady + 1] = bb.label end
	end
	if #notReady > 0 then
		X.dsMsg("no script built yet on: " .. table.concat(notReady, ", ") .. " (tap the button > Script to rebuild)")
	end
	if not X.REQUIRE_KEY then
		local okB, code = pcall(X.dsLocal)
		if not okB then return out("Design Script: " .. tostring(code)) end
		return cb(code)
	end
	out("Design Script: asking your server to build the script...")
	task.spawn(function()
		local data, err = X.httpPost("/generate", { key = X.access.key, userId = lp.UserId, hwid = X.hwid(), buttons = X.dsPayload(), joystick = X.ds.joy and { x = X.ds.joy.x, y = X.ds.joy.y, size = X.ds.joy.size, deadzone = X.ds.joy.deadzone, runAt = X.ds.joy.runAt, sprintAt = X.ds.joy.sprintAt, walkSpeed = X.ds.joy.walkSpeed, runSpeed = X.ds.joy.runSpeed, sprintSpeed = X.ds.joy.sprintSpeed, animSpeed = X.ds.joy.animSpeed, strafe = X.ds.joy.strafe, hideDefault = X.ds.joy.hideDefault, a = X.ds.joy.a } or nil, jump = X.ds.jump })
		if not data then
			out("Design Script: " .. tostring(err))
			return
		end
		cb(data.script)
	end)
end

X.REQUIRE_KEY = false

X.DS_RUNTIME = [==[
-- Uses Roblox's OWN controls: the thumbstick, the jump button and ContextActionService touch buttons.
local Players = game:GetService("Players")
local UIS = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local CAS = game:GetService("ContextActionService")
local lp = Players.LocalPlayer
local env = (getgenv and getgenv()) or _G
if env.__DuaDesignStop then pcall(env.__DuaDesignStop) end

local alive, conns, tracks, casNames = true, {}, {}, {}
local function conn(c)
	conns[#conns + 1] = c
	return c
end

local function getHum()
	local ch = lp.Character
	return ch and ch:FindFirstChildOfClass("Humanoid"), ch
end

local function loadTrack(id, prio)
	local hum = getHum()
	if not hum or id == nil or id == "" then return nil end
	if not id:find("^rbx") and id:match("^%d+$") then id = "rbxassetid://" .. id end
	local key = id .. "|" .. prio.Name
	local c = tracks[key]
	if c and c.hum == hum then return c.track end
	local animator = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 2)
	if not animator then return nil end
	local a = Instance.new("Animation")
	a.AnimationId = id
	local ok, tr = pcall(function() return animator:LoadAnimation(a) end)
	if not ok or not tr then return nil end
	tr.Priority = prio
	tracks[key] = { hum = hum, track = tr }
	return tr
end

local function remoteFor(path)
	if path == nil or path == "" then return nil end
	local cur = game
	for part in path:gmatch("[^%.]+") do
		if part ~= "game" then
			cur = cur and cur:FindFirstChild(part)
		end
	end
	return cur
end

-- ===== stored scripts (Frames / Full-FX anim types) =====
local codeFns = {}
local function codeRun(code, speed, loop) -- runs one stored script (cached), speed / loop patched in
	local per = codeFns[code]
	if not per then
		per = {}
		codeFns[code] = per
	end
	local k = tostring(speed) .. "|" .. tostring(loop)
	local fn = per[k]
	if fn == nil then
		local src = code
		src = src:gsub("local SPEED = [^\n]*", "local SPEED = " .. tostring(speed), 1)
		src = src:gsub("local LOOP_FOREVER = [^\n]*", "local LOOP_FOREVER = " .. tostring(loop), 1)
		src = src:gsub("local CANCEL_ON_MOVE = [^\n]*", "local CANCEL_ON_MOVE = false", 1)
		local loader = loadstring or load
		fn = loader and loader(src) or false
		per[k] = fn
	end
	if fn then task.spawn(fn) end
end
local function codeStop()
	local st = _G.StopRecreatedAnim
	if st then pcall(st) end
end

-- ===== move buttons: ContextActionService (touch button on mobile, key on PC) =====
local function px(cfg)
	local vp = workspace.CurrentCamera.ViewportSize
	return math.max(math.floor(cfg.size * vp.X + 0.5), 24)
end

local casList = {}
local function bindBtn(cfg, name, onBegin, onEnd)
	-- same recipe as the JJS moveset: BindAction with createTouchButton = true and a real input, then SetTitle;
	-- the layout loop below keeps size + position right (CAS re-lays its buttons out by itself)
	local key
	if cfg.key and cfg.key ~= "" then
		local okK, kc = pcall(function() return Enum.KeyCode[cfg.key] end)
		if okK and kc then key = kc end
	end
	local okB = pcall(function()
		CAS:BindAction(name, function(_, state)
			if state == Enum.UserInputState.Begin then
				onBegin()
			elseif state == Enum.UserInputState.End or state == Enum.UserInputState.Cancel then
				onEnd()
			end
			return Enum.ContextActionResult.Pass
		end, true, key or Enum.KeyCode.F13)
	end)
	if not okB then return end
	casNames[#casNames + 1] = name
	casList[#casList + 1] = { name = name, cfg = cfg }
	pcall(function() CAS:SetTitle(name, cfg.label) end)
end

local function layoutCas()
	for _, it in ipairs(casList) do
		local btn = CAS:GetButton(it.name)
		local sg = btn and btn:FindFirstAncestorOfClass("ScreenGui")
		local parent = btn and btn.Parent
		if sg and parent then
			local size = px(it.cfg)
			local pa, sp, ss = parent.AbsolutePosition, sg.AbsolutePosition, sg.AbsoluteSize
			btn.AnchorPoint = Vector2.new(0.5, 0.5)
			btn.Size = UDim2.fromOffset(size, size)
			btn.Position = UDim2.fromOffset(sp.X + it.cfg.x * ss.X - pa.X, sp.Y + it.cfg.y * ss.Y - pa.Y)
		end
	end
end

for i, cfg in ipairs(BUTTONS) do
	local casName = "DuaBtn" .. i
	local cdUntil, active = 0, false
	local function dim(v)
		local b = CAS:GetButton(casName)
		if b then pcall(function() b.ImageTransparency = v end) end
	end
	local function getTr() -- a stored script behaves like a track: Play / Stop
		if cfg.code and cfg.code ~= "" then
			return { Looped = false, Play = function() codeRun(cfg.code, cfg.speed, cfg.mode ~= "once") end, Stop = function() codeStop() end }
		end
		return loadTrack(cfg.anim, Enum.AnimationPriority.Action4)
	end

	local function doDamage()
		if not cfg.dmg then return end
		local hum, ch = getHum()
		local root = ch and ch:FindFirstChild("HumanoidRootPart")
		if not root then return end
		local params = OverlapParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { ch }
		local hit = {}
		for _, p in ipairs(workspace:GetPartBoundsInRadius(root.Position, cfg.range, params)) do
			local m = p:FindFirstAncestorOfClass("Model")
			if m and not hit[m] then
				local h = m:FindFirstChildOfClass("Humanoid")
				if h and h.Health > 0 and not (cfg.npcOnly and Players:GetPlayerFromCharacter(m)) then
					hit[m] = true
					local rem = remoteFor(cfg.remote)
					if rem and rem:IsA("RemoteEvent") then
						pcall(function() rem:FireServer(m, cfg.dmgAmt) end)
					elseif rem and rem:IsA("RemoteFunction") then
						pcall(function() rem:InvokeServer(m, cfg.dmgAmt) end)
					else
						pcall(function() h:TakeDamage(cfg.dmgAmt) end)
					end
				end
			end
		end
	end

	local function start()
		local tr = getTr()
		if not tr then return end
		if cfg.mode == "once" then
			if os.clock() < cdUntil then return end
			cdUntil = os.clock() + cfg.cd
			tr.Looped = false
			tr:Play(0.1, 1, cfg.speed)
			if cfg.dmg then task.delay(cfg.delay, doDamage) end
			if cfg.cd > 0.15 then
				dim(0.6)
				task.delay(cfg.cd, function() dim(0) end)
			end
		elseif cfg.mode == "toggle" and active then
			active = false
			tr:Stop(0.15)
			dim(0)
		elseif not active then
			active = true
			tr.Looped = true
			tr:Play(0.1, 1, cfg.speed)
			dim(0.5)
			if cfg.dmg then
				task.spawn(function()
					while active and alive do
						task.wait(math.max(cfg.delay, 0.3))
						if active then doDamage() end
					end
				end)
			end
		end
	end

	local function release()
		if cfg.mode == "hold" and active then
			active = false
			local tr = getTr()
			if tr then tr:Stop(0.15) end
			dim(0)
		end
	end

	bindBtn(cfg, casName, start, release)
end
task.spawn(function()
	while alive do
		pcall(layoutCas)
		task.wait(0.5)
	end
end)

-- ===== joystick: Roblox's own thumbstick (how far you push it picks idle / walk / run / sprint) =====
local locoTrack, locoState, locoStop = nil, "", nil
if JOY then
	local function setLoco(key)
		if key == locoState then return end
		local code = JOY.codes and JOY.codes[key]
		local hasCode = code ~= nil and code ~= ""
		if hasCode or locoStop then
			-- a button move is playing: leave it alone and try again next frame
			if _G.StopRecreatedAnim ~= nil and _G.StopRecreatedAnim ~= locoStop then return end
		end
		locoState = key
		if locoTrack then
			locoTrack:Stop(0.2)
			locoTrack = nil
		end
		if locoStop and _G.StopRecreatedAnim == locoStop then codeStop() end
		locoStop = nil
		if hasCode then
			codeRun(code, JOY.animSpeed, true)
			locoStop = _G.StopRecreatedAnim
			return
		end
		local id = JOY.a[key]
		if id and id ~= "" then
			local tr = loadTrack(id, Enum.AnimationPriority.Action)
			if tr then
				tr.Looped = true
				tr:Play(0.2, 1, JOY.animSpeed)
				locoTrack = tr
			end
		end
	end

	conn(RunService.RenderStepped:Connect(function()
		local hum, ch = getHum()
		local root = ch and ch:FindFirstChild("HumanoidRootPart")
		if not hum or not root or hum.Health <= 0 then return end
		local moveDir = hum.MoveDirection
		local m = moveDir.Magnitude
		local tier = "idle"
		if m > JOY.deadzone then
			if m < JOY.runAt then tier = "walk" elseif m < JOY.sprintAt then tier = "run" else tier = "sprint" end
		end
		local spd = JOY.walkSpeed
		if tier == "run" then spd = JOY.runSpeed elseif tier == "sprint" then spd = JOY.sprintSpeed end
		hum.WalkSpeed = spd
		local key = tier
		if JOY.strafe then
			hum.AutoRotate = false
			local cf = workspace.CurrentCamera.CFrame
			local fwd = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
			if fwd.Magnitude > 0 then
				fwd = fwd.Unit
				root.CFrame = root.CFrame:Lerp(CFrame.lookAt(root.Position, root.Position + fwd), 0.35)
			end
			if tier ~= "idle" and moveDir.Magnitude > 0.1 then
				local rel = root.CFrame:VectorToObjectSpace(moveDir)
				if rel.Z > 0.5 and JOY.a.back ~= "" then
					key = "back"
				elseif rel.X < -0.6 and JOY.a.left ~= "" then
					key = "left"
				elseif rel.X > 0.6 and JOY.a.right ~= "" then
					key = "right"
				end
			end
		else
			hum.AutoRotate = true
		end
		if JOY.a[key] == "" and key ~= "idle" then key = (JOY.a[tier] ~= "") and tier or "walk" end
		if locoStop and _G.StopRecreatedAnim == nil then locoState = "" end -- our script ended (a move finished): start it again
		setLoco(key)
	end))
end

-- ===== jump: Roblox's own jump button / space bar (animation + extra jumps + height + fall animation) =====
local airJumps, lastJump, fallActive, fallStop = 0, 0, false, nil
if JUMP then
	local function jumpTr() -- a stored jump script behaves like a track
		if JUMP.code and JUMP.code ~= "" then
			return { Looped = false, Play = function() codeRun(JUMP.code, 1, false) end, Stop = function() codeStop() end }
		end
		return loadTrack(JUMP.anim, Enum.AnimationPriority.Action2)
	end

	conn(UIS.JumpRequest:Connect(function()
		local hum, ch = getHum()
		local root = ch and ch:FindFirstChild("HumanoidRootPart")
		if not hum or not root or hum.Health <= 0 then return end
		if os.clock() - lastJump < 0.2 then return end
		local grounded = hum.FloorMaterial ~= Enum.Material.Air
		if grounded then
			airJumps = 0 -- Roblox does this jump itself
		elseif airJumps < JUMP.extra then
			airJumps = airJumps + 1
			local power = math.sqrt(2 * workspace.Gravity * JUMP.height)
			local v = root.AssemblyLinearVelocity
			root.AssemblyLinearVelocity = Vector3.new(v.X, power, v.Z)
		else
			return
		end
		lastJump = os.clock()
		local tr = jumpTr()
		if tr then
			tr.Looped = false
			tr:Play(0.05, 1, 1)
		end
	end))

	conn(RunService.Heartbeat:Connect(function()
		local hum, ch = getHum()
		local root = ch and ch:FindFirstChild("HumanoidRootPart")
		if not hum or not root then return end
		pcall(function()
			hum.UseJumpPower = false
			hum.JumpHeight = JUMP.height
		end)
		if hum.FloorMaterial ~= Enum.Material.Air then airJumps = 0 end
		local falling = hum:GetState() == Enum.HumanoidStateType.Freefall and root.AssemblyLinearVelocity.Y < -8
		if JUMP.fallCode and JUMP.fallCode ~= "" then
			if falling and not fallActive then
				fallActive = true
				codeRun(JUMP.fallCode, 1, true)
				fallStop = _G.StopRecreatedAnim
			elseif not falling and fallActive then
				fallActive = false
				if fallStop and _G.StopRecreatedAnim == fallStop then codeStop() end
				fallStop = nil
			end
		elseif JUMP.fall ~= "" then
			local ft = loadTrack(JUMP.fall, Enum.AnimationPriority.Action2)
			if ft then
				if falling and not ft.IsPlaying then
					ft.Looped = true
					ft:Play(0.15)
				elseif not falling and ft.IsPlaying then
					ft:Stop(0.1)
				end
			end
		end
	end))
end

conn(lp.CharacterAdded:Connect(function()
	table.clear(tracks)
	locoTrack, locoState, locoStop = nil, "", nil
	fallActive, fallStop = false, nil
end))

env.__DuaDesignStop = function()
	alive = false
	pcall(codeStop)
	for _, n in ipairs(casNames) do pcall(function() CAS:UnbindAction(n) end) end
	for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
	for _, c in pairs(tracks) do pcall(function() c.track:Stop(0) end) end
	local hum = getHum()
	if hum then hum.AutoRotate = true end
	env.__DuaDesignStop = nil
end
]==]

function X.dsSer(v)
	local t = type(v)
	if t == "number" then return K.g(v) end
	if t == "boolean" then return tostring(v) end
	if t == "string" then return string.format("%q", v) end
	if t == "table" then
		local parts = {}
		if #v > 0 then
			for i = 1, #v do parts[#parts + 1] = X.dsSer(v[i]) end
		else
			local keys = {}
			for k in pairs(v) do keys[#keys + 1] = k end
			table.sort(keys)
			for _, k in ipairs(keys) do parts[#parts + 1] = k .. " = " .. X.dsSer(v[k]) end
		end
		return "{ " .. table.concat(parts, ", ") .. " }"
	end
	return "nil"
end

function X.dsLocal()
	local L = {
		"-- Design Script: " .. #X.ds.buttons .. " button(s)" .. (X.ds.joy and " + joystick" or "") .. (X.ds.jump and " + jump button" or ""),
		"-- Positions are screen fractions (0-1) with the ScreenGui ignoring the top bar, so each button is exactly where you put it.",
		"local BUTTONS = " .. X.dsSer(X.dsPayload()),
	}
	local jy, jp = X.ds.joy, X.ds.jump
	if jy then
		L[#L + 1] = "local JOY = " .. X.dsSer({
			x = jy.x, y = jy.y, size = jy.size, deadzone = jy.deadzone, runAt = jy.runAt, sprintAt = jy.sprintAt,
			walkSpeed = jy.walkSpeed, runSpeed = jy.runSpeed, sprintSpeed = jy.sprintSpeed, animSpeed = jy.animSpeed,
			strafe = jy.strafe, hideDefault = jy.hideDefault, type = jy.type,
			a = { idle = jy.a.idle, walk = jy.a.walk, run = jy.a.run, sprint = jy.a.sprint, back = jy.a.back, left = jy.a.left, right = jy.a.right },
			codes = { idle = jy.codes.idle, walk = jy.codes.walk, run = jy.codes.run, sprint = jy.codes.sprint, back = jy.codes.back, left = jy.codes.left, right = jy.codes.right },
		})
	else
		L[#L + 1] = "local JOY = nil"
	end
	if jp then
		L[#L + 1] = "local JUMP = " .. X.dsSer({
			x = jp.x, y = jp.y, size = jp.size, label = jp.label, height = jp.height, extra = jp.extra,
			hideDefault = jp.hideDefault, anim = jp.anim, fall = jp.fall, type = jp.type, code = jp.code, fallCode = jp.fallCode,
		})
	else
		L[#L + 1] = "local JUMP = nil"
	end
	L[#L + 1] = X.DS_RUNTIME
	return table.concat(L, "\n")
end

function X.dsOpen()
	if X.dsWin and X.dsWin.frame.Parent then
		X.dsWin.frame.Visible = true
		X.dsWin.mini.Visible = false
		X.dsDraw()
		X.dsProps()
		return
	end
	local win = createWindow({
		title = "Design Screen - drag to place, tap to edit",
		size = Vector2.new(640, 440),
		pos = UDim2.new(0.5, -320, 0.5, -220),
		minSize = Vector2.new(340, 300),
		miniText = "DS",
		onClose = function()
			X.dsWin = nil
			X.dsPv, X.dsList, X.dsPropsFrame = nil, nil, nil
			X.dsEditClose()
			X.dsHint = nil
			X.dsPanelOpen, X.ds.sel = false, nil
			X.dsPage = X.dsTabPage
			X.svDirty = true
			task.defer(X.dsBuild)
		end,
	})
	X.dsWin = win
	X.dsPage = win.content
	X.dsBuild()
end

function X.dsLauncher(page)
	local sf = newList(page, UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 1, 0))
	sf:SetAttribute("dsRoot", true)
	local order = 0
	local function line(text, h)
		order += 1
		local l = Instance.new("TextLabel")
		l.Size = UDim2.new(1, -6, 0, h)
		l.BackgroundTransparency = 1
		l.TextWrapped = true
		l.Text = text
		l.TextColor3 = C.sub
		l.Font = Th.font
		l.TextSize = 14
		l.TextXAlignment = Enum.TextXAlignment.Left
		l.TextYAlignment = Enum.TextYAlignment.Top
		l.LayoutOrder = order
		l.Parent = sf
	end
	local function btn(text, color, fn)
		order += 1
		local b = K.newButton(sf, text, color)
		b.Size = UDim2.new(1, -6, 0, 38)
		b.LayoutOrder = order
		b.MouseButton1Click:Connect(function()
			local ok, err = pcall(fn)
			if not ok then out("Design: " .. tostring(err)) end
		end)
	end
	line("Design Script: put buttons, a joystick and a jump button on a screen, then copy the finished script. The screen opens in its own window; in the copied script everything is exactly where you placed it.", 62)
	line(string.format("On the design now: %d button(s)%s%s.", #X.ds.buttons, X.ds.joy and ", joystick" or "", X.ds.jump and ", jump button" or ""), 22)
	btn("Open design screen", C.green, function()
		if not X.dsWin then X.dsPanelOpen, X.ds.sel = false, nil end
		X.dsOpen()
	end)
	btn("Download script (you name the file)", C.sel, function()
		X.dsGenerate(function(code)
			X.saveScriptFile(code, "DesignScript")
		end)
	end)
	btn("+ Button", C.btn, function()
		X.dsNew()
		X.svDirty = true
	end)
	btn("+ Jump button", C.btn, function()
		X.ds.jump = X.ds.jump or X.jumpNew()
		X.ds.sel = "jump"
		X.dsPanelOpen = false
		X.svDirty = true
		X.dsOpen()
	end)
	btn("+ Joystick", C.btn, function()
		X.ds.joy = X.ds.joy or X.joyNew()
		X.ds.sel = "joy"
		X.dsPanelOpen = false
		X.svDirty = true
		X.dsOpen()
	end)
end

function X.dsNeedsFrames(id)
	local it = X.eds.items[id]
	return (it and it.anim ~= nil) or tostring(id):find("^combo:") ~= nil
end

function X.dsPick(cb, allowNone)
	local page = (X.dsEditWin and X.dsEditWin.content) or X.dsPage
	local ov = Instance.new("Frame")
	ov.Size = UDim2.new(1, 0, 1, 0)
	ov.BackgroundColor3 = C.win
	ov.ZIndex = 50
	ov.Parent = page
	local title = Instance.new("TextLabel")
	title.Size = UDim2.new(1, -90, 0, 30)
	title.Position = UDim2.new(0, 8, 0, 0)
	title.BackgroundTransparency = 1
	title.Text = "Pick an animation"
	title.TextColor3 = C.text
	title.Font = Th.bold
	title.TextSize = 16
	title.TextXAlignment = Enum.TextXAlignment.Left
	title.ZIndex = 51
	title.Parent = ov
	local close = K.newButton(ov, "Close", C.danger)
	close.Size = UDim2.new(0, 76, 0, 28)
	close.Position = UDim2.new(1, -82, 0, 1)
	close.ZIndex = 51
	close.MouseButton1Click:Connect(function() ov:Destroy() end)
	local box = Instance.new("TextBox")
	box.Size = UDim2.new(1, -8, 0, 28)
	box.Position = UDim2.new(0, 4, 0, 34)
	box.BackgroundColor3 = C.btn
	box.BorderSizePixel = 0
	box.TextColor3 = C.text
	box.PlaceholderText = "Search by name, id or folder..."
	box.PlaceholderColor3 = C.sub
	box.Text = ""
	box.ClearTextOnFocus = false
	box.Font = Th.font
	box.TextSize = 14
	box.TextXAlignment = Enum.TextXAlignment.Left
	box.ZIndex = 51
	box.Parent = ov
	local pad = Instance.new("UIPadding")
	pad.PaddingLeft = UDim.new(0, 8)
	pad.Parent = box
	local list = newList(ov, UDim2.new(0, 4, 0, 66), UDim2.new(1, -8, 1, -70))
	list.ZIndex = 51

	local entries, seen = {}, {}
	local function collect(id, name, tag, folder)
		if seen[id] then return end
		seen[id] = true
		entries[#entries + 1] = { id = id, name = name, tag = tag, folder = folder or "" }
	end
	if allowNone then collect("", "(no animation)", "") end
	for _, eid in ipairs(X.eds.order) do
		local eit = X.eds.items[eid]
		if eit and eit.anim then collect(eid, eit.name or eid, "[edit] ") end
	end
	local favs, others = {}, {}
	for _, r in ipairs(X.sv.list) do table.insert(r.fav and favs or others, r) end
	for _, r in ipairs(favs) do collect(r.id, r.name, "* ", r.folder) end
	for _, r in ipairs(others) do collect(r.id, r.name, "", r.folder) end
	for id, name in pairs(animLabel) do collect(id, name, "") end

	local function render()
		for _, c in ipairs(list:GetChildren()) do
			if c:IsA("GuiObject") then c:Destroy() end
		end
		local q = box.Text:lower():gsub("^%s+", ""):gsub("%s+$", "")
		local n = 0
		for _, e in ipairs(entries) do
			local hay = (tostring(e.name) .. " " .. tostring(e.id) .. " " .. e.folder):lower()
			if q == "" or e.id == "" or hay:find(q, 1, true) then
				n += 1
				local b = K.newButton(list, "", n % 2 == 1 and C.row1 or C.row2)
				b.Size = UDim2.new(1, -6, 0, 36)
				b.LayoutOrder = n
				b.ZIndex = 52
				b.TextXAlignment = Enum.TextXAlignment.Left
				b.TextTruncate = Enum.TextTruncate.AtEnd
				b.TextSize = 14
				b.Text = "  " .. e.tag .. tostring(e.name) .. (e.id ~= "" and ("   (" .. (tostring(e.id):match("%d+") or "?") .. ")") or "")
					.. (e.folder ~= "" and ("   [" .. e.folder .. "]") or "")
				b.MouseButton1Click:Connect(function()
					ov:Destroy()
					cb(e.id, e.name)
				end)
			end
		end
		if n == 0 then
			local l = Instance.new("TextLabel")
			l.Size = UDim2.new(1, -6, 0, 40)
			l.BackgroundTransparency = 1
			l.Text = "Nothing matches that search."
			l.TextColor3 = C.sub
			l.Font = Th.font
			l.TextSize = 14
			l.ZIndex = 52
			l.Parent = list
		end
	end
	box:GetPropertyChangedSignal("Text"):Connect(render)
	render()
end

X.DS_LIM = { joy = { 0.08, 0.92, 0.1, 0.9 }, jump = { 0.04, 0.96, 0.06, 0.94 }, btn = { 0.03, 0.97, 0.05, 0.95 } }

function X.dsItem(sel)
	if sel == "joy" then return X.ds.joy end
	if sel == "jump" then return X.ds.jump end
	if type(sel) == "number" then return X.ds.buttons[sel] end
	return nil
end

function X.dsMark()
	local pv = X.dsPv
	if not (pv and pv.Parent) then return end
	local sel = X.ds.sel ~= nil and tostring(X.ds.sel) or nil
	for _, c in ipairs(pv:GetChildren()) do
		local k = c:GetAttribute("dsKey")
		local st = k and c:FindFirstChild("St")
		if st then
			local on = (k == sel)
			st.Color = on and Color3.fromRGB(255, 214, 64) or Color3.new(1, 1, 1)
			st.Transparency = on and 0 or 0.6
			st.Thickness = on and 3 or 2
		end
	end
end

function X.dsMsg(text)
	out("Design: " .. tostring(text))
	local pv = X.dsPv
	if not (pv and pv.Parent) then return end
	local l = pv:FindFirstChild("Msg")
	if not l then
		l = Instance.new("TextLabel")
		l.Name = "Msg"
		l:SetAttribute("NoCorner", true)
		l.Position = UDim2.new(0, 6, 1, -40)
		l.Size = UDim2.new(1, -12, 0, 34)
		l.BackgroundColor3 = Color3.fromRGB(120, 40, 40)
		l.BorderSizePixel = 0
		l.TextColor3 = Color3.new(1, 1, 1)
		l.Font = Th.font
		l.TextSize = 14
		l.TextWrapped = true
		l.ZIndex = 30
		l.Parent = pv
	end
	l.Text = tostring(text)
	l.Visible = true
	X.dsMsgT = (X.dsMsgT or 0) + 1
	local stamp = X.dsMsgT
	task.delay(6, function()
		if X.dsMsgT == stamp and l.Parent then l.Visible = false end
	end)
end

function X.dsEditClose()
	local w = X.dsEditWin
	X.dsEditWin, X.dsPropsFrame, X.dsPanelTitle, X.dsPanelBody, X.dsPanelLast = nil, nil, nil, nil, nil
	if w then pcall(w.destroy) end
end

function X.dsEditOpen(item)
	local sc = X.guiScale()
	local left = item.x > 0.5
	local win = createWindow({
		title = "Button settings",
		size = Vector2.new(300, 400),
		pos = left and UDim2.fromOffset(8, 40) or UDim2.new(1, -(300 * sc + 8), 0, 40),
		minSize = Vector2.new(240, 220),
		miniText = "SET",
		onClose = function()
			X.dsEditWin, X.dsPropsFrame, X.dsPanelTitle, X.dsPanelBody, X.dsPanelLast = nil, nil, nil, nil, nil
			X.dsPanelOpen, X.ds.sel = false, nil
			X.dsMark()
		end,
	})
	X.dsEditWin = win
	local ptitle = Instance.new("TextLabel")
	ptitle.Position = UDim2.new(0, 8, 0, 0)
	ptitle.Size = UDim2.new(1, -84, 0, 30)
	ptitle.BackgroundTransparency = 1
	ptitle.Text = ""
	ptitle.TextColor3 = C.text
	ptitle.Font = Th.bold
	ptitle.TextSize = 16
	ptitle.TextXAlignment = Enum.TextXAlignment.Left
	ptitle.TextTruncate = Enum.TextTruncate.AtEnd
	ptitle.Parent = win.content
	local done = K.newButton(win.content, "Done", C.green)
	done.Size = UDim2.new(0, 68, 0, 26)
	done.Position = UDim2.new(1, -74, 0, 2)
	done.TextSize = 14
	done.MouseButton1Click:Connect(function() X.dsClose() end)
	local plist = newList(win.content, UDim2.new(0, 0, 0, 32), UDim2.new(1, 0, 1, -32))
	local props = Instance.new("Frame")
	props.Size = UDim2.new(1, -6, 0, 0)
	props.AutomaticSize = Enum.AutomaticSize.Y
	props.BackgroundTransparency = 1
	props.Parent = plist
	local pl = Instance.new("UIListLayout")
	pl.SortOrder = Enum.SortOrder.LayoutOrder
	pl.Padding = UDim.new(0, 2)
	pl.Parent = props
	X.dsPanelTitle, X.dsPanelBody, X.dsPropsFrame = ptitle, plist, props
end

function X.dsPanelShow()
	local sel = X.ds.sel
	local item = sel ~= nil and X.dsItem(sel) or nil
	if not (X.dsPanelOpen and item and X.dsPv and X.dsPv.Parent) then
		X.dsEditClose()
		return false
	end
	if not (X.dsEditWin and X.dsEditWin.frame.Parent) then X.dsEditOpen(item) end
	if X.dsPanelTitle then
		X.dsPanelTitle.Text = (sel == "joy" and "Joystick") or (sel == "jump" and "Jump button") or ("Button: " .. tostring(item.label))
	end
	if X.dsPanelLast ~= sel and X.dsPanelBody then X.dsPanelBody.CanvasPosition = Vector2.zero end
	X.dsPanelLast = sel
	return X.dsPropsFrame ~= nil and X.dsPropsFrame.Parent ~= nil
end

function X.dsClose()
	X.ds.sel = nil
	X.dsPanelOpen = false
	X.dsMark()
	X.dsPanelShow()
end

function X.dsSelect(sel, open)
	X.ds.sel = sel
	X.dsPanelOpen = (open and sel ~= nil) and true or false
	X.svDirty = true
	X.dsDraw()
	X.dsProps()
end

function X.dsDrag(el, item, key)
	local lim = X.DS_LIM[(key == "joy" and "joy") or (key == "jump" and "jump") or "btn"]
	local moved = false
	local function openIt()
		X.ds.sel = key
		X.dsLast = key
		X.dsPanelOpen = true
		X.dsMark()
		local okP, err = pcall(function()
			X.dsPanelShow()
			X.dsProps()
		end)
		if not okP then X.dsMsg("settings window error: " .. tostring(err)) end
	end
	X.dsOpenIt = X.dsOpenIt or {}
	el.InputBegan:Connect(function(input)
		if not K.isPress(input) then return end
		local pv = X.dsPv
		if not (pv and pv.Parent) then return end
		local p0, x0, y0 = input.Position, item.x, item.y
		moved = false
		X.ds.sel = key
		X.dsLast = key
		X.dsMark()
		local conn
		conn = UserInputService.InputChanged:Connect(function(i2)
			if not isMove(i2) then return end
			local d = i2.Position - p0
			if not moved and math.abs(d.X) + math.abs(d.Y) < 22 then return end
			moved = true
			local as = pv.AbsoluteSize
			item.x = math.clamp(x0 + d.X / math.max(as.X, 1), lim[1], lim[2])
			item.y = math.clamp(y0 + d.Y / math.max(as.Y, 1), lim[3], lim[4])
			el.Position = UDim2.new(item.x, 0, item.y, 0)
		end)
		input.Changed:Connect(function()
			if input.UserInputState ~= Enum.UserInputState.End then return end
			conn:Disconnect()
			if moved then
				X.svDirty = true
				if X.dsPanelOpen then openIt() end
			else
				openIt()
			end
		end)
	end)
	el.Activated:Connect(function()
		if not moved then openIt() end
	end)
end

function X.dsDraw()
	local pv = X.dsPv
	if not (pv and pv.Parent) then return end
	for _, c in ipairs(pv:GetChildren()) do
		if c:GetAttribute("dsBtn") then c:Destroy() end
	end
	local function circle(item, key, text, color, transp, z)
		local b = Instance.new("TextButton")
		b:SetAttribute("dsBtn", true)
		b:SetAttribute("dsKey", tostring(key))
		b:SetAttribute("NoCorner", true)
		b.AutoButtonColor = false
		b.AnchorPoint = Vector2.new(0.5, 0.5)
		b.Position = UDim2.new(item.x, 0, item.y, 0)
		b.Size = UDim2.new(item.size, 0, 0, 0)
		b.BackgroundColor3 = color
		b.BackgroundTransparency = transp
		b.BorderSizePixel = 0
		b.Text = text
		b.TextColor3 = Color3.new(1, 1, 1)
		b.Font = Enum.Font.GothamBold
		b.TextScaled = true
		b.ZIndex = z
		local ar = Instance.new("UIAspectRatioConstraint")
		ar.AspectRatio = 1
		ar.Parent = b
		local cr = Instance.new("UICorner")
		cr.CornerRadius = UDim.new(1, 0)
		cr.Parent = b
		local ts = Instance.new("UITextSizeConstraint")
		ts.MaxTextSize = 16
		ts.Parent = b
		local mn = Instance.new("UISizeConstraint")
		mn.MinSize = Vector2.new(key == "joy" and 54 or 34, key == "joy" and 54 or 34)
		mn.Parent = b
		local st = Instance.new("UIStroke")
		st.Name = "St"
		st.Color = Color3.new(1, 1, 1)
		st.Transparency = 0.6
		st.Thickness = 2
		st.Parent = b
		b.Parent = pv
		X.dsDrag(b, item, key)
		return b
	end
	local function round(o)
		local cr = Instance.new("UICorner")
		cr.CornerRadius = UDim.new(1, 0)
		cr.Parent = o
	end
	local jy = X.ds.joy
	if jy then
		local base = circle(jy, "joy", "", Color3.fromRGB(44, 50, 66), 0.35, 2)
		local thumb = Instance.new("Frame")
		thumb:SetAttribute("NoCorner", true)
		thumb.AnchorPoint = Vector2.new(0.5, 0.5)
		thumb.Position = UDim2.new(0.5, 0, 0.5, 0)
		thumb.Size = UDim2.new(0.42, 0, 0.42, 0)
		thumb.BackgroundColor3 = Color3.fromRGB(190, 196, 214)
		thumb.BorderSizePixel = 0
		round(thumb)
		thumb.Parent = base
	end
	local jp = X.ds.jump
	if jp then circle(jp, "jump", jp.label, Color3.fromRGB(70, 90, 130), 0.15, 3) end
	for i, b in ipairs(X.ds.buttons) do
		local el = circle(b, i, b.label, Color3.fromRGB(46, 160, 98), 0.15, 4)
		if b.anim == "" then
			local dot = Instance.new("Frame")
			dot.Name = "Badge"
			dot:SetAttribute("NoCorner", true)
			dot.AnchorPoint = Vector2.new(0.5, 0.5)
			dot.Position = UDim2.new(0.85, 0, 0.15, 0)
			dot.Size = UDim2.new(0.24, 0, 0.24, 0)
			dot.BackgroundColor3 = Color3.fromRGB(235, 70, 70)
			dot.BorderSizePixel = 0
			dot.ZIndex = 6
			round(dot)
			dot.Parent = el
		end
	end
	if X.dsHint then X.dsHint.Visible = (#X.ds.buttons == 0 and not X.ds.joy and not X.ds.jump) end
	X.dsMark()
end

function X.dsProps()
	if not X.dsPanelShow() then return end
	local props = X.dsPropsFrame
	if not (props and props.Parent) then return end
	for _, c in ipairs(props:GetChildren()) do
		if c:IsA("GuiObject") then c:Destroy() end
	end
	local b = X.ds.buttons[X.ds.sel or 0]
	local order = 0
	local function row(label)
		order += 1
		local r = Instance.new("Frame")
		r.Size = UDim2.new(1, 0, 0, 34)
		r.BackgroundColor3 = order % 2 == 0 and C.row1 or C.row2
		r.BorderSizePixel = 0
		r.LayoutOrder = order
		r.Parent = props
		local l = Instance.new("TextLabel")
		l.Position = UDim2.new(0, 8, 0, 0)
		l.Size = UDim2.new(0.42, -8, 1, 0)
		l.TextWrapped = true
		l.BackgroundTransparency = 1
		l.Text = label
		l.TextColor3 = C.text
		l.Font = Th.font
		l.TextSize = 13
		l.TextXAlignment = Enum.TextXAlignment.Left
		l.Parent = r
		return r
	end
	local function changed()
		X.svDirty = true
		X.dsDraw()
	end
	local function boxRow(label, get, set, numeric, placeholder)
		local r = row(label)
		local tb = X.mkBox(r, 10, tostring(get()), placeholder)
		tb.Position = UDim2.new(0.42, 0, 0.5, -14)
		tb.Size = UDim2.new(0.58, -8, 0, 28)
		tb.FocusLost:Connect(function()
			if numeric then
				local v = tonumber(tb.Text)
				if v then set(v) end
				tb.Text = tostring(get())
			else
				set(tb.Text)
			end
			changed()
		end)
	end
	local function btnRow(label, text, color, fn)
		local r = row(label)
		local bt = K.newButton(r, text, color)
		bt.Position = UDim2.new(0.42, 0, 0.5, -14)
		bt.Size = UDim2.new(0.58, -8, 0, 28)
		bt.TextSize = 13
		bt.TextTruncate = Enum.TextTruncate.AtEnd
		bt.MouseButton1Click:Connect(function()
			fn()
			changed()
			X.dsProps()
		end)
	end
	local function posRows(item, lim)
		boxRow("Left / right (0-1)", function() return math.floor(item.x * 1000 + 0.5) / 1000 end, function(v) item.x = math.clamp(v, lim[1], lim[2]) end, true)
		boxRow("Up / down (0-1)", function() return math.floor(item.y * 1000 + 0.5) / 1000 end, function(v) item.y = math.clamp(v, lim[3], lim[4]) end, true)
	end
	if X.ds.sel == "jump" and X.ds.jump then
		local j = X.ds.jump
		boxRow("Label", function() return j.label end, function(v) j.label = tostring(v):sub(1, 8) end, false)
		posRows(j, X.DS_LIM.jump)
		boxRow("Size (0.03-0.2)", function() return j.size end, function(v) j.size = math.clamp(v, 0.03, 0.2) end, true)
		boxRow("Jump height (studs)", function() return j.height end, function(v) j.height = math.clamp(v, 1, 100) end, true)
		boxRow("Extra jumps in air (0-3)", function() return j.extra end, function(v) j.extra = math.floor(math.clamp(v, 0, 3)) end, true)
		btnRow("Jump animation", j.anim ~= "" and (((j.animName ~= "" and j.animName) or j.anim):sub(1, 22) .. "  (change)") or "Pick animation...", j.anim ~= "" and C.green or C.sel, function()
			X.dsPick(function(id, name)
				j.anim, j.animName = id, tostring(name or "")
				if X.dsNeedsFrames(id) and j.type == "id" then j.type = "frames" end
				X.dsGenJump(j)
				changed()
				X.dsProps()
			end, true)
		end)
		btnRow("Anim type", X.DS_TYPES[X.dsTypeIndex(j.type)].name, j.type ~= "id" and C.sel or C.btn, function()
			j.type = X.DS_TYPES[X.dsTypeIndex(j.type) % #X.DS_TYPES + 1].key
			X.dsGenJump(j)
		end)
		if j.type ~= "id" then
			btnRow("Script (tap = rebuild)", j.codeInfo ~= "" and j.codeInfo or "not generated", j.code ~= "" and C.green or C.btn, function()
				X.dsGenJump(j)
			end)
		end
		btnRow("Fall animation", j.fall ~= "" and (((j.fallName ~= "" and j.fallName) or j.fall):sub(1, 22) .. "  (change)") or "Pick animation...", j.fall ~= "" and C.green or C.sel, function()
			X.dsPick(function(id, name)
				j.fall, j.fallName = id, tostring(name or "")
				if X.dsNeedsFrames(id) and j.type == "id" then j.type = "frames" end
				X.dsGenJump(j)
				changed()
				X.dsProps()
			end, true)
		end)
		btnRow("Jump button", "Remove jump button", C.danger, function()
			X.ds.jump = nil
			X.ds.sel = nil
		end)
		return
	end
	if X.ds.sel == "joy" and X.ds.joy then
		local j = X.ds.joy
		posRows(j, X.DS_LIM.joy)
		boxRow("Size (0.08-0.35)", function() return j.size end, function(v) j.size = math.clamp(v, 0.08, 0.35) end, true)
		boxRow("Dead zone (0-0.5)", function() return j.deadzone end, function(v) j.deadzone = math.clamp(v, 0, 0.5) end, true)
		boxRow("Run starts at (0.1-0.95)", function() return j.runAt end, function(v) j.runAt = math.clamp(v, 0.1, 0.95) end, true)
		boxRow("Sprint starts at (0.2-1)", function() return j.sprintAt end, function(v) j.sprintAt = math.clamp(v, 0.2, 1) end, true)
		boxRow("Walk speed", function() return j.walkSpeed end, function(v) j.walkSpeed = math.clamp(v, 0, 200) end, true)
		boxRow("Run speed", function() return j.runSpeed end, function(v) j.runSpeed = math.clamp(v, 0, 200) end, true)
		boxRow("Sprint speed", function() return j.sprintSpeed end, function(v) j.sprintSpeed = math.clamp(v, 0, 200) end, true)
		boxRow("Animation speed", function() return j.animSpeed end, function(v) j.animSpeed = math.clamp(v, 0.1, 5) end, true)
		btnRow("Strafe mode", j.strafe and "On: face camera, side/back anims" or "Off: turn toward movement", j.strafe and C.sel or C.btn, function() j.strafe = not j.strafe end)
		btnRow("Anim type (all anims)", X.DS_TYPES[X.dsTypeIndex(j.type)].name, j.type ~= "id" and C.sel or C.btn, function()
			j.type = X.DS_TYPES[X.dsTypeIndex(j.type) % #X.DS_TYPES + 1].key
			X.dsGenJoy(j)
		end)
		if j.type ~= "id" then
			btnRow("Scripts (tap = rebuild)", j.codeInfo ~= "" and j.codeInfo or "not generated", (j.codeInfo:sub(1, 5) == "ready") and C.green or C.btn, function()
				X.dsGenJoy(j)
			end)
		end
		for _, slot in ipairs({ { "idle", "Idle" }, { "walk", "Walk" }, { "run", "Run" }, { "sprint", "Sprint" }, { "back", "Backward" }, { "left", "Strafe left" }, { "right", "Strafe right" } }) do
			local key = slot[1]
			local has = j.a[key] ~= ""
			btnRow(slot[2] .. " anim", has and (((j.an[key] ~= "" and j.an[key]) or j.a[key]):sub(1, 22) .. "  (change)") or "Pick animation...", has and C.green or C.sel, function()
				X.dsPick(function(id, name)
					j.a[key], j.an[key] = id, tostring(name or "")
					if X.dsNeedsFrames(id) and j.type == "id" then j.type = "frames" end
					if j.type ~= "id" then X.dsGenJoy(j) end
					changed()
					X.dsProps()
				end, true)
			end)
		end
		btnRow("Joystick", "Remove joystick", C.danger, function()
			X.ds.joy = nil
			X.ds.sel = nil
		end)
		return
	end
	if not b then
		order += 1
		local l = Instance.new("TextLabel")
		l.Size = UDim2.new(1, 0, 0, 40)
		l.BackgroundTransparency = 1
		l.TextWrapped = true
		l.Text = "Tap a button, the joystick or the jump button on the screen above to edit it, or press + Button / + Joystick / + Jump."
		l.TextColor3 = C.sub
		l.Font = Th.font
		l.TextSize = 14
		l.LayoutOrder = order
		l.Parent = props
		return
	end
	boxRow("Label", function() return b.label end, function(v) b.label = tostring(v):sub(1, 12) end, false)
	posRows(b, X.DS_LIM.btn)
	btnRow("Animation", b.anim ~= "" and ((b.animName ~= "" and b.animName or b.anim):sub(1, 24) .. "  (change)") or "Pick animation...", b.anim ~= "" and C.green or C.sel, function()
		X.dsPick(function(id, name)
			b.anim, b.animName = id, tostring(name or "")
			if X.dsNeedsFrames(id) and b.type == "id" then b.type = "frames" end
			if b.label:match("^B%d+$") then b.label = tostring(name or "B"):sub(1, 5) end
			X.dsGenCode(b)
			changed()
			X.dsProps()
		end)
	end)
	boxRow("Or paste AnimationId", function() return "" end, function(v)
		local d = tostring(v):match("(%d%d%d+)")
		if d then
			b.anim, b.animName = "rbxassetid://" .. d, ""
			X.dsGenCode(b)
			X.dsProps()
		end
	end, false, "rbxassetid://...")
	btnRow("Anim type", X.DS_TYPES[X.dsTypeIndex(b.type)].name, b.type ~= "id" and C.sel or C.btn, function()
		b.type = X.DS_TYPES[X.dsTypeIndex(b.type) % #X.DS_TYPES + 1].key
		X.dsGenCode(b)
	end)
	if b.type ~= "id" then
		btnRow("Script (tap = rebuild)", b.codeInfo ~= "" and b.codeInfo or "not generated", b.code ~= "" and C.green or C.btn, function()
