		boxRow("Hit delay (s)", function() return b.delay end, function(v) b.delay = math.clamp(v, 0, 10) end, true)
		btnRow("Only NPCs", b.npcOnly and "On (skip players)" or "Off (players too)", b.npcOnly and C.sel or C.btn, function() b.npcOnly = not b.npcOnly end)
		boxRow("Damage remote (optional)", function() return b.remote end, function(v) b.remote = tostring(v):sub(1, 120) end, false, "ReplicatedStorage.Events.Hit")
	end
	btnRow("This button", "Delete button", C.danger, function()
		table.remove(X.ds.buttons, X.ds.sel)
