function X.dsBuild()
	local page = X.dsPage
	for _, c in ipairs(page:GetChildren()) do
		if c:GetAttribute("dsRoot") then c:Destroy() end
	end
	if page == X.dsTabPage then return X.dsLauncher(page) end
	local function root()
		local sf = newList(page, UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 1, 0))
		sf:SetAttribute("dsRoot", true)
		return sf
	end
	local sf = root()
	X.dsList = sf
	local order = 0
	local function text(str, h, color)
		order += 1
		local l = Instance.new("TextLabel")
		l.Size = UDim2.new(1, -6, 0, h)
		l.BackgroundTransparency = 1
		l.TextWrapped = true
		l.Text = str
		l.TextColor3 = color or C.sub
		l.Font = Th.font
		l.TextSize = 14
		l.TextXAlignment = Enum.TextXAlignment.Left
		l.TextYAlignment = Enum.TextYAlignment.Top
		l.LayoutOrder = order
		l.Parent = sf
		return l
	end

	if X.REQUIRE_KEY and not X.access.ok then
		text("Design Script is for approved users only. The finished script is built on the owner's server, so it only works with a valid key.", 56, C.text)
		local status = text(X.access.msg ~= "" and X.access.msg or "Paste your key and press Unlock.", 44, X.access.msg ~= "" and C.danger or C.sub)
		order += 1
		local keyBox = X.mkBox(sf, 10, "", "paste your key here")
		keyBox.Size = UDim2.new(1, -6, 0, 32)
		keyBox.LayoutOrder = order
		order += 1
		local go = K.newButton(sf, "Unlock", C.green)
		go.Size = UDim2.new(1, -6, 0, 34)
		go.LayoutOrder = order
		go.MouseButton1Click:Connect(function()
			local key = keyBox.Text:gsub("%s", "")
			if #key < 20 then
				status.Text = "That does not look like a key."
				return
			end
			status.Text = "Checking..."
			X.accessVerify(key, function()
				X.dsBuild()
			end)
		end)
		return
	end

	sf:Destroy()
	X.dsList = nil
	local function tag(o)
		o:SetAttribute("dsRoot", true)
		return o
	end
	if X.ds.sel ~= nil and not X.dsItem(X.ds.sel) then X.ds.sel = nil end

	local bar = tag(X.mkBar(page, 4, 30))
	X.mkTool(bar, "+ Button", 76, C.green, function() X.dsNew() X.svDirty = true end)
	X.mkTool(bar, "+ Jump", 70, C.green, function()
		X.ds.jump = X.ds.jump or X.jumpNew()
		X.dsSelect("jump")
	end)
	X.mkTool(bar, "+ Joystick", 92, C.green, function()
		X.ds.joy = X.ds.joy or X.joyNew()
		X.dsSelect("joy")
	end)
	X.mkTool(bar, "Edit", 52, C.sel, function()
		local sel = X.ds.sel
		if sel == nil or not X.dsItem(sel) then sel = X.dsLast end
		if sel == nil or not X.dsItem(sel) then
			local only = nil
			if #X.ds.buttons == 1 and not X.ds.joy and not X.ds.jump then only = 1
			elseif #X.ds.buttons == 0 and X.ds.joy and not X.ds.jump then only = "joy"
			elseif #X.ds.buttons == 0 and X.ds.jump and not X.ds.joy then only = "jump" end
			sel = only
		end
		if sel == nil or not X.dsItem(sel) then
			return X.dsMsg("tap a button on the screen first, then press Edit")
		end
		X.ds.sel = sel
		X.dsPanelOpen = true
		X.dsMark()
		local okP, err = pcall(function()
			X.dsPanelShow()
			X.dsProps()
		end)
		if not okP then X.dsMsg("settings window error: " .. tostring(err)) end
	end)
	X.mkTool(bar, "Copy script", 92, C.sel, function(b)
		X.dsGenerate(function(code)
			toClip(code, "the Design Script")
			K.flash(b, "Copied")
		end)
	end)
	X.mkTool(bar, "View code", 84, C.btn, function()
		X.dsGenerate(function(code)
			openViewer("Design Script", { { name = "Script", get = function(cb2) cb2(code) end } }, 1)
		end)
	end)
	X.mkTool(bar, "Download", 84, C.green, function(b)
		X.dsGenerate(function(code)
			X.saveScriptFile(code, "DesignScript", b)
		end)
	end)
	X.mkTool(bar, "Edit code", 80, C.btn, function()
		X.dsGenerate(function(code)
			X.codeEdit("Design Script - edit / run", code, function(text) toClip(text, "your edited Design Script") end)
		end)
	end)
	X.mkTool(bar, "Run now", 74, C.btn, function(b)
		X.dsGenerate(function(code)
			local loader = loadstring or load
			local fn, err = loader and loader(code)
			if fn then
				pcall(fn)
				K.flash(b, "Running")
			else
				out("Design Script: " .. tostring(err or "no loadstring"))
			end
		end)
	end)
	X.mkTool(bar, "Clear all", 76, C.danger, function()
		X.confirm("Clear the design?", "Removes all buttons from the screen.", function()
			X.ds.buttons, X.ds.joy, X.ds.jump = {}, nil, nil
			X.svDirty = true
			X.dsClose()
			X.dsDraw()
		end)
	end)
	if X.REQUIRE_KEY then
		X.mkTool(bar, "Change key", 88, C.btn, function()
			X.access.ok, X.access.key = false, ""
			if writefile then pcall(writefile, X.KEY_FILE, "") end
			X.dsBuild()
		end)
	end

	local stage = tag(Instance.new("Frame"))
	stage.Name = "DesignStage"
	stage:SetAttribute("NoCorner", true)
	stage.Position = UDim2.new(0, 6, 0, 38)
	stage.Size = UDim2.new(1, -12, 1, -44)
	stage.BackgroundColor3 = Color3.fromRGB(8, 10, 14)
	stage.BorderSizePixel = 0
	stage.ClipsDescendants = true
	stage.Parent = page

	local screen = Instance.new("Frame")
	screen.Name = "Screen"
	screen:SetAttribute("NoCorner", true)
	screen.AnchorPoint = Vector2.new(0.5, 0.5)
	screen.Position = UDim2.new(0.5, 0, 0.5, 0)
	screen.Size = UDim2.new(1, 0, 1, 0)
	screen.BackgroundColor3 = Color3.fromRGB(26, 32, 46)
	screen.BorderSizePixel = 0
	screen.ClipsDescendants = true
	screen.Parent = stage
	local asp = Instance.new("UIAspectRatioConstraint")
	local cam = workspace.CurrentCamera
	local vs = cam and cam.ViewportSize or Vector2.new(16, 9)
	asp.AspectRatio = math.clamp(vs.X / math.max(vs.Y, 1), 1.2, 2.4)
	asp.Parent = screen
	local grad = Instance.new("UIGradient")
	grad.Color = ColorSequence.new(Color3.fromRGB(34, 44, 66), Color3.fromRGB(14, 18, 26))
	grad.Rotation = 90
	grad.Parent = screen

	local bg = Instance.new("TextButton")
	bg:SetAttribute("NoCorner", true)
	bg.Size = UDim2.new(1, 0, 1, 0)
	bg.BackgroundTransparency = 1
	bg.AutoButtonColor = false
	bg.Text = ""
	bg.ZIndex = 1
	bg.Parent = screen
	bg.MouseButton1Click:Connect(X.dsClose)
	for _, f in ipairs({ 1 / 3, 2 / 3 }) do
		local v = Instance.new("Frame")
		v:SetAttribute("NoCorner", true)
		v.Position = UDim2.new(f, 0, 0, 0)
		v.Size = UDim2.new(0, 1, 1, 0)
		v.BackgroundColor3 = Color3.new(1, 1, 1)
		v.BackgroundTransparency = 0.94
		v.BorderSizePixel = 0
		v.ZIndex = 1
		v.Parent = screen
		local h = Instance.new("Frame")
		h:SetAttribute("NoCorner", true)
		h.Position = UDim2.new(0, 0, f, 0)
		h.Size = UDim2.new(1, 0, 0, 1)
		h.BackgroundColor3 = Color3.new(1, 1, 1)
		h.BackgroundTransparency = 0.94
		h.BorderSizePixel = 0
		h.ZIndex = 1
		h.Parent = screen
	end
	local hint = Instance.new("TextLabel")
	hint:SetAttribute("NoCorner", true)
	hint.Size = UDim2.new(1, 0, 1, 0)
	hint.BackgroundTransparency = 1
	hint.Text = "your screen\nPress + Button, + Jump or + Joystick.\nThe real button shows up here: drag it, tap it to edit it."
	hint.TextColor3 = Color3.fromRGB(96, 108, 132)
	hint.Font = Th.bold
	hint.TextSize = 16
	hint.TextWrapped = true
	hint.ZIndex = 1
	hint.Parent = screen
	X.dsHint = hint
	X.dsPv = screen

	X.dsPanelLast = nil
	X.dsDraw()
	X.dsProps()
end

function X.timed(name, fn, ...)
	if X.off[name] then return end
	local t0 = os.clock()
	local ok, err = pcall(fn, ...)
	local dt = os.clock() - t0
	local c = X.cost[name]
	if not c then
		c = { ms = 0, n = 0, rate = 0, rms = 0, hot = 0 }
		X.cost[name] = c
	end
	if dt < 0.1 then c.ms += dt * 1000 end
	c.n += 1
	if not ok and os.clock() - (X.errT or 0) > 5 then
		X.errT = os.clock()
		warn("[Logger] " .. name .. " error: " .. tostring(err))
	end
end

function X.guardBanner()
	local names = {}
	for _, k in ipairs(X.GUARD_ORDER) do
		if X.off[k] and X.offWhy[k] ~= "turned off by you" then names[#names + 1] = X.GUARD[k] end
	end
	if #names == 0 then
		if X.banner then X.banner.Visible = false end
		return
	end
	if not X.banner then
		local b = Instance.new("TextButton")
		b.AnchorPoint = Vector2.new(0.5, 0)
		b.Position = UDim2.new(0.5, 0, 0, 52)
		b.Size = UDim2.new(0, 340, 0, 56)
		b.BackgroundColor3 = C.danger
		b.BorderSizePixel = 0
		b.TextColor3 = Color3.fromRGB(255, 255, 255)
		b.Font = Th.font
		b.TextSize = 14
		b.TextWrapped = true
		b.ZIndex = 100
		b.Parent = gui
		local bs = Instance.new("UIScale")
		bs.Name = "AVLScale"
		bs.Scale = X.guiScale()
		bs.Parent = b
		b.MouseButton1Click:Connect(function()
			local keys = {}
			for k in pairs(X.off) do keys[#keys + 1] = k end
			for _, k in ipairs(keys) do X.guardBack(k) end
		end)
		X.banner = b
	end
	X.banner.Visible = true
	X.banner.Text = "Auto-protect turned OFF: " .. table.concat(names, ", ") .. " (it was causing lag). Tap here to turn back on, or Settings > Auto-protect."
end

function X.guardTrip(name, why)
	X.off[name] = true
	X.offWhy[name] = why
	local msg = string.format(
		"Auto-protect: %s turned OFF - %s. To turn it back on: tap the red bar at the top, or Settings > Auto-protect > %s.",
		X.GUARD[name], why, X.GUARD[name]
	)
	out(msg)
	warn("[Logger] " .. msg)
	X.guardBanner()
	K.syncUI()
end

function X.guardBack(name)
	X.off[name] = nil
	X.offWhy[name] = nil
	X.cost[name] = nil
	X.guardBanner()
	K.syncUI()
end

function X.guardStep(dt)
	local g = X.g
	g.frames += 1
	g.time += dt
	g.worst = math.max(g.worst, dt)
	if g.time < 1 then return end
	local fps, avgDt = g.frames / g.time, g.time / g.frames
	local top, topMs = nil, 0
	for name, c in pairs(X.cost) do
		c.rms, c.rate = c.ms / g.time, c.n / g.time
		if c.rms > topMs and not X.off[name] then top, topMs = name, c.rms end
		c.ms, c.n = 0, 0
	end
	local lagging = avgDt > 0.045 or g.worst > 0.3
	g.frames, g.time, g.worst = 0, 0, 0
	if not X.guardOn or os.clock() - X.t0 < 6 then return end
	for name, c in pairs(X.cost) do
		if not X.off[name] and c.rate > 80 then
			c.hot += 1
			if c.hot >= 2 then
				return X.guardTrip(name, string.format("it was handling %d events per second (spam)", c.rate))
			end
		else
			c.hot = 0
		end
	end
	if lagging and top and topMs > 50 then
		X.guardTrip(top, string.format("it used %d ms of every second while the game ran at %d FPS", topMs, fps))
	end
end

X.svLoad()
X.svReady = true
X.svRender()
task.spawn(function()
	while gui.Parent and Run.alive do
		task.wait(1.5)
		if X.svDirty then
			X.svDirty = false
			X.svWrite()
		end
		if X.keptDirty then
			X.keptDirty = false
			pcall(X.keptWrite)
		end
		X.keepTick = (X.keepTick or 0) + 1
		if X.keepTick % 4 == 0 then pcall(X.keepNext) end
	end
end)
X.dsBuild()
task.spawn(function()
	if isfile and readfile and X.KEY_FILE then
		local okF, key = pcall(function() return isfile(X.KEY_FILE) and readfile(X.KEY_FILE) or "" end)
		key = okF and tostring(key):gsub("%s", "") or ""
		if #key >= 20 then X.accessVerify(key, function() X.dsBuild() end) end
	end
end)
table.insert(Run.conns, RunService.Heartbeat:Connect(function(dt)
	if Run.alive then X.guardStep(dt) end
end))

local lastSavedJson
saveSettings = function()
	if not writefile then return end
	local function labelsFor(set, labels)
		local t = {}
		for id in pairs(set) do t[id] = labels[id] or "" end
		return t
	end
	local ok, json = pcall(function()
		return HttpService:JSONEncode({
			version = 3, theme = Th.cur.name, filter = X.filter, compact = X.compact, deepHook = X.deep,
			thorough = X.thorough, guessFX = X.guess, objOn = X.objOn, gui2d = X.gui2d, guardOn = X.guardOn, fxPre = X.pre,
			quality = QUALITY, ownOnly = ownOnly, uniqueOnly = uniqueOnly, detailedMode = detailedMode,
			tab = lastLogTab,
			excluded = labelsFor(excluded, animLabel),
			blocked = labelsFor(blocked, animLabel),
			logVariants = X.variants, strictFX = X.strict, fxAll = X.fxAll, guiSize = X.guiSize, logCutscenes = X.cutscenes, logMovement = X.logMove,
			autoCombine = X.combo and X.combo.on, comboGap = X.combo and X.combo.gap,
			blockedVFX = labelsFor(X.blockV, vfxLabel),
			blockedSFX = labelsFor(X.blockS, sfxLabel),
			excludedVFX = labelsFor(excludedVFX, vfxLabel),
			excludedSFX = labelsFor(excludedSFX, sfxLabel),
			window = mainWin.getState(),
		})
	end)
	if ok and json ~= lastSavedJson then
		if pcall(writefile, SETTINGS_FILE, json) then lastSavedJson = json end
	end
end

task.spawn(function()
	while gui.Parent do
		task.wait(2)
		saveSettings()
	end
end)

Run.cleanup = function()
	Run.alive = false
		pcall(X.pvClose)
	pcall(function() if X.vfxEd and X.vfxEd.stage then X.vfxEd.stage:Destroy() end end)
	pcall(X.edClose)
	pcall(X.aeClose)
	pcall(X.v3Close)
	pcall(function() if X.dsWin then X.dsWin.destroy() end end)
	pcall(X.tpFxClear)
	if X.auto then X.auto.stop = true end
	pcall(function() if X.loadGui then X.loadGui:Destroy() end end)
	pcall(function() if X.dialog then X.dialog:Destroy() end end)
	pcall(saveSettings)
	for _, c in ipairs(Run.conns) do pcall(function() c:Disconnect() end) end
	pcall(function() gui:Destroy() end)
end

local worldList, soundList = workspace:GetDescendants(), SoundService:GetDescendants()

table.insert(Run.conns, workspace.DescendantAdded:Connect(function(d)
	if not Run.alive then return end
	if d:IsA("Animator") then
		if not d:GetAttribute("_LoggerClone") then watchAnimator(d) end
	elseif d:IsA("Sound") then
		X.timed("sfx", hookSound, d, true)
	elseif VFX_CLASSES[d.ClassName] then
		task.defer(X.timed, "vfx", watchVFX, d)
	elseif X.objOn and (d:IsA("Model") or d:IsA("Tool") or d:IsA("Accoutrement") or d:IsA("BasePart")) then
		task.defer(X.timed, "obj", X.watchObj, d)
	elseif X.objOn and X.gui2d ~= false and (d:IsA("BillboardGui") or d:IsA("SurfaceGui")) then
		task.delay(0.25, function()
			if not Run.alive or not d.Parent or d:GetAttribute("_Replay") or d:GetAttribute("_LoggerClone") then return end
			if X.guiCache then X.guiCache[d] = nil end
			pcall(recordFX, "gui", d, nil, os.clock())
		end)
	end
end))
table.insert(Run.conns, RunService.Heartbeat:Connect(function()
	if Run.alive and X.objOn then X.timed("cam", X.camStep) end
end))
table.insert(Run.conns, SoundService.DescendantAdded:Connect(function(d)
	if Run.alive and d:IsA("Sound") then X.timed("sfx", hookSound, d, true) end
end))

-- screen effects (bloom, blur, color correction, atmosphere...) live in Lighting, not workspace
do
