	))
end

do
	local EX = {}
	X.ex = EX
	local ROW = 22
	EX.expanded, EX.rows, EX.pool = {}, {}, {}
	EX.cnt = { anim = {}, sfx = {}, vfx = {} }
	EX.all, EX.anims, EX.byId, EX.nilExtra, EX.logNodes = {}, {}, {}, {}, {}
	EX.kind, EX.results, EX.gen, EX.sel = "all", nil, 0, nil
	EX.nilRoot = { name = "Nil Instances", class = "Folder", virt = "nil" }
	EX.logRoot = { name = "Logged animations", class = "Folder", virt = "log" }
	local V = {}

	local KEYWORDS = {}
	for w in ("and break do else elseif end false for function if in local nil not or repeat return then true until while continue"):gmatch("%a+") do KEYWORDS[w] = true end
	local FXK = { ParticleEmitter = true, Beam = true, Trail = true, Fire = true, Smoke = true, Sparkles = true, Explosion = true }
	local ORDER = {}
	for i, n in ipairs({ "Workspace", "Players", "Lighting", "ReplicatedFirst", "ReplicatedStorage", "StarterGui", "StarterPack", "StarterPlayer", "SoundService", "Teams", "Chat", "TextChatService" }) do ORDER[n] = i end
	local KIND_COL = { anim = "#7db9ff", sfx = "#8be08b", vfx = "#ffaa5a" }
	local KIND_NAME = { all = "Show: All", anim = "Show: Anims", sfx = "Show: Sounds", vfx = "Show: VFX" }
	local KIND_NEXT = { all = "anim", anim = "sfx", sfx = "vfx", vfx = "all" }

	local function isInst(n) return typeof(n) == "Instance" end
	local function nName(n) if isInst(n) then return n.Name end return n.name or "?" end
	local function nClass(n) if isInst(n) then return n.ClassName end return n.class or "Folder" end
	local function kindOf(cn)
		if cn == "Animation" then return "anim" end
		if cn == "Sound" then return "sfx" end
		if FXK[cn] then return "vfx" end
		return nil
	end
	local function normId(v)
		if type(v) ~= "string" then v = tostring(v) end
		return v:match("%d+") or v
	end

	local function iconKey(n)
		if not isInst(n) then
			if n.virt == "nil" then return "nil" end
			return "anim"
		end
		local cn = n.ClassName
		if cn == "Animation" or cn == "AnimationController" or cn == "Animator" or cn == "KeyframeSequence" or cn == "AnimationTrack" then return "anim" end
		if cn == "Sound" or cn == "SoundGroup" then return "sound" end
		if FXK[cn] then return "fx" end
		if cn:find("Light") or cn == "Highlight" then return "light" end
		if cn == "Folder" or cn == "Configuration" then return "folder" end
		if cn == "Model" or cn == "Actor" then return "model" end
		if cn == "Tool" or cn == "Accessory" or cn == "Accoutrement" or cn == "Hat" then return "tool" end
		if cn == "ModuleScript" then return "module" end
		if cn:find("Script") then return "script" end
		if cn:find("Remote") or cn:find("Bindable") then return "remote" end
		if cn == "ImageLabel" or cn == "ImageButton" or cn == "Decal" or cn == "Texture" or cn == "SurfaceAppearance" then return "image" end
		if cn == "TextLabel" or cn == "TextButton" or cn == "TextBox" then return "text" end
		if cn:find("Gui") or cn:find("Frame") or cn:find("UI") then return "gui" end
		if cn == "Humanoid" or cn == "Player" or cn == "HumanoidDescription" then return "humanoid" end
		if cn:find("Value") then return "value" end
		if cn == "Motor6D" or cn:find("Weld") or cn == "Attachment" or cn:find("Constraint") then return "joint" end
		if cn == "Camera" then return "camera" end
		if cn:find("Part") or cn:find("Union") or cn:find("Mesh") or cn:find("Seat") or cn:find("Spawn") or cn == "Terrain" then return "part" end
		if n.Parent == game then return "service" end
		return "other:" .. cn:sub(1, 1)
	end

	local function box(parent, x, y, w, h, col, round)
		local f = Instance.new("Frame")
		f:SetAttribute("NoCorner", true)
		f.BorderSizePixel = 0
		f.Position = UDim2.fromOffset(x, y)
		f.Size = UDim2.fromOffset(w, h)
		f.BackgroundColor3 = col
		if round then
			local c = Instance.new("UICorner")
			c.CornerRadius = UDim.new(0, round)
			c.Parent = f
		end
		f.Parent = parent
		return f
	end
	local function glyph(parent, text, col, size)
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1
		t.Size = UDim2.fromOffset(16, 16)
		t.Font = Enum.Font.SourceSansBold
		t.TextSize = size or 13
		t.TextColor3 = col or Color3.new(1, 1, 1)
		t.Text = text
		t.Parent = parent
	end

	function EX.drawIcon(h, key)
		for _, c in ipairs(h:GetChildren()) do
			if c:IsA("GuiObject") then c:Destroy() end
		end
		local W = Color3.new(1, 1, 1)
		if key == "folder" then
			box(h, 0, 2, 7, 4, Color3.fromRGB(222, 181, 84), 1)
			box(h, 0, 4, 16, 10, Color3.fromRGB(222, 181, 84), 1)
			box(h, 0, 6, 16, 2, Color3.fromRGB(242, 208, 125))
		elseif key == "model" then
			box(h, 1, 1, 10, 10, Color3.fromRGB(100, 122, 172), 1)
			box(h, 5, 5, 10, 10, Color3.fromRGB(140, 166, 216), 1)
			box(h, 5, 5, 10, 2, Color3.fromRGB(180, 200, 240))
		elseif key == "part" then
			box(h, 1, 3, 14, 10, Color3.fromRGB(150, 150, 156), 1)
			box(h, 1, 3, 14, 3, Color3.fromRGB(205, 205, 212), 1)
		elseif key == "tool" then
			box(h, 7, 2, 3, 13, Color3.fromRGB(150, 100, 60), 1)
			box(h, 3, 1, 11, 5, Color3.fromRGB(200, 200, 208), 1)
		elseif key == "script" or key == "module" then
			local col = key == "script" and Color3.fromRGB(70, 175, 105) or Color3.fromRGB(150, 110, 205)
			box(h, 2, 1, 12, 14, col, 2)
			box(h, 4, 4, 8, 1, W)
			box(h, 4, 7, 8, 1, W)
			box(h, 4, 10, 5, 1, W)
		elseif key == "sound" then
			box(h, 1, 5, 3, 6, Color3.fromRGB(110, 205, 120), 1)
			box(h, 5, 3, 3, 10, Color3.fromRGB(110, 205, 120), 1)
			box(h, 9, 1, 3, 14, Color3.fromRGB(110, 205, 120), 1)
			box(h, 13, 4, 2, 8, Color3.fromRGB(110, 205, 120), 1)
		elseif key == "anim" then
			box(h, 0, 0, 16, 16, Color3.fromRGB(80, 155, 255), 8)
			glyph(h, ">", W, 14)
		elseif key == "fx" then
			box(h, 0, 0, 16, 16, Color3.fromRGB(255, 150, 60), 8)
			box(h, 3, 3, 3, 3, W, 2)
			box(h, 9, 6, 4, 4, W, 2)
			box(h, 5, 10, 2, 2, W, 1)
		elseif key == "light" then
			box(h, 2, 0, 12, 12, Color3.fromRGB(255, 220, 90), 6)
			box(h, 5, 12, 6, 3, Color3.fromRGB(170, 170, 175), 1)
		elseif key == "gui" then
			box(h, 1, 2, 14, 12, Color3.fromRGB(100, 150, 235), 2)
			box(h, 1, 2, 14, 3, Color3.fromRGB(60, 100, 190), 1)
		elseif key == "image" then
			box(h, 1, 2, 14, 12, Color3.fromRGB(232, 232, 232), 2)
			box(h, 3, 4, 10, 8, Color3.fromRGB(110, 170, 230))
			box(h, 3, 9, 10, 3, Color3.fromRGB(90, 170, 100))
		elseif key == "text" then
			box(h, 1, 2, 14, 12, Color3.fromRGB(100, 150, 235), 2)
			glyph(h, "T", W, 12)
		elseif key == "remote" then
			box(h, 0, 0, 16, 16, Color3.fromRGB(235, 195, 80), 3)
			glyph(h, "<>", Color3.fromRGB(60, 45, 10), 12)
		elseif key == "value" then
			box(h, 1, 1, 14, 14, Color3.fromRGB(80, 190, 175), 3)
			glyph(h, "=", W, 14)
		elseif key == "humanoid" then
			box(h, 5, 0, 6, 6, Color3.fromRGB(140, 220, 200), 3)
			box(h, 3, 7, 10, 8, Color3.fromRGB(140, 220, 200), 3)
		elseif key == "joint" then
			box(h, 1, 5, 6, 6, Color3.fromRGB(210, 140, 200), 1)
			box(h, 9, 5, 6, 6, Color3.fromRGB(210, 140, 200), 1)
			box(h, 6, 7, 4, 2, Color3.fromRGB(240, 190, 235))
		elseif key == "camera" then
			box(h, 1, 4, 10, 9, Color3.fromRGB(95, 95, 102), 2)
			box(h, 11, 6, 4, 5, Color3.fromRGB(150, 150, 158), 1)
		elseif key == "service" then
			box(h, 0, 0, 16, 16, Color3.fromRGB(150, 170, 205), 8)
			box(h, 5, 5, 6, 6, Color3.fromRGB(55, 65, 90), 3)
		elseif key == "nil" then
			box(h, 1, 1, 14, 14, Color3.fromRGB(85, 85, 92), 7)
			glyph(h, "?", W, 13)
		else
			box(h, 1, 1, 14, 14, Color3.fromRGB(140, 140, 146), 3)
			glyph(h, (key:match("^other:(.*)$") or "?"):upper(), W, 11)
		end
	end

	function EX.path(inst)
		local chain, p, g = {}, inst, 0
		while p and g < 100 do table.insert(chain, 1, p); p = p.Parent; g += 1 end
		if chain[1] ~= game then
			return string.format(
				"local obj\nfor _, i in ipairs(getnilinstances()) do\n\tif i.Name == %q and i.ClassName == %q then obj = i break end\nend\n-- (this one has no parent in the game)",
				inst.Name, inst.ClassName
			)
		end
		local s = "game"
		for i = 2, #chain do
			local c = chain[i]
			if i == 2 then
				if c == workspace then s = "workspace" else s = string.format("game:GetService(%q)", c.ClassName) end
			elseif c == lp then
				s = s .. ".LocalPlayer"
			elseif c.Name:match("^[%a_][%w_]*$") and not KEYWORDS[c.Name] then
				s = s .. "." .. c.Name
			else
				s = s .. string.format("[%q]", c.Name)
			end
		end
		return s
	end

	function EX.nilList()
		if not EX.nilCache then
			local list = {}
			if getnilinstances then
				local ok, l = pcall(getnilinstances)
				if ok and type(l) == "table" then
					for _, i in ipairs(l) do
						local okP, par = pcall(function() return i.Parent end)
						if okP and par == nil then list[#list + 1] = i end
					end
				end
			end
			EX.nilCache = list
		end
		local res, seen = {}, {}
		for _, i in ipairs(EX.nilCache) do if not seen[i] then seen[i] = true; res[#res + 1] = i end end
		for i in pairs(EX.nilExtra) do if not seen[i] then seen[i] = true; res[#res + 1] = i end end
		return res
	end

	local function sortKids(list)
		if #list > 4000 then return list end
		local keyed = table.create(#list)
		for i, c in ipairs(list) do
			keyed[i] = { isInst(c) and c.Name:lower() or (c.name or ""):lower(), c }
		end
		table.sort(keyed, function(a, b) return a[1] < b[1] end)
		for i, k in ipairs(keyed) do list[i] = k[2] end
		return list
	end

	function EX.kids(n)
		if isInst(n) then
			local ok, list = pcall(n.GetChildren, n)
			if not ok then return {} end
			return sortKids(list)
		elseif n.virt == "nil" then
			return sortKids(EX.nilList())
		elseif n.virt == "log" then
			local list = {}
			for id, label in pairs(animLabel) do
				local nd = EX.logNodes[id]
				if not nd then
					nd = { virt = "anim", id = id, class = "Animation" }
					EX.logNodes[id] = nd
				end
				nd.name = K.animName and K.animName(id) or tostring(id)
				nd.label = label
				nd.inst = X.animInstOf[id]
				list[#list + 1] = nd
			end
			return sortKids(list)
		end
		return {}
	end

	function EX.hasKids(n)
		if isInst(n) then
			local ok, list = pcall(n.GetChildren, n)
			return ok and #list > 0
		elseif n.virt == "nil" then
			return true
		elseif n.virt == "log" then
			return next(animLabel) ~= nil
		end
		return false
	end

	function EX.count(n, kind)
		local t = EX.cnt[kind]
		return t and t[n] or 0
	end

	function EX.show(c)
		if EX.kind == "all" then return true end
		if not isInst(c) then
			if c.virt == "nil" then return EX.count(c, EX.kind) > 0 end
			return EX.kind == "anim"
		end
		return kindOf(c.ClassName) == EX.kind or EX.count(c, EX.kind) > 0
	end

	function EX.roots()
		local list = { EX.logRoot }
		local svcs = {}
		local ok, l = pcall(function() return game:GetChildren() end)
		if ok then for _, c in ipairs(l) do svcs[#svcs + 1] = c end end
		table.sort(svcs, function(a, b)
			local ia, ib = ORDER[a.ClassName] or 99, ORDER[b.ClassName] or 99
			if ia ~= ib then return ia < ib end
			return a.Name < b.Name
		end)
		for _, c in ipairs(svcs) do list[#list + 1] = c end
		list[#list + 1] = EX.nilRoot
		return list
	end

	local function alive() return V.tree ~= nil and V.tree.Parent ~= nil end

	local function countsText(n)
		local parts = {}
		if EX.kind == "all" then
			for _, k in ipairs({ "anim", "sfx", "vfx" }) do
				local c = EX.count(n, k)
				if c > 0 then parts[#parts + 1] = string.format('<font color="%s">%s%d</font>', KIND_COL[k], k == "anim" and "A" or (k == "sfx" and "S" or "V"), c) end
			end
		else
			local c = EX.count(n, EX.kind)
			if c > 0 then parts[#parts + 1] = string.format('<font color="%s">%d</font>', KIND_COL[EX.kind], c) end
		end
		if #parts == 0 then return "" end
		return "  " .. table.concat(parts, " ")
	end

	function EX.render()
		if not alive() then return end
		local tree = V.tree
		local rows = EX.rows
		local H = tree.AbsoluteSize.Y / X.guiScale()
		if H <= 0 then H = 300 end
		local top = math.floor(tree.CanvasPosition.Y / ROW)
		local need = math.ceil(H / ROW) + 2
		local sub = K.hex(C.sub)
		for i = 1, need do
			local r = EX.pool[i] or EX.mkRow(i)
			local idx = top + i
			local rec = rows[idx]
			if rec then
				local n = rec.n
				r.rec = rec
				r.f.Position = UDim2.fromOffset(0, (idx - 1) * ROW)
				r.f.BackgroundColor3 = (EX.sel == n) and C.sel or (idx % 2 == 0 and C.row1 or C.row2)
				local x = rec.d * 16 + 4
				local hk = (not rec.flat) and EX.hasKids(n)
				r.arrow.Visible = hk and true or false
				r.arrow.Position = UDim2.fromOffset(x, 0)
				r.arrow.Rotation = EX.expanded[n] and 90 or 0
				local key = iconKey(n)
				r.icon.Position = UDim2.fromOffset(x + 18, 3)
				if r.iconKey ~= key then
					r.iconKey = key
					EX.drawIcon(r.icon, key)
				end
				r.lbl.Position = UDim2.fromOffset(x + 40, 0)
				r.lbl.Size = UDim2.new(1, -(x + 44), 1, 0)
				local cn = nClass(n)
				local txt = "<b>" .. K.esc(nName(n)) .. "</b>"
				if isInst(n) then
					if n.Parent ~= game and cn ~= "Folder" and cn ~= "Model" then txt ..= string.format(' <font color="%s">%s</font>', sub, K.esc(cn)) end
					if cn == "Animation" then
						local okI, aid = pcall(function() return n.AnimationId end)
						if okI then txt ..= string.format(' <font color="#7db9ff">%s</font>', K.esc((tostring(aid):gsub("rbxassetid://", "")))) end
					elseif cn == "Sound" then
						local okI, sid = pcall(function() return n.SoundId end)
						if okI then txt ..= string.format(' <font color="#8be08b">%s</font>', K.esc((tostring(sid):gsub("rbxassetid://", "")))) end
					end
					if cn ~= "Animation" and cn ~= "Sound" then txt ..= countsText(n) end
					if rec.flat then
						local okP, par = pcall(function() return n.Parent and n.Parent:GetFullName() or "nil" end)
						if okP then txt ..= string.format(' <font color="%s">in %s</font>', sub, K.esc(par)) end
					end
				elseif n.virt == "log" then
					local c = 0
					for _ in pairs(animLabel) do c += 1 end
					txt ..= string.format(' <font color="#7db9ff">%d seen playing</font>', c)
				elseif n.virt == "nil" then
					txt ..= countsText(n)
				elseif n.virt == "anim" then
					txt ..= string.format(' <font color="%s">%s</font>', sub, K.esc(n.label or ""))
					if not n.inst then txt ..= ' <font color="#d49a5a">id only</font>' end
				end
				r.lbl.Text = txt
				r.f.Visible = true
			else
				r.f.Visible = false
				r.rec = nil
			end
		end
		for i = need + 1, #EX.pool do EX.pool[i].f.Visible = false end
	end

	function EX.mkRow(i)
		local f = Instance.new("TextButton")
		f.AutoButtonColor = false
		f.Text = ""
		f.BorderSizePixel = 0
		f.Size = UDim2.new(1, -2, 0, ROW)
		f.Parent = V.tree
		local arrow = Instance.new("TextButton")
		arrow.BackgroundTransparency = 1
		arrow.Size = UDim2.new(0, 16, 0, ROW)
		arrow.Text = ">"
		arrow.Font = Enum.Font.SourceSansBold
		arrow.TextSize = 14
		arrow.TextColor3 = C.sub
		arrow.ZIndex = 2
		arrow.Parent = f
		local icon = Instance.new("Frame")
		icon.BackgroundTransparency = 1
		icon.Size = UDim2.fromOffset(16, 16)
		icon.Parent = f
		local lbl = Instance.new("TextLabel")
		lbl.BackgroundTransparency = 1
		lbl.RichText = true
		lbl.Font = Th.font
		lbl.TextSize = 15
		lbl.TextColor3 = C.text
		lbl.TextXAlignment = Enum.TextXAlignment.Left
		lbl.TextTruncate = Enum.TextTruncate.AtEnd
		lbl.Parent = f
		local r = { f = f, arrow = arrow, icon = icon, lbl = lbl }
		f.MouseButton1Click:Connect(function() EX.click(r) end)
		arrow.MouseButton1Click:Connect(function() if r.rec then EX.toggle(r.rec.n) end end)
		EX.pool[i] = r
		return r
	end

	function EX.rebuild()
		if not alive() then return end
		local rows = {}
		if EX.results then
			for _, n in ipairs(EX.results) do rows[#rows + 1] = { n = n, d = 0, flat = true } end
		else
			local function walk(n, depth)
				rows[#rows + 1] = { n = n, d = depth }
				if EX.expanded[n] and #rows < 60000 then
					for _, c in ipairs(EX.kids(n)) do
						if EX.show(c) then walk(c, depth + 1) end
					end
				end
			end
			for _, n in ipairs(EX.roots()) do
				if EX.show(n) then walk(n, 0) end
			end
		end
		EX.rows = rows
		V.tree.CanvasSize = UDim2.fromOffset(0, #rows * ROW + 4)
		EX.render()
	end

	function EX.toggle(n)
		EX.expanded[n] = (not EX.expanded[n]) or nil
		if n == EX.nilRoot and EX.expanded[n] then EX.nilCache = nil end
		EX.rebuild()
	end

	function EX.rowIndex(n)
		for i, rec in ipairs(EX.rows) do if rec.n == n then return i end end
	end

	function EX.reveal(inst)
		if not isInst(inst) or not alive() then return end
		if EX.results then
			EX.results = nil
			EX.gen += 1
			V.box.Text = ""
		end
		local chain, p, g = {}, inst, 0
		while p and g < 100 do chain[#chain + 1] = p; p = p.Parent; g += 1 end
		local top = chain[#chain]
		if top ~= game then
			EX.nilExtra[top] = true
			EX.nilCache = nil
			EX.expanded[EX.nilRoot] = true
		end
		for i = #chain, 2, -1 do EX.expanded[chain[i]] = true end
		if top ~= game then EX.expanded[top] = true end
		if EX.kind ~= "all" and kindOf(inst.ClassName) ~= EX.kind then
			EX.kind = "all"
			V.kindBtn.Text = KIND_NAME.all
		end
		EX.sel = inst
		EX.rebuild()
		local i = EX.rowIndex(inst)
		if i then V.tree.CanvasPosition = Vector2.new(0, math.max(0, (i - 4) * ROW)) end
		EX.render()
		EX.showInfo(inst)
	end

	function EX.click(r)
		local n = r.rec and r.rec.n
		if n == nil then return end
		local now = os.clock()
		EX.select(n)
		if EX.lastN == n and now - (EX.lastT or 0) < 0.35 then
			if r.rec.flat then
				EX.reveal(n)
			elseif not isInst(n) and n.virt == "anim" then
				if n.inst then EX.reveal(n.inst) end
			else
				EX.toggle(n)
			end
		end
		EX.lastN, EX.lastT = n, now
	end

	function EX.select(n)
		EX.sel = n
		EX.render()
		EX.showInfo(n)
	end

	local function addBtn(text, color, fn)
		local b = K.newButton(V.grid, text, color or C.btn)
		b.TextScaled = true
		b.LayoutOrder = #V.grid:GetChildren()
		local limit = Instance.new("UITextSizeConstraint")
		limit.MaxTextSize = 15
		limit.MinTextSize = 9
		limit.Parent = b
		b.MouseButton1Click:Connect(function()
			local ok, err = pcall(fn, b)
			if not ok then out("Error: " .. tostring(err)); K.flash(b, "Fail") end
		end)
		return b
	end

	function EX.otherPlaces(aid, skip)
		local list = EX.byId[normId(aid)]
		if not list then return "" end
		local lines = {}
		for _, a in ipairs(list) do
			if a ~= skip then
				local ok, p = pcall(function() return a:GetFullName() end)
				if ok then lines[#lines + 1] = "  " .. p end
				if #lines >= 6 then break end
			end
		end
		if #lines == 0 then return "" end
		return "\n<font color=\"#8fd3ff\">Same id also lives at:</font>\n" .. K.esc(table.concat(lines, "\n"))
	end

	function EX.animActions(aid, name, path, inst)
		local e = { id = aid, name = name, path = path or "?", inst = inst, alt = {} }
		local ok, acts = pcall(X.searchActions, e)
		if not ok or type(acts) ~= "table" then return end
		for _, a in ipairs(acts) do
			local label = a.text
			if not label and a.state then
				local okS, t = pcall(a.state)
				label = okS and t or "Convert"
			end
			addBtn(label or "?", a.color, function(btn) a.fn(btn) end)
		end
	end

	function EX.showInfo(n)
		if not alive() then return end
		for _, c in ipairs(V.grid:GetChildren()) do
			if c:IsA("GuiButton") then c:Destroy() end
		end
		if n == nil then
			V.title.Text = "Nothing picked"
			V.sub.Text = "Pick something in the tree"
			V.info.Text = ""
			EX.drawIcon(V.hicon, "other:?")
			return
		end
		local sub = K.hex(C.sub)
		EX.drawIcon(V.hicon, iconKey(n))
		V.title.Text = nName(n)
		V.sub.Text = nClass(n)
		if isInst(n) then
			local okP, full = pcall(function() return n:GetFullName() end)
			local lines = { string.format("<font color=\"%s\">%s</font>", sub, K.esc(okP and full or "?")) }
			if n.Parent == nil and n ~= game then lines[#lines + 1] = "<font color=\"#d49a5a\">no parent (nil instance)</font>" end
			local parts = {}
			for _, k in ipairs({ "anim", "sfx", "vfx" }) do
				local c = EX.count(n, k)
				if c > 0 and kindOf(n.ClassName) == nil then
					parts[#parts + 1] = string.format("<font color=\"%s\">%d %s</font>", KIND_COL[k], c, k == "anim" and "animations" or (k == "sfx" and "sounds" or "effects"))
				end
			end
			if #parts > 0 then lines[#lines + 1] = "Inside: " .. table.concat(parts, ", ") end
			local aid
			if n.ClassName == "Animation" then
				local okI, v = pcall(function() return n.AnimationId end)
				aid = okI and v or nil
				lines[#lines + 1] = "AnimationId: <font color=\"#7db9ff\">" .. K.esc(tostring(aid)) .. "</font>"
				if animLabel[aid] then lines[#lines + 1] = "Seen playing: " .. K.esc(animLabel[aid]) end
			elseif n.ClassName == "Sound" then
				local okS, v = pcall(function() return n.SoundId end)
				aid = okS and v or nil
				lines[#lines + 1] = "SoundId: <font color=\"#8be08b\">" .. K.esc(tostring(aid)) .. "</font>"
				local okL, len = pcall(function() return n.TimeLength end)
				if okL and len and len > 0 then lines[#lines + 1] = string.format("Length: %.2fs", len) end
			end
			V.info.Text = table.concat(lines, "\n") .. (aid and EX.otherPlaces(aid, n) or "")
			addBtn("Copy path", C.btn, function(b) toClip(EX.path(n), "the path"); K.flash(b, "Copied!") end)
			addBtn("Copy name", C.btn, function(b) toClip(n.Name, "the name"); K.flash(b, "Copied!") end)
			if n.ClassName == "Animation" then
				addBtn("Copy ID", C.btn, function(b) toClip(tostring(aid), "the AnimationId"); K.flash(b, "Copied!") end)
				EX.animActions(aid, n.Name, okP and full or "?", n)
			elseif n.ClassName == "Sound" then
				addBtn("Copy SoundId", C.btn, function(b) toClip(tostring(aid), "the SoundId"); K.flash(b, "Copied!") end)
			end
			if kindOf(n.ClassName) == nil and (EX.count(n, "anim") + EX.count(n, "sfx") + EX.count(n, "vfx")) > 0 then
				addBtn("List inside", C.sel, function() EX.listInside(n) end)
			end
			if EX.results then addBtn("Show in tree", C.sel, function() EX.reveal(n) end) end
		elseif n.virt == "anim" then
			local lines = {
				"Played by: " .. K.esc(n.label or "?"),
				"AnimationId: <font color=\"#7db9ff\">" .. K.esc(tostring(n.id)) .. "</font>",
			}
			local inst = n.inst
			if inst and inst.Parent ~= nil then
				local ok, full = pcall(function() return inst:GetFullName() end)
				lines[#lines + 1] = "Comes from: " .. K.esc(ok and full or "?")
			elseif inst then
				lines[#lines + 1] = "Comes from: an Animation with no parent (nil instance)"
			else
				lines[#lines + 1] = "<font color=\"#d49a5a\">The Animation instance was not seen. It was made by code (Instance.new) or only the id was used.</font>"
			end
			V.info.Text = table.concat(lines, "\n") .. EX.otherPlaces(n.id, inst)
			if inst then
				addBtn("Show in tree", C.sel, function() EX.reveal(inst) end)
				addBtn("Copy path", C.btn, function(b) toClip(EX.path(inst), "the path"); K.flash(b, "Copied!") end)
			end
			addBtn("Copy ID", C.btn, function(b) toClip(tostring(n.id), "the AnimationId"); K.flash(b, "Copied!") end)
			local okF, full = false, nil
			if inst then okF, full = pcall(function() return inst:GetFullName() end) end
			EX.animActions(n.id, n.name, okF and full or "?", inst)
		elseif n.virt == "log" then
			V.info.Text = "Every animation the logger has seen playing. Pick one to see the Animation it came from, then Show in tree to jump to its place in the game."
		elseif n.virt == "nil" then
			V.info.Text = "Things that exist but have no parent. Cutscene rigs and scripts often keep animations here."
		end
	end

	function EX.listInside(n)
		local res = {}
		local want = EX.kind == "all" and nil or EX.kind
		for _, list in ipairs({ EX.anims, EX.sounds or {}, EX.fxs or {} }) do
			for _, a in ipairs(list) do
				if a ~= n and (not want or kindOf(a.ClassName) == want) then
					local ok, inside = pcall(a.IsDescendantOf, a, n)
					if ok and inside then
						res[#res + 1] = a
						if #res >= 800 then break end
					end
				end
			end
		end
		EX.gen += 1
		EX.results = res
		V.status.Text = string.format("%d thing(s) inside %s  (Refresh goes back to the tree)", #res, nName(n))
		EX.rebuild()
		V.tree.CanvasPosition = Vector2.new(0, 0)
	end

	function EX.search(text)
		EX.gen += 1
		local gen = EX.gen
		text = text:lower()
		if text:gsub("%s", "") == "" then
			EX.results = nil
			EX.rebuild()
			EX.setStatus()
			return
		end
		local tokens = {}
		for w in text:gmatch("%S+") do tokens[#tokens + 1] = w end
		task.spawn(function()
			local res = {}
			for id, label in pairs(animLabel) do
				local nd = EX.logNodes[id]
				local hay = ((K.animName and K.animName(id) or "") .. " " .. label .. " " .. tostring(id)):lower()
				local okAll = true
				for _, t in ipairs(tokens) do if not hay:find(t, 1, true) then okAll = false break end end
				if okAll then
					if not nd then
						nd = { virt = "anim", id = id, class = "Animation", name = K.animName and K.animName(id) or tostring(id), label = label, inst = X.animInstOf[id] }
						EX.logNodes[id] = nd
					end
					res[#res + 1] = nd
				end
			end
			local all = EX.all
			for i = 1, #all do
				if gen ~= EX.gen or not Run.alive or not alive() then return end
				if i % 20000 == 0 then task.wait() end
				local inst = all[i]
				local cn = inst.ClassName
				if EX.kind == "all" or kindOf(cn) == EX.kind then
					local hay = inst.Name:lower() .. " " .. cn:lower()
					if cn == "Animation" then hay ..= " " .. tostring(inst.AnimationId):lower()
					elseif cn == "Sound" then hay ..= " " .. tostring(inst.SoundId):lower() end
					local okAll = true
					for _, t in ipairs(tokens) do if not hay:find(t, 1, true) then okAll = false break end end
					if okAll then
						res[#res + 1] = inst
						if #res >= 800 then break end
					end
				end
			end
			if gen ~= EX.gen then return end
			EX.results = res
			if alive() then
				V.status.Text = string.format("%d result(s)%s", #res, #res >= 800 and " (first 800)" or "")
				EX.rebuild()
				V.tree.CanvasPosition = Vector2.new(0, 0)
			end
		end)
	end

	function EX.setStatus()
		if not alive() then return end
		V.status.Text = string.format("%d instances  |  %d animations, %d sounds, %d effects%s", #EX.all, #EX.anims, #(EX.sounds or {}), #(EX.fxs or {}), EX.scanning and "  (scanning...)" or "")
	end

	function EX.scan()
		if EX.scanning then return end
		EX.scanning = true
		local all, anims, sounds, fxs, byId = {}, {}, {}, {}, {}
		local cnt = { anim = {}, sfx = {}, vfx = {} }
		EX.all, EX.anims, EX.sounds, EX.fxs, EX.byId, EX.cnt = all, anims, sounds, fxs, byId, cnt
		local seen, n = {}, 0
		local function add(inst)
			if seen[inst] then return end
			seen[inst] = true
			n += 1
			all[n] = inst
			local cn = inst.ClassName
			local k = kindOf(cn)
			if k then
				if k == "anim" then anims[#anims + 1] = inst elseif k == "sfx" then sounds[#sounds + 1] = inst else fxs[#fxs + 1] = inst end
				if k ~= "vfx" then
					local okI, aid = pcall(function() return k == "anim" and inst.AnimationId or inst.SoundId end)
					if okI then
						local key = normId(aid)
						local l = byId[key]
						if not l then l = {}; byId[key] = l end
						if #l < 40 then l[#l + 1] = inst end
					end
				end
				local ct = cnt[k]
				local p, last, g = inst, inst, 0
				while p and g < 100 do
					ct[p] = (ct[p] or 0) + 1
					last = p
					p = p.Parent
					g += 1
				end
				if last ~= game then ct[EX.nilRoot] = (ct[EX.nilRoot] or 0) + 1 end
			end
		end
		task.spawn(function()
			local lists = {}
			if getinstances then
				local ok, l = pcall(getinstances)
				if ok and type(l) == "table" then lists[#lists + 1] = l end
			end
			if #lists == 0 then
				local ok, l = pcall(function() return game:GetDescendants() end)
				if ok then lists[#lists + 1] = l end
			end
			local nilTop = {}
			if getnilinstances then
				local ok, l = pcall(getnilinstances)
				if ok and type(l) == "table" then nilTop = l end
			end
			local steps = 0
			for _, l in ipairs(lists) do
				for i = 1, #l do
					if not Run.alive then EX.scanning = false return end
					pcall(add, l[i])
					steps += 1
					if steps % 4000 == 0 then
						EX.setStatus()
						task.wait()
					end
				end
			end
			for _, top in ipairs(nilTop) do
				if not Run.alive then EX.scanning = false return end
				pcall(add, top)
				local ok, d = pcall(function() return top:GetDescendants() end)
				if ok then
					for _, c in ipairs(d) do
						pcall(add, c)
						steps += 1
						if steps % 4000 == 0 then EX.setStatus(); task.wait() end
					end
				end
			end
			EX.scanning = false
			EX.scanned = true
			if not EX.results then EX.setStatus() end
			EX.rebuild()
			if EX.sel then EX.showInfo(EX.sel) end
		end)
	end

	function EX.layout()
		if not alive() then return end
		local host = V.host
		local sz = host.AbsoluteSize / X.guiScale()
		local top = 54
		if sz.X >= 560 then
			V.tree.Position = UDim2.new(0, 4, 0, top)
			V.tree.Size = UDim2.new(0.56, -6, 1, -top - 4)
			V.det.Position = UDim2.new(0.56, 2, 0, top)
			V.det.Size = UDim2.new(0.44, -6, 1, -top - 4)
		else
			V.tree.Position = UDim2.new(0, 4, 0, top)
			V.tree.Size = UDim2.new(1, -8, 0.55, -top)
			V.det.Position = UDim2.new(0, 4, 0.55, 4)
			V.det.Size = UDim2.new(1, -8, 0.45, -8)
		end
		EX.render()
	end

	function EX.buildUI(host)
		V = { host = host }
		EX.pool = {}
		local bar = Instance.new("Frame")
		bar.Position = UDim2.new(0, 4, 0, 4)
		bar.Size = UDim2.new(1, -8, 0, 28)
		bar.BackgroundTransparency = 1
		bar.Parent = host

		local box = Instance.new("TextBox")
		box.Size = UDim2.new(1, -184, 1, 0)
		box.BackgroundColor3 = C.code
		box.BorderSizePixel = 0
		box.TextColor3 = C.text
		box.PlaceholderColor3 = C.sub
		box.PlaceholderText = "Search workspace: name, class, id..."
		box.Text = ""
		box.ClearTextOnFocus = false
		box.Font = Th.font
		box.TextSize = 16
		box.TextXAlignment = Enum.TextXAlignment.Left
		local boxPad = Instance.new("UIPadding")
		boxPad.PaddingLeft = UDim.new(0, 8)
		boxPad.Parent = box
		box.Parent = bar
		V.box = box

		local kindBtn = K.newButton(bar, KIND_NAME[EX.kind], C.btn)
		kindBtn.Position = UDim2.new(1, -178, 0, 0)
		kindBtn.Size = UDim2.new(0, 108, 1, 0)
		kindBtn.TextSize = 15
		V.kindBtn = kindBtn
		local refBtn = K.newButton(bar, "Refresh", C.btn)
		refBtn.Position = UDim2.new(1, -66, 0, 0)
		refBtn.Size = UDim2.new(0, 66, 1, 0)
		refBtn.TextSize = 15

		local status = Instance.new("TextLabel")
		status.Position = UDim2.new(0, 8, 0, 34)
		status.Size = UDim2.new(1, -16, 0, 16)
		status.BackgroundTransparency = 1
		status.Font = Th.font
		status.TextSize = 13
		status.TextColor3 = C.sub
		status.TextXAlignment = Enum.TextXAlignment.Left
		status.TextTruncate = Enum.TextTruncate.AtEnd
		status.Text = EX.scanned and "" or "Scanning..."
		status.Parent = host
		V.status = status

		local tree = Instance.new("ScrollingFrame")
		tree.BackgroundColor3 = C.code
		tree.BorderSizePixel = 0
		tree.ScrollBarThickness = 8
		tree.CanvasSize = UDim2.new()
		tree.AutomaticCanvasSize = Enum.AutomaticSize.None
		tree.Parent = host
		V.tree = tree

		local det = Instance.new("Frame")
		det.BackgroundColor3 = C.row2
		det.BorderSizePixel = 0
		det.Parent = host
		V.det = det

		local head = Instance.new("Frame")
		head.Size = UDim2.new(1, 0, 0, 40)
		head.BackgroundColor3 = C.title
		head.BorderSizePixel = 0
		head.Parent = det
		local hbox = Instance.new("Frame")
		hbox.BackgroundTransparency = 1
		hbox.Size = UDim2.fromOffset(16, 16)
		hbox.Position = UDim2.fromOffset(10, 12)
		hbox.Parent = head
		local hs = Instance.new("UIScale")
		hs.Scale = 1.5
		hs.Parent = hbox
		V.hicon = hbox
		local title = Instance.new("TextLabel")
		title.Position = UDim2.new(0, 42, 0, 3)
		title.Size = UDim2.new(1, -48, 0, 20)
		title.BackgroundTransparency = 1
		title.Font = Th.bold
		title.TextSize = 17
		title.TextColor3 = C.text
		title.TextXAlignment = Enum.TextXAlignment.Left
		title.TextTruncate = Enum.TextTruncate.AtEnd
		title.Parent = head
		V.title = title
		local sub = Instance.new("TextLabel")
		sub.Position = UDim2.new(0, 42, 0, 22)
		sub.Size = UDim2.new(1, -48, 0, 16)
		sub.BackgroundTransparency = 1
		sub.Font = Th.font
		sub.TextSize = 13
		sub.TextColor3 = C.sub
		sub.TextXAlignment = Enum.TextXAlignment.Left
		sub.TextTruncate = Enum.TextTruncate.AtEnd
		sub.Parent = head
		V.sub = sub

		local infoHost = Instance.new("ScrollingFrame")
		infoHost.Position = UDim2.new(0, 0, 0, 42)
		infoHost.Size = UDim2.new(1, 0, 0.5, -42)
		infoHost.BackgroundColor3 = C.code
		infoHost.BorderSizePixel = 0
		infoHost.ScrollBarThickness = 6
		infoHost.CanvasSize = UDim2.new()
		infoHost.AutomaticCanvasSize = Enum.AutomaticSize.Y
		infoHost.Parent = det
		local info = Instance.new("TextLabel")
		info.Size = UDim2.new(1, -10, 0, 0)
		info.Position = UDim2.new(0, 5, 0, 3)
		info.AutomaticSize = Enum.AutomaticSize.Y
		info.BackgroundTransparency = 1
		info.RichText = true
		info.TextWrapped = true
		info.Font = Th.font
		info.TextSize = 14
		info.TextColor3 = C.text
		info.TextXAlignment = Enum.TextXAlignment.Left
		info.TextYAlignment = Enum.TextYAlignment.Top
		info.Text = ""
		info.Parent = infoHost
		V.info = info

		local grid = Instance.new("ScrollingFrame")
		grid.Position = UDim2.new(0, 0, 0.5, 4)
		grid.Size = UDim2.new(1, 0, 0.5, -4)
		grid.BackgroundTransparency = 1
		grid.BorderSizePixel = 0
		grid.ScrollBarThickness = 6
		grid.CanvasSize = UDim2.new()
		grid.AutomaticCanvasSize = Enum.AutomaticSize.Y
		grid.Parent = det
		local gl = Instance.new("UIGridLayout")
		gl.CellSize = UDim2.new(0.5, -4, 0, 28)
		gl.CellPadding = UDim2.new(0, 4, 0, 4)
		gl.SortOrder = Enum.SortOrder.LayoutOrder
		gl.Parent = grid
		V.grid = grid

		table.insert(Run.conns, tree:GetPropertyChangedSignal("CanvasPosition"):Connect(function() EX.render() end))
		table.insert(Run.conns, tree:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() EX.render() end))
		table.insert(Run.conns, host:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() EX.layout() end))

		local tok = 0
		box:GetPropertyChangedSignal("Text"):Connect(function()
			tok += 1
			local my = tok
			task.delay(0.3, function()
				if my == tok and Run.alive and alive() then EX.search(box.Text) end
			end)
		end)
		kindBtn.MouseButton1Click:Connect(function()
			EX.kind = KIND_NEXT[EX.kind]
			kindBtn.Text = KIND_NAME[EX.kind]
			K.paint(kindBtn, EX.kind == "all" and C.btn or C.sel)
			if EX.results and box.Text ~= "" then EX.search(box.Text) else EX.rebuild() end
		end)
		K.paint(kindBtn, EX.kind == "all" and C.btn or C.sel)
		refBtn.MouseButton1Click:Connect(function()
			EX.nilCache = nil
			EX.results = nil
			EX.gen += 1
			if box.Text ~= "" then box.Text = "" end
			EX.scanned = false
			EX.scan()
			EX.rebuild()
		end)
		EX.layout()
		EX.showInfo(EX.sel)
	end

	function EX.openWin()
		if EX.win and EX.win.frame and EX.win.frame.Parent then
			if not EX.win.frame.Visible then EX.win.setMinimized(false) end
			return
		end
		if not EX.opened then
			EX.opened = true
			EX.expanded[EX.logRoot] = true
			for _, c in ipairs(EX.roots()) do
				if isInst(c) and c == workspace then EX.expanded[c] = true end
			end
		end
		local win = createWindow({
			title = "Explorer",
			size = Vector2.new(640, 470),
			pos = UDim2.new(0, 16, 0.5, -235),
			minSize = Vector2.new(360, 340),
			miniText = "EXP",
			onClose = function() EX.win = nil; V = {} end,
		})
		EX.win = win
		EX.buildUI(win.content)
		EX.rebuild()
		if not EX.scanned and not EX.scanning then EX.scan() else EX.setStatus() end
	end

	local page = newPage("Explorer")
	local msg = Instance.new("TextLabel")
	msg.Position = UDim2.new(0, 10, 0, 10)
	msg.Size = UDim2.new(1, -20, 0, 90)
	msg.BackgroundTransparency = 1
	msg.RichText = true
	msg.TextWrapped = true
	msg.Font = Th.font
	msg.TextSize = 16
	msg.TextColor3 = C.text
	msg.TextXAlignment = Enum.TextXAlignment.Left
	msg.TextYAlignment = Enum.TextYAlignment.Top
	msg.Text = "<b>Explorer</b>\nThe full Dex Explorer and Properties open at the right side. The InstanceX button at the top center opens every other Dex app (Notepad, Console, 3D Viewer...). The small explorer below only shows where logged animations come from."
	msg.Parent = page
	local dexBtn = K.newButton(page, "Open Explorer (Dex)", C.sel)
	dexBtn.Position = UDim2.new(0, 10, 0, 112)
	dexBtn.Size = UDim2.new(1, -20, 0, 38)
	dexBtn.TextSize = 17
	dexBtn.MouseButton1Click:Connect(function() X.dexOpen(dexBtn) end)
	if tabButtons.Explorer then
		tabButtons.Explorer.MouseButton1Click:Connect(function() X.dexOpen() end)
	end
end

do
		local ED = { orig = {}, list = {}, sel = nil, temps = {}, srcOf = {}, rows = {} }
	X.vfxEd = ED

	local function mk(class, props, parent)
		local o = Instance.new(class)
		for k, v in pairs(props) do o[k] = v end
		if parent then o.Parent = parent end
		return o
	end
	local function isAlive(o) return o ~= nil and (o.Parent ~= nil or ED.temps[o] ~= nil) end

	local SPEC = {
		ParticleEmitter = { { "Enabled", "b" }, { "Rate", "n" }, { "Lifetime", "nr" }, { "Speed", "nr" }, { "Size", "ns" }, { "Transparency", "ns" },
			{ "Color", "cs" }, { "LightEmission", "n" }, { "Drag", "n" }, { "Rotation", "nr" }, { "RotSpeed", "nr" }, { "SpreadAngle", "v2" },
			{ "Acceleration", "v3" }, { "Squash", "ns" }, { "ZOffset", "n" }, { "TimeScale", "n" }, { "LockedToPart", "b" }, { "Texture", "s" } },
		Beam = { { "Enabled", "b" }, { "Width0", "n" }, { "Width1", "n" }, { "Color", "cs" }, { "Transparency", "ns" }, { "LightEmission", "n" },
			{ "Segments", "n" }, { "CurveSize0", "n" }, { "CurveSize1", "n" }, { "TextureSpeed", "n" }, { "TextureLength", "n" } },
		Trail = { { "Enabled", "b" }, { "Lifetime", "n" }, { "Color", "cs" }, { "Transparency", "ns" }, { "WidthScale", "ns" }, { "LightEmission", "n" }, { "MinLength", "n" } },
		Fire = { { "Enabled", "b" }, { "Size", "n" }, { "Heat", "n" }, { "Color", "c" }, { "SecondaryColor", "c" } },
		Smoke = { { "Enabled", "b" }, { "Size", "n" }, { "Opacity", "n" }, { "RiseVelocity", "n" }, { "Color", "c" } },
		Sparkles = { { "Enabled", "b" }, { "SparkleColor", "c" }, { "TimeScale", "n" } },
		Highlight = { { "Enabled", "b" }, { "FillColor", "c" }, { "FillTransparency", "n" }, { "OutlineColor", "c" }, { "OutlineTransparency", "n" } },
		PointLight = { { "Enabled", "b" }, { "Brightness", "n" }, { "Range", "n" }, { "Color", "c" } },
		SpotLight = { { "Enabled", "b" }, { "Brightness", "n" }, { "Range", "n" }, { "Angle", "n" }, { "Color", "c" } },
		SurfaceLight = { { "Enabled", "b" }, { "Brightness", "n" }, { "Range", "n" }, { "Angle", "n" }, { "Color", "c" } },
	}
	local function num(v) return (string.format("%.4f", v):gsub("0+$", ""):gsub("%.$", "")) end
	local function lit(t, v)
		if t == "n" then return num(v)
		elseif t == "b" then return tostring(v)
		elseif t == "c" then return string.format("Color3.fromRGB(%d, %d, %d)", math.round(v.R * 255), math.round(v.G * 255), math.round(v.B * 255))
		elseif t == "nr" then return string.format("NumberRange.new(%s, %s)", num(v.Min), num(v.Max))
		elseif t == "v3" then return string.format("Vector3.new(%s, %s, %s)", num(v.X), num(v.Y), num(v.Z))
		elseif t == "v2" then return string.format("Vector2.new(%s, %s)", num(v.X), num(v.Y))
		elseif t == "s" then return string.format("%q", v)
		elseif t == "ns" then
			local p = {}
			for _, k in ipairs(v.Keypoints) do p[#p + 1] = string.format("NumberSequenceKeypoint.new(%s, %s, %s)", num(k.Time), num(k.Value), num(k.Envelope)) end
			return "NumberSequence.new({" .. table.concat(p, ", ") .. "})"
		elseif t == "cs" then
			local p = {}
			for _, k in ipairs(v.Keypoints) do p[#p + 1] = string.format("ColorSequenceKeypoint.new(%s, %s)", num(k.Time), lit("c", k.Value)) end
			return "ColorSequence.new({" .. table.concat(p, ", ") .. "})"
		end
		return "nil"
	end
	local function scaleNS(v, k)
		local p = {}
		for _, kp in ipairs(v.Keypoints) do p[#p + 1] = NumberSequenceKeypoint.new(kp.Time, kp.Value * k, kp.Envelope * k) end
		return NumberSequence.new(p)
	end
	local function scaleNR(v, k) return NumberRange.new(v.Min * k, v.Max * k) end

	local function read(inst, prop)
		local ok, v = pcall(function() return inst[prop] end)
		if ok then return v end
	end
	local function write(inst, prop, v) return (pcall(function() inst[prop] = v end)) end

	function ED.snapshot(inst)
		if ED.orig[inst] then return end
		local spec = SPEC[inst.ClassName]
		if not spec then return end
		local o = {}
		for _, s in ipairs(spec) do o[s[1]] = read(inst, s[1]) end
		ED.orig[inst] = o
	end

	local GROUPS = {
		Size = { ParticleEmitter = { { "Size", "ns" } }, Beam = { { "Width0", "n" }, { "Width1", "n" } }, Trail = { { "WidthScale", "ns" } },
			Fire = { { "Size", "n" } }, Smoke = { { "Size", "n" } }, PointLight = { { "Range", "n" } }, SpotLight = { { "Range", "n" } }, SurfaceLight = { { "Range", "n" } } },
		Speed = { ParticleEmitter = { { "Speed", "nr" } }, Smoke = { { "RiseVelocity", "n" } }, Beam = { { "TextureSpeed", "n" } } },
		Life = { ParticleEmitter = { { "Lifetime", "nr" } }, Trail = { { "Lifetime", "n" } } },
		Amount = { ParticleEmitter = { { "Rate", "n" } }, Fire = { { "Heat", "n" } } },
		Glow = { ParticleEmitter = { { "LightEmission", "n" } }, Beam = { { "LightEmission", "n" } }, Trail = { { "LightEmission", "n" } },
			PointLight = { { "Brightness", "n" } }, SpotLight = { { "Brightness", "n" } }, SurfaceLight = { { "Brightness", "n" } } },
	}
	function ED.scaleAll(group, k)
		local n = 0
		for _, inst in ipairs(ED.list) do
			if isAlive(inst) then
				ED.snapshot(inst)
				local g = GROUPS[group][inst.ClassName]
				if g then
					for _, s in ipairs(g) do
						local v = read(inst, s[1])
						if v ~= nil then
							local nv
							if s[2] == "n" then nv = v * k elseif s[2] == "nr" then nv = scaleNR(v, k) elseif s[2] == "ns" then nv = scaleNS(v, k) end
							if nv ~= nil and write(inst, s[1], nv) then n += 1 end
						end
					end
				end
			end
		end
		ED.showProps()
		return n
	end

	function ED.reset()
		for inst, o in pairs(ED.orig) do
			if isAlive(inst) then
				local spec = SPEC[inst.ClassName]
				for _, s in ipairs(spec or {}) do
					if o[s[1]] ~= nil then write(inst, s[1], o[s[1]]) end
				end
			end
		end
		ED.showProps()
	end

	function ED.code()
		local lines = { "-- VFX edits (run again after the effect respawns)" }
		for inst, o in pairs(ED.orig) do
			if isAlive(inst) then
				local spec = SPEC[inst.ClassName] or {}
				local changes = {}
				for _, s in ipairs(spec) do
					local cur = read(inst, s[1])
					if cur ~= nil and o[s[1]] ~= nil and lit(s[2], cur) ~= lit(s[2], o[s[1]]) then
						changes[#changes + 1] = string.format("\tfx.%s = %s", s[1], lit(s[2], cur))
					end
				end
									if #changes > 0 then
						local tgt = ED.srcOf[inst] or inst
						local expr = X.ex and X.ex.path and X.ex.path(tgt) or ("workspace -- " .. tgt:GetFullName())
					lines[#lines + 1] = "do"
					lines[#lines + 1] = "\tlocal ok, fx = pcall(function() return " .. (expr:find("\n") and ("workspace:FindFirstChild(" .. string.format("%q", inst.Name) .. ", true)") or expr) .. " end)"
					lines[#lines + 1] = "\tif ok and fx then"
					for _, c in ipairs(changes) do lines[#lines + 1] = "\t" .. c end
					lines[#lines + 1] = "\tend"
					lines[#lines + 1] = "end"
				end
			end
		end
		if #lines == 1 then lines[#lines + 1] = "-- nothing was changed" end
		return table.concat(lines, "\n")
	end

	function ED.loadTargets(list, temps, onSave)
		if ED.stage then
			pcall(function() ED.stage:Destroy() end)
			ED.stage, ED.preSpawn, ED.paused = nil, nil, false
			if ED.pauseBtn then ED.pauseBtn.Text = "Pause" end
		end
		ED.list = {}
		ED.temps = temps or {}
		ED.onSave = onSave
		for _, v in ipairs(list or {}) do
			if isAlive(v) and SPEC[v.ClassName] then ED.list[#ED.list + 1] = v end
		end
		ED.sel = ED.list[1]
		ED.showList()
		ED.showProps()
	end

	function ED.fromEvents(evs, onSave)
		local list, temps = {}, {}
		for _, ev in ipairs(evs) do
			if type(ev) == "table" and ev.kind == "vfx" and SPEC[ev.class] then
				local okI, inst = pcall(Instance.new, ev.class)
				if okI then
					for _, pr in ipairs(ev.props or {}) do
						local fn = loadstring and loadstring("return " .. tostring(pr[2]))
						if fn then
							local okV, v = pcall(fn)
							if okV and v ~= nil then write(inst, pr[1], v) end
						end
					end
					if ev.enabled ~= nil then write(inst, "Enabled", ev.enabled) end
					inst.Name = tostring(ev.name or ev.class)
					list[#list + 1] = inst
					temps[inst] = ev
				end
			end
		end
		if #list == 0 then error("no editable effect in this one") end
		ED.open(list, temps, onSave)
	end

	function ED.save(b)
		if next(ED.temps) then
			local n = 0
			for inst, ev in pairs(ED.temps) do
				ev.props = K.readProps(inst, VFX_PROPS[ev.class] or {})
				local okE, en = pcall(function() return inst.Enabled end)
				if okE then ev.enabled = en end
				n += 1
			end
			if ED.onSave then pcall(ED.onSave) end
			K.flash(b, n .. " saved")
		else
			local evs = {}
			for _, inst in ipairs(ED.list) do
				if isAlive(inst) then
					local okV, ev = pcall(K.buildVFXEvent, inst, nil, 0)
					if okV and ev then evs[#evs + 1] = ev end
				end
			end
			if #evs == 0 then error("nothing to save") end
			X.libSave(evs, "Edited VFX", b)
		end
	end

	function ED.loadNearby()
		local char = lp.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		if not hrp then error("no character") end
		local out2 = {}
		for _, d in ipairs(workspace:GetDescendants()) do
			if SPEC[d.ClassName] and not d:IsDescendantOf(char) then
				local part = d:FindFirstAncestorWhichIsA("BasePart")
				if not part and d.Parent and d.Parent:IsA("Attachment") then part = d.Parent.Parent end
				if part and part:IsA("BasePart") and (part.Position - hrp.Position).Magnitude <= 90 then
					out2[#out2 + 1] = d
					if #out2 >= 300 then break end
				end
			end
		end
		ED.loadTargets(out2)
		return #out2
	end

	local function colorBox(parent, text, size, pos)
		return mk("TextBox", {
			Size = size, Position = pos, BackgroundColor3 = C.code, BorderSizePixel = 0, TextColor3 = C.text,
			Font = Th.font, TextSize = 14, Text = text, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left,
		}, parent)
	end

		function ED.paintList()
		for inst, b in pairs(ED.rows) do
			if b.Parent then K.paint(b, inst == ED.sel and C.sel or C.row1) end
		end
	end

	function ED.showList()
		if not ED.listHost then return end
		ED.rowsTok = (ED.rowsTok or 0) + 1
		local tok = ED.rowsTok
		for _, c in ipairs(ED.listHost:GetChildren()) do
			if c:IsA("GuiButton") then c:Destroy() end
		end
		ED.rows = {}
		ED.status.Text = string.format("%d effect(s) loaded%s", #ED.list, ED.stage and "  -  spawned in front of you" .. (ED.paused and " (paused)" or "") or "")
		local host = ED.listHost
		task.spawn(function()
			for i, inst in ipairs(ED.list) do
				if tok ~= ED.rowsTok or ED.listHost ~= host then return end
				local b = K.newButton(host, inst.ClassName .. ": " .. inst.Name, inst == ED.sel and C.sel or C.row1)
				b.Size = UDim2.new(1, -4, 0, 24)
				b.LayoutOrder = i
				b.TextSize = 14
				b.TextXAlignment = Enum.TextXAlignment.Left
				b.TextTruncate = Enum.TextTruncate.AtEnd
				ED.rows[inst] = b
				b.MouseButton1Click:Connect(function()
					ED.sel = inst
					ED.paintList()
					ED.showProps()
				end)
				if i % 30 == 0 then task.wait() end
			end
		end)
	end

	function ED.setPaused(on)
		ED.paused = on and true or false
		for _, inst in ipairs(ED.list) do
			if isAlive(inst) and (inst:IsA("ParticleEmitter") or inst:IsA("Sparkles")) then
				ED.snapshot(inst)
				local base = (ED.orig[inst] and ED.orig[inst].TimeScale) or 1
				write(inst, "TimeScale", on and 0 or (base == 0 and 1 or base))
			end
		end
		if ED.pauseBtn then ED.pauseBtn.Text = ED.paused and "Play" or "Pause" end
		if ED.status then ED.status.Text = string.format("%d effect(s) loaded%s", #ED.list, ED.stage and "  -  spawned in front of you" .. (ED.paused and " (paused)" or "") or "") end
		ED.showProps()
	end

	function ED.clearStage()
		if ED.stage then pcall(function() ED.stage:Destroy() end) end
		ED.stage, ED.paused = nil, false
		if ED.pauseBtn then ED.pauseBtn.Text = "Pause" end
		if ED.preSpawn then
			ED.list, ED.sel = ED.preSpawn.list, ED.preSpawn.sel
			ED.preSpawn = nil
			ED.showList()
			ED.showProps()
		end
	end

	function ED.stageHome()
		local char = lp.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		return hrp and (hrp.CFrame * CFrame.new(0, 1, -10)) or CFrame.new(0, 8, 0)
	end

	function ED.spawnPaused()
		local src = ED.preSpawn and ED.preSpawn.list or ED.list
		local items = {}
		for _, inst in ipairs(src) do
			if isAlive(inst) and SPEC[inst.ClassName] then items[#items + 1] = inst end
		end
		if #items == 0 then error("load an effect first (Nearby, or Edit VFX on the VFX / Search / Library tabs)") end
		local pre = ED.preSpawn or { list = ED.list, sel = ED.sel }
		if ED.stage then pcall(function() ED.stage:Destroy() end) end
		local stage = mk("Part", { Name = "_RPPStage", Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false,
			Transparency = 1, Size = Vector3.new(1, 1, 1), CFrame = ED.stageHome() })
		stage:SetAttribute("_LoggerClone", true)
		stage.Parent = workspace
		local mount = mk("Attachment", { Name = "Mount" }, stage)
		local a0 = mk("Attachment", { Name = "A0", Position = Vector3.new(-3, 0, 0) }, stage)
		local a1 = mk("Attachment", { Name = "A1", Position = Vector3.new(3, 0, 0) }, stage)
		local newList, newSel = {}, nil
		for _, inst in ipairs(items) do
			pcall(function() inst.Archivable = true end)
			local okC, c = pcall(function() return inst:Clone() end)
			if okC and c then
				ED.srcOf[c] = ED.srcOf[inst] or inst
				if ED.temps[inst] then ED.temps[c] = ED.temps[inst] end
				ED.snapshot(c)
				if c:IsA("Beam") or c:IsA("Trail") then
					pcall(function() c.Attachment0, c.Attachment1 = a0, a1 end)
					c.Parent = stage
				elseif c:IsA("Highlight") then
					c.Parent = stage
				else
					c.Parent = mount
				end
				if c:IsA("ParticleEmitter") or c:IsA("Fire") or c:IsA("Smoke") or c:IsA("Sparkles") or c:IsA("Beam") or c:IsA("Trail") then write(c, "Enabled", true) end
				newList[#newList + 1] = c
				if inst == pre.sel then newSel = c end
			end
		end
		if #newList == 0 then stage:Destroy() error("could not copy those effects") end
		ED.stage, ED.preSpawn = stage, pre
		ED.list, ED.sel = newList, newSel or newList[1]
		ED.showList()
		ED.showProps()
		for _, c in ipairs(newList) do
			if c:IsA("ParticleEmitter") then pcall(c.Emit, c, 20) end
		end
		task.delay(0.8, function()
			if ED.stage == stage then ED.setPaused(true) end
		end)
	end

	function ED.replay()
		if not ED.stage then error("press Spawn paused first") end
		ED.setPaused(false)
		local stage = ED.stage
		for _, c in ipairs(ED.list) do
			if c:IsA("ParticleEmitter") then
				pcall(c.Clear, c)
				pcall(c.Emit, c, 25)
			end
		end
		task.delay(1, function()
			if ED.stage == stage then ED.setPaused(true) end
		end)
	end

	function ED.nudge(dx, dy, dz)
		if not (ED.stage and ED.stage.Parent) then error("press Spawn paused first") end
		ED.stage.CFrame = ED.stage.CFrame + Vector3.new(dx, dy, dz)
	end

	function ED.showProps()
		if not ED.propHost then return end
		for _, c in ipairs(ED.propHost:GetChildren()) do
			if c:IsA("GuiObject") then c:Destroy() end
		end
		local inst = ED.sel
		if not isAlive(inst) then return end
		ED.snapshot(inst)
		local o = ED.orig[inst] or {}
		local y = 0
		local function row(label)
			local r = mk("Frame", { Size = UDim2.new(1, -6, 0, 26), Position = UDim2.fromOffset(0, y), BackgroundTransparency = 1 }, ED.propHost)
			mk("TextLabel", { Size = UDim2.new(0.38, 0, 1, 0), BackgroundTransparency = 1, Font = Th.font, TextSize = 14, TextColor3 = C.sub,
				TextXAlignment = Enum.TextXAlignment.Left, Text = label, TextTruncate = Enum.TextTruncate.AtEnd }, r)
			y += 28
			return r
		end
		for _, s in ipairs(SPEC[inst.ClassName] or {}) do
			local prop, t = s[1], s[2]
			local cur = read(inst, prop)
			if cur ~= nil then
				local r = row(prop)
				local W, P = UDim2.new(0.62, 0, 1, 0), UDim2.new(0.38, 0, 0, 0)
				if t == "b" then
					local b = K.newButton(r, tostring(cur), cur and C.green or C.btn)
					b.Size, b.Position, b.TextSize = W, P, 14
					b.MouseButton1Click:Connect(function()
						local nv = not read(inst, prop)
						write(inst, prop, nv)
						b.Text = tostring(nv)
						K.paint(b, nv and C.green or C.btn)
					end)
				elseif t == "ns" then
					local box = colorBox(r, "x1", W, P)
					box.FocusLost:Connect(function()
						local k = tonumber((box.Text:gsub("[xX]", "")))
						if k and o[prop] then write(inst, prop, scaleNS(o[prop], k)); box.Text = "x" .. num(k) else box.Text = "x1" end
					end)
				elseif t == "cs" then
					local first = cur.Keypoints[1].Value
					local box = colorBox(r, string.format("%d, %d, %d", math.round(first.R * 255), math.round(first.G * 255), math.round(first.B * 255)), W, P)
					box.FocusLost:Connect(function()
						local a, b2, c2 = box.Text:match("(%d+)%D+(%d+)%D+(%d+)")
						if a then write(inst, prop, ColorSequence.new(Color3.fromRGB(math.min(tonumber(a), 255), math.min(tonumber(b2), 255), math.min(tonumber(c2), 255)))) end
					end)
				else
					local txt
					if t == "n" then txt = num(cur)
					elseif t == "c" then txt = string.format("%d, %d, %d", math.round(cur.R * 255), math.round(cur.G * 255), math.round(cur.B * 255))
					elseif t == "nr" then txt = num(cur.Min) .. ", " .. num(cur.Max)
					elseif t == "v3" then txt = num(cur.X) .. ", " .. num(cur.Y) .. ", " .. num(cur.Z)
					elseif t == "v2" then txt = num(cur.X) .. ", " .. num(cur.Y)
					else txt = tostring(cur) end
					local box = colorBox(r, txt, W, P)
					box.FocusLost:Connect(function()
						local nums = {}
						for m in box.Text:gmatch("-?%d+%.?%d*") do nums[#nums + 1] = tonumber(m) end
						local nv
						if t == "n" and nums[1] then nv = nums[1]
						elseif t == "c" and #nums >= 3 then nv = Color3.fromRGB(math.clamp(nums[1], 0, 255), math.clamp(nums[2], 0, 255), math.clamp(nums[3], 0, 255))
						elseif t == "nr" and #nums >= 1 then nv = NumberRange.new(nums[1], nums[2] or nums[1])
						elseif t == "v3" and #nums >= 3 then nv = Vector3.new(nums[1], nums[2], nums[3])
						elseif t == "v2" and #nums >= 2 then nv = Vector2.new(nums[1], nums[2])
						elseif t == "s" then nv = box.Text end
						if nv ~= nil then write(inst, prop, nv) end
					end)
				end
			end
		end
		ED.propHost.CanvasSize = UDim2.fromOffset(0, y + 4)
	end

	X.vfxEditorOpen = function(list) return ED.open(list or ED.list or {}) end
	function ED.open(list, temps, onSave)
		if ED.win and ED.win.frame and ED.win.frame.Parent then
			if not ED.win.frame.Visible then ED.win.setMinimized(false) end
			ED.loadTargets(list or ED.list, temps, onSave)
			return
		end
		local win = createWindow({
			title = "VFX Editor", size = Vector2.new(560, 440), pos = UDim2.new(1, -580, 0.5, -220),
			minSize = Vector2.new(380, 320), miniText = "VFX", onClose = function() pcall(ED.clearStage); ED.win = nil; ED.listHost = nil; ED.propHost = nil end,
		})
		ED.win = win
		local host = win.content
		local function topBtn(text, x, w, color, fn)
			local b = K.newButton(host, text, color or C.btn)
			b.Position, b.Size, b.TextSize = UDim2.new(0, x, 0, 4), UDim2.new(0, w, 0, 26), 14
			b.MouseButton1Click:Connect(function()
				local ok, err = pcall(fn, b)
				if not ok then out("Error: " .. tostring(err)); K.flash(b, "Fail") end
			end)
			return b
		end
		topBtn("Save", 4, 92, C.green, function(b) ED.save(b) end)
		topBtn("Nearby", 100, 70, C.btn, function(b) local n = ED.loadNearby(); K.flash(b, n .. " loaded") end)
		topBtn("Reset", 174, 56, C.btn, function() ED.reset() end)
		topBtn("Copy code", 234, 84, C.sel, function(b) toClip(ED.code(), "the edit code"); K.flash(b, "Copied!") end)
		topBtn("Emit", 322, 50, C.btn, function()
			for _, v in ipairs(ED.list) do if v:IsA("ParticleEmitter") then pcall(v.Emit, v, 15) end end
		end)

		local row2 = mk("Frame", { Position = UDim2.new(0, 4, 0, 34), Size = UDim2.new(1, -8, 0, 26), BackgroundTransparency = 1 }, host)
		mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder }, row2)
		local factor = mk("TextBox", { Size = UDim2.new(0, 48, 1, 0), BackgroundColor3 = C.code, BorderSizePixel = 0, TextColor3 = C.text, Font = Th.font,
			TextSize = 14, Text = "1.5", ClearTextOnFocus = false, LayoutOrder = 0 }, row2)
		for i, g in ipairs({ "Size", "Speed", "Life", "Amount", "Glow" }) do
			local b = K.newButton(row2, g .. " x", C.btn)
			b.Size, b.TextSize, b.LayoutOrder = UDim2.new(0, 64, 1, 0), 14, i
			b.MouseButton1Click:Connect(function()
				local k = tonumber(factor.Text)
				if not k or k <= 0 then return K.flash(b, "Bad x") end
				K.flash(b, ED.scaleAll(g, k) .. " changed")
			end)
		end
		local div = mk("Frame", { Size = UDim2.new(0, 2, 1, 0), BackgroundColor3 = C.outline or C.btn, BorderSizePixel = 0, LayoutOrder = 6 }, row2)
		local inv = K.newButton(row2, "1 / x", C.btn)
		inv.Size, inv.TextSize, inv.LayoutOrder = UDim2.new(0, 40, 1, 0), 14, 7
		inv.MouseButton1Click:Connect(function()
			local k = tonumber(factor.Text)
			if k and k > 0 then factor.Text = num(1 / k) end
		end)

		local row3 = mk("ScrollingFrame", { Position = UDim2.new(0, 4, 0, 64), Size = UDim2.new(1, -8, 0, 28), BackgroundTransparency = 1, BorderSizePixel = 0,
			ScrollBarThickness = 0, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.X, ScrollingDirection = Enum.ScrollingDirection.X }, host)
		mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder }, row3)
		local order = 0
		local function r3(text, w, color, fn)
			order += 1
			local b = K.newButton(row3, text, color or C.btn)
			b.Size, b.TextSize, b.LayoutOrder = UDim2.new(0, w, 0, 26), 14, order
			b.MouseButton1Click:Connect(function()
				local ok, err = pcall(fn, b)
				if not ok then out("Error: " .. tostring(err)); K.flash(b, "Fail") end
			end)
			return b
		end
		r3("Spawn paused", 104, C.green, function(b) ED.spawnPaused() end)
		ED.pauseBtn = r3("Pause", 54, C.btn, function()
			if not ED.stage then error("press Spawn paused first") end
			ED.setPaused(not ED.paused)
		end)
		r3("Replay", 56, C.btn, function() ED.replay() end)
		r3("Clear", 48, C.danger, function() ED.clearStage() end)
		order += 1
		local step = mk("TextBox", { Size = UDim2.new(0, 40, 0, 26), BackgroundColor3 = C.code, BorderSizePixel = 0, TextColor3 = C.text, Font = Th.font,
			TextSize = 14, Text = "1", ClearTextOnFocus = false, LayoutOrder = order }, row3)
		local function mv(label, dx, dy, dz)
			r3(label, 32, C.btn, function()
				local s = tonumber(step.Text) or 1
				ED.nudge(dx * s, dy * s, dz * s)
			end)
		end
		mv("X-", -1, 0, 0) mv("X+", 1, 0, 0) mv("Y-", 0, -1, 0) mv("Y+", 0, 1, 0) mv("Z-", 0, 0, -1) mv("Z+", 0, 0, 1)
		r3("Here", 46, C.btn, function()
			if not (ED.stage and ED.stage.Parent) then error("press Spawn paused first") end
			ED.stage.CFrame = ED.stageHome()
		end)

		ED.status = mk("TextLabel", { Position = UDim2.new(0, 8, 0, 94), Size = UDim2.new(1, -16, 0, 16), BackgroundTransparency = 1, Font = Th.font,
			TextSize = 13, TextColor3 = C.sub, TextXAlignment = Enum.TextXAlignment.Left, Text = "" }, host)
		ED.listHost = mk("ScrollingFrame", { Position = UDim2.new(0, 4, 0, 114), Size = UDim2.new(0.4, -6, 1, -118), BackgroundColor3 = C.code, BorderSizePixel = 0,
			ScrollBarThickness = 6, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y }, host)
		mk("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }, ED.listHost)
		ED.propHost = mk("ScrollingFrame", { Position = UDim2.new(0.4, 2, 0, 114), Size = UDim2.new(0.6, -6, 1, -118), BackgroundColor3 = C.row2, BorderSizePixel = 0,
			ScrollBarThickness = 6, CanvasSize = UDim2.new() }, host)
		ED.loadTargets(list or ED.list, temps, onSave)
	end
end

function X.dexOpen(btn)
