L.MAX_SAVES = 100
L.CODE_CUT = 40000

function L.credit()
	task.spawn(function()
		local icon
		pcall(function()
			local id = Players:GetUserIdFromNameAsync("DuaKNo")
			icon = "rbxthumb://type=AvatarHeadShot&id=" .. id .. "&w=150&h=150"
		end)
		local list = {
			{ Title = "Copy: copy any GUI or tool", Text = "By DuaKNo", Icon = icon },
			{ Title = "Follow on Instagram", Text = "me_duakno" },
			{ Title = "Join Discord server for more", Text = "discord.gg/empgqd5qpq" },
		}
		for _, n in ipairs(list) do
			n.Duration = 6
			for _ = 1, 10 do
				local ok = pcall(function() StarterGui:SetCore("SendNotification", n) end)
