	end)
end

local function num(n)
	if n ~= n then return "0/0" end
	if n == math.huge then return "math.huge" end
	if n == -math.huge then return "-math.huge" end
	if n == math.floor(n) and math.abs(n) < 1e15 then return string.format("%d", n) end
	return string.format("%.9g", n)
end

local function lit(v)
	local t = typeof(v)
	if t == "number" then
		return num(v)
	elseif t == "boolean" then
		return tostring(v)
	elseif t == "string" then
		return string.format("%q", v)
	elseif t == "EnumItem" then
		return tostring(v)
	elseif t == "Color3" then
		local r, g, b = math.floor(v.R * 255 + 0.5), math.floor(v.G * 255 + 0.5), math.floor(v.B * 255 + 0.5)
		if Color3.fromRGB(r, g, b) == v then
			return string.format("Color3.fromRGB(%d, %d, %d)", r, g, b)
		end
		return string.format("Color3.new(%s, %s, %s)", num(v.R), num(v.G), num(v.B))
	elseif t == "UDim2" then
		return string.format("UDim2.new(%s, %s, %s, %s)", num(v.X.Scale), num(v.X.Offset), num(v.Y.Scale), num(v.Y.Offset))
	elseif t == "UDim" then
		return string.format("UDim.new(%s, %s)", num(v.Scale), num(v.Offset))
	elseif t == "Vector2" then
		return string.format("Vector2.new(%s, %s)", num(v.X), num(v.Y))
	elseif t == "Vector3" then
		return string.format("Vector3.new(%s, %s, %s)", num(v.X), num(v.Y), num(v.Z))
	elseif t == "Rect" then
		return string.format("Rect.new(%s, %s, %s, %s)", num(v.Min.X), num(v.Min.Y), num(v.Max.X), num(v.Max.Y))
	elseif t == "NumberRange" then
		return string.format("NumberRange.new(%s, %s)", num(v.Min), num(v.Max))
	elseif t == "NumberSequence" then
		local parts = {}
		for _, k in ipairs(v.Keypoints) do
			if k.Envelope ~= 0 then
				parts[#parts + 1] = string.format("NumberSequenceKeypoint.new(%s, %s, %s)", num(k.Time), num(k.Value), num(k.Envelope))
			else
				parts[#parts + 1] = string.format("NumberSequenceKeypoint.new(%s, %s)", num(k.Time), num(k.Value))
			end
		end
		return "NumberSequence.new({ " .. table.concat(parts, ", ") .. " })"
	elseif t == "ColorSequence" then
		local parts = {}
		for _, k in ipairs(v.Keypoints) do
			parts[#parts + 1] = string.format("ColorSequenceKeypoint.new(%s, %s)", num(k.Time), lit(k.Value))
		end
		return "ColorSequence.new({ " .. table.concat(parts, ", ") .. " })"
	elseif t == "Content" then
		local okU, uri = pcall(function() return v.Uri end)
		if okU and type(uri) == "string" and uri ~= "" then return string.format("%q", uri) end
		return nil
	elseif t == "Font" then
		return string.format("Font.new(%q, %s, %s)", v.Family, tostring(v.Weight), tostring(v.Style))
	elseif t == "BrickColor" then
		return string.format("BrickColor.new(%q)", v.Name)
	elseif t == "CFrame" then
		local c = { v:GetComponents() }
		for i, x in ipairs(c) do c[i] = num(x) end
		return "CFrame.new(" .. table.concat(c, ", ") .. ")"
	end
	return nil
end

