local defaults = {}
function L.defaultFor(class)
	if defaults[class] == nil then
		local ok, o = pcall(Instance.new, class)
		defaults[class] = ok and o or false
	end
	return defaults[class]
end

local function isA(o, c)
	local ok, r = pcall(o.IsA, o, c)
	return ok and r == true
end

function L.propNames(o)
	local names, seen = {}, {}
	for _, entry in ipairs(PROPS) do
		if isA(o, entry[1]) then
			for _, n in ipairs(entry[2]) do
				if not seen[n] then
					seen[n] = true
					names[#names + 1] = n
				end
			end
		end
	end
	return names
end

function L.readProps(o)
	local def = L.defaultFor(o.ClassName)
	local res = {}
	for _, name in ipairs(L.propNames(o)) do
		local ok, v = pcall(function() return o[name] end)
		if ok and v ~= nil then
			local s = lit(v)
			if s then
				local keep = (name == "Name")
				if not keep then
					if def then
						local okD, dv = pcall(function() return def[name] end)
						if okD and dv ~= nil then keep = (lit(dv) ~= s) else keep = true end
					else
						keep = true
					end
				end
				if keep then res[#res + 1] = { name, s } end
			end
		end
	end
	return res
end

function L.isChanged(o, name, s)
	if name == "Name" then return o.Name ~= o.ClassName end
	local def = L.defaultFor(o.ClassName)
	if not def then return true end
	local ok, dv = pcall(function() return def[name] end)
	if ok and dv ~= nil then return lit(dv) ~= s end
	return true
end

function L.setProp(list, key, code)
	for _, p in ipairs(list) do
		if p[1] == key then p[2] = code return end
	end
	list[#list + 1] = { key, code }
end

function L.dropProp(list, key)
	for i = #list, 1, -1 do
		if list[i][1] == key then table.remove(list, i) end
	end
end

function L.supported(c)
	if c:GetAttribute(MARK_ATTR) then return false end
	return isA(c, "GuiBase2d") and not isA(c, "LayerCollector")
		or isA(c, "UIComponent") or isA(c, "UIBase")
		or isA(c, "ValueBase") or isA(c, "Sound")
		or c.ClassName == "Folder" or c.ClassName == "Configuration"
end

function L.ownerOf(o)
	local p = o
	while p do
		if isA(p, "LayerCollector") then return p end
		p = p.Parent
	end
end

function L.buildNodes(root, opts)
	local nodes, skipped, truncated = {}, {}, false
	local owner = L.ownerOf(root)
	local rootIsLayer = isA(root, "LayerCollector")
	local parentOfRoot = 0
	if not rootIsLayer then
		local props = {}
		props[#props + 1] = { "Name", lit("UICopy") }
		local function copyFrom(name, fallback)
			local v = fallback
			if owner then
				local ok, r = pcall(function() return owner[name] end)
				if ok and r ~= nil then v = r end
			end
			if v ~= nil then props[#props + 1] = { name, lit(v) } end
		end
		copyFrom("DisplayOrder", 10)
		copyFrom("IgnoreGuiInset", false)
		copyFrom("ZIndexBehavior", Enum.ZIndexBehavior.Sibling)
		props[#props + 1] = { "ResetOnSpawn", "false" }
		nodes[1] = { parent = 0, class = "ScreenGui", props = props }
		parentOfRoot = 1
	end

	local function walk(inst, parentId)
		if #nodes >= L.MAX_NODES then truncated = true return end
		local id = #nodes + 1
		nodes[id] = { parent = parentId, class = inst.ClassName, props = L.readProps(inst) }
		for _, c in ipairs(inst:GetChildren()) do
			if c:GetAttribute(MARK_ATTR) then
			elseif L.S and L.S.ignore[c] then
			elseif L.supported(c) then
				if opts.desc or isA(c, "UIComponent") then walk(c, id) end
			else
				skipped[c.ClassName] = (skipped[c.ClassName] or 0) + 1
			end
		end
	end
	walk(root, parentOfRoot)

	if parentOfRoot == 1 and opts.place and isA(root, "GuiObject") then
		local direct = root.Parent and isA(root.Parent, "LayerCollector")
		if not direct then
			local node = nodes[2]
			local okP, absPos = pcall(function() return root.AbsolutePosition end)
			local okS, absSize = pcall(function() return root.AbsoluteSize end)
			if node and okP and okS then
				local base = Vector2.new(0, 0)
				if owner then
					local okO, ap = pcall(function() return owner.AbsolutePosition end)
					if okO then base = ap end
				end
				local rel = absPos - base
				L.setProp(node.props, "AnchorPoint", "Vector2.new(0, 0)")
				L.setProp(node.props, "Position", string.format("UDim2.new(0, %s, 0, %s)", num(math.floor(rel.X + 0.5)), num(math.floor(rel.Y + 0.5))))
				L.setProp(node.props, "Size", string.format("UDim2.new(0, %s, 0, %s)", num(math.floor(absSize.X + 0.5)), num(math.floor(absSize.Y + 0.5))))
				L.dropProp(node.props, "AutomaticSize")
				L.dropProp(node.props, "SizeConstraint")
				L.dropProp(node.props, "LayoutOrder")
			end
		end
	end

	local sk = {}
	for k, v in pairs(skipped) do sk[#sk + 1] = k .. " x" .. v end
	table.sort(sk)
	local meta = {
		name = root.Name,
		class = root.ClassName,
		skipped = sk,
		truncated = truncated,
		adornee = isA(root, "BillboardGui") or isA(root, "SurfaceGui"),
	}
	return nodes, meta
end

function L.codeFrom(nodes, meta, opts)
	local out = {}
	local function add(s) out[#out + 1] = s end
	local nm = tostring(meta.name):gsub("[\r\n]", " ")
	add("-- UI Copier by DuaKNo")
	add(string.format("-- source: %s (%s)", nm, tostring(meta.class)))
	add(string.format("-- %d objects%s", #nodes, meta.truncated and (" (stopped at " .. L.MAX_NODES .. ")") or ""))
	if meta.skipped and #meta.skipped > 0 then add("-- not copied: " .. table.concat(meta.skipped, ", ")) end
	if meta.adornee then
		add("-- this one needs an Adornee: set made.Adornee to a part after it is created")
	end
	add("")
	if opts.hui then
		add('local container = (gethui and gethui()) or game:GetService("CoreGui")')
	else
		add('local container = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")')
	end
	add("")
	add("local data = {")
	for _, n in ipairs(nodes) do
		if opts.compact then
			local parts = {}
			for _, p in ipairs(n.props) do
				parts[#parts + 1] = string.format("%q,%s", p[1], p[2])
			end
			add(string.format("{%d,%q,{%s}},", n.parent, n.class, table.concat(parts, ",")))
		else
			add(string.format("\t{ %d, %q, {", n.parent, n.class))
			for _, p in ipairs(n.props) do
				add(string.format("\t\t%q, %s,", p[1], p[2]))
			end
			add("\t} },")
		end
	end
	add("}")
	add("")
	add("local made = {}")
	add("for i, d in ipairs(data) do")
	add("\tlocal okNew, obj = pcall(Instance.new, d[2])")
	add("\tif okNew then")
	add("\t\tlocal p = d[3]")
	add("\t\tfor j = 1, #p, 2 do")
	add("\t\t\tpcall(function() obj[p[j]] = p[j + 1] end)")
	add("\t\tend")
	add("\t\tmade[i] = obj")
	add("\t\tif d[1] == 0 then")
	add("\t\t\tobj.Parent = container")
	add("\t\telseif made[d[1]] then")
	add("\t\t\tobj.Parent = made[d[1]]")
	add("\t\tend")
	add("\tend")
	add("end")
	add("")
	add("return made[1]")
	return table.concat(out, "\n")
end

local function pack(nodes)
	local st, idx = {}, {}
	local function si(s)
		local i = idx[s]
		if not i then
			i = #st + 1
			st[i] = s
			idx[s] = i
		end
		return i
	end
	local out = {}
	for i, n in ipairs(nodes) do
		local row = { n.parent, si(n.class) }
		for _, p in ipairs(n.props) do
			row[#row + 1] = si(p[1])
			row[#row + 1] = si(p[2])
		end
		out[i] = row
	end
	return { st = st, n = out }
end

L.ALLOWED_WORDS = {
	"Color3.fromRGB", "Color3.new", "UDim2.new", "UDim.new", "Vector2.new", "Vector3.new", "Rect.new",
	"NumberRange.new", "NumberSequenceKeypoint.new", "NumberSequence.new", "ColorSequenceKeypoint.new",
	"ColorSequence.new", "Font.new", "BrickColor.new", "CFrame.new", "math.huge", "true", "false",
}
function L.escPat(w) return (w:gsub("%p", "%%%0")) end

function L.safeLiteral(s)
	if type(s) ~= "string" or #s > 6000 then return false end
	if s:sub(1, 1) == '"' then
		local i, n = 2, #s
		while i <= n do
			local c = s:sub(i, i)
			if c == "\\" then
				i += 2
			elseif c == '"' then
				return i == n
			else
				i += 1
			end
		end
		return false
	end
	local t = s:gsub('"[^"\\]*"', '""')
	t = t:gsub("Enum%.[%w_]+%.[%w_]+", "")
	for _, w in ipairs(L.ALLOWED_WORDS) do
		t = t:gsub(L.escPat(w), "")
	end
	return t:match('^[%d%s%.,%-%+{}%(%)eE/"]*$') ~= nil
end

function L.unpackNodes(p)
	if type(p) ~= "table" or type(p.st) ~= "table" or type(p.n) ~= "table" then return nil end
	local nodes = {}
	for i, row in ipairs(p.n) do
		if type(row) ~= "table" then return nil end
		local par, cls = row[1], p.st[row[2]]
		if type(par) ~= "number" or type(cls) ~= "string" or not cls:match("^%w+$") then return nil end
		local props = {}
		for j = 3, #row, 2 do
			local k, v = p.st[row[j]], p.st[row[j + 1]]
			if type(k) ~= "string" or not k:match("^[%w_]+$") or not L.safeLiteral(v) then return nil end
			props[#props + 1] = { k, v }
		end
		nodes[i] = { parent = par, class = cls, props = props }
	end
	return nodes
end

L.KEYWORDS = {}
for w in ("and break do else elseif end false for function if in local nil not or repeat return then true until while continue"):gmatch("%a+") do L.KEYWORDS[w] = true end

function L.pathOf(inst)
	local chain, p = {}, inst
	while p and p ~= game do
		table.insert(chain, 1, p)
		p = p.Parent
	end
	if p ~= game then return "-- no path: this object has no parent" end
	local s = "game"
	for i, c in ipairs(chain) do
		if i == 1 then
			s = s .. string.format(":GetService(%q)", c.ClassName)
		elseif c == lp then
			s = s .. ".LocalPlayer"
		elseif c.Name:match("^[%a_][%w_]*$") and not L.KEYWORDS[c.Name] then
			s = s .. "." .. c.Name
		else
			s = s .. string.format("[%q]", c.Name)
		end
	end
	return s
end

local function rgb(c)
	return string.format("%d, %d, %d", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
end

function L.realKids(o)
	local list = {}
	for _, c in ipairs(o:GetChildren()) do
		if not c:GetAttribute(MARK_ATTR) then list[#list + 1] = c end
	end
	return list
end

local function tally(o)
	local counts, total = {}, 0
	for _, d in ipairs(o:GetDescendants()) do
		if not d:GetAttribute(MARK_ATTR) then
			total += 1
			counts[d.ClassName] = (counts[d.ClassName] or 0) + 1
		end
	end
	local arr = {}
	for k, v in pairs(counts) do arr[#arr + 1] = { k, v } end
	table.sort(arr, function(a, b) return a[2] > b[2] end)
	local parts = {}
	for i = 1, math.min(6, #arr) do parts[i] = arr[i][1] .. " x" .. arr[i][2] end
	return total, table.concat(parts, ", ")
end

function L.connInfo(o)
	if not getconnections or not isA(o, "GuiObject") then return nil end
	local parts = {}
	for _, sig in ipairs({ "Activated", "MouseButton1Click", "MouseButton1Down", "MouseButton1Up", "InputBegan", "MouseEnter" }) do
		local ok, s = pcall(function() return o[sig] end)
		if ok and typeof(s) == "RBXScriptSignal" then
			local ok2, conns = pcall(getconnections, s)
			if ok2 and type(conns) == "table" and #conns > 0 then
				local who, seen = {}, {}
				for _, c in ipairs(conns) do
					local okF, fn = pcall(function() return c.Function end)
					if okF and type(fn) == "function" and getfenv then
						local okE, fenv = pcall(getfenv, fn)
						if okE and type(fenv) == "table" then
							local okS, sc = pcall(function() return fenv.script end)
							if okS and typeof(sc) == "Instance" and not seen[sc] then
								seen[sc] = true
								local okN, full = pcall(function() return sc:GetFullName() end)
								if okN then who[#who + 1] = full end
							end
						end
					end
				end
				local text = sig .. " x" .. #conns
				if #who > 0 then text ..= " (" .. table.concat(who, ", ") .. ")" end
				parts[#parts + 1] = text
			end
		end
	end
	if #parts == 0 then return "none found" end
	return table.concat(parts, "; ")
end

local function details(o)
	local out = {}
	local function add(k, v) out[#out + 1] = { k, tostring(v) } end
	add("Name", o.Name)
	add("Class", o.ClassName)
	add("Path", L.pathOf(o))
	if o.Parent then add("Parent", o.Parent.Name .. " (" .. o.Parent.ClassName .. ")") end
	if isA(o, "GuiObject") then
		add("Position", lit(o.Position))
		add("Size", lit(o.Size))
		add("AnchorPoint", lit(o.AnchorPoint))
		add("On screen", string.format("%d, %d  size %d x %d", math.floor(o.AbsolutePosition.X), math.floor(o.AbsolutePosition.Y), math.floor(o.AbsoluteSize.X), math.floor(o.AbsoluteSize.Y)))
		if o.Rotation ~= 0 then add("Rotation", o.Rotation) end
		add("ZIndex / Layout", o.ZIndex .. " / " .. o.LayoutOrder)
		local hiddenBy
		local p = o
		while p do
			if isA(p, "GuiObject") and not p.Visible then hiddenBy = p break end
			if isA(p, "LayerCollector") and p.Enabled == false then hiddenBy = p break end
			p = p.Parent
		end
		add("Visible", hiddenBy and ("no, hidden by " .. hiddenBy.Name) or "yes")
		add("Background", string.format("rgb(%s)  transparency %s", rgb(o.BackgroundColor3), num(o.BackgroundTransparency)))
		if o.BorderSizePixel > 0 then add("Border", string.format("%d px  rgb(%s)", o.BorderSizePixel, rgb(o.BorderColor3))) end
		if o.ClipsDescendants then add("Clips", "yes") end
		if o.AutomaticSize ~= Enum.AutomaticSize.None then add("AutomaticSize", tostring(o.AutomaticSize)) end
	end
	if isA(o, "TextLabel") or isA(o, "TextButton") or isA(o, "TextBox") then
		local t = o.Text
		if #t > 120 then t = t:sub(1, 120) .. "..." end
		add("Text", t)
		add("Font", string.format("%s  size %d  rgb(%s)", tostring(o.Font), o.TextSize, rgb(o.TextColor3)))
		if o.TextScaled then add("TextScaled", "yes") end
		if o.RichText then add("RichText", "yes") end
	end
	if isA(o, "ImageLabel") or isA(o, "ImageButton") then
		add("Image", o.Image)
		add("ImageColor3", string.format("rgb(%s)  transparency %s  %s", rgb(o.ImageColor3), num(o.ImageTransparency), tostring(o.ScaleType)))
		if o.ImageRectSize ~= Vector2.new(0, 0) then add("Sprite rect", lit(o.ImageRectOffset) .. " / " .. lit(o.ImageRectSize)) end
	end
	if isA(o, "ScrollingFrame") then
		add("Canvas", lit(o.CanvasSize) .. "  scroll " .. lit(o.CanvasPosition))
	end
	if isA(o, "ScreenGui") then
		add("ScreenGui", string.format("order %d  reset %s  inset ignored %s  enabled %s", o.DisplayOrder, tostring(o.ResetOnSpawn), tostring(o.IgnoreGuiInset), tostring(o.Enabled)))
	end
	local kids = L.realKids(o)
	if #kids > 0 then
		local total, mix = tally(o)
		add("Children", #kids .. " direct, " .. total .. " in total")
		add("Contains", mix)
	end
	local mods = {}
	for _, c in ipairs(kids) do
		if isA(c, "UIComponent") then mods[#mods + 1] = c.ClassName end
	end
	if #mods > 0 then add("UI parts", table.concat(mods, ", ")) end
	local owner = L.ownerOf(o)
	if owner and owner ~= o then
		local extra = ""
		if isA(owner, "ScreenGui") then
			extra = string.format("  order %d  reset %s  inset ignored %s", owner.DisplayOrder, tostring(owner.ResetOnSpawn), tostring(owner.IgnoreGuiInset))
		end
		add("Inside", owner.Name .. " (" .. owner.ClassName .. ")" .. extra)
	end
	local c = L.connInfo(o)
	if c then add("Connections", c) end
	return out
end

local function esc(s)
	return (tostring(s):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

local function splitNums(s)
	local inner = s:match("%((.*)%)") or s
	inner = inner:gsub("[{}]", " ")
	local t = {}
	for tok in inner:gmatch("[^,%s]+") do
		local n = tonumber(tok)
		if n == nil then
			if tok == "math.huge" then n = math.huge elseif tok == "-math.huge" then n = -math.huge end
		end
		if n == nil then return nil end
		t[#t + 1] = n
	end
	return t
end

function L.parseValue(cur, raw)
	local t = typeof(cur)
	if t == "string" then return true, raw end
	local s = raw:gsub("^%s+", ""):gsub("%s+$", "")
	if t == "number" then
		local n = tonumber(s)
		if s == "math.huge" then n = math.huge end
		if n == nil then return false, "not a number" end
		return true, n
	elseif t == "boolean" then
		local l = s:lower()
		if l == "true" or l == "1" or l == "yes" or l == "on" then return true, true end
		if l == "false" or l == "0" or l == "no" or l == "off" then return true, false end
		return false, "use true or false"
	elseif t == "Color3" then
		local hex = s:match("^#?(%x%x%x%x%x%x)$")
		if hex then return true, Color3.fromHex(hex) end
		local n = splitNums(s)
		if not n or #n < 3 then return false, "use r, g, b or #hex" end
		local big = n[1] > 1 or n[2] > 1 or n[3] > 1
		local inner = s:match("%((.*)%)") or s
		local rawMode
		if s:find("fromRGB", 1, true) then
			rawMode = false
		elseif s:find("Color3.new", 1, true) then
			rawMode = true
		else
			rawMode = (not big) and inner:find("%.") ~= nil
		end
		if rawMode then return true, Color3.new(n[1], n[2], n[3]) end
		return true, Color3.fromRGB(n[1], n[2], n[3])
	elseif t == "UDim2" then
		local n = splitNums(s)
		if n and #n == 4 then return true, UDim2.new(n[1], n[2], n[3], n[4]) end
		if n and #n == 2 then return true, UDim2.fromOffset(n[1], n[2]) end
		return false, "use scaleX, offsetX, scaleY, offsetY"
	elseif t == "UDim" then
		local n = splitNums(s)
		if n and #n == 2 then return true, UDim.new(n[1], n[2]) end
		return false, "use scale, offset"
	elseif t == "Vector2" then
		local n = splitNums(s)
		if n and #n == 2 then return true, Vector2.new(n[1], n[2]) end
		return false, "use x, y"
	elseif t == "Vector3" then
		local n = splitNums(s)
		if n and #n == 3 then return true, Vector3.new(n[1], n[2], n[3]) end
		return false, "use x, y, z"
	elseif t == "Rect" then
		local n = splitNums(s)
		if n and #n == 4 then return true, Rect.new(n[1], n[2], n[3], n[4]) end
		return false, "use minX, minY, maxX, maxY"
	elseif t == "NumberRange" then
		local n = splitNums(s)
		if n and #n == 2 then return true, NumberRange.new(n[1], n[2]) end
		if n and #n == 1 then return true, NumberRange.new(n[1]) end
		return false, "use min, max"
	elseif t == "EnumItem" then
		local name = s:match("([%w_]+)$")
		for _, it in ipairs(cur.EnumType:GetEnumItems()) do
			if it.Name == name or tostring(it.Value) == s then return true, it end
		end
		return false, "unknown option"
	elseif t == "Font" then
		local name = s:match("([%w_]+)$")
		local ok, it = pcall(function() return Enum.Font[name] end)
		if ok and it then return true, Font.fromEnum(it) end
		return false, "type a font name like Gotham"
	elseif t == "BrickColor" then
		local ok, b = pcall(BrickColor.new, s)
		if ok and b then return true, b end
		return false, "unknown brick color"
	end
	return false, "this type can't be edited"
end

L.READONLY = { NumberSequence = true, ColorSequence = true, CFrame = true }

local C3 = Color3.fromRGB
local function mkTheme(bg, title, row1, row2, code, btn, sel, green, danger, text, sub, line)
	return { BG = bg, TITLE = title, ROW1 = row1, ROW2 = row2, CODE = code, BTN = btn, SEL = sel, GREEN = green, DANGER = danger, TEXT = text, SUB = sub, LINE = line }
end
local THEMES = {
	{ "Dark", mkTheme(C3(45, 45, 45), C3(52, 52, 52), C3(50, 50, 50), C3(45, 45, 45), C3(38, 38, 38), C3(60, 60, 60), C3(11, 90, 175), C3(40, 120, 70), C3(135, 50, 50), C3(255, 255, 255), C3(185, 185, 185), C3(33, 33, 33)) },
