local T = {}
function L.rebuildTheme()
	local base
	for _, t in ipairs(THEMES) do
		if t[1] == cfg.theme then base = t[2] end
	end
	base = base or THEMES[1][2]
	for k, v in pairs(base) do T[k] = v end
	if cfg.accent then T.SEL = Color3.fromRGB(cfg.accent[1], cfg.accent[2], cfg.accent[3]) end
	local okF, f = pcall(function() return Enum.Font[cfg.font] end)
	T.FONT = (okF and f) or Enum.Font.SourceSans
	T.ONACC = Color3.new(1, 1, 1)
end

local hasFS = (writefile and readfile and isfile) and true or false
local mem = genv.UICopierMem
if type(mem) ~= "table" then
	mem = { index = {}, data = {}, settings = nil }
	genv.UICopierMem = mem
end

function L.ensureDir()
	pcall(function()
		if makefolder and isfolder and not isfolder(DIR) then makefolder(DIR) end
	end)
end

function L.readJson(path)
	if not hasFS then return nil end
	local ok, raw = pcall(function()
		if isfile(path) then return readfile(path) end
	end)
	if ok and type(raw) == "string" then
		local ok2, d = pcall(function() return HttpService:JSONDecode(raw) end)
		if ok2 then return d end
	end
	return nil
end

function L.writeJson(path, data)
	if not hasFS then return false, "no file support" end
	local okE, raw = pcall(function() return HttpService:JSONEncode(data) end)
	if not okE then return false, tostring(raw) end
	L.ensureDir()
	local ok, err = pcall(writefile, path, raw)
	if not ok then return false, tostring(err) end
	return true, #raw
end

local Store = { index = {} }
function Store.load()
	if hasFS then
		local d = L.readJson(L.INDEX_FILE)
		Store.index = (type(d) == "table" and type(d.items) == "table") and d.items or {}
	else
		Store.index = mem.index
	end
end
function Store.saveIndex()
	table.sort(Store.index, function(a, b)
		if (a.t or 0) ~= (b.t or 0) then return (a.t or 0) > (b.t or 0) end
		return tostring(a.id) > tostring(b.id)
	end)
	if hasFS then return L.writeJson(L.INDEX_FILE, { v = 1, items = Store.index }) end
	mem.index = Store.index
	return true
end
function Store.put(id, payload)
	if hasFS then return L.writeJson(DIR .. "/s_" .. id .. ".json", payload) end
	local ok, raw = pcall(function() return HttpService:JSONEncode(payload) end)
	mem.data[id] = payload
	return true, ok and #raw or 0
end
function Store.get(id)
	if hasFS then return L.readJson(DIR .. "/s_" .. id .. ".json") end
	return mem.data[id]
end
function Store.del(id)
	if hasFS then
		pcall(function()
			local path = DIR .. "/s_" .. id .. ".json"
			if delfile and isfile(path) then delfile(path) end
		end)
	else
		mem.data[id] = nil
	end
end

local function findItem(id)
	for i, it in ipairs(Store.index) do
		if it.id == id then return it, i end
	end
end

function L.uniqueName(base)
	local function taken(n)
		for _, it in ipairs(Store.index) do
			if it.name == n then return true end
		end
		return false
	end
	if not taken(base) then return base end
	local i = 2
	while taken(base .. " (" .. i .. ")") do i += 1 end
	return base .. " (" .. i .. ")"
end

function L.addEntry(name, kind, class, n, payload)
	if #Store.index >= L.MAX_SAVES then
		return nil, "Saved list is full (" .. L.MAX_SAVES .. "). Delete some first."
	end
	local id
	repeat
		id = string.format("%x%03x", os.time(), math.random(0, 4095))
	until not findItem(id)
	local ok, sz = Store.put(id, payload)
	if not ok then return nil, "Could not write the file: " .. tostring(sz) end
	table.insert(Store.index, { id = id, name = name, kind = kind, class = class, n = n, sz = sz, t = os.time() })
	Store.saveIndex()
	return id
end

local function ago(t)
	local d = os.time() - (t or 0)
	if d < 60 then return "now" end
	if d < 3600 then return math.floor(d / 60) .. "m ago" end
	if d < 86400 then return math.floor(d / 3600) .. "h ago" end
	return math.floor(d / 86400) .. "d ago"
end

local function fmtSize(b)
	b = b or 0
	if b < 1024 then return b .. "B" end
	return string.format("%.1fKB", b / 1024)
end

function L.saveSettingsNow()
	local data = {
		v = 1, theme = cfg.theme, accent = cfg.accent, textSize = cfg.textSize, font = cfg.font,
		corner = cfg.corner, alpha = cfg.alpha, ask = cfg.ask, after = cfg.after, hover = cfg.hover,
		hotkey = cfg.hotkey, W = cfg.W, H = cfg.H,
		opts = { desc = S.opts.desc, place = S.opts.place, hui = S.opts.hui, core = S.opts.core, compact = S.opts.compact },
	}
	if hasFS then
		L.writeJson(L.SET_FILE, data)
	else
		mem.settings = data
	end
end

function L.loadSettings()
	local d = hasFS and L.readJson(L.SET_FILE) or mem.settings
	if type(d) ~= "table" then return end
	local function pick(k, ty)
		if type(d[k]) == ty then cfg[k] = d[k] end
	end
	pick("theme", "string"); pick("font", "string"); pick("after", "string")
	pick("textSize", "number"); pick("corner", "number"); pick("alpha", "number")
	pick("ask", "boolean"); pick("hover", "boolean"); pick("hotkey", "boolean")
	pick("W", "number"); pick("H", "number")
	if type(d.accent) == "table" and #d.accent == 3 then cfg.accent = { d.accent[1], d.accent[2], d.accent[3] } end
	if type(d.opts) == "table" then
		for k in pairs(S.opts) do
			if type(d.opts[k]) == "boolean" then S.opts[k] = d.opts[k] end
		end
	end
	cfg.textSize = math.clamp(cfg.textSize, 10, 22)
	cfg.corner = math.clamp(cfg.corner, 0, 14)
	cfg.alpha = math.clamp(cfg.alpha, 0, 0.6)
end

