local function isPointer(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function new(class, props, parent)
	local o = Instance.new(class)
	for k, v in pairs(props or {}) do o[k] = v end
	o.Parent = parent
	return o
end

local reg = setmetatable({}, { __mode = "k" })
L.corners = setmetatable({}, { __mode = "k" })
L.ACCENT_ROLES = { SEL = true, GREEN = true, DANGER = true }

local function bind(o, prop, rn)
	local m = reg[o]
	if not m then
		m = {}
		reg[o] = m
	end
	m[prop] = rn
	local v = T[rn]
	o[prop] = v
	if prop == "BackgroundColor3" and o:GetAttribute("base") ~= nil then o:SetAttribute("base", v) end
end

local function rounded(o)
	local c = new("UICorner", { CornerRadius = UDim.new(0, HOST and 0 or cfg.corner) }, o)
	L.corners[c] = true
	return c
end

local function label(parent, text, size, rn, props)
	local l = new("TextLabel", {
		BackgroundTransparency = 1, Text = text, TextSize = size or 14,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, parent)
	bind(l, "Font", "FONT")
	bind(l, "TextColor3", rn or "TEXT")
	if props then
		for k, v in pairs(props) do l[k] = v end
	end
	return l
end

local function button(parent, text, rn)
	rn = rn or "BTN"
	local b = new("TextButton", { AutoButtonColor = false, BorderSizePixel = HOST and 1 or 0, BorderColor3 = Color3.fromRGB(33, 33, 33), Text = text, TextSize = HOST and 14 or 15 }, parent)
	b:SetAttribute("base", true)
	bind(b, "BackgroundColor3", rn)
	bind(b, "TextColor3", L.ACCENT_ROLES[rn] and "ONACC" or "TEXT")
	bind(b, "Font", "FONT")
	rounded(b)
	b.MouseEnter:Connect(function()
		b.BackgroundColor3 = b:GetAttribute("base"):Lerp(Color3.new(1, 1, 1), 0.12)
	end)
	b.MouseLeave:Connect(function()
		b.BackgroundColor3 = b:GetAttribute("base")
	end)
	return b
end

local function paint(b, rn)
	bind(b, "BackgroundColor3", rn)
	bind(b, "TextColor3", L.ACCENT_ROLES[rn] and "ONACC" or "TEXT")
end

function L.textbox(parent, placeholder)
	local t = new("TextBox", {
		BorderSizePixel = HOST and 1 or 0, BorderColor3 = Color3.fromRGB(33, 33, 33), ClearTextOnFocus = false, Text = "", PlaceholderText = placeholder or "",
		TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left,
	}, parent)
	bind(t, "BackgroundColor3", "CODE")
	bind(t, "TextColor3", "TEXT")
	bind(t, "PlaceholderColor3", "SUB")
	bind(t, "Font", "FONT")
	new("UIPadding", { PaddingLeft = UDim.new(0, 5), PaddingRight = UDim.new(0, 5) }, t)
	rounded(t)
	return t
end

local function makeRow(host, pos, size, defs)
	local row = new("Frame", { Position = pos, Size = size, BackgroundTransparency = 1 }, host)
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder }, row)
	local total = 0
	for _, d in ipairs(defs) do total += (d.w or 1) end
	local gaps = 3 * (#defs - 1)
	local out = {}
	for i, d in ipairs(defs) do
		local frac = (d.w or 1) / total
		local b
		if d.box then
			b = L.textbox(row, d.box)
			if d.fn then
				b.FocusLost:Connect(function(enter)
					local ok, err = pcall(d.fn, b, enter)
					if not ok then setStatus("Error: " .. tostring(err)) end
				end)
			end
		else
			b = button(row, d.text, d.color)
			b.TextScaled = true
			new("UITextSizeConstraint", { MaxTextSize = 15, MinTextSize = 8 }, b)
			b.MouseButton1Click:Connect(function()
				if not d.fn then return end
				local ok, err = pcall(d.fn, b)
				if not ok then
					warn("[UI Copier] " .. tostring(err))
					setStatus("Error: " .. tostring(err))
				end
			end)
		end
		b.LayoutOrder = i
		b.Size = UDim2.new(frac, -gaps * frac, 1, 0)
		out[d.key or i] = b
	end
	return out
end

local armedBtns = setmetatable({}, { __mode = "k" })
function L.confirmTap(b, idle, run)
	if armedBtns[b] then
		armedBtns[b] = nil
		b.Text = idle
		return run()
	end
	armedBtns[b] = true
	b.Text = "Sure?"
	task.delay(2.5, function()
		if armedBtns[b] then
			armedBtns[b] = nil
			if b.Parent then b.Text = idle end
		end
	end)
end

local function selectable(box)
	local H = { cur = 1 }
	local function track()
		local s, c = box.SelectionStart, box.CursorPosition
		if c <= 0 then return end
		H.cur = c
		if s > 0 and s ~= c then
			H.s, H.e = math.min(s, c), math.max(s, c)
		else
			H.s, H.e = nil, nil
		end
	end
	table.insert(S.conns, box:GetPropertyChangedSignal("SelectionStart"):Connect(track))
	table.insert(S.conns, box:GetPropertyChangedSignal("CursorPosition"):Connect(track))
	table.insert(S.conns, box:GetPropertyChangedSignal("Text"):Connect(function() H.s, H.e = nil, nil end))
	function H.apply(s, e)
		local function set()
			pcall(function()
				box.CursorPosition = e
				box.SelectionStart = s
			end)
			H.s, H.e = s, e
		end
		pcall(function() box:CaptureFocus() end)
		set()
		task.delay(0.06, function()
			if S.alive then set() end
		end)
	end
	function H.text()
		if H.s and H.e and H.e > H.s then return box.Text:sub(H.s, H.e - 1) end
		return nil
	end
	function H.all()
		H.apply(1, #box.Text + 1)
	end
	function H.word()
		local t, c = box.Text, H.cur or 1
		local s = c
		while s > 1 and t:sub(s - 1, s - 1):match("[%w_]") do s -= 1 end
		local e = c
		while e <= #t and t:sub(e, e):match("[%w_]") do e += 1 end
		if e > s then H.apply(s, e) end
	end
	function H.line()
		local t, c = box.Text, H.cur or 1
		local s = c
		while s > 1 and t:sub(s - 1, s - 1) ~= "\n" do s -= 1 end
		local e = c
		while e <= #t and t:sub(e, e) ~= "\n" do e += 1 end
		H.apply(s, e)
	end
	return H
end

function L.selBar(parent, pos, H)
	return makeRow(parent, pos, UDim2.new(1, 0, 0, 22), {
		{ text = "Select all", fn = function() H.all() end },
		{ text = "Word", fn = function() H.word() end },
		{ text = "Line", fn = function() H.line() end },
		{ text = "Copy sel", color = "GREEN", fn = function()
			local t = H.text()
			if not t or t == "" then
				return setStatus("Nothing selected. Tap in the text, then use Word or Line.")
			end
			copyText(t, "Copied " .. #t .. " selected characters.")
		end },
	})
end

function L.clampOnScreen(f)
	if L.hosted and f.Name == "PanelHosted" then return end
	local v = viewport()
	local ap, as = f.AbsolutePosition, f.AbsoluteSize
	local dx, dy = 0, 0
	if f.Name == "Panel" then
		local keep = 80
		if ap.X + as.X < keep then dx = keep - (ap.X + as.X) elseif ap.X > v.X - keep then dx = (v.X - keep) - ap.X end
		if ap.Y < 0 then dy = -ap.Y elseif ap.Y > v.Y - 30 then dy = (v.Y - 30) - ap.Y end
	else
		if ap.X < 0 then dx = -ap.X elseif ap.X + as.X > v.X then dx = v.X - (ap.X + as.X) end
		if ap.Y < 0 then dy = -ap.Y elseif ap.Y + as.Y > v.Y then dy = v.Y - (ap.Y + as.Y) end
	end
	if dx ~= 0 or dy ~= 0 then
		local p = f.Position
		f.Position = UDim2.new(p.X.Scale, p.X.Offset + dx, p.Y.Scale, p.Y.Offset + dy)
	end
end

