			b.TextSize = HOST and 13 or 11
		if HOST then
			b.BorderSizePixel = 0
			b.Size = UDim2.new(1 / #TABS, 0, 1, 0)
			b.Position = UDim2.new((i - 1) / #TABS, 0, 0, 0)
			local hl = new("Frame", { Name = "Hl", Size = UDim2.new(1, 0, 0, 2), Position = UDim2.new(0, 0, 1, -2), BorderSizePixel = 0, Visible = false }, b)
			bind(hl, "BackgroundColor3", "SEL")
		end
		tabBtns[name] = b
	pages[name] = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false }, body)
	b.MouseButton1Click:Connect(function() showTab(name) end)
end

function L.paintTab(n)
	local b = tabBtns[n]
	if not b then return end
	local on = n == S.tab
	if HOST then
		paint(b, on and "BG" or "TITLE")
		local hl = b:FindFirstChild("Hl")
		if hl then hl.Visible = on end
	else
		paint(b, on and "SEL" or "BTN")
	end
end

