function L.pushUndo(o, name, old)
	S.undo[#S.undo + 1] = { o = o, name = name, old = old }
	if #S.undo > 100 then table.remove(S.undo, 1) end
end

local function setValue(o, name, val)
	local okR, old = pcall(function() return o[name] end)
	local ok = pcall(function() o[name] = val end)
	if ok and okR then L.pushUndo(o, name, old) end
	return ok
end

function L.afterEdit(name)
	if name == "Name" or name == "Text" then
		refreshInfo()
		refreshList()
	end
end

