			local o = S.sel
			if not o then return setStatus("Pick something first.") end
			local p = o.Parent
			pcall(function() o:Destroy() end)
			for i = #S.stack, 1, -1 do
				if S.stack[i] == o then table.remove(S.stack, i) end
