function L.buildPropRow(o, name, v, s, idx, rowH, changed)
	local t = typeof(v)
	local row = new("Frame", {
		Size = UDim2.new(1, -6, 0, rowH), BorderSizePixel = 0, LayoutOrder = idx,
		BackgroundColor3 = (idx % 2 == 0) and T.ROW1 or T.ROW2,
	}, propScroll)
	new("TextLabel", {
		Size = UDim2.new(0.4, -4, 1, 0), Position = UDim2.new(0, 4, 0, 0), BackgroundTransparency = 1, Font = T.FONT,
		TextSize = cfg.textSize - 1, TextColor3 = changed and T.TEXT or T.SUB, TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd, Text = name,
	}, row)
	local cell = new("Frame", { Size = UDim2.new(0.6, -4, 1, -4), Position = UDim2.new(0.4, 0, 0, 2), BackgroundTransparency = 1 }, row)

	if t == "boolean" then
		local b = new("TextButton", {
			Size = UDim2.new(1, 0, 1, 0), AutoButtonColor = false, BorderSizePixel = 0, Font = T.FONT, TextSize = cfg.textSize,
			Text = tostring(v), BackgroundColor3 = v and T.GREEN or T.BTN, TextColor3 = v and T.ONACC or T.TEXT,
		}, cell)
		b.MouseButton1Click:Connect(function()
			local okR, cur = pcall(function() return o[name] end)
			if not okR then return end
			if setValue(o, name, not cur) then
				local nv = o[name]
				b.Text = tostring(nv)
				b.BackgroundColor3 = nv and T.GREEN or T.BTN
				b.TextColor3 = nv and T.ONACC or T.TEXT
				L.afterEdit(name)
				setStatus("Set " .. name .. " = " .. tostring(nv))
			else
				setStatus("Could not set " .. name)
			end
		end)
		return
	end

	local left, right = 0, 0
	local swatch
	if t == "Color3" then
		left = 20
		swatch = new("Frame", { Size = UDim2.new(0, 16, 1, 0), BackgroundColor3 = v, BorderSizePixel = 0 }, cell)
		bind(new("UIStroke", { Thickness = 1 }, swatch), "Color", "LINE")
	end
	local enumBtn, moreBtn
	if t == "EnumItem" then
		right = 24
		enumBtn = new("TextButton", {
			Size = UDim2.new(0, 22, 1, 0), Position = UDim2.new(1, -22, 0, 0), BorderSizePixel = 0, AutoButtonColor = false,
			Text = ">", Font = T.FONT, TextSize = cfg.textSize, BackgroundColor3 = T.BTN, TextColor3 = T.TEXT,
		}, cell)
	elseif t == "string" and (name == "Text" or name == "PlaceholderText") then
		right = 24
		moreBtn = new("TextButton", {
			Size = UDim2.new(0, 22, 1, 0), Position = UDim2.new(1, -22, 0, 0), BorderSizePixel = 0, AutoButtonColor = false,
			Text = "...", Font = T.FONT, TextSize = cfg.textSize, BackgroundColor3 = T.BTN, TextColor3 = T.TEXT,
		}, cell)
	end
	local tb = new("TextBox", {
		Size = UDim2.new(1, -(left + right), 1, 0), Position = UDim2.new(0, left, 0, 0), BorderSizePixel = 0,
		ClearTextOnFocus = false, Text = s, TextSize = cfg.textSize - 1, Font = T.FONT, TextColor3 = T.TEXT,
		BackgroundColor3 = T.CODE, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
		TextEditable = not L.READONLY[t],
	}, cell)
	local shownText = s
	local function reload()
		local okN, nv = pcall(function() return o[name] end)
		if okN and nv ~= nil then
			shownText = lit(nv) or tostring(nv)
			tb.Text = shownText
			if swatch and typeof(nv) == "Color3" then swatch.BackgroundColor3 = nv end
		end
	end
	tb.FocusLost:Connect(function()
		if tb.Text == shownText then return end
		local okR, cur = pcall(function() return o[name] end)
		if not okR then return end
		local okP, val = L.parseValue(cur, tb.Text)
		if not okP then
			setStatus(name .. ": " .. tostring(val))
			reload()
			return
		end
		if setValue(o, name, val) then
			setStatus("Set " .. name)
			L.afterEdit(name)
		else
			setStatus("Could not set " .. name)
		end
		reload()
	end)
	if enumBtn then
		enumBtn.MouseButton1Click:Connect(function()
			local okR, cur = pcall(function() return o[name] end)
			if not okR then return end
			local items = cur.EnumType:GetEnumItems()
			local nxt = items[1]
			for i, it in ipairs(items) do
				if it == cur then
					nxt = items[(i % #items) + 1]
					break
				end
			end
			if setValue(o, name, nxt) then
				reload()
				L.afterEdit(name)
				setStatus(name .. " = " .. tostring(nxt))
			end
		end)
	end
	if moreBtn then
		moreBtn.MouseButton1Click:Connect(function()
			local okR, cur = pcall(function() return o[name] end)
			if not okR then return end
			openEditor("Edit " .. name .. " of " .. o.Name, cur, function(newText)
				if setValue(o, name, newText) then
					setStatus("Set " .. name)
					L.afterEdit(name)
					reload()
				end
			end)
		end)
	end
end

function refreshProps()
	for _, c in ipairs(propScroll:GetChildren()) do
		if c:IsA("Frame") then c:Destroy() end
	end
	local rawShown = P.view == "Raw"
	propScroll.Visible = not rawShown
	L.rawHost.Visible = rawShown
	for _, b in pairs(L.rawBar) do b.Parent.Visible = rawShown break end
	local o = S.sel
	if not o or not o.Parent then
		L.propHead.Text = "Nothing picked. Use the Pick tab first."
		rawBox.Text = ""
		return
	end
	local rowH = cfg.textSize + 12
	local raw, shown = {}, 0
	local fl = P.filter:lower()
	for _, name in ipairs(L.propNames(o)) do
		local ok, v = pcall(function() return o[name] end)
		local s = (ok and v ~= nil) and lit(v) or nil
		if s and (fl == "" or name:lower():find(fl, 1, true)) then
			local changed = L.isChanged(o, name, s)
			if not P.changed or changed then
				shown += 1
				raw[#raw + 1] = name .. " = " .. s
				if not rawShown then L.buildPropRow(o, name, v, s, shown, rowH, changed) end
			end
		end
	end
	rawBox.Text = table.concat(raw, "\n")
	L.propHead.Text = o.Name .. "  (" .. o.ClassName .. ")  " .. shown .. " properties"
end

