function L.plainReplace(s, q, r, case)
	if q == "" then return s end
	local hay = case and s or s:lower()
	local nq = case and q or q:lower()
	local out, i = {}, 1
	while true do
		local a, b = hay:find(nq, i, true)
		if not a then break end
		out[#out + 1] = s:sub(i, a - 1)
		out[#out + 1] = r
		i = b + 1
	end
	out[#out + 1] = s:sub(i)
	return table.concat(out)
end

