function L.isShown(o)
	local p = o
	while p do
		if isA(p, "GuiObject") and not p.Visible then return false end
		if isA(p, "LayerCollector") and p.Enabled == false then return false end
		p = p.Parent
	end
	return true
end

function L.fieldsOf(o, by)
	local f = {}
	local isText = isA(o, "TextLabel") or isA(o, "TextButton") or isA(o, "TextBox")
	local isImg = isA(o, "ImageLabel") or isA(o, "ImageButton")
	if (by == "Text" or by == "Any") and isText then f[#f + 1] = o.Text end
	if by == "Name" or by == "Any" then f[#f + 1] = o.Name end
	if by == "Class" or by == "Any" then f[#f + 1] = o.ClassName end
	if (by == "Image" or by == "Any") and isImg then f[#f + 1] = o.Image end
	return f
end

function renderResults()
	for _, c in ipairs(fres:GetChildren()) do
		if c:IsA("GuiButton") then c:Destroy() end
	end
	for i, r in ipairs(F.results) do
		if i > 200 then break end
		local o = r.o
		local snippet = tostring(r.f):gsub("[\r\n]+", " ")
		if #snippet > 40 then snippet = snippet:sub(1, 40) .. ".." end
		local row = new("TextButton", {
			Size = UDim2.new(1, -6, 0, HOST and 20 or 22), BorderSizePixel = 0, AutoButtonColor = false, TextSize = 14, Font = T.FONT,
			BackgroundColor3 = (i % 2 == 0) and T.ROW1 or T.ROW2, TextColor3 = T.TEXT, TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd, RichText = true, LayoutOrder = i,
			Text = string.format('%s  <font color="#b9b9b9">%s: %s</font>', esc(o.Name), esc(o.ClassName), esc(snippet)),
		}, fres)
		new("UIPadding", { PaddingLeft = UDim.new(0, 6) }, row)
		row.MouseButton1Click:Connect(function()
			if o and o.Parent then
				selectObj(o)
				flash(o)
			else
				setStatus("That object is gone.")
			end
		end)
	end
end

function runSearch()
	local q = fa.q.Text
	if q == "" and F.by ~= "Text" then
		F.results = {}
		renderResults()
		return setStatus("Type something to search.")
	end
	local roots = {}
	if F.scope == "Picked" then
		if S.sel then roots = { S.sel } end
	else
		roots = { L.playerGui }
		if F.scope == "Core+Gui" then roots[#roots + 1] = CoreGui end
	end
	local qq = F.case and q or q:lower()
	local res = {}
	local function consider(o)
		if o == ui or o:GetAttribute(MARK_ATTR) or o:IsDescendantOf(ui) then return end
		for _, s in ipairs(L.fieldsOf(o, F.by)) do
			local hit
			if q == "" then
				hit = s ~= ""
			else
				local hay = F.case and s or s:lower()
				if F.exact then hit = (hay == qq) else hit = hay:find(qq, 1, true) ~= nil end
			end
			if hit then
				if F.vis and isA(o, "GuiObject") and not L.isShown(o) then return end
				res[#res + 1] = { o = o, f = s }
				return
			end
		end
	end
	for _, r in ipairs(roots) do
		consider(r)
		local ok, desc = pcall(function() return r:GetDescendants() end)
		if ok then
			for _, d in ipairs(desc) do
				consider(d)
				if #res >= 500 then break end
			end
		end
	end
	F.results = res
	renderResults()
	setStatus(#res .. " found" .. (#res >= 500 and " (stopped at 500)" or "") .. (#res > 200 and ", showing 200" or ""))
end

