function L.codeText()
	if V.truncated and codeBox.Text == V.shown then return V.full end
	return codeBox.Text
end

local ca, cb, cc, cd
function L.updFindCount()
	if cb and cb.count then
		cb.count.Text = (#V.matches == 0) and "0/0" or (V.mi .. "/" .. #V.matches)
	end
end

local function codeFindAll()
	V.matches = {}
	V.mi = 0
	local q = cb and cb.find.Text or ""
	if q ~= "" then
		local hay, nq = codeBox.Text, q
		if not V.case then hay, nq = hay:lower(), q:lower() end
		local i = 1
		while true do
			local s = hay:find(nq, i, true)
			if not s then break end
			V.matches[#V.matches + 1] = s
			i = s + #nq
			if #V.matches >= 2000 then break end
		end
	end
	L.updFindCount()
end

function L.codeJump(idx)
	if #V.matches == 0 then return setStatus("No matches.") end
	if idx < 1 then idx = #V.matches end
	if idx > #V.matches then idx = 1 end
	V.mi = idx
	local s = V.matches[idx]
	local e = s + #cb.find.Text
	local txt = codeBox.Text
	local _, before = txt:sub(1, s - 1):gsub("\n", "")
	local _, total = txt:gsub("\n", "")
	local lineH = codeBox.TextBounds.Y / (total + 1)
	codeHost.CanvasPosition = Vector2.new(0, math.max(0, before * lineH - 24))
	L.codeSel.apply(s, e)
	L.updFindCount()
end

function setCodeText(text)
	V.full = text
	local shown = text
	if #shown > L.CODE_CUT then
		shown = shown:sub(1, L.CODE_CUT) .. "\n-- (cut here: Copy all has the full text)"
		V.truncated = true
	else
		V.truncated = false
	end
	V.shown = shown
	codeBox.Text = shown
	codeHost.CanvasPosition = Vector2.new(0, 0)
	codeFindAll()
end

function L.spawnCode(txt)
	if not loadstring then return setStatus("This executor has no loadstring.") end
	local fn, err = loadstring(txt)
	if not fn then return setStatus("Could not load: " .. tostring(err)) end
	local ok, res = pcall(fn)
	if ok and typeof(res) == "Instance" then
		setSpawn(res)
		setStatus("Ran it. The result is spawned (press Spawn/Remove to remove it).")
	elseif ok then
		setStatus("Ran it.")
	else
		setStatus("Run failed: " .. tostring(res))
	end
end

