		local ok, d = pcall(function() return HttpService:JSONDecode(txt) end)
		if not ok or type(d) ~= "table" then return setStatus("That text is not valid JSON.") end
		local items = (d.data ~= nil) and { d } or d
		local added = 0
		for _, e in ipairs(items) do
			if type(e) == "table" and type(e.data) == "table" then
				local p = e.data
				local good = false
				if p.k == "text" and type(p.text) == "string" then
					good = true
				elseif p.k == "ui" and L.unpackNodes(p) then
					good = true
				end
				if good then
					local id = L.addEntry(L.uniqueName(tostring(e.name or "Imported")), p.k, tostring(e.class or p.cl or ""), tonumber(e.n) or 0, p)
					if id then added += 1 end
				end
			end
		end
		setStatus(added > 0 and ("Imported " .. added .. " save(s). Only import JSON you trust.") or "Nothing valid to import.")
		refreshSaved()
	end },
})
