function L.entryCode(id)
	local p = Store.get(id)
	if not p then return nil, "Could not read that save." end
	if p.k == "text" then return tostring(p.text or ""), nil, p end
	local nodes = L.unpackNodes(p)
	if not nodes then return nil, "That save is damaged or not safe." end
	local meta = { name = p.nm or "UI", class = p.cl or "Frame", skipped = p.sk or {}, truncated = false, adornee = p.ad and true or false }
	return L.codeFrom(nodes, meta, S.opts), nil, p
end

