function refreshSaved()
	for _, c in ipairs(L.svList:GetChildren()) do
		if c:IsA("GuiButton") then c:Destroy() end
	end
	local fl = SV.filter:lower()
	local shown = 0
	for _, it in ipairs(Store.index) do
		local nm = tostring(it.name or "?")
		if fl == "" or nm:lower():find(fl, 1, true) then
			shown += 1
			local info
			if it.kind == "ui" then
				info = string.format("%s, %d obj, %s, %s", tostring(it.class or ""), tonumber(it.n) or 0, fmtSize(it.sz), ago(it.t))
			else
				info = string.format("text, %s, %s", fmtSize(it.sz), ago(it.t))
			end
			local row = new("TextButton", {
				Size = UDim2.new(1, -6, 0, HOST and 20 or 22), BorderSizePixel = 0, AutoButtonColor = false, TextSize = 14, Font = T.FONT,
				BackgroundColor3 = (it.id == SV.sel) and T.SEL or ((shown % 2 == 0) and T.ROW1 or T.ROW2),
				TextColor3 = (it.id == SV.sel) and T.ONACC or T.TEXT, TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd, RichText = true, LayoutOrder = shown,
				Text = string.format('%s  <font color="#b9b9b9">%s</font>', esc(nm), esc(info)),
			}, L.svList)
			new("UIPadding", { PaddingLeft = UDim.new(0, 6) }, row)
			row.MouseButton1Click:Connect(function()
				SV.sel = it.id
				sc.name.Text = nm
				refreshSaved()
			end)
		end
	end
	local sel = SV.sel and findItem(SV.sel)
	if sel then
		L.svMeta.Text = string.format("%s  |  %s  |  %s", tostring(sel.name), fmtSize(sel.sz), ago(sel.t))
	else
		L.svMeta.Text = string.format("%d saved  |  %s", #Store.index, hasFS and ("files in " .. DIR .. "/") or "memory only (no file support)")
	end
end

function saveSelected()
	if not S.sel then return setStatus("Pick something first.") end
	local nodes, meta = L.buildNodes(S.sel, S.opts)
	local p = pack(nodes)
	p.v = 1
	p.k = "ui"
	p.nm = meta.name
	p.cl = meta.class
	p.ad = meta.adornee or nil
	p.sk = meta.skipped
	local id, err = L.addEntry(L.uniqueName(meta.name), "ui", meta.class, #nodes, p)
	if id then
		SV.sel = id
		local it = findItem(id)
		setStatus("Saved " .. meta.name .. " (" .. #nodes .. " objects, " .. fmtSize(it and it.sz) .. ").")
		refreshSaved()
	else
		setStatus(err)
	end
end

