function refreshSettingsUI()
	for _, s in pairs(setUI) do
		if s.b and s.b.Parent then s.b.Text = s.get() end
	end
end

function setStatus(msg)
	L.status.Text = tostring(msg)
end

function copyText(text, okMsg)
	local fn = setclipboard or toclipboard or (Clipboard and Clipboard.set)
	if fn then
		local ok = pcall(fn, text)
		if ok then return L.toast(okMsg) end
	end
	setStatus("No clipboard in this executor. Copy it by hand from the box.")
	openEditor("Copy by hand", text, nil)
end

function genAll(root)
	local nodes, meta = L.buildNodes(root, S.opts)
	return L.codeFrom(nodes, meta, S.opts), nodes, meta
end

function setSpawn(inst)
	if S.spawned then
		pcall(function() S.spawned:Destroy() end)
		S.spawned = nil
	end
	S.spawned = inst
	local on = inst ~= nil
	pickSpawn.Text = on and "Remove copy" or "Spawn copy"
	paint(pickSpawn, on and "DANGER" or "SEL")
	svSpawnBtn.Text = on and "Remove" or "Spawn"
	paint(svSpawnBtn, on and "DANGER" or "SEL")
end

function setMark(slot, obj, color)
	local cur = S.marks[slot]
	if cur and cur.obj == obj then return end
	if cur then
		pcall(function() cur.stroke:Destroy() end)
		S.marks[slot] = nil
	end
	if not obj or not isA(obj, "GuiObject") then return end
	local ok, st = pcall(function()
		local s = Instance.new("UIStroke")
		s.Name = "Mark"
		s.Color = color
		s.Thickness = 2
		s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		s:SetAttribute(MARK_ATTR, true)
		s.Parent = obj
		return s
	end)
	if ok then S.marks[slot] = { obj = obj, stroke = st } end
end

function flash(o)
	if not o or not isA(o, "GuiObject") then return end
	task.spawn(function()
		local ok, st = pcall(function()
			local s = Instance.new("UIStroke")
			s.Name = "Flash"
			s.Color = Color3.fromRGB(255, 60, 60)
			s.Thickness = 4
			s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			s:SetAttribute(MARK_ATTR, true)
			s.Parent = o
			return s
		end)
		if not ok then return end
		for _ = 1, 3 do
			task.wait(0.18)
			pcall(function() st.Enabled = false end)
			task.wait(0.18)
			pcall(function() st.Enabled = true end)
		end
		pcall(function() st:Destroy() end)
	end)
end

function refreshInfo()
	if not S.sel then
		infoBox.Text = "Press Click mode (or Tap in the title bar), then tap any UI on the screen."
		return
	end
	local parts = {}
	for _, kv in ipairs(details(S.sel)) do
		parts[#parts + 1] = kv[1] .. ": " .. kv[2]
	end
	infoBox.Text = table.concat(parts, "\n")
	L.infoHost.CanvasPosition = Vector2.new(0, 0)
end

function L.rootList()
	local r = {}
	local function addFrom(container)
		local ok, kids = pcall(function() return container:GetChildren() end)
		if not ok then return end
		for _, c in ipairs(kids) do
			if c ~= ui and not c:GetAttribute(MARK_ATTR) and isA(c, "LayerCollector") then r[#r + 1] = c end
		end
	end
	addFrom(L.playerGui)
	if S.opts.core then addFrom(CoreGui) end
	return r
end

function refreshList()
	for _, c in ipairs(list:GetChildren()) do
		if c:IsA("GuiButton") then c:Destroy() end
	end
	local items
	if S.mode == "children" then
		items = S.sel and L.realKids(S.sel) or {}
	elseif S.mode == "roots" then
		items = L.rootList()
	else
		items = S.stack
	end
	modeBtn.Text = "List: " .. ({ layers = "Layers", children = "Children", roots = "Roots" })[S.mode]
	for i, o in ipairs(items) do
		if i > 300 then break end
		local extra = ""
		if isA(o, "TextLabel") or isA(o, "TextButton") or isA(o, "TextBox") then
			local t = o.Text:gsub("[\r\n]+", " ")
			if #t > 24 then t = t:sub(1, 24) .. ".." end
			if t ~= "" then extra = ': "' .. t .. '"' end
		end
		local row = new("TextButton", {
			Size = UDim2.new(1, -6, 0, HOST and 20 or 22), BorderSizePixel = 0, AutoButtonColor = false, TextSize = 14, Font = T.FONT,
			BackgroundColor3 = (o == S.sel) and T.SEL or (i % 2 == 0 and T.ROW1 or T.ROW2),
			TextColor3 = (o == S.sel) and T.ONACC or T.TEXT, TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd, RichText = true, LayoutOrder = i,
			Text = string.format('%s  <font color="#b9b9b9">%s%s</font>', esc(o.Name), esc(o.ClassName), esc(extra)),
		}, list)
		new("UIPadding", { PaddingLeft = UDim.new(0, 6) }, row)
		row.MouseButton1Click:Connect(function()
			if S.mode == "roots" then S.mode = "children" end
			selectObj(o)
		end)
	end
end

function selectObj(o)
	S.sel = o
	setMark("sel", o, Color3.fromRGB(60, 150, 255))
	if #S.stack == 0 then S.mode = "children" end
	refreshList()
	refreshInfo()
	if S.tab == "Props" then refreshProps() end
	setStatus("Picked " .. o.Name .. " (" .. o.ClassName .. ")")
end

function L.hitTest(x, y)
	local res, seen = {}, {}
	local function add(l)
		for _, o in ipairs(l) do
			local skip = o:IsDescendantOf(ui)
			if not skip then
				for ign in pairs(S.ignore) do
					if o == ign or o:IsDescendantOf(ign) then skip = true break end
				end
			end
			if not seen[o] and not skip then
				seen[o] = true
				res[#res + 1] = o
			end
		end
	end
	local ok, l = pcall(function() return L.playerGui:GetGuiObjectsAtPosition(x, y) end)
	if ok then add(l) end
	if S.opts.core then
		local ok2, l2 = pcall(function() return CoreGui:GetGuiObjectsAtPosition(x, y) end)
		if ok2 then add(l2) end
	end
	return res
end

local CAS = cloneref(game:GetService("ContextActionService"))
local SINK_NAME = "UICopierSink"
local function setSink(on)
	pcall(function() CAS:UnbindAction(SINK_NAME) end)
	if on then
		pcall(function()
			CAS:BindActionAtPriority(SINK_NAME, function() return Enum.ContextActionResult.Sink end, false, 3000000,
				Enum.UserInputType.Touch, Enum.UserInputType.MouseButton1, Enum.UserInputType.MouseButton2, Enum.UserInputType.MouseWheel)
		end)
	end
end

function setClick(on)
	S.click = on
	L.overlay.Visible = on
	L.overlay.Active = on
	L.overlay.Modal = on
	setSink(on)
	hint.Visible = on
	paint(navRow.click, on and "DANGER" or "SEL")
	navRow.click.Text = on and "Cancel" or "Click mode"
	if not on then setMark("hover", nil) L.selectMode = false L.areaMode = false end
	if on then
		hint.Text = L.areaMode and "Area mode: tap corners (2 = box, 3+ = shape)" or (L.selectMode and "Select mode: tap parts to add or remove them" or "Tap the UI you want to copy")
		setStatus("Click mode on.")
	end
end

function updIgnore()
	local n = 0
	for _ in pairs(S.ignore) do n += 1 end
	navRow.ign.Text = n > 0 and ("Ignore " .. n) or "Ignore"
	if setUI.ign then setUI.ign.b.Text = setUI.ign.get() end
end

function showTab(name)
	S.tab = name
	for n, p in pairs(pages) do p.Visible = (n == name) end
	for n in pairs(tabBtns) do L.paintTab(n) end
	if name == "Props" then
		refreshProps()
	elseif name == "Saved" then
		refreshSaved()
	elseif name == "Set" then
		refreshSettingsUI()
	end
end

function setTextSize(n)
	cfg.textSize = math.clamp(n, 10, 22)
	infoBox.TextSize = cfg.textSize
	rawBox.TextSize = cfg.textSize
	if S.tab == "Props" then refreshProps() end
	refreshSettingsUI()
	scheduleSave()
end

L.saveToken = 0
function scheduleSave()
	L.saveToken += 1
	local my = L.saveToken
	task.delay(1, function()
		if my == L.saveToken and S.alive then L.saveSettingsNow() end
	end)
end

function applyTheme()
	L.rebuildTheme()
	for o, m in pairs(reg) do
		pcall(function()
			for prop, rn in pairs(m) do
				local v = T[rn]
				o[prop] = v
				if prop == "BackgroundColor3" and o:GetAttribute("base") ~= nil then o:SetAttribute("base", v) end
			end
		end)
	end
	for c in pairs(L.corners) do
		pcall(function() c.CornerRadius = UDim.new(0, HOST and 0 or cfg.corner) end)
	end
	panel.BackgroundTransparency = cfg.alpha
	infoBox.TextSize = cfg.textSize
	rawBox.TextSize = cfg.textSize
	for _, name in ipairs(TABS) do L.paintTab(name) end
	paint(navRow.click, S.click and "DANGER" or "SEL")
	paint(pickSpawn, S.spawned and "DANGER" or "SEL")
	paint(svSpawnBtn, S.spawned and "DANGER" or "SEL")
	refreshList()
	refreshSaved()
	renderResults()
	if S.tab == "Props" then refreshProps() end
	refreshSettingsUI()
end

function relayout()
	if HOST then return end
	panel.Size = UDim2.fromOffset(W, H)
end

function setMini(on)
	if HOST then return end
	S.mini = on
	if on then
		local ap = panel.AbsolutePosition
		mini.Position = UDim2.fromOffset(ap.X, ap.Y)
		panel.Visible = false
		mini.Visible = true
		L.clampOnScreen(mini)
	else
		local ap = mini.AbsolutePosition
		panel.Position = UDim2.fromOffset(ap.X, ap.Y)
		mini.Visible = false
		panel.Visible = true
		L.clampOnScreen(panel)
	end
end

table.insert(S.conns, L.overlay.InputChanged:Connect(function(input)
	if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
	local stack = L.hitTest(input.Position.X, input.Position.Y)
	local top = stack[1]
	if cfg.hover then
		if top and top ~= S.sel then setMark("hover", top, Color3.fromRGB(255, 170, 60)) else setMark("hover", nil) end
	end
	hint.Text = top and (top.Name .. "  (" .. top.ClassName .. ")") or "Nothing here"
end))

table.insert(S.conns, L.overlay.InputBegan:Connect(function(input)
	if not isPointer(input) then return end
	if L.areaMode and L.areaAdd then
		L.areaAdd(input.Position)
		hint.Text = "Point added. Tap more corners, then Copy area in the Tools tab"
		return
	end
	local stack = L.hitTest(input.Position.X, input.Position.Y)
	if #stack == 0 then
		hint.Text = "Nothing under that spot, try again"
		return
	end
	if L.selectMode and L.multiAdd then
		L.multiAdd(stack[1])
		hint.Text = "Selected: " .. stack[1].Name .. "  (tap more, Cancel when done)"
		return
	end
	S.stack = stack
	S.mode = "layers"
	setClick(false)
	selectObj(stack[1])
	showTab(cfg.after == "Props" and "Props" or "Pick")
end))

do
	local function drag(handle, target, onTap)
		local active, startIn, startPos, moved
		table.insert(S.conns, handle.InputBegan:Connect(function(input)
			if isPointer(input) then
				active = true
				moved = false
				startIn = input.Position
				startPos = target.Position
			end
		end))
		table.insert(S.conns, UserInputService.InputChanged:Connect(function(input)
			if not active then return end
			if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
			local d = input.Position - startIn
			if not moved and d.Magnitude < 6 then return end
			moved = true
			target.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
		end))
		table.insert(S.conns, UserInputService.InputEnded:Connect(function(input)
			if active and isPointer(input) then
				active = false
				if moved then
					L.clampOnScreen(target)
				elseif onTap then
					onTap()
				end
			end
		end))
	end
	if not HOST then drag(titleBar, panel, nil) end
	drag(mini, mini, function() setMini(false) end)

	local resizing, startW, startH, rStart
	table.insert(S.conns, grip.InputBegan:Connect(function(input)
		if isPointer(input) then
			resizing = true
			rStart = input.Position
			startW, startH = W, H
		end
	end))
	table.insert(S.conns, UserInputService.InputChanged:Connect(function(input)
		if not resizing then return end
		if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
		local d = input.Position - rStart
		local v = viewport()
		W = math.clamp(startW + d.X, 250, math.max(250, v.X - 10))
		H = math.clamp(startH + d.Y, 300, math.max(300, v.Y - 10))
		relayout()
	end))
	table.insert(S.conns, UserInputService.InputEnded:Connect(function(input)
		if resizing and isPointer(input) then
			resizing = false
			cfg.W, cfg.H = W, H
			scheduleSave()
		end
	end))
end

table.insert(S.conns, UserInputService.InputBegan:Connect(function(input, gp)
	if gp or not cfg.hotkey then return end
	if input.KeyCode == Enum.KeyCode.RightShift and not HOST then setMini(not S.mini) end
end))

L.tapBtn.MouseButton1Click:Connect(function() setClick(not S.click) end)
L.minBtn.MouseButton1Click:Connect(function() setMini(true) end)
L.closeBtn.MouseButton1Click:Connect(function()
	if cfg.ask then
		modal.Visible = true
	else
		cleanup()
	end
end)

function cleanup()
	pcall(setSink, false)
	if not S.alive then return end
	S.alive = false
	pcall(L.saveSettingsNow)
	setMark("hover", nil)
	setMark("sel", nil)
	for _, c in ipairs(S.conns) do pcall(function() c:Disconnect() end) end
	if S.spawned then pcall(function() S.spawned:Destroy() end) end
	for _, d in pairs(defaults) do
		if d then pcall(function() d:Destroy() end) end
	end
	pcall(function() ui:Destroy() end)
	pcall(function() if L.topGui then L.topGui:Destroy() end end)
	if HOST then pcall(function() panel:Destroy() end) end
	genv.UICopierCleanup = nil
end
genv.UICopierCleanup = cleanup

local function setupTools()
	local GuiService = cloneref(game:GetService("GuiService"))
	local pg = pages.Tools
	function L.deliver(code, name, msg)
		local mode = L.outMode or "Copy"
		if mode ~= "Save" then copyText(code, msg) end
		if mode ~= "Copy" then
			local id, err = L.addEntry(L.uniqueName(name), "text", "text", #code, { v = 1, k = "text", text = code })
			if id then
				pcall(refreshSaved)
				setStatus("Saved in the Saved tab as " .. name .. ".")
			else
				setStatus(err or "Could not save.")
			end
		end
	end
	function L.copyCode(o)
		local opts = table.clone(S.opts)
		opts.desc = true
		local nodes, meta = L.buildNodes(o, opts)
		return L.codeFrom(nodes, meta, opts)
	end
	local scroll = new("ScrollingFrame", {
		Size = UDim2.fromScale(1, 1), BorderSizePixel = 0, ScrollBarThickness = 6, CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
	}, pg)
	new("UIListLayout", { Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder }, scroll)

	local order = 0
	local function nextOrder()
		order += 1
		return order
	end
	local function head(text)
		return label(scroll, text, 14, "SUB", { Size = UDim2.new(1, -6, 0, 18), LayoutOrder = nextOrder() })
	end
	local function rowOf(items, h)
		local row = new("Frame", { Size = UDim2.new(1, -6, 0, h or 26), BackgroundTransparency = 1, LayoutOrder = nextOrder() }, scroll)
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder }, row)
		local total = 0
		for _, it in ipairs(items) do total += (it.w or 1) end
		local made = {}
		for i, it in ipairs(items) do
			local o
			if it.box then
				o = L.textbox(row, it.box)
				o.TextSize = 13
			else
				o = button(row, it.text, it.color or "BTN")
				o.TextSize = 13
				if it.fn then
					o.MouseButton1Click:Connect(function()
						local ok, err = pcall(it.fn, o)
						if not ok then setStatus("Error: " .. tostring(err)) end
					end)
				end
			end
			o.LayoutOrder = i
			o.Size = UDim2.new((it.w or 1) / total, -3, 1, 0)
			made[it.key or i] = o
		end
		return made
	end

	head("List (tree, matches, multi)")
	local resBox = new("ScrollingFrame", {
		Size = UDim2.new(1, -6, 0, 170), BorderSizePixel = 0, ScrollBarThickness = 6, CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y, LayoutOrder = nextOrder(),
	}, scroll)
	bind(resBox, "BackgroundColor3", "CODE")
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, resBox)
	local resIdx = 0
	local function clearRes()
		resIdx = 0
		for _, c in ipairs(resBox:GetChildren()) do
			if c:IsA("GuiObject") then c:Destroy() end
		end
	end
	local function addRes(text, indent, onClick)
		resIdx += 1
		local r = new("TextButton", {
			Size = UDim2.new(1, -4, 0, 22), BorderSizePixel = 0, AutoButtonColor = false, TextSize = 13, Font = T.FONT,
			TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, LayoutOrder = resIdx,
			Text = text, BackgroundColor3 = (resIdx % 2 == 0) and T.ROW1 or T.ROW2, TextColor3 = T.TEXT,
		}, resBox)
		new("UIPadding", { PaddingLeft = UDim.new(0, 4 + (indent or 0) * 12) }, r)
		r.MouseButton1Click:Connect(function()
			local ok, err = pcall(onClick)
			if not ok then setStatus("Error: " .. tostring(err)) end
		end)
		return r
	end

	local function underUI(o)
		return o == ui or o:IsDescendantOf(ui) or o:GetAttribute(MARK_ATTR) ~= nil
	end

	local exp = {}
	local function drawTree()
		clearRes()
		local count = 0
		local function walk(o, depth)
			if count >= 400 then return end
			count += 1
			local kids = L.realKids(o)
			local mark = #kids > 0 and (exp[o] and "- " or "+ ") or "  "
			addRes(mark .. o.Name .. "  (" .. o.ClassName .. ")", depth, function()
				selectObj(o)
				if #kids > 0 then
					exp[o] = not exp[o]
					drawTree()
				end
			end)
			if exp[o] then
				for _, c in ipairs(kids) do walk(c, depth + 1) end
			end
		end
		for _, r in ipairs(L.rootList()) do
			if not underUI(r) then walk(r, 0) end
		end
		if count == 0 then addRes("No UI found.", 0, function() end) end
		setStatus("Tree: " .. count .. " rows. Tap a row to pick and expand.")
	end
	local function setAll(on)
		exp = {}
		if on then
			for _, r in ipairs(L.rootList()) do
				for _, d in ipairs(r:GetDescendants()) do
					if not underUI(d) then exp[d] = true end
				end
				exp[r] = true
			end
		end
		drawTree()
	end
	rowOf({
		{ text = "Tree", color = "SEL", fn = drawTree },
		{ text = "Expand all", fn = function() setAll(true) end },
		{ text = "Collapse all", fn = function() setAll(false) end },
	})

	head("Output and undo history")
	local hist = {}
	local function pushHist(label, fn)
		hist[#hist + 1] = { label, fn }
		if #hist > 50 then table.remove(hist, 1) end
	end
	local function undoLast()
		local e = table.remove(hist)
		if not e then return setStatus("Nothing to undo.") end
		pcall(e[2])
		setStatus("Undid: " .. e[1] .. " (" .. #hist .. " left)")
	end
	local showHist
	showHist = function()
		clearRes()
		for i = #hist, 1, -1 do
			addRes(hist[i][1] .. "  (tap to undo)", 0, function()
				local e = table.remove(hist, i)
				if e then pcall(e[2]) end
				showHist()
			end)
		end
		if #hist == 0 then addRes("History is empty.", 0, function() end) end
	end
	rowOf({
		{ text = "Output: Copy", w = 1.3, fn = function(b)
			local order = { "Copy", "Save", "Both" }
			local idx = table.find(order, L.outMode or "Copy") or 1
			L.outMode = order[idx % #order + 1]
			b.Text = "Output: " .. L.outMode
			setStatus("Area, tool, character, multi and search copies will: " .. L.outMode:lower() .. ".")
		end },
		{ text = "Undo last", fn = undoLast },
		{ text = "History", fn = showHist },
	})

	head("Multi pick")
	local multi = {}
	local function showMulti()
		clearRes()
		for i, o in ipairs(multi) do
			addRes(i .. ". " .. o.Name .. "  (" .. o.ClassName .. ")  tap to remove", 0, function()
				table.remove(multi, i)
				showMulti()
			end)
		end
		setStatus("Multi list: " .. #multi .. " UIs.")
	end
	function L.multiAdd(o)
		for i, x in ipairs(multi) do
			if x == o then
				table.remove(multi, i)
				return setStatus("Removed " .. o.Name .. ". Selected: " .. #multi)
			end
		end
		multi[#multi + 1] = o
		setMark("sel", o, Color3.fromRGB(80, 220, 120))
		setStatus("Selected " .. o.Name .. ". Total: " .. #multi)
	end
	rowOf({
		{ text = "Add picked", color = "GREEN", fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			for _, o in ipairs(multi) do
				if o == S.sel then return setStatus("Already in the multi list.") end
			end
			multi[#multi + 1] = S.sel
			setStatus("Multi list: " .. #multi .. " UIs.")
		end },
		{ text = "Show", fn = showMulti },
		{ text = "Clear", color = "DANGER", fn = function()
			multi = {}
			clearRes()
			setStatus("Multi list cleared.")
		end },
		{ text = "Copy selected", color = "SEL", w = 1.4, fn = function()
			if #multi == 0 then return setStatus("Add some UIs first.") end
			local parts = { "-- UI Copier multi: " .. #multi .. " UIs" }
			local made = 0
			for _, o in ipairs(multi) do
				if o.Parent then
					local ok, code = pcall(L.copyCode, o)
					if ok and code then
						made += 1
						parts[#parts + 1] = "task.spawn(function()\n" .. code .. "\nend)"
					end
				end
			end
			if made == 0 then return setStatus("Nothing left to copy.") end
			L.deliver(table.concat(parts, "\n\n"), "Multi " .. made .. " UIs", "Copied " .. made .. " UIs as one script.")
		end },
	})

	head("Ignore list (left out of copies)")
	local function showIgnore()
		clearRes()
		local n = 0
		for o in pairs(S.ignore) do
			n += 1
			addRes(o.Name .. "  (" .. o.ClassName .. ")  tap to remove", 0, function()
				S.ignore[o] = nil
				pcall(updIgnore)
				showIgnore()
			end)
		end
		setStatus("Ignoring " .. n .. " parts.")
	end
	rowOf({
		{ text = "Ignore picked", color = "DANGER", w = 1.3, fn = function()
			local o = S.sel
			if not o then return setStatus("Pick something first.") end
			if S.ignore[o] then
				S.ignore[o] = nil
				setStatus("No longer ignoring " .. o.Name)
			else
				S.ignore[o] = true
				setStatus("Ignoring " .. o.Name .. ". It will be left out of copies.")
			end
			pcall(updIgnore)
		end },
		{ text = "Show", fn = showIgnore },
		{ text = "Clear", fn = function()
			S.ignore = {}
			pcall(updIgnore)
			clearRes()
			setStatus("Ignore list cleared.")
		end },
	})

	head("Move this panel")
	local function nudge(dx, dy)
		local p = panel.Position
		panel.Position = UDim2.new(p.X.Scale, p.X.Offset + dx, p.Y.Scale, p.Y.Offset + dy)
		L.clampOnScreen(panel)
	end
	rowOf({
		{ text = "Up", fn = function() nudge(0, -60) end },
		{ text = "Down", fn = function() nudge(0, 60) end },
		{ text = "Left", fn = function() nudge(-60, 0) end },
		{ text = "Right", fn = function() nudge(60, 0) end },
		{ text = "Reset", color = "SEL", fn = function()
			local v = viewport()
			panel.Position = UDim2.fromOffset(math.max(5, v.X - panel.AbsoluteSize.X - 10), 30)
		end },
	})

	head("Drag the picked UI")
	local moveOn = false
	local function newHandle(text, color)
		local h = button(ui, text, color)
		h.Size = UDim2.fromOffset(40, 40)
		h.ZIndex = 4
		h.Visible = false
		h.TextSize = 12
		return h
	end
	local moveH = newHandle("Move", "SEL")
	local sizeH = newHandle("Size", "GREEN")
	local function targetGui()
		local o = S.sel
		if o and o.Parent and isA(o, "GuiObject") then return o end
	end
	local function insetY()
		local o = targetGui()
		local sg = o and o:FindFirstAncestorWhichIsA("LayerCollector")
		if sg and sg:IsA("ScreenGui") and not sg.IgnoreGuiInset then
			local ok, i = pcall(function() return GuiService:GetGuiInset() end)
			if ok then return i.Y end
		end
		return 0
	end
	local function drag(handle, apply)
		local active, startIn, base, baseObj
		table.insert(S.conns, handle.InputBegan:Connect(function(input)
			if isPointer(input) and targetGui() then
				active = true
				startIn = input.Position
				base = { pos = targetGui().Position, size = targetGui().Size }
				baseObj = targetGui()
			end
		end))
		table.insert(S.conns, UserInputService.InputChanged:Connect(function(input)
			if not active then return end
			if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
			local t = targetGui()
			if not t then active = false return end
			local d = input.Position - startIn
			apply(t, base, d)
			handle.Position = UDim2.fromOffset(input.Position.X - 20, input.Position.Y - 20)
		end))
		table.insert(S.conns, UserInputService.InputEnded:Connect(function(input)
			if active and isPointer(input) then
				active = false
				local o, b = baseObj, base
				if o and o.Parent and b and (o.Position ~= b.pos or o.Size ~= b.size) then
					pushHist("move or resize " .. o.Name, function() o.Position = b.pos o.Size = b.size end)
				end
			end
		end))
		return function() return active end
	end
	local movingNow = drag(moveH, function(t, b, d)
		t.Position = UDim2.new(b.pos.X.Scale, b.pos.X.Offset + d.X, b.pos.Y.Scale, b.pos.Y.Offset + d.Y)
	end)
	local sizingNow = drag(sizeH, function(t, b, d)
		t.Size = UDim2.new(b.size.X.Scale, math.max(4, b.size.X.Offset + d.X), b.size.Y.Scale, math.max(4, b.size.Y.Offset + d.Y))
	end)
	table.insert(S.conns, game:GetService("RunService").Heartbeat:Connect(function()
		local t = moveOn and targetGui()
		moveH.Visible = t and true or false
		sizeH.Visible = t and true or false
		if not t then return end
		local ap, as = t.AbsolutePosition, t.AbsoluteSize
		local iy = insetY()
		if not movingNow() then moveH.Position = UDim2.fromOffset(ap.X + as.X / 2 - 20, ap.Y + iy + as.Y / 2 - 20) end
		if not sizingNow() then sizeH.Position = UDim2.fromOffset(ap.X + as.X - 20, ap.Y + iy + as.Y - 20) end
	end))
	rowOf({
		{ key = "tog", text = "Handles: off", fn = function(b)
			moveOn = not moveOn
			b.Text = moveOn and "Handles: on" or "Handles: off"
			paint(b, moveOn and "SEL" or "BTN")
			setStatus(moveOn and "Drag Move or Size on the picked UI." or "Handles off.")
		end },
	})

	head("Compare two UIs")
	local cmpA, cmpB
	local function propMap(o)
		local m = {}
		for _, kv in ipairs(L.readProps(o)) do m[kv[1]] = kv[2] end
		return m
	end
	local function diff(a, b, path, out)
		if #out > 400 then return end
		if a.ClassName ~= b.ClassName then out[#out + 1] = path .. ": class A=" .. a.ClassName .. " B=" .. b.ClassName end
		local pa, pb = propMap(a), propMap(b)
		local names = {}
		for k in pairs(pa) do names[k] = true end
		for k in pairs(pb) do names[k] = true end
		local keys = {}
		for k in pairs(names) do keys[#keys + 1] = k end
		table.sort(keys)
		for _, k in ipairs(keys) do
			if k ~= "Name" and pa[k] ~= pb[k] then
				out[#out + 1] = path .. ": " .. k .. "  A=" .. tostring(pa[k] or "(default)") .. "  B=" .. tostring(pb[k] or "(default)")
			end
		end
		local ka, kb = L.realKids(a), L.realKids(b)
		for i = 1, math.max(#ka, #kb) do
			local x, y = ka[i], kb[i]
			if x and y then
				diff(x, y, path .. "/" .. x.Name, out)
			elseif x then
				out[#out + 1] = path .. ": only in A -> " .. x.Name .. " (" .. x.ClassName .. ")"
			else
				out[#out + 1] = path .. ": only in B -> " .. y.Name .. " (" .. y.ClassName .. ")"
			end
		end
	end
	rowOf({
		{ text = "Set A", fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			cmpA = S.sel
			setStatus("A = " .. cmpA.Name)
		end },
		{ text = "Set B", fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			cmpB = S.sel
			setStatus("B = " .. cmpB.Name)
		end },
		{ text = "Compare", color = "SEL", fn = function()
			if not (cmpA and cmpB and cmpA.Parent and cmpB.Parent) then return setStatus("Set A and B first.") end
			local out = {}
			diff(cmpA, cmpB, cmpA.Name, out)
			local text = "A = " .. L.pathOf(cmpA) .. "\nB = " .. L.pathOf(cmpB) .. "\n\n"
			text ..= (#out == 0) and "No differences." or table.concat(out, "\n")
			openEditor("Differences (" .. #out .. ")", text, nil)
		end },
	})

	head("Export")
	local function plainBuilder(root)
		local lines = {
			"-- UI Copier plain Lua builder",
			'local container = (gethui and gethui()) or game:GetService("CoreGui")',
			"local function set(o, k, v) pcall(function() o[k] = v end) end",
			"local n = {}",
		}
		local count = 0
		local parentVar = "container"
		if not isA(root, "LayerCollector") then
			lines[#lines + 1] = 'local holder = Instance.new("ScreenGui")'
			lines[#lines + 1] = 'holder.Name = "UICopy"; holder.ResetOnSpawn = false; holder.Parent = container'
			parentVar = "holder"
		end
		local function emit(o, parent)
			if count >= L.MAX_NODES then return end
			count += 1
			local v = "n[" .. count .. "]"
			lines[#lines + 1] = v .. " = Instance.new(" .. string.format("%q", o.ClassName) .. ")"
			for _, kv in ipairs(L.readProps(o)) do
				lines[#lines + 1] = "set(" .. v .. ", " .. string.format("%q", kv[1]) .. ", " .. kv[2] .. ")"
			end
			lines[#lines + 1] = v .. ".Parent = " .. parent
			for _, c in ipairs(L.realKids(o)) do emit(c, v) end
		end
		emit(root, parentVar)
		return table.concat(lines, "\n"), count
	end
	rowOf({
		{ text = "Plain Lua builder", color = "SEL", w = 1.6, fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			local code, count = plainBuilder(S.sel)
			copyText(code, "Copied builder: " .. count .. " Instance.new objects.")
		end },
		{ text = "To Code tab", fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			local code, count = plainBuilder(S.sel)
			setCodeText(code)
			showTab("Code")
			setStatus("Builder: " .. count .. " objects.")
		end },
	})

	head("Auto reload saved UI")
	local AUTO = DIR .. "/autoload.txt"
	rowOf({
		{ text = "Auto: use selected save", color = "GREEN", w = 1.6, fn = function()
			if not SV.sel then return setStatus("Tap a save in the Saved tab first.") end
			if not writefile then return setStatus("This executor has no writefile.") end
			pcall(function() if makefolder and not isfolder(DIR) then makefolder(DIR) end end)
			writefile(AUTO, tostring(SV.sel))
			setStatus("Saved. Put this script in your autoexec folder so it runs on rejoin.")
		end },
		{ text = "Auto: off", fn = function()
			pcall(function() if isfile and isfile(AUTO) and delfile then delfile(AUTO) end end)
			setStatus("Auto reload is off.")
		end },
	})
	task.spawn(function()
		if not (isfile and readfile) then return end
		local okF, has = pcall(isfile, AUTO)
		if not (okF and has) then return end
		local okR, id = pcall(readfile, AUTO)
		if not okR or not id or id == "" then return end
		task.wait(2)
		if not S.alive then return end
		local code = L.entryCode(id)
		if code then L.spawnCode(code) end
	end)

	head("Images and sounds")
	local ASSET_PROPS = { "Image", "SoundId", "HoverImage", "PressedImage", "TopImage", "MidImage", "BottomImage" }
	local function eachNode(root, fn)
		fn(root)
		for _, d in ipairs(root:GetDescendants()) do fn(d) end
	end
	local assetFrom = rowOf({ { key = "a", box = "old id or text" }, { key = "b", box = "new id or text" } })
	rowOf({
		{ text = "List assets", fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			local seen, out = {}, {}
			eachNode(S.sel, function(o)
				for _, p in ipairs(ASSET_PROPS) do
					local ok, v = pcall(function() return o[p] end)
					if ok and type(v) == "string" and v ~= "" then
						local key = p .. " " .. v
						if not seen[key] then
							seen[key] = true
							out[#out + 1] = o.Name .. "  " .. p .. "  " .. v
						end
					end
				end
			end)
			openEditor("Assets (" .. #out .. ")", #out > 0 and table.concat(out, "\n") or "None found.", nil)
		end },
		{ text = "Remap", color = "SEL", fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			local a, b = assetFrom.a.Text, assetFrom.b.Text
			if a == "" then return setStatus("Type the old id first.") end
			local pat = L.escPat(a)
			local n = 0
			eachNode(S.sel, function(o)
				for _, p in ipairs(ASSET_PROPS) do
					local ok, v = pcall(function() return o[p] end)
					if ok and type(v) == "string" and v:find(pat) then
						local nv = v:gsub(pat, (b:gsub("%%", "%%%%")))
						if pcall(function() o[p] = nv end) then n += 1 end
					end
				end
			end)
			setStatus("Remapped " .. n .. " values.")
		end },
	})

	head("Events")
	local SIGS = { "MouseButton1Click", "MouseButton1Down", "MouseButton1Up", "MouseButton2Click", "Activated", "MouseEnter", "MouseLeave", "TouchTap", "InputBegan", "InputEnded", "FocusLost", "Changed" }
	rowOf({
		{ text = "Dump events to file", color = "SEL", w = 1.6, fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			if not getconnections then return setStatus("This executor has no getconnections.") end
			local out = { "-- events under " .. L.pathOf(S.sel) }
			local total = 0
			eachNode(S.sel, function(o)
				if not isA(o, "GuiObject") then return end
				for _, sigName in ipairs(SIGS) do
					local okS, sig = pcall(function() return o[sigName] end)
					if okS and sig then
						local okC, conns = pcall(getconnections, sig)
						if okC and type(conns) == "table" then
							for _, c in ipairs(conns) do
								total += 1
								local fnv = c.Function
								local src = "?"
								if fnv and debug and debug.getinfo then
									local okI, info = pcall(debug.getinfo, fnv)
									if okI and info then src = tostring(info.short_src or info.source) .. ":" .. tostring(info.linedefined or info.currentline) end
								end
								out[#out + 1] = string.format("%s [%s] enabled=%s fn=%s src=%s", L.pathOf(o), sigName, tostring(c.Enabled), tostring(fnv), src)
							end
						end
					end
				end
			end)
			local text = table.concat(out, "\n")
			if writefile then
				pcall(function() if makefolder and not isfolder(DIR) then makefolder(DIR) end end)
				local file = DIR .. "/events_" .. tostring(S.sel.Name):gsub("[^%w_]", "_") .. ".txt"
				pcall(writefile, file, text)
				setStatus("Dumped " .. total .. " connections to " .. file)
			else
				setStatus("Dumped " .. total .. " connections (no writefile).")
			end
			openEditor("Events (" .. total .. ")", text, nil)
		end },
	})

	head("Find copies")
	local function signature(o)
		return o.ClassName .. "|" .. o.Name .. "|" .. #L.realKids(o) .. "|" .. #o:GetDescendants()
	end
	local function findCopies()
		if not S.sel then return setStatus("Pick something first.") end
		local want = signature(S.sel)
		clearRes()
		local found = 0
		for _, r in ipairs(L.rootList()) do
			if not underUI(r) then
				for _, d in ipairs(r:GetDescendants()) do
					if found >= 200 then break end
					if d ~= S.sel and d.ClassName == S.sel.ClassName and d.Name == S.sel.Name and signature(d) == want then
						found += 1
						addRes(L.pathOf(d), 0, function() selectObj(d) end)
					end
				end
			end
		end
		setStatus("Found " .. found .. " copies of " .. S.sel.Name .. ".")
	end
	rowOf({ { text = "Find copies of picked", color = "SEL", w = 1.6, fn = findCopies } })

	head("Recolor (r,g,b or #hex)")
	local function parseColor(txt)
		local s = txt:gsub("%s", "")
		local h = s:match("^#?(%x%x%x%x%x%x)$")
		if h then
			return Color3.fromRGB(tonumber(h:sub(1, 2), 16), tonumber(h:sub(3, 4), 16), tonumber(h:sub(5, 6), 16))
		end
		local r, g, b = s:match("^(%d+),(%d+),(%d+)$")
		if r then return Color3.fromRGB(math.min(255, tonumber(r)), math.min(255, tonumber(g)), math.min(255, tonumber(b))) end
	end
	local function near(a, b)
		return math.abs(a.R - b.R) < 0.012 and math.abs(a.G - b.G) < 0.012 and math.abs(a.B - b.B) < 0.012
	end
	local COLOR_PROPS = { "BackgroundColor3", "TextColor3", "ImageColor3", "BorderColor3", "TextStrokeColor3", "ScrollBarImageColor3", "PlaceholderColor3", "GroupColor3", "Color" }
	local lastRecolor = {}
	local colBox = rowOf({ { key = "from", box = "from  255,0,0" }, { key = "to", box = "to  #00aaff" } })
	rowOf({
		{ text = "From: picked", fn = function()
			local t = S.sel
			if not t then return setStatus("Pick something first.") end
			for _, p in ipairs(COLOR_PROPS) do
				local ok, v = pcall(function() return t[p] end)
				if ok and typeof(v) == "Color3" then
					colBox.from.Text = string.format("%d,%d,%d", math.floor(v.R * 255 + 0.5), math.floor(v.G * 255 + 0.5), math.floor(v.B * 255 + 0.5))
					return setStatus("From = " .. p .. " of " .. t.Name)
				end
			end
			setStatus("No color found on that object.")
		end },
		{ text = "Recolor all", color = "SEL", fn = function()
			if not S.sel then return setStatus("Pick something first.") end
			local from, to = parseColor(colBox.from.Text), parseColor(colBox.to.Text)
			if not (from and to) then return setStatus("Use r,g,b or #hex in both boxes.") end
			lastRecolor = {}
			local n = 0
			eachNode(S.sel, function(o)
				for _, p in ipairs(COLOR_PROPS) do
					local ok, v = pcall(function() return o[p] end)
					if ok and typeof(v) == "Color3" and near(v, from) then
						if pcall(function() o[p] = to end) then
							lastRecolor[#lastRecolor + 1] = { o, p, v }
							n += 1
						end
					end
				end
				if o:IsA("UIGradient") then
					local seq = o.Color
					local pts, hit = {}, false
					for _, k in ipairs(seq.Keypoints) do
						if near(k.Value, from) then
							hit = true
							pts[#pts + 1] = ColorSequenceKeypoint.new(k.Time, to)
						else
							pts[#pts + 1] = k
						end
					end
					if hit and pcall(function() o.Color = ColorSequence.new(pts) end) then
						lastRecolor[#lastRecolor + 1] = { o, "Color", seq }
						n += 1
					end
				end
			end)
			local snap = lastRecolor
			if n > 0 then pushHist("recolor " .. n .. " values", function() for _, e in ipairs(snap) do pcall(function() e[1][e[2]] = e[3] end) end end) end
			setStatus("Recolored " .. n .. " values. Undo last reverts it.")
		end },
		{ text = "Undo", fn = undoLast },
	})

	head("Preview of a saved UI")
	local pf = new("Frame", { Size = UDim2.new(1, -6, 0, 160), BorderSizePixel = 0, ClipsDescendants = true, LayoutOrder = nextOrder() }, scroll)
	bind(pf, "BackgroundColor3", "CODE")
	rounded(pf)
	local canvas
	local function clearPreview()
		if canvas then canvas:Destroy() canvas = nil end
	end
	rowOf({
		{ text = "Preview selected save", color = "SEL", w = 1.6, fn = function()
			if not SV.sel then return setStatus("Tap a save in the Saved tab first.") end
			if not loadstring then return setStatus("This executor has no loadstring.") end
			local code, err = L.entryCode(SV.sel)
			if not code then return setStatus(err or "Could not read that save.") end
			local fnv, lerr = loadstring(code)
			if not fnv then return setStatus("Could not load: " .. tostring(lerr)) end
			local ok, res = pcall(fnv)
			if not ok or typeof(res) ~= "Instance" then return setStatus("Preview failed.") end
			clearPreview()
			local vp = viewport()
			canvas = new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromOffset(vp.X, vp.Y), ClipsDescendants = true }, pf)
			local sc = new("UIScale", {}, canvas)
			local w = pf.AbsoluteSize.X > 0 and pf.AbsoluteSize.X or 300
			sc.Scale = math.min(w / vp.X, 160 / vp.Y)
			if res:IsA("LayerCollector") then
				for _, c in ipairs(res:GetChildren()) do c.Parent = canvas end
				res:Destroy()
			else
				res.Parent = canvas
			end
			setStatus("Preview ready.")
		end },
		{ text = "Clear", fn = function()
			clearPreview()
			setStatus("Preview cleared.")
		end },
	})

	head("Select area (tap corners, then Done)")
	local areaPts = {}
	local areaLayer = new("Frame", { Name = "AreaLayer", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 3, Active = false, Visible = false }, ui)
	local function insetOf()
		local ok, i = pcall(function() return GuiService:GetGuiInset() end)
		return ok and i.Y or 0
	end
	local function areaShape()
		if #areaPts < 2 then return nil end
		if #areaPts == 2 then
			local a, b = areaPts[1], areaPts[2]
			local x0, x1 = math.min(a.X, b.X), math.max(a.X, b.X)
			local y0, y1 = math.min(a.Y, b.Y), math.max(a.Y, b.Y)
			return { Vector2.new(x0, y0), Vector2.new(x1, y0), Vector2.new(x1, y1), Vector2.new(x0, y1) }
		end
		return areaPts
	end
	local function inPoly(x, y, poly)
		local inside = false
		local j = #poly
		for i = 1, #poly do
			local a, b = poly[i], poly[j]
			if (a.Y > y) ~= (b.Y > y) and x < (b.X - a.X) * (y - a.Y) / (b.Y - a.Y) + a.X then inside = not inside end
			j = i
		end
		return inside
	end
	local function rectOf(o)
		local ap, as = o.AbsolutePosition, o.AbsoluteSize
		local sg = o:FindFirstAncestorWhichIsA("LayerCollector")
		local sy = 0
		if sg and sg:IsA("ScreenGui") and sg.IgnoreGuiInset then sy = -insetOf() end
		return ap.X, ap.Y + sy, as.X, as.Y
	end
	local function isIgnored(o)
		local p = o
		while p do
			if S.ignore[p] then return true end
			p = p.Parent
		end
		return false
	end
	local function collectArea()
		local shape = areaShape()
		if not shape then return nil end
		local minx, miny, maxx, maxy = math.huge, math.huge, -math.huge, -math.huge
		for _, p in ipairs(shape) do
			minx, miny = math.min(minx, p.X), math.min(miny, p.Y)
			maxx, maxy = math.max(maxx, p.X), math.max(maxy, p.Y)
		end
		local picked, order = {}, {}
		for _, r in ipairs(L.rootList()) do
			if not underUI(r) then
				for _, d in ipairs(r:GetDescendants()) do
					if isA(d, "GuiObject") and not underUI(d) then
						local x, y, w, h = rectOf(d)
						if w > 0 and h > 0 then
							local contains = x <= minx + 4 and y <= miny + 4 and x + w >= maxx - 4 and y + h >= maxy - 4
							local bigger = w > (maxx - minx) + 8 or h > (maxy - miny) + 8
							if not (contains and bigger) and inPoly(x + w / 2, y + h / 2, shape) and L.isShown(d) and not isIgnored(d) then
								picked[d] = true
								order[#order + 1] = d
							end
						end
					end
				end
			end
		end
		local tops = {}
		for _, d in ipairs(order) do
			local p, has = d.Parent, false
			while p do
				if picked[p] then has = true break end
				p = p.Parent
			end
			if not has then tops[#tops + 1] = d end
		end
		return tops
	end
	local barInfo
	local function redrawArea()
		areaLayer:ClearAllChildren()
		local iy = insetOf()
		local green = Color3.fromRGB(80, 220, 120)
		local orange = Color3.fromRGB(255, 170, 60)
		local function toUI(p) return Vector2.new(p.X, p.Y + iy) end
		local tops = collectArea()
		if tops then
			for i, d in ipairs(tops) do
				if i > 60 then break end
				local x, y, w, h = rectOf(d)
				local f = new("Frame", {
					Position = UDim2.fromOffset(x, y + iy), Size = UDim2.fromOffset(w, h), BackgroundColor3 = orange,
					BackgroundTransparency = 0.85, BorderSizePixel = 0, ZIndex = 3,
				}, areaLayer)
				new("UIStroke", { Color = orange, Thickness = 2 }, f)
			end
		end
		local shape = areaShape()
		if shape then
			for i = 1, #shape do
				local a, b = toUI(shape[i]), toUI(shape[i % #shape + 1])
				local d = b - a
				new("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(math.max(d.Magnitude, 1), 3),
					Position = UDim2.fromOffset((a.X + b.X) / 2, (a.Y + b.Y) / 2), Rotation = math.deg(math.atan2(d.Y, d.X)),
					BackgroundColor3 = green, BorderSizePixel = 0, ZIndex = 4,
				}, areaLayer)
			end
		end
		for i, p in ipairs(areaPts) do
			local q = toUI(p)
			local dot = new("TextLabel", {
				AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(24, 24), Position = UDim2.fromOffset(q.X, q.Y),
				BackgroundColor3 = green, BorderSizePixel = 0, Text = tostring(i), TextSize = 13, TextColor3 = Color3.new(0, 0, 0), ZIndex = 5,
			}, areaLayer)
			new("UICorner", { CornerRadius = UDim.new(1, 0) }, dot)
		end
		if barInfo then
			if #areaPts == 0 then
				barInfo.Text = "Tap the first corner"
			elseif #areaPts == 1 then
				barInfo.Text = "Tap a second point"
			else
				barInfo.Text = (tops and #tops or 0) .. " parts inside. Tap more points or Done"
			end
		end
	end
	function L.areaAdd(p)
		areaPts[#areaPts + 1] = Vector2.new(p.X, p.Y)
		redrawArea()
		setStatus("Area points: " .. #areaPts .. (#areaPts == 2 and " (box)" or (#areaPts > 2 and " (shape)" or "")))
		return #areaPts
	end
	local function copyArea()
		local tops = collectArea()
		if not tops then return setStatus("Tap at least 2 points first.") end
		if #tops == 0 then return setStatus("Nothing inside that area.") end
		local parts = {}
		for i, d in ipairs(tops) do
			if i > 80 then break end
			local ok, code = pcall(L.copyCode, d)
			if ok and code then parts[#parts + 1] = "task.spawn(function()\n" .. code .. "\nend)" end
		end
		L.deliver("-- UI Copier area copy: " .. #parts .. " parts\n\n" .. table.concat(parts, "\n\n"), "Area " .. #parts .. " parts", "Copied " .. #parts .. " parts from the area, everything inside included.")
		return true
	end
	local bar = new("Frame", {
		Name = "AreaBar", AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -12),
		Size = UDim2.fromOffset(math.min(viewport().X - 16, 340), 62), BorderSizePixel = 0, Active = true, Visible = false, ZIndex = 12,
	}, ui)
	bind(bar, "BackgroundColor3", "BG")
	rounded(bar)
	bind(new("UIStroke", { Thickness = 1 }, bar), "Color", "LINE")
	barInfo = label(bar, "Tap the first corner", 13, "TEXT", { Position = UDim2.new(0, 8, 0, 3), Size = UDim2.new(1, -16, 0, 18), TextTruncate = Enum.TextTruncate.AtEnd })
	makeRow(bar, UDim2.new(0, 4, 0, 26), UDim2.new(1, -8, 0, 30), {
		{ text = "Undo", w = 0.9, fn = function()
			table.remove(areaPts)
			redrawArea()
		end },
		{ text = "Clear", w = 0.9, fn = function()
			areaPts = {}
			redrawArea()
		end },
		{ text = "Done", color = "GREEN", w = 1.2, fn = function()
			if copyArea() then
				areaPts = {}
				setClick(false)
			end
		end },
		{ text = "Cancel", color = "DANGER", w = 1, fn = function() setClick(false) end },
	})
	local wasOn = false
	table.insert(S.conns, game:GetService("RunService").Heartbeat:Connect(function()
		local on = L.areaMode == true
		bar.Visible = on
		areaLayer.Visible = on
		if wasOn and not on and #areaPts > 0 then
			areaPts = {}
			redrawArea()
		end
		wasOn = on
	end))
	local function startArea()
		L.selectMode = false
		L.areaMode = true
		areaPts = {}
		setClick(true)
		redrawArea()
		setStatus("Select area: tap corners on the screen, then Done.")
	end
	rowOf({
		{ text = "Select area", color = "SEL", w = 1.2, fn = startArea },
		{ text = "Undo point", fn = function()
			table.remove(areaPts)
			redrawArea()
		end },
		{ text = "Clear", color = "DANGER", fn = function()
			areaPts = {}
			redrawArea()
		end },
	})
	rowOf({ { text = "Copy area (all inside)", color = "GREEN", w = 2, fn = copyArea } })

	head("Copy a tool (model, scripts, abilities)")
	local PARTP = { "Name", "Size", "CFrame", "Color", "Material", "Transparency", "Reflectance", "Anchored", "CanCollide", "CanTouch", "CanQuery", "Massless", "CastShadow", "Shape" }
	local function cat(a, b)
		local r = {}
		for _, x in ipairs(a) do r[#r + 1] = x end
		for _, x in ipairs(b) do r[#r + 1] = x end
		return r
	end
	local TP = {
		Tool = { "Name", "CanBeDropped", "RequiresHandle", "ToolTip", "GripPos", "GripForward", "GripRight", "GripUp", "Enabled", "ManualActivationOnly", "TextureId" },
		Part = PARTP, WedgePart = PARTP, CornerWedgePart = PARTP, TrussPart = PARTP,
		MeshPart = cat(PARTP, { "TextureID", "DoubleSided" }),
		SpecialMesh = { "Name", "MeshType", "MeshId", "TextureId", "Scale", "Offset", "VertexColor" },
		BlockMesh = { "Name", "Scale", "Offset", "VertexColor" }, CylinderMesh = { "Name", "Scale", "Offset", "VertexColor" },
		SurfaceAppearance = { "Name", "ColorMap", "MetalnessMap", "NormalMap", "RoughnessMap", "AlphaMode", "Color" },
		Attachment = { "Name", "CFrame", "Visible" },
		Weld = { "Name", "C0", "C1", "Enabled" }, ManualWeld = { "Name", "C0", "C1", "Enabled" }, Motor6D = { "Name", "C0", "C1", "Enabled", "MaxVelocity" },
		WeldConstraint = { "Name", "Enabled" },
		Sound = { "Name", "SoundId", "Volume", "Looped", "PlaybackSpeed", "RollOffMaxDistance", "RollOffMinDistance", "RollOffMode", "PlayOnRemove" },
		Animation = { "Name", "AnimationId" },
		ParticleEmitter = { "Name", "Texture", "Rate", "Lifetime", "Speed", "Size", "Color", "Transparency", "Rotation", "RotSpeed", "SpreadAngle", "Acceleration", "EmissionDirection", "Enabled", "LightEmission", "LightInfluence", "Drag", "ZOffset" },
		PointLight = { "Name", "Brightness", "Color", "Range", "Enabled", "Shadows" },
		SpotLight = { "Name", "Brightness", "Color", "Range", "Enabled", "Shadows", "Angle", "Face" },
		Trail = { "Name", "Color", "Transparency", "Lifetime", "MinLength", "Texture", "Enabled", "LightEmission", "WidthScale", "FaceCamera" },
		Beam = { "Name", "Color", "Transparency", "Width0", "Width1", "Texture", "Segments", "LightEmission", "Enabled", "FaceCamera" },
		Decal = { "Name", "Texture", "Face", "Transparency", "Color3" },
		Texture = { "Name", "Texture", "Face", "Transparency", "Color3", "StudsPerTileU", "StudsPerTileV" },
		StringValue = { "Name", "Value" }, NumberValue = { "Name", "Value" }, IntValue = { "Name", "Value" }, BoolValue = { "Name", "Value" },
		Color3Value = { "Name", "Value" }, Vector3Value = { "Name", "Value" }, CFrameValue = { "Name", "Value" }, BrickColorValue = { "Name", "Value" },
		ObjectValue = { "Name" }, Folder = { "Name" }, Configuration = { "Name" },
		RemoteEvent = { "Name" }, RemoteFunction = { "Name" }, BindableEvent = { "Name" }, BindableFunction = { "Name" },
		Model = { "Name" }, Humanoid = { "Name", "DisplayName", "HipHeight", "RigType", "MaxHealth", "Health", "RequiresNeck", "AutoRotate" },
		Accessory = { "Name", "AttachmentPoint" }, Shirt = { "Name", "ShirtTemplate" }, Pants = { "Name", "PantsTemplate" }, ShirtGraphic = { "Name", "Graphic" },
		BodyColors = { "Name", "HeadColor3", "LeftArmColor3", "LeftLegColor3", "RightArmColor3", "RightLegColor3", "TorsoColor3" },
		CharacterMesh = { "Name", "MeshId", "BaseTextureId", "OverlayTextureId", "BodyPart" },
		LocalScript = { "Name" }, Script = { "Name" }, ModuleScript = { "Name" },
	}
	local REFS = {
		Weld = { "Part0", "Part1" }, ManualWeld = { "Part0", "Part1" }, Motor6D = { "Part0", "Part1" }, WeldConstraint = { "Part0", "Part1" },
		Trail = { "Attachment0", "Attachment1" }, Beam = { "Attachment0", "Attachment1" }, ObjectValue = { "Value" }, Model = { "PrimaryPart" },
	}
	local function sourceOf(s)
		if decompile then
			local ok, r = pcall(decompile, s)
			if ok and type(r) == "string" and r ~= "" then return r end
		end
		local ok, r = pcall(function() return s.Source end)
		if ok and type(r) == "string" and r ~= "" then return r end
	end
	local RUNNER = [[
local running = {}
local function runSource(inst, src)
	local fn, err = loadstring(src, "=" .. inst.Name)
	if not fn then warn("[ToolCopy] " .. inst.Name .. ": " .. tostring(err)) return end
	local env = setmetatable({
		script = inst,
		require = function(m)
			local s = srcOf[m]
			if s then
				if running[m] == nil then running[m] = { runSource(m, s) } end
				return running[m][1]
			end
			return require(m)
		end,
	}, { __index = getfenv() })
	setfenv(fn, env)
	local ok, res = pcall(fn)
	if not ok then warn("[ToolCopy] " .. inst.Name .. ": " .. tostring(res)) end
	return res
end
for inst, src in pairs(srcOf) do
	if inst:IsA("LocalScript") then task.spawn(runSource, inst, src) end
end]]
	local function toolCode(tool, mode)
		mode = mode or "tool"
		local nodes, idOf, skipped, nsrc, nscripts = {}, {}, {}, 0, 0
		local function walk(o, parentId)
			if #nodes >= 600 then return end
			if not TP[o.ClassName] then
				skipped[o.ClassName] = true
				return
			end
			if mode == "model" and o:IsA("LuaSourceContainer") then return end
			local id = #nodes + 1
			idOf[o] = id
			nodes[id] = { o = o, parent = parentId }
			for _, c in ipairs(o:GetChildren()) do walk(c, id) end
		end
		walk(tool, 0)
		local lines = {
			"-- Tool copy by UI Copier (DuaKNo): " .. tool.Name,
			"-- Client side copy. Anything that needs the original server will not work in other games.",
			"local lp = game:GetService(\"Players\").LocalPlayer",
			"local function set(o, k, v) if not pcall(function() o[k] = v end) and sethiddenproperty then pcall(sethiddenproperty, o, k, v) end end",
			"local InsertService = game:GetService(\"InsertService\")",
			"local function mkMesh(id, cf, rf)",
			"\tif id ~= \"\" then",
			"\t\tlocal ok, m = pcall(function() return InsertService:CreateMeshPartAsync(id, cf, rf) end)",
			"\t\tif ok and m then return m end",
			"\tend",
			"\tlocal m = Instance.new(\"MeshPart\")",
			"\tif id ~= \"\" then set(m, \"MeshId\", id) end",
			"\treturn m",
			"end",
			"local n, srcOf = {}, {}",
		}
		for i, nd in ipairs(nodes) do
			local o = nd.o
			if o.ClassName == "MeshPart" then
				local okM, mid = pcall(function() return o.MeshId end)
				local okC, cfid = pcall(function() return o.CollisionFidelity.Name end)
				local okR, rfid = pcall(function() return o.RenderFidelity.Name end)
				lines[#lines + 1] = string.format("n[%d] = mkMesh(%q, Enum.CollisionFidelity.%s, Enum.RenderFidelity.%s)",
					i, okM and tostring(mid) or "", okC and cfid or "Default", okR and rfid or "Automatic")
			else
				lines[#lines + 1] = "n[" .. i .. "] = Instance.new(" .. string.format("%q", o.ClassName) .. ")"
			end
			for _, name in ipairs(TP[o.ClassName]) do
				local ok, v = pcall(function() return o[name] end)
				if ok and v ~= nil then
					local s = lit(v)
					if s then lines[#lines + 1] = "set(n[" .. i .. "], " .. string.format("%q", name) .. ", " .. s .. ")" end
				end
			end
			if o:IsA("LuaSourceContainer") then
				nscripts += 1
				local src = sourceOf(o)
				if src then
					nsrc += 1
					local level = 0
					while src:find("]" .. string.rep("=", level) .. "]", 1, true) do level += 1 end
					local eq = string.rep("=", level)
					lines[#lines + 1] = "srcOf[n[" .. i .. "]] = [" .. eq .. "[\n" .. src .. "\n]" .. eq .. "]"
				else
					lines[#lines + 1] = "-- no source readable for " .. o.Name .. " (this executor has no decompile)"
				end
			end
		end
		for i, nd in ipairs(nodes) do
			if nd.parent > 0 then lines[#lines + 1] = "n[" .. i .. "].Parent = n[" .. nd.parent .. "]" end
		end
		for i, nd in ipairs(nodes) do
			for _, rn in ipairs(REFS[nd.o.ClassName] or {}) do
				local ok, ref = pcall(function() return nd.o[rn] end)
				if ok and typeof(ref) == "Instance" and idOf[ref] then
					lines[#lines + 1] = "set(n[" .. i .. "], " .. string.format("%q", rn) .. ", n[" .. idOf[ref] .. "])"
				end
			end
		end
		if mode == "tool" then
			lines[#lines + 1] = "n[1].Parent = lp:WaitForChild(\"Backpack\")"
			lines[#lines + 1] = RUNNER
			local sn = L.bindSnippet and L.bindSnippet()
			if sn then lines[#lines + 1] = sn end
		else
			lines[#lines + 1] = "n[1].Parent = workspace"
			lines[#lines + 1] = "for _, d in ipairs(n[1]:GetDescendants()) do if d:IsA(\"BasePart\") then d.Anchored = true end end"
			lines[#lines + 1] = "pcall(function() n[1]:PivotTo((lp.Character and lp.Character:GetPivot() or CFrame.new()) * CFrame.new(0, 0, -6)) end)"
		end
		local sk = {}
		for k in pairs(skipped) do sk[#sk + 1] = k end
		table.sort(sk)
		return table.concat(lines, "\n"), #nodes, nsrc, nscripts, sk
	end
	local function copyTool(tool)
		local code, count, nsrc, nscripts, sk = toolCode(tool)
		L.deliver(code, tool.Name .. " tool", string.format("Copied %s: %d objects, %d/%d scripts%s", tool.Name, count, nsrc, nscripts, #sk > 0 and (", skipped " .. table.concat(sk, ", ")) or ""))
	end
	local function myTools()
		local list, seen = {}, {}
		local function add(container, where)
			if not container then return end
			for _, c in ipairs(container:GetChildren()) do
				if c:IsA("Tool") and not seen[c] then
					seen[c] = true
					list[#list + 1] = { c, where }
				end
			end
		end
		local lp = Players.LocalPlayer
		add(lp:FindFirstChildOfClass("Backpack"), "backpack")
		add(lp.Character, "equipped")
		add(lp:FindFirstChild("StarterGear"), "starter gear")
		return list
	end
	rowOf({
		{ text = "List my tools", color = "SEL", w = 1.3, fn = function()
			clearRes()
			local list = myTools()
			for _, e in ipairs(list) do
				addRes(e[1].Name .. "  (" .. e[2] .. ")  tap to copy", 0, function() copyTool(e[1]) end)
			end
			if #list == 0 then addRes("No tools found.", 0, function() end) end
			setStatus(#list .. " tools. Tap one to copy it with its scripts.")
		end },
		{ text = "Copy equipped", fn = function()
			local ch = Players.LocalPlayer.Character
			local t = ch and ch:FindFirstChildOfClass("Tool")
			if not t then return setStatus("Equip a tool first.") end
			copyTool(t)
		end },
	})

	local function copyChar(model, who)
		local code, count, _, _, sk = toolCode(model, "model")
		L.deliver(code, who .. " character", string.format("Copied %s: %d objects%s", who, count, #sk > 0 and (", skipped " .. table.concat(sk, ", ")) or ""))
	end
	rowOf({
		{ text = "Copy my character", color = "SEL", w = 1.5, fn = function()
			local ch = Players.LocalPlayer.Character
			if not ch then return setStatus("No character yet.") end
			copyChar(ch, "My")
		end },
		{ text = "Players", fn = function()
			clearRes()
			local n = 0
			for _, p in ipairs(Players:GetPlayers()) do
				if p.Character then
					n += 1
					addRes(p.DisplayName .. " (" .. p.Name .. ")  tap to copy", 0, function()
						if p.Character then copyChar(p.Character, p.Name) else setStatus("No character.") end
					end)
				end
			end
			setStatus(n .. " characters. Tap one to copy.")
		end },
	})
	head("Tool rebuild: use Spy > Rec while using a tool, then copy it")

	head("Hotkeys: P pick, C copy code, F find copies")
	table.insert(S.conns, UserInputService.InputBegan:Connect(function(input, gp)
		if gp or UserInputService:GetFocusedTextBox() then return end
		if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
		if input.KeyCode == Enum.KeyCode.P then
			setClick(not S.click)
		elseif input.KeyCode == Enum.KeyCode.C then
			if S.sel then
				local code = genAll(S.sel)
				copyText(code, "Copied code of " .. S.sel.Name)
			end
		elseif input.KeyCode == Enum.KeyCode.F then
			findCopies()
		end
	end))
	L.toolCode, L.myTools, L.copyTool = toolCode, myTools, copyTool
end
setupTools()

local function setupSpy()
	local pg = pages.Spy
	local lp = Players.LocalPlayer
	local spy = {
		on = false, incoming = false, log = {}, excluded = {}, blocked = {}, white = {}, whiteOn = false, rate = {},
		auto = false, filter = "", repeatN = 1, recording = false, rec = {}, recLast = 0, dirty = false, total = 0,
		skipped = 0, view = "log", cur = nil, replaying = false, hookInfo = "hook not installed", inConns = {}, inHooked = {},
	}
	L.spy = spy

	local function instExpr(i)
		if i == game then return "game" end
		if i == lp then return 'game:GetService("Players").LocalPlayer' end
		if lp.Character and i == lp.Character then return 'game:GetService("Players").LocalPlayer.Character' end
		local chain, cur = {}, i
		while cur and cur ~= game do
			table.insert(chain, 1, cur)
			cur = cur.Parent
		end
		if cur ~= game or #chain == 0 then return "nil" end
		local s = "game:GetService(" .. string.format("%q", chain[1].ClassName) .. ")"
		for k = 2, #chain do s ..= ":FindFirstChild(" .. string.format("%q", chain[k].Name) .. ")" end
		return s
	end
	L.instExpr = instExpr
	local function instName(i)
		local names, cur = {}, i
		while cur and cur ~= game do
			table.insert(names, 1, cur.Name)
			cur = cur.Parent
		end
		return (cur == game and "game." or "nil.") .. table.concat(names, ".")
	end
	local function ser(v, depth, seen)
		local t = typeof(v)
		if t == "Instance" then return instExpr(v) end
		if t == "table" then
			if depth > 4 or seen[v] then return "{}" end
			seen[v] = true
			local parts = {}
			local n = 0
			for k, x in pairs(v) do
				n += 1
				if n > 40 then parts[#parts + 1] = "--[[ more ]]" break end
				local ks
				if type(k) == "number" then ks = "[" .. k .. "]" elseif type(k) == "string" then ks = "[" .. string.format("%q", k) .. "]" else ks = "[nil]" end
				parts[#parts + 1] = ks .. " = " .. ser(x, depth + 1, seen)
			end
			seen[v] = nil
			return "{ " .. table.concat(parts, ", ") .. " }"
		end
		if t == "function" or t == "thread" or t == "userdata" then return "nil --[[" .. t .. "]]" end
		if t == "nil" then return "nil" end
		return lit(v) or ("nil --[[" .. t .. "]]")
	end
	local function argList(args)
		local out = {}
		for i = 1, args.n do out[i] = ser(args[i], 0, {}) end
		return table.concat(out, ", ")
	end
	local function shortArgs(args)
		local out = {}
		for i = 1, math.min(args.n, 4) do
			local v = args[i]
			local t = typeof(v)
			local s
			if t == "Instance" then s = v.Name elseif t == "table" then s = "{..}" elseif t == "string" then s = '"' .. (#v > 14 and v:sub(1, 14) .. ".." or v) .. '"' else s = tostring(v) end
			out[i] = s
		end
		if args.n > 4 then out[#out + 1] = "+" .. (args.n - 4) end
		return table.concat(out, ", ")
	end
	local function recCode(rec)
		local lines = { "local remote = " .. instExpr(rec.remote) }
		if rec.dir == "in" then
			lines[#lines + 1] = "-- incoming: the server fired this at you with:"
			lines[#lines + 1] = "-- " .. argList(rec.args):gsub("\n", " ")
			lines[#lines + 1] = "firesignal(remote.OnClientEvent, " .. argList(rec.args) .. ")"
		elseif rec.method:lower() == "invokeserver" then
			lines[#lines + 1] = "local result = remote:InvokeServer(" .. argList(rec.args) .. ")"
		else
			lines[#lines + 1] = "remote:FireServer(" .. argList(rec.args) .. ")"
		end
		return table.concat(lines, "\n")
	end

	local canNC = type(getnamecallmethod) == "function" and (type(hookmetamethod) == "function" or (type(getrawmetatable) == "function" and type(setreadonly) == "function"))
	local METH = { FireServer = true, InvokeServer = true, fireServer = true, invokeServer = true }
	local function ensureHook()
		if genv.UCSpyHooked then
			spy.hookInfo = "active (installed earlier this session)"
			return true
		end
		if not canNC and type(hookfunction) ~= "function" then
			spy.hookInfo = "this executor has no hookmetamethod or hookfunction"
			return false
		end
		local wrap = type(newcclosure) == "function" and newcclosure or function(f) return f end
		local setm = type(setnamecallmethod) == "function" and setnamecallmethod or nil
		local function run(self, method, args)
			if genv.UCSpyBusy or not genv.UCSpyCB then return nil end
			genv.UCSpyBusy = true
			local ok, verdict, rec = pcall(genv.UCSpyCB, self, method, args)
			genv.UCSpyBusy = false
			if ok then return verdict, rec end
		end
		local ncOk = false
		if canNC then
			ncOk = pcall(function()
				local old
				local hook = wrap(function(self, ...)
					local method = getnamecallmethod()
					if METH[method] then
						local verdict, rec = run(self, method, table.pack(...))
						if setm then setm(method) end
						if verdict == "BLOCK" then return nil end
						if rec and method:lower() == "invokeserver" then
							local ret = table.pack(old(self, ...))
							rec.ret = ret
							spy.dirty = true
							return table.unpack(ret, 1, ret.n)
						end
					end
					return old(self, ...)
				end)
				if type(hookmetamethod) == "function" then
					old = hookmetamethod(game, "__namecall", hook)
				else
					local gm = getrawmetatable(game)
					old = gm.__namecall
					setreadonly(gm, false)
					gm.__namecall = hook
					setreadonly(gm, true)
				end
			end)
		end
		local fnOk = false
		if type(hookfunction) == "function" then
			fnOk = pcall(function()
				local function hookFn(inst, name)
					local old
					old = hookfunction(inst[name], wrap(function(self, ...)
						local verdict, rec = run(self, name, table.pack(...))
						if verdict == "BLOCK" then return nil end
						if rec and name == "InvokeServer" then
							local ret = table.pack(old(self, ...))
							rec.ret = ret
							spy.dirty = true
							return table.unpack(ret, 1, ret.n)
						end
						return old(self, ...)
					end))
				end
				hookFn(Instance.new("RemoteEvent"), "FireServer")
				hookFn(Instance.new("RemoteFunction"), "InvokeServer")
				pcall(hookFn, Instance.new("UnreliableRemoteEvent"), "FireServer")
			end)
		end
		spy.hookInfo = "namecall " .. (ncOk and "ok" or (canNC and "failed" or "unsupported")) .. ", function hooks " .. (fnOk and "ok" or "failed or unsupported")
		if ncOk or fnOk then genv.UCSpyHooked = true end
		return ncOk or fnOk
	end

	local function addRec(rec)
		spy.log[#spy.log + 1] = rec
		if #spy.log > 500 then table.remove(spy.log, 1) end
		spy.total += 1
		spy.dirty = true
		if spy.recording and rec.dir == "out" and #spy.rec < 100 then
			local now = os.clock()
			spy.rec[#spy.rec + 1] = { rec = rec, delay = math.min(1, now - spy.recLast) }
			spy.recLast = now
		end
	end
	genv.UCSpyCB = function(remote, method, args)
		if not spy.on or spy.replaying then return nil end
		local ok, cls = pcall(function() return remote.ClassName end)
		if not ok or not (cls == "RemoteEvent" or cls == "RemoteFunction" or cls == "UnreliableRemoteEvent") then return nil end
		local name = remote.Name
		local now = os.clock()
		local verdict = spy.blocked[name] and "BLOCK" or nil
		local r = spy.rate[name]
		if not r or now - r.t > 1 then
			r = { t = now, n = 0 }
			spy.rate[name] = r
		end
		r.n += 1
		if spy.auto and r.n > 20 and not spy.excluded[name] and not verdict then
			spy.excluded[name] = true
			spy.note = "Auto-excluded " .. name .. " (spam)"
		end
		if spy.excluded[name] then
			spy.skipped += 1
			return verdict
		end
		if spy.whiteOn and not spy.white[name] then return verdict end
		local rec = { remote = remote, name = name, method = method, args = args, t = now, blocked = verdict ~= nil, dir = "out" }
		if spy.scripts and type(getcallingscript) == "function" then
			local okS, scr = pcall(getcallingscript)
			if okS and typeof(scr) == "Instance" then rec.script = scr end
		end
		addRec(rec)
		return verdict, (not verdict) and rec or nil
	end
	table.insert(S.conns, { Disconnect = function() genv.UCSpyCB = nil end })

	local function hookIncoming(remote)
		if spy.inHooked[remote] then return end
		local ok, cls = pcall(function() return remote.ClassName end)
		if not ok or not (cls == "RemoteEvent" or cls == "UnreliableRemoteEvent") then return end
		spy.inHooked[remote] = true
		local okC, conn = pcall(function()
			return remote.OnClientEvent:Connect(function(...)
				if not spy.on or spy.replaying or spy.excluded[remote.Name] then return end
				if spy.whiteOn and not spy.white[remote.Name] then return end
				addRec({ remote = remote, name = remote.Name, method = "OnClientEvent", args = table.pack(...), t = os.clock(), dir = "in" })
			end)
		end)
		if okC and conn then table.insert(spy.inConns, conn) end
	end
	local function setIncoming(on)
		spy.incoming = on
		for _, c in ipairs(spy.inConns) do pcall(function() c:Disconnect() end) end
		spy.inConns, spy.inHooked = {}, {}
		if spy.inAdded then
			spy.inAdded:Disconnect()
			spy.inAdded = nil
		end
		if on then
			for _, d in ipairs(game:GetDescendants()) do hookIncoming(d) end
			spy.inAdded = game.DescendantAdded:Connect(hookIncoming)
			table.insert(S.conns, spy.inAdded)
		end
	end

	local top, filt
	top = makeRow(pg, UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 0, 26), {
		{ key = "on", text = "Spy: off", w = 1.1, fn = function(b)
			if not spy.on and not ensureHook() then return setStatus("Spy: " .. spy.hookInfo) end
			spy.on = not spy.on
			b.Text = spy.on and "Spy: on" or "Spy: off"
			paint(b, spy.on and "GREEN" or "BTN")
			spy.dirty = true
			setStatus("Spy " .. (spy.on and "on. " or "off. ") .. spy.hookInfo)
		end },
		{ key = "inc", text = "In: off", w = 0.8, fn = function(b)
			setIncoming(not spy.incoming)
			b.Text = spy.incoming and "In: on" or "In: off"
			paint(b, spy.incoming and "SEL" or "BTN")
		end },
		{ key = "auto", text = "Auto: off", w = 0.9, fn = function(b)
			spy.auto = not spy.auto
			b.Text = spy.auto and "Auto: on" or "Auto: off"
			paint(b, spy.auto and "SEL" or "BTN")
			setStatus(spy.auto and "Auto-exclude: remotes firing over 20 times a second are hidden." or "Auto-exclude off.")
		end },
		{ key = "clr", text = "Clear", w = 0.8, color = "DANGER", fn = function()
			spy.log = {}
			spy.total, spy.skipped = 0, 0
			spy.dirty = true
		end },
	})
	filt = makeRow(pg, UDim2.new(0, 0, 0, 29), UDim2.new(1, 0, 0, 24), {
		{ key = "q", box = "Filter by name or args..", w = 2.2 },
		{ key = "rec", text = "Rec: off", w = 0.9, fn = function(b)
			spy.recording = not spy.recording
			if spy.recording then
				spy.rec = {}
				spy.recLast = os.clock()
			end
			b.Text = spy.recording and "Rec: on" or ("Rec: " .. #spy.rec)
			paint(b, spy.recording and "DANGER" or "BTN")
			setStatus(spy.recording and "Recording remote calls. Use the tool, then press Rec again." or ("Recorded " .. #spy.rec .. " calls. They are added when you copy a tool."))
		end },
		{ key = "lists", text = "Lists", w = 0.8, fn = function() spy.view = "lists" spy.dirty = true end },
	})
	local info = label(pg, "", 12, "SUB", { Position = UDim2.new(0, 2, 0, 55), Size = UDim2.new(1, -4, 0, 16), TextTruncate = Enum.TextTruncate.AtEnd })
	local list = new("ScrollingFrame", {
		Position = UDim2.new(0, 0, 0, 74), Size = UDim2.new(1, 0, 1, -74), BorderSizePixel = 0, ScrollBarThickness = 6,
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
	}, pg)
	bind(list, "BackgroundColor3", "CODE")
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, list)

	local det = new("Frame", { Position = UDim2.new(0, 0, 0, 29), Size = UDim2.new(1, 0, 1, -29), BackgroundTransparency = 1, Visible = false, ZIndex = 2 }, pg)
	local d1, d2
	local detBox
	local function showDetail(rec)
		spy.cur = rec
		spy.view = "detail"
		local head = string.format("%s  %s  (%s)\nremote: %s\nargs: %d\n", rec.name, rec.method, rec.dir == "in" and "incoming" or "outgoing", instName(rec.remote), rec.args.n)
		if rec.script then head ..= "from script: " .. instName(rec.script) .. "\n" end
		if rec.ret then head ..= "returned: " .. argList(rec.ret) .. "\n" end
		detBox.Text = head .. "\n" .. recCode(rec)
		spy.dirty = true
	end
	d1 = makeRow(det, UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 0, 26), {
		{ text = "Back", w = 0.8, fn = function() spy.view = "log" spy.dirty = true end },
		{ text = "Copy code", color = "SEL", w = 1.2, fn = function()
			if spy.cur then copyText(detBox.Text:match("\n\n(.*)$") or detBox.Text, "Copied the call as code.") end
		end },
		{ text = "Replay", color = "GREEN", w = 1, fn = function()
			local rec = spy.cur
			if not rec or rec.dir == "in" then return setStatus("Only outgoing calls can be replayed.") end
			local n = spy.repeatN
			task.spawn(function()
				spy.replaying = true
				for _ = 1, n do
					pcall(function() rec.remote[rec.method](rec.remote, table.unpack(rec.args, 1, rec.args.n)) end)
					if n > 1 then task.wait() end
				end
				spy.replaying = false
			end)
			setStatus("Replayed " .. rec.name .. " x" .. n)
		end },
		{ key = "rep", text = "x1", w = 0.6, fn = function(b)
			local opts = { 1, 5, 20, 100 }
			local idx = table.find(opts, spy.repeatN) or 1
			spy.repeatN = opts[idx % #opts + 1]
			b.Text = "x" .. spy.repeatN
		end },
	})
	d2 = makeRow(det, UDim2.new(0, 0, 0, 29), UDim2.new(1, 0, 0, 26), {
		{ text = "Block", color = "DANGER", w = 1, fn = function()
			local rec = spy.cur
			if not rec then return end
			spy.blocked[rec.name] = not spy.blocked[rec.name] or nil
			setStatus(spy.blocked[rec.name] and ("Blocking " .. rec.name .. ". Calls will not reach the server.") or ("Unblocked " .. rec.name))
		end },
		{ text = "Exclude", w = 1, fn = function()
			local rec = spy.cur
			if not rec then return end
			spy.excluded[rec.name] = true
			spy.view = "log"
			spy.dirty = true
			setStatus("Hiding " .. rec.name .. " from the log.")
		end },
		{ text = "Only this", w = 1, fn = function()
			local rec = spy.cur
			if not rec then return end
			spy.white = { [rec.name] = true }
			spy.whiteOn = true
			spy.view = "log"
			spy.dirty = true
			setStatus("Only logging " .. rec.name .. ". Lists > Show all to undo.")
		end },
	})
	local detScroll = new("ScrollingFrame", {
		Position = UDim2.new(0, 0, 0, 58), Size = UDim2.new(1, 0, 1, -58), BorderSizePixel = 0, ScrollBarThickness = 6,
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
	}, det)
	bind(detScroll, "BackgroundColor3", "CODE")
	detBox = new("TextBox", {
		Size = UDim2.new(1, -8, 0, 24), Position = UDim2.new(0, 4, 0, 2), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
		BorderSizePixel = 0, ClearTextOnFocus = false, MultiLine = true, TextWrapped = true, TextEditable = false, TextSize = 13,
		Font = Enum.Font.Code, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, Text = "",
	}, detScroll)
	bind(detBox, "TextColor3", "TEXT")

	local function row(i, text, onClick)
		local r = new("TextButton", {
			Size = UDim2.new(1, -6, 0, 22), BorderSizePixel = 0, AutoButtonColor = false, TextSize = 13, Font = T.FONT,
			BackgroundColor3 = (i % 2 == 0) and T.ROW1 or T.ROW2, TextColor3 = T.TEXT, TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd, RichText = true, LayoutOrder = i, Text = text,
		}, list)
		new("UIPadding", { PaddingLeft = UDim.new(0, 6) }, r)
		r.MouseButton1Click:Connect(onClick)
	end
	local function render()
		spy.dirty = false
		for _, c in ipairs(list:GetChildren()) do
			if c:IsA("GuiButton") then c:Destroy() end
		end
		det.Visible = spy.view == "detail"
		list.Visible = spy.view ~= "detail"
		top.on.Parent.Visible = spy.view ~= "detail"
		filt.q.Parent.Visible = spy.view ~= "detail"
		info.Visible = spy.view ~= "detail"
		info.Text = string.format("%s | logged %d, hidden %d", spy.hookInfo, spy.total, spy.skipped)
		if spy.note then
			setStatus(spy.note)
			spy.note = nil
		end
		if spy.view == "lists" then
			local i = 0
			local function sect(title, set, onTap)
				i += 1
				row(i, '<b>' .. title .. '</b>  <font color="#b9b9b9">tap a name to remove</font>', function() end)
				for name in pairs(set) do
					i += 1
					row(i, esc(name), function() onTap(name) spy.dirty = true end)
				end
			end
			sect("Hidden from log", spy.excluded, function(n) spy.excluded[n] = nil end)
			sect("Blocked", spy.blocked, function(n) spy.blocked[n] = nil end)
			if spy.whiteOn then
				i += 1
				row(i, "<b>Only logging a chosen remote - tap to show all</b>", function() spy.whiteOn = false spy.white = {} spy.dirty = true end)
			end
			i += 1
			row(i, "<b>Back to the log</b>", function() spy.view = "log" spy.dirty = true end)
			return
		end
		if spy.view ~= "log" then return end
		local q = filt.q.Text:lower()
		local shown = 0
		for idx = #spy.log, 1, -1 do
			local rec = spy.log[idx]
			local text = string.format("%s%s  <font color=\"#b9b9b9\">%s %s%s</font>", rec.dir == "in" and "< " or "> ", esc(rec.name), esc(rec.method), esc(shortArgs(rec.args)), rec.blocked and "  [blocked]" or "")
			if q == "" or (rec.name:lower():find(q, 1, true) or shortArgs(rec.args):lower():find(q, 1, true)) then
				shown += 1
				if shown > 120 then break end
				row(shown, text, function() showDetail(rec) end)
			end
		end
	end
	filt.q:GetPropertyChangedSignal("Text"):Connect(function() spy.dirty = true end)
	local acc = 0
	table.insert(S.conns, game:GetService("RunService").Heartbeat:Connect(function(dt)
		acc += dt
		if acc < 0.3 then return end
		acc = 0
		if spy.dirty and S.tab == "Spy" then
			local ok, err = pcall(render)
			if not ok then spy.dirty = false setStatus("Spy view error: " .. tostring(err)) end
		end
	end))
	spy.dirty = true

	function L.bindSnippet()
		if #spy.rec == 0 then return nil end
		local out = { "", "-- recorded remote calls, fired when the tool is used (needs the same remotes to exist)" }
		out[#out + 1] = "local calls = {"
		for _, e in ipairs(spy.rec) do
			local rec = e.rec
			out[#out + 1] = string.format("\t{ r = function() return %s end, m = %q, d = %s, a = table.pack(%s) },", instExpr(rec.remote), rec.method, tostring(math.floor(e.delay * 100) / 100), argList(rec.args))
		end
		out[#out + 1] = "}"
		out[#out + 1] = "local busy = false"
		out[#out + 1] = "n[1].Activated:Connect(function()"
		out[#out + 1] = "\tif busy then return end"
		out[#out + 1] = "\tbusy = true"
		out[#out + 1] = "\tfor _, c in ipairs(calls) do"
		out[#out + 1] = "\t\tif c.d > 0 then task.wait(c.d) end"
		out[#out + 1] = "\t\tlocal ok, r = pcall(c.r)"
		out[#out + 1] = "\t\tif ok and r then pcall(function() r[c.m](r, table.unpack(c.a, 1, c.a.n)) end) end"
		out[#out + 1] = "\tend"
		out[#out + 1] = "\tbusy = false"
		out[#out + 1] = "end)"
		return table.concat(out, "\n")
	end
end
setupSpy()

local P3 = {
	{ "Instance", { "Name" } },
	{ "BasePart", { "Anchored", "CanCollide", "CanTouch", "CanQuery", "CastShadow", "Massless", "Locked", "Color", "Material", "Reflectance", "Transparency", "Size", "CFrame", "TopSurface", "BottomSurface" } },
	{ "Part", { "Shape" } },
	{ "MeshPart", { "TextureID", "DoubleSided", "RenderFidelity" } },
	{ "DataModelMesh", { "Scale", "Offset", "VertexColor" } },
	{ "FileMesh", { "MeshId", "TextureId" } },
	{ "SpecialMesh", { "MeshType" } },
	{ "Decal", { "Texture", "Face", "Transparency", "Color3", "ZIndex" } },
	{ "Texture", { "StudsPerTileU", "StudsPerTileV" } },
	{ "SurfaceAppearance", { "ColorMap", "NormalMap", "MetalnessMap", "RoughnessMap", "AlphaMode" } },
	{ "Light", { "Brightness", "Color", "Enabled", "Shadows" } },
	{ "PointLight", { "Range" } },
	{ "SpotLight", { "Range", "Angle", "Face" } },
	{ "SurfaceLight", { "Range", "Angle", "Face" } },
	{ "Attachment", { "CFrame", "Visible" } },
	{ "ParticleEmitter", { "Texture", "Rate", "Lifetime", "Speed", "SpreadAngle", "Size", "Color", "Transparency", "Rotation", "RotSpeed", "Acceleration", "Drag", "EmissionDirection", "LightEmission", "LightInfluence", "ZOffset", "Squash", "Orientation", "LockedToPart", "TimeScale", "Enabled", "Shape", "ShapeStyle" } },
	{ "Fire", { "Color", "SecondaryColor", "Heat", "Size", "Enabled" } },
	{ "Smoke", { "Color", "Opacity", "RiseVelocity", "Size", "Enabled" } },
	{ "Sparkles", { "SparkleColor", "Enabled" } },
	{ "Beam", { "Color", "Texture", "Width0", "Width1", "Transparency", "LightEmission", "LightInfluence", "FaceCamera", "Segments", "TextureLength", "TextureSpeed", "CurveSize0", "CurveSize1", "Enabled" } },
	{ "Trail", { "Color", "Texture", "Transparency", "Lifetime", "LightEmission", "LightInfluence", "FaceCamera", "MinLength", "WidthScale", "Enabled" } },
	{ "Highlight", { "FillColor", "FillTransparency", "OutlineColor", "OutlineTransparency", "DepthMode", "Enabled" } },
	{ "Model", { "WorldPivot" } },
	{ "JointInstance", { "C0", "C1", "Enabled" } },
	{ "WeldConstraint", { "Enabled" } },
	{ "ValueBase", { "Value" } },
	{ "Sound", { "SoundId", "Volume", "PlaybackSpeed", "Looped" } },
	{ "Accessory", { "AccessoryType" } },
}
local REFS = { PrimaryPart = true, Part0 = true, Part1 = true, Attachment0 = true, Attachment1 = true }
local REF_OF = { "Model", "Weld", "Motor6D", "WeldConstraint", "Beam", "Trail" }

function L.structCodeMulti(roots, label, opts)
	opts = opts or {}
	local maxNodes = opts.maxNodes or L.MAX_NODES
	local keep = opts.keep
	local items, index, skipped, ops, rootIdx = {}, {}, 0, 0, {}
	local function walk(o, parentIdx)
		if #items >= maxNodes then skipped += 1 return end
		if o:GetAttribute(MARK_ATTR) or isA(o, "LuaSourceContainer") or isA(o, "Player") or isA(o, "Humanoid") or isA(o, "Terrain") or isA(o, "Camera") then return end
		if keep and parentIdx and isA(o, "BasePart") and not keep(o) then return end
		local cls = o.ClassName
		local isOp = isA(o, "PartOperation")
		local okNew, probe = false, nil
		if isOp then
			ops += 1
		else
			okNew, probe = pcall(Instance.new, cls)
			if okNew and probe then pcall(function() probe:Destroy() end) end
		end
		local useClass = (okNew and cls) or (isA(o, "BasePart") and "Part" or "Folder")
		local rec = { inst = o, class = useClass, parent = parentIdx, props = {}, refs = {} }
		items[#items + 1] = rec
		index[o] = #items
		local seen = {}
		local def = L.defaultFor(useClass)
		local function scan(list)
			for _, entry in ipairs(list) do
				if isA(o, entry[1]) then
					for _, n in ipairs(entry[2]) do
						if not seen[n] then
							seen[n] = true
							local ok, v = pcall(function() return o[n] end)
							if ok and v ~= nil then
								local s = lit(v)
								if s then
									local keepProp = n == "Name" or n == "CFrame" or n == "Size"
									if not keepProp then
										local okD, dv = false, nil
										if def then okD, dv = pcall(function() return def[n] end) end
										keepProp = not (okD and dv ~= nil and lit(dv) == s)
									end
									if keepProp then rec.props[#rec.props + 1] = { n, s } end
								end
							end
						end
					end
				end
			end
		end
		scan(P3)
		scan(PROPS)
		if isA(o, "MeshPart") then
			local ok, id = pcall(function() return o.MeshId end)
			if ok and id and id ~= "" then rec.meshId = id end
		end
		for rn in pairs(REFS) do
			local ok, v = pcall(function() return o[rn] end)
			if ok and typeof(v) == "Instance" then rec.refs[#rec.refs + 1] = { rn, v } end
		end
		local i = #items
		for _, ch in ipairs(o:GetChildren()) do walk(ch, i) end
	end
	for _, r in ipairs(roots) do
		local before = #items
		walk(r, nil)
		if #items > before then rootIdx[#rootIdx + 1] = before + 1 end
	end
	if #items == 0 then return nil end
	local multi = opts.container == true or #rootIdx ~= 1
	local first = roots[1]
	local out = {}
	local function add(s) out[#out + 1] = s end
	add("-- Structure copy: " .. tostring(label) .. " (" .. #items .. " instances" .. (skipped > 0 and (", " .. skipped .. " left out, too many") or "") .. ")")
	add("-- works in any game: it rebuilds everything from properties. Meshes / textures use the same asset ids, so the game must be able to load them.")
	if ops > 0 then
		add("-- note: " .. ops .. " union / CSG part(s) cannot be rebuilt from code, they come back as plain blocks of the same size.")
	end
	add("local KEEP_POSITION = false -- true = rebuild it at the exact original place, false = in front of you")
	add("local ANCHOR_ALL = false -- true = anchor every part so nothing falls or drifts")
	add('local InsertService = game:GetService("InsertService")')
	add('local lp = game:GetService("Players").LocalPlayer')
	add("local I = {}")
	add("local function set(o, p, v) pcall(function() o[p] = v end) end")
	add("local function mk(class, meshId)")
	add('\tif class == "MeshPart" then')
	add("\t\tif meshId then")
	add("\t\t\tlocal ok, m = pcall(function() return InsertService:CreateMeshPartAsync(meshId, Enum.CollisionFidelity.Default, Enum.RenderFidelity.Automatic) end)")
	add("\t\t\tif ok and m then return m end")
	add("\t\tend")
	add('\t\treturn Instance.new("Part")')
	add("\tend")
	add("\treturn Instance.new(class)")
	add("end")
	for i, r in ipairs(items) do
		if r.meshId then
			add(string.format("I[%d] = mk(%q, %q)", i, r.class, r.meshId))
		else
			add(string.format("I[%d] = mk(%q)", i, r.class))
		end
		for _, p in ipairs(r.props) do add(string.format("set(I[%d], %q, %s)", i, p[1], p[2])) end
	end
	for i, r in ipairs(items) do
		if r.parent then add(string.format("I[%d].Parent = I[%d]", i, r.parent)) end
		for _, rf in ipairs(r.refs) do
			local j = index[rf[2]]
			if j then add(string.format("set(I[%d], %q, I[%d])", i, rf[1], j)) end
		end
	end
	local rootIsStructure = isA(first, "BasePart") or isA(first, "Model") or isA(first, "Folder") or isA(first, "Accoutrement")
	if multi or rootIsStructure then
		if multi then
			add('local top = Instance.new("Model")')
			add(string.format("top.Name = %q", tostring(label)))
			for _, idx in ipairs(rootIdx) do add(string.format("I[%d].Parent = top", idx)) end
		else
			add("local top = I[1]")
		end
		add("local parts = {}")
		add('for _, o in pairs(I) do if typeof(o) == "Instance" and o:IsA("BasePart") then parts[#parts + 1] = o end end')
		add("if ANCHOR_ALL then for _, p in ipairs(parts) do p.Anchored = true end end")
		add('local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")')
		add("if not KEEP_POSITION and hrp and #parts > 0 then")
		add("\tlocal function ext(p)")
		add("\t\tlocal cf, s = p.CFrame, p.Size")
		add("\t\tlocal r, u, l = cf.RightVector, cf.UpVector, cf.LookVector")
		add("\t\treturn Vector3.new(")
		add("\t\t\t(math.abs(r.X) * s.X + math.abs(u.X) * s.Y + math.abs(l.X) * s.Z) / 2,")
		add("\t\t\t(math.abs(r.Y) * s.X + math.abs(u.Y) * s.Y + math.abs(l.Y) * s.Z) / 2,")
		add("\t\t\t(math.abs(r.Z) * s.X + math.abs(u.Z) * s.Y + math.abs(l.Z) * s.Z) / 2)")
		add("\tend")
		add("\tlocal mn = Vector3.new(math.huge, math.huge, math.huge)")
		add("\tlocal mx = Vector3.new(-math.huge, -math.huge, -math.huge)")
		add("\tfor _, p in ipairs(parts) do")
		add("\t\tlocal e, c = ext(p), p.Position")
		add("\t\tmn = Vector3.new(math.min(mn.X, c.X - e.X), math.min(mn.Y, c.Y - e.Y), math.min(mn.Z, c.Z - e.Z))")
		add("\t\tmx = Vector3.new(math.max(mx.X, c.X + e.X), math.max(mx.Y, c.Y + e.Y), math.max(mx.Z, c.Z + e.Z))")
		add("\tend")
		add("\tlocal center, size = (mn + mx) / 2, mx - mn")
		add("\tlocal look = hrp.CFrame.LookVector * Vector3.new(1, 0, 1)")
		add("\tlook = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0, -1)")
		add("\tlocal target = hrp.Position + look * (6 + math.max(size.X, size.Z) / 2)")
		add("\ttarget = Vector3.new(target.X, hrp.Position.Y - 3 + size.Y / 2, target.Z)")
		add("\tlocal delta = target - center")
		add("\tfor _, p in ipairs(parts) do p.CFrame = p.CFrame + delta end")
		add('\tfor _, o in pairs(I) do if typeof(o) == "Instance" and o:IsA("Model") then pcall(function() o.WorldPivot = o.WorldPivot + delta end) end end')
		add("end")
		add("top.Parent = workspace")
		add("return top")
	else
		add('local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")')
		add('local holder = Instance.new("Part")')
		add('holder.Name = "Holder"')
		add("holder.Anchored = true")
		add("holder.CanCollide = false")
		add("holder.CanQuery = false")
		add("holder.Transparency = 1")
		add("holder.Size = Vector3.new(1, 1, 1)")
		add("holder.CFrame = hrp and (hrp.CFrame * CFrame.new(0, 0, -8)) or CFrame.new(0, 10, 0)")
		add("holder.Parent = workspace")
		add("I[1].Parent = holder")
		add('if I[1]:IsA("ParticleEmitter") then pcall(function() I[1]:Emit(20) end) end')
		add('if I[1]:IsA("Sound") then pcall(function() I[1]:Play() end) end')
		add("return I[1]")
	end
	return table.concat(out, "\n"), #items, skipped
end

function L.structCode(root)
	return L.structCodeMulti({ root }, root.Name)
end

local function validInst(o)
	if typeof(o) ~= "Instance" then return false end
	local ok, par = pcall(function() return o.Parent end)
	return ok and par ~= nil
end

function L.classify(o)
	if not validInst(o) then return nil end
	if isA(o, "Tool") then return "tool" end
	if isA(o, "Animation") then return "anim" end
	if isA(o, "LayerCollector") or isA(o, "GuiBase2d") or isA(o, "UIComponent") then return "gui" end
	if isA(o, "BasePart") or isA(o, "Model") or isA(o, "Folder") or isA(o, "Accoutrement") then return "structure" end
	return nil
end

function L.currentTarget()
	local ch = lp.Character
	local cand = {
		tool = ch and ch:FindFirstChildOfClass("Tool") or nil,
		explorer = (function()
			local R = genv.__RPP
			if R and R.GetSelection then
				local ok, sel = pcall(R.GetSelection)
				if ok and sel then return sel[1] end
			end
		end)(),
		gui = S.sel,
	}
	local order = { "explorer", "tool", "gui" }
	if L.focus and cand[L.focus] then table.insert(order, 1, L.focus) end
	for _, k in ipairs(order) do
		local o = cand[k]
		local kind = o and L.classify(o)
		if kind then return { kind = kind, inst = o, src = k }, cand end
	end
	return nil, cand
end

local lastSeen = {}
function L.watchTargets()
	local tg, cand = L.currentTarget()
	for k, v in pairs(cand) do
		if v ~= nil and v ~= lastSeen[k] then L.focus = k end
	end
	lastSeen = cand
	tg = L.currentTarget()
	if L.targetLbl then
		if tg then
			L.targetLbl.Text = ({ tool = "Tool", anim = "Animation", gui = "GUI", structure = "Structure" })[tg.kind] .. ": " .. tg.inst.Name
		else
			L.targetLbl.Text = "Select something in the Explorer (or hold a tool)"
		end
	end
end

function L.animCodeFor(inst, cb)
	local Lg = genv.__RPP_Logger
	local id = inst.AnimationId
	if Lg and Lg.animCode then
		return Lg.animCode(id, function(ok, code)
			if ok and code then cb(code) else cb(nil, "could not read the keyframes of that animation (" .. tostring(code) .. ")") end
		end)
	end
	cb(string.format('local anim = Instance.new("Animation")\nanim.AnimationId = %q\nlocal hum = game:GetService("Players").LocalPlayer.Character:FindFirstChildOfClass("Humanoid")\nlocal track = hum:LoadAnimation(anim)\ntrack:Play()', id), "the Recorder is not loaded: this version only plays the id")
end

function L.targetCode(tg, cb)
	local o = tg.inst
	if tg.kind == "tool" then
		local ok, res = pcall(L.toolCode, o)
		if ok and res then return cb(res, o.Name .. "_tool", "tool " .. o.Name) end
		return cb(nil, nil, "Could not copy that tool: " .. tostring(res))
	elseif tg.kind == "gui" then
		local ok, res = pcall(genAll, o)
		if ok and res then return cb(res, o.Name, "gui " .. o.Name) end
		return cb(nil, nil, "Could not copy that GUI: " .. tostring(res))
	elseif tg.kind == "structure" then
		local ok, res = pcall(L.structCode, o)
		if ok and res then return cb(res, o.Name .. "_structure", "structure " .. o.Name) end
		return cb(nil, nil, "Could not copy that structure: " .. tostring(res))
	elseif tg.kind == "anim" then
		setStatus("Reading the animation frames...")
		return L.animCodeFor(o, function(code, note)
			if code then cb(code, (o.Name ~= "Animation" and o.Name or "animation") .. "_anim", "animation " .. o.Name .. (note and (" (" .. note .. ")") or "")) else cb(nil, nil, note) end
		end)
	end
	cb(nil, nil, "Nothing to copy.")
end

function L.top()
	if L.topGui and L.topGui.Parent then return L.topGui end
	local g = Instance.new("ScreenGui")
	g.Name = "UICopierTop" .. math.random(1000, 9999)
	g.ResetOnSpawn = false
	g.IgnoreGuiInset = true
	g.DisplayOrder = 250000
	g.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	pcall(function() if syn and syn.protect_gui then syn.protect_gui(g) end end)
	local parent
	if gethui then
		local ok, h = pcall(gethui)
		if ok then parent = h end
	end
	local ok = pcall(function() g.Parent = parent or CoreGui end)
	if not ok or not g.Parent then g.Parent = L.playerGui end
	L.topGui = g
	return g
end

function L.toast(msg, secs)
	msg = tostring(msg)
	pcall(function() setStatus(msg) end)
	pcall(function()
		local g = L.top()
		if L.toastLbl then pcall(function() L.toastLbl:Destroy() end) end
		local t = Instance.new("TextLabel")
		t.Name = "Toast"
		t.AnchorPoint = Vector2.new(0.5, 1)
		t.Position = UDim2.new(0.5, 0, 1, -24)
		t.Size = UDim2.fromOffset(math.min(viewport().X - 20, 420), 40)
		t.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
		t.BackgroundTransparency = 0.08
		t.BorderSizePixel = 0
		t.TextColor3 = Color3.new(1, 1, 1)
		t.Font = Enum.Font.SourceSansBold
		t.TextSize = 15
		t.TextWrapped = true
		t.Text = msg
		t.ZIndex = 50
		t.Parent = g
		Instance.new("UICorner", t).CornerRadius = UDim.new(0, 6)
		L.toastLbl = t
		task.delay(secs or 3.5, function()
			if L.toastLbl == t then
				pcall(function() t:Destroy() end)
				L.toastLbl = nil
			end
		end)
	end)
	pcall(function()
		StarterGui:SetCore("SendNotification", { Title = "UI Copier", Text = msg:sub(1, 200), Duration = 3 })
	end)
end

function L.askName(default, onSave)
	if L.nameDlg then pcall(function() L.nameDlg:Destroy() end) end
	local dlg = new("Frame", {
		Name = "NameDialog", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.4),
		Size = UDim2.fromOffset(math.min(viewport().X - 24, 340), 104),
		BorderSizePixel = 1, BorderColor3 = Color3.fromRGB(33, 33, 33), ZIndex = 40, Active = true,
	}, L.top())
	bind(dlg, "BackgroundColor3", "TITLE")
	L.nameDlg = dlg
	label(dlg, "What name do you want? (saved as .lua)", 14, "TEXT", { Position = UDim2.new(0, 8, 0, 6), Size = UDim2.new(1, -16, 0, 18), ZIndex = 41 })
	local box = L.textbox(dlg, "file name")
	box.Position = UDim2.new(0, 8, 0, 30)
	box.Size = UDim2.new(1, -16, 0, 28)
	box.Text = default
	box.ZIndex = 41
	local function doSave()
		local name = box.Text:gsub("[^%w_%-%. ]", ""):gsub("^%s+", ""):gsub("%s+$", "")
		if name == "" then name = default end
		name = name:gsub("%.lua$", "")
		pcall(function() dlg:Destroy() end)
		L.nameDlg = nil
		onSave(name)
	end
	makeRow(dlg, UDim2.new(0, 8, 1, -36), UDim2.new(1, -16, 0, 28), {
		{ key = "ok", text = "Save", color = "GREEN", fn = doSave },
		{ key = "no", text = "Cancel", color = "DANGER", fn = function() dlg:Destroy() L.nameDlg = nil end },
	})
	for _, d in ipairs(dlg:GetDescendants()) do
		if d:IsA("GuiObject") then d.ZIndex = 41 end
	end
	box.FocusLost:Connect(function(enter) if enter then doSave() end end)
	pcall(function() box:CaptureFocus() end)
end

function L.saveFile(name, code, what)
	if not writefile then
		copyText(code, "This executor can't write files: copied " .. what .. " instead.")
		return
	end
	pcall(function() if makefolder and not (isfolder and isfolder(DIR)) then makefolder(DIR) end end)
	local base = DIR .. "/" .. (name:gsub("[^%w_%-%. ]", "_"))
	local path, n = base .. ".lua", 1
	while isfile and isfile(path) do
		n += 1
		path = base .. "_" .. n .. ".lua"
	end
	local ok, err = pcall(writefile, path, code)
	L.toast(ok and ("Saved " .. what .. " to workspace/" .. path) or ("Could not save: " .. tostring(err)), 5)
end

function L.doHeld(download)
	local ok, err = pcall(function()
		local tg = L.currentTarget()
		if not tg then
			return L.toast("Select a GUI, part, model or animation in the Explorer first (or hold a tool).")
		end
		L.targetCode(tg, function(code, name, what)
			if not code then return L.toast(what or "Could not copy that.") end
			if download then
				L.askName(name, function(chosen) L.saveFile(chosen, code, what) end)
			else
				copyText(code, "Copied " .. what)
			end
		end)
	end)
	if not ok then L.toast("Error: " .. tostring(err), 5) end
end
task.spawn(function()
	while S.alive do
		pcall(L.watchTargets)
		task.wait(0.4)
	end
end)
genv.__RPP_Copy = L

if HOST then
	local function dexSkin(o)
		if o:IsA("UICorner") then
			o.CornerRadius = UDim.new(0, 0)
		elseif o:IsA("ScrollingFrame") then
			o.ScrollBarThickness = math.min(o.ScrollBarThickness, 8)
			o.ScrollBarImageColor3 = Color3.fromRGB(70, 70, 70)
		elseif o:IsA("TextBox") then
			o.BorderSizePixel = 1
			o.BorderColor3 = Color3.fromRGB(33, 33, 33)
		end
		if (o:IsA("TextButton") or o:IsA("TextLabel") or o:IsA("TextBox")) and not o.TextScaled and o.TextSize > 14 then
			o.TextSize = 14
		end
	end
	for _, o in ipairs(panel:GetDescendants()) do pcall(dexSkin, o) end
	table.insert(S.conns, panel.DescendantAdded:Connect(function(o) task.defer(function() pcall(dexSkin, o) end) end))
end
-- start clean: no leftover click-mode overlay or input sink from an earlier run
pcall(function()
	L.overlay.Visible, L.overlay.Active, L.overlay.Modal = false, false, false
	modal.Visible = false
	setSink(false)
end)
showTab("Pick")
refreshList()
refreshInfo()
refreshSaved()
updIgnore()
if not HOST then L.credit() end

