Main.ToolSrc = [=====[
local genv = (getgenv and getgenv()) or _G
local R = genv.__RPP
local CP = genv.__RPP_Copy
local win = R and R.ToolWin
if not (win and win.GuiElems and win.GuiElems.Content) then return end

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS = game:GetService("UserInputService")
local lp = Players.LocalPlayer
local content = win.GuiElems.Content

local T = {
	bar = Color3.fromRGB(52, 52, 52),
	back = Color3.fromRGB(32, 32, 32),
	btn = Color3.fromRGB(60, 60, 60),
	line = Color3.fromRGB(55, 55, 55),
	sel = Color3.fromRGB(11, 90, 175),
	text = Color3.fromRGB(255, 255, 255),
	sub = Color3.fromRGB(185, 185, 185),
}

local function new(class, props, parent)
	local o = Instance.new(class)
	for k, v in pairs(props) do o[k] = v end
	if parent then o.Parent = parent end
	return o
end

local S = { mode = "held", zoom = 1, sel = nil, cells = {}, conns = {}, sig = "", drag = 0, alive = true }

for _, c in ipairs(content:GetChildren()) do c:Destroy() end

local bar = new("Frame", { Size = UDim2.new(1, 0, 0, 26), BackgroundColor3 = T.bar, BorderSizePixel = 0 }, content)
new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder, VerticalAlignment = Enum.VerticalAlignment.Center }, bar)
new("UIPadding", { PaddingLeft = UDim.new(0, 4) }, bar)

local function barBtn(text, w, order)
	local b = new("TextButton", {
		Size = UDim2.fromOffset(w, 20), Text = text, AutoButtonColor = false, BackgroundColor3 = T.btn, BorderColor3 = T.line,
		TextColor3 = T.text, TextTransparency = 0.1, Font = Enum.Font.SourceSans, TextSize = 14, LayoutOrder = order,
	}, bar)
	local base = T.btn
	b:SetAttribute("base", 0)
	b.MouseEnter:Connect(function() b.BackgroundColor3 = b.BackgroundColor3:Lerp(Color3.new(1, 1, 1), 0.06) end)
	b.MouseLeave:Connect(function() b.BackgroundColor3 = (b:GetAttribute("on") and T.sel) or base end)
	return b
end
local heldBtn = barBtn("Held", 46, 1)
local allBtn = barBtn("List all", 58, 2)
local zoomOut = barBtn("-", 24, 3)
local zoomIn = barBtn("+", 24, 4)
local copyBtn = barBtn("Copy", 46, 5)
local dlBtn = barBtn("Download", 72, 6)

local status = new("TextLabel", {
	Size = UDim2.new(1, -8, 0, 18), Position = UDim2.new(0, 6, 1, -19), BackgroundTransparency = 1, Font = Enum.Font.SourceSans, TextSize = 14,
	TextColor3 = T.sub, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Text = "Hold a tool, or press List all.",
}, content)
local function say(t) status.Text = tostring(t) end

local area = new("Frame", { Position = UDim2.new(0, 0, 0, 27), Size = UDim2.new(1, 0, 1, -48), BackgroundColor3 = T.back, BorderSizePixel = 0, ClipsDescendants = true }, content)
local empty = new("TextLabel", {
	Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Font = Enum.Font.SourceSans, TextSize = 16, TextColor3 = T.sub,
	Text = "", TextWrapped = true, Visible = false, ZIndex = 3,
}, area)

local function setOn(b, on)
	b:SetAttribute("on", on)
	b.BackgroundColor3 = on and T.sel or T.btn
end

local function clear()
	for _, c in ipairs(S.cells) do pcall(function() c.root:Destroy() end) end
	S.cells = {}
end

local function buildPreview(vp, tool)
	local was = tool.Archivable
	tool.Archivable = true
	local ok, clone = pcall(tool.Clone, tool)
	tool.Archivable = was
	if not ok or not clone then return nil end
	local model = Instance.new("Model")
	model.Name = "Preview"
	for _, d in ipairs(clone:GetDescendants()) do
		if d:IsA("LuaSourceContainer") or d:IsA("Sound") or d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail") or d:IsA("Light") or d:IsA("Highlight") or d:IsA("BillboardGui") or d:IsA("SurfaceGui") then
			pcall(function() d:Destroy() end)
		end
	end
	for _, c in ipairs(clone:GetChildren()) do c.Parent = model end
	clone:Destroy()
	local parts = 0
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("BasePart") then
			parts += 1
			d.Anchored = true
			d.CanCollide = false
			d.CanQuery = false
			d.CanTouch = false
			d.Massless = true
		end
	end
	if parts == 0 then model:Destroy() return nil end
	local wm = Instance.new("WorldModel")
	wm.Parent = vp
	model.Parent = wm
	local cf, size = model:GetBoundingBox()
	local pivot = model:GetPivot()
	model:PivotTo(pivot - (cf.Position - Vector3.zero))
	local cam = Instance.new("Camera")
	cam.FieldOfView = 50
	cam.Parent = vp
	vp.CurrentCamera = cam
	return { cam = cam, radius = math.max(size.Magnitude / 2, 0.5) }
end

local function addCell(tool, w, h, order)
	local root = new("Frame", { Size = UDim2.new(0, w, 1, h), BackgroundColor3 = T.back, BorderSizePixel = 0, LayoutOrder = order, ClipsDescendants = true }, area)
	local vp = new("ViewportFrame", {
		Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Ambient = Color3.fromRGB(150, 150, 160),
		LightColor = Color3.fromRGB(255, 250, 240), LightDirection = Vector3.new(-0.5, -1, -0.6),
	}, root)
	local name = new("TextLabel", {
		Size = UDim2.new(1, -8, 0, 18), Position = UDim2.new(0, 5, 0, 2), BackgroundTransparency = 1, Font = Enum.Font.SourceSansBold, TextSize = 14,
		TextColor3 = T.text, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Text = tool.Name, ZIndex = 4,
	}, root)
	local info = buildPreview(vp, tool)
	if not info then
		name.Text = tool.Name .. "  (no parts to show)"
	end
	local stroke = new("UIStroke", { Color = T.sel, Thickness = 2, Enabled = false }, root)
	local cell = { root = root, vp = vp, info = info, tool = tool, stroke = stroke }
	local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 6, Visible = S.mode == "all" }, root)
	hit.MouseButton1Click:Connect(function()
		S.sel = tool
		for _, c in ipairs(S.cells) do c.stroke.Enabled = (c.tool == S.sel) and S.mode == "all" end
		say("Selected " .. tool.Name .. ". Copy or Download.")
	end)
	S.cells[#S.cells + 1] = cell
	return cell
end

local function myTools()
	local list = {}
	if CP and CP.myTools then
		local ok, res = pcall(CP.myTools)
		if ok and type(res) == "table" then
			for _, e in ipairs(res) do list[#list + 1] = e[1] end
		end
	else
		local seen = {}
		local function add(c)
			if not c then return end
			for _, t in ipairs(c:GetChildren()) do
				if t:IsA("Tool") and not seen[t] then seen[t] = true list[#list + 1] = t end
			end
		end
		add(lp:FindFirstChildOfClass("Backpack"))
		add(lp.Character)
	end
	return list
end
local function heldTool()
	local ch = lp.Character
	return ch and ch:FindFirstChildOfClass("Tool") or nil
end

local ids, nextId = setmetatable({}, { __mode = "k" }), 0
local function idOf(o)
	if not ids[o] then
		nextId += 1
		ids[o] = nextId
	end
	return ids[o]
end

local function signature()
	if S.mode == "held" then
		local t = heldTool()
		return "held:" .. (t and (t.Name .. idOf(t)) or "-")
	end
	local parts = {}
	for _, t in ipairs(myTools()) do parts[#parts + 1] = t.Name .. idOf(t) end
	return "all:" .. table.concat(parts, "|")
end

local list
local function rebuild()
	clear()
	if list then list:Destroy() list = nil end
	S.sig = signature()
	empty.Visible = false
	if S.mode == "held" then
		local t = heldTool()
		if not t then
			empty.Text = "You are not holding a tool.\nEquip one, or press List all."
			empty.Visible = true
			S.sel = nil
			say("Hold a tool to see it here.")
			return
		end
		S.sel = t
		addCell(t, 0, 0, 1).root.Size = UDim2.fromScale(1, 1)
		say("Holding " .. t.Name .. ". Scroll or pinch to zoom, drag to turn.")
	else
		local tools = myTools()
		if #tools == 0 then
			empty.Text = "No tools found in your backpack."
			empty.Visible = true
			S.sel = nil
			say("No tools found.")
			return
		end
		list = new("ScrollingFrame", {
			Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 6,
			ScrollBarImageColor3 = Color3.fromRGB(70, 70, 70), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.X,
			ScrollingDirection = Enum.ScrollingDirection.X,
		}, area)
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, list)
		local keep = S.sel
		S.sel = nil
		for i, t in ipairs(tools) do
			local c = addCell(t, 150, -8, i)
			c.root.Parent = list
			if t == keep or (not S.sel and t == heldTool()) then S.sel = t end
		end
		if not S.sel then S.sel = tools[1] end
		for _, c in ipairs(S.cells) do c.stroke.Enabled = c.tool == S.sel end
		say(#tools .. " tools. Pick one, then Copy or Download.")
	end
end

local function setMode(m)
	S.mode = m
	setOn(heldBtn, m == "held")
	setOn(allBtn, m == "all")
	rebuild()
end

local function codeOf()
	local tool = S.sel
	if not tool then say("Nothing to copy. Hold a tool first.") return end
	if not (CP and CP.toolCode) then say("The Copy module is not loaded.") return end
	local ok, code, count, nsrc, nscripts = pcall(CP.toolCode, tool)
	if not ok or not code then say("Could not copy " .. tool.Name .. ": " .. tostring(code)) return end
	return code, tool, count, nsrc, nscripts
end

copyBtn.MouseButton1Click:Connect(function()
	local code, tool, count, nsrc, nscripts = codeOf()
	if not code then return end
	local clip = setclipboard or toclipboard or (Clipboard and Clipboard.set)
	if clip then
		pcall(clip, code)
		say(string.format("Copied %s: %d objects, %d/%d scripts.", tool.Name, count or 0, nsrc or 0, nscripts or 0))
	else
		say("No clipboard in this executor. Use Download.")
	end
end)

dlBtn.MouseButton1Click:Connect(function()
	local code, tool = codeOf()
	if not code then return end
	if not (writefile and makefolder) then
		local clip = setclipboard or toclipboard
		if clip then pcall(clip, code) end
		say("No file access here, copied to the clipboard instead.")
		return
	end
	pcall(function() if isfolder and not isfolder("ToolCopies") then makefolder("ToolCopies") elseif not isfolder then makefolder("ToolCopies") end end)
	local safe = tool.Name:gsub("[^%w_%-]", "_")
	local path = "ToolCopies/" .. safe .. ".lua"
	local n = 1
	while isfile and isfile(path) do
		n += 1
		path = "ToolCopies/" .. safe .. "_" .. n .. ".lua"
	end
	local ok, err = pcall(writefile, path, code)
	say(ok and ("Saved to workspace/" .. path) or ("Could not save: " .. tostring(err)))
end)

heldBtn.MouseButton1Click:Connect(function() setMode("held") end)
allBtn.MouseButton1Click:Connect(function() setMode("all") end)
zoomIn.MouseButton1Click:Connect(function() S.zoom = math.clamp(S.zoom * 1.2, 0.3, 6) end)
zoomOut.MouseButton1Click:Connect(function() S.zoom = math.clamp(S.zoom / 1.2, 0.3, 6) end)

local function overArea()
	local p = UIS:GetMouseLocation()
	local a, s = area.AbsolutePosition, area.AbsoluteSize
	local inset = game:GetService("GuiService"):GetGuiInset()
	for _, q in ipairs({ p, p - inset }) do
		if q.X >= a.X and q.X <= a.X + s.X and q.Y >= a.Y and q.Y <= a.Y + s.Y then return true end
	end
	return false
end
table.insert(S.conns, UIS.InputChanged:Connect(function(input, gp)
	if input.UserInputType == Enum.UserInputType.MouseWheel and overArea() then
		S.zoom = math.clamp(S.zoom * (1.12 ^ input.Position.Z), 0.3, 6)
	elseif S.dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and S.mode == "held" then
		S.drag += input.Delta.X * 0.012
	end
end))
local pinchBase
table.insert(S.conns, UIS.TouchPinch:Connect(function(_, scale, _, state)
	if not overArea() then return end
	if state == Enum.UserInputState.Begin then pinchBase = S.zoom end
	if pinchBase then S.zoom = math.clamp(pinchBase * scale, 0.3, 6) end
end))
area.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then S.dragging = true end
end)
table.insert(S.conns, UIS.InputEnded:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then S.dragging = false end
end))

table.insert(S.conns, RunService.RenderStepped:Connect(function()
	if win.Closed or win.Minimized then return end
	local ang = os.clock() * 0.9 + S.drag
	for i, c in ipairs(S.cells) do
		local info = c.info
		if info and info.cam.Parent then
			local dist = info.radius / math.tan(math.rad(25)) * 1.15 / S.zoom
			local a = ang + i * 0.6
			local pos = Vector3.new(math.sin(a) * dist, info.radius * 0.35 / S.zoom, math.cos(a) * dist)
			info.cam.CFrame = CFrame.lookAt(pos, Vector3.zero)
		end
	end
end))

task.spawn(function()
	while S.alive do
		task.wait(0.5)
		if not (win.Closed or win.Minimized) and content.Parent then
			local ok, sig = pcall(signature)
			if ok and sig ~= S.sig then pcall(rebuild) end
		end
	end
end)

genv.__RPP_ToolCleanup = function()
	S.alive = false
	for _, c in ipairs(S.conns) do pcall(function() c:Disconnect() end) end
	clear()
end

setMode("held")

]=====]

do
	local genv0 = (getgenv or function() return _G end)()
	if type(genv0.__RPP_Cleanup) == "function" then pcall(genv0.__RPP_Cleanup) end
	genv0.__RPP_Cleanup = function()
		pcall(function()
			local L = genv0.__AnimVFXLogger
			if type(L) == "table" and type(L.cleanup) == "function" then L.cleanup() end
		end)
		pcall(function() if genv0.__RPP and genv0.__RPP.Main then genv0.__RPP.Main.Uninit() end end)
		pcall(function()
			local pg = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui")
			if pg then
				for _, g in ipairs(pg:GetChildren()) do
					if g.Name == "AnimVFXLogger" or g.Name == "AnimVFXLoggerLoading" then g:Destroy() end
				end
			end
		end)
		pcall(function() if type(genv0.UICopierCleanup) == "function" then genv0.UICopierCleanup() end end)
		pcall(function() if type(genv0.__RPP_ToolCleanup) == "function" then genv0.__RPP_ToolCleanup() end end)
		genv0.__RPP, genv0.__RPP_Logger, genv0.__AnimVFXLogger, genv0.__RPP_Copy, genv0.__RPP_CopyHost = nil, nil, nil, nil, nil
	end
end
Main.Init()
